drive(t, c, out) {
      out.amount = 0.55 + 1.6 * c.erupt;
      out.parts.burst = { visible: smoothstep(0, 0.2, c.erupt) };
    }

build:
build(k) {
      const V = unit([0.15, 0.25, 1]);
      const iceCol = (deep) => (c) => {
        const rim = 1 - Math.abs(dot(c.n, V));
        const g = c.fbm(c.p[0] * 5, c.p[1] * 5, c.p[2] * 5);
        const l = clamp(0.5 + 0.45 * dot(c.n, LIGHT) + 0.2 * g - deep, 0, 1);
        let col = ramp(["#3f8fc0", "#7cc0e4", "#bfe6f7", "#f2fbff"], l);
        col = mix(col, "#ffffff", 0.55 * Math.pow(rim, 3));
        if (Math.abs(g) < 0.018) col = mix(col, "#ffffff", 0.6);
        return col;
      };
      const ice = (deep = 0) => ({ flat: 0.25, opacity: 0.9, color: iceCol(deep) });
      // Each piece of the swan is a part that melts (gets smaller about
      // where it joins the rest) and may break off (ICE_PIECES).
      const P = Object.fromEntries(
        ICE_PIECES.map((pc) => [pc.name, k.part(pc.name, { pivot: pc.pivot })]),
      );
      // The frost coat: fewer, bigger splats over the same surfaces,
      // coloured as the ice there, that glow as the frost front (channel
      // 0, by height) passes. Hidden except while it runs, when the swan is
      // whole again.
      const coat = k.part("coat", { pivot: [0, 0.5, 0] });
      const both = (shape, opts) => {
        k.add(shape, opts);
        const { interior, core, part, ...rest } = opts;
        k.add(shape, {
          ...rest,
          weight: 0.3,
          size: 1.5,
          flat: 0.4,
          part: coat,
          opacity: 0.45,
          kind: "band",
          channel: 0,
          params: (c) => [clamp(c.p[1] / 1.25, 0, 1), 0.12],
        });
      };
      // The pedestal: a thick slab of ice.
      both(k.box(1.0, 0.3, 0.62), {
        pos: [0, 0.15, 0],
        interior: 0.08,
        core: "#a8dcf4",
        ...ice(0.1),
      });
      // The swan: a full body with a lifted tail, arched wings and an S neck.
      both(k.ellipsoid(0.38, 0.19, 0.21), {
        pos: [-0.02, 0.47, 0],
        interior: 0.08,
        core: "#bfe8fa",
        part: P.body,
        ...ice(),
      });
      both(
        k.tube(
          spline([
            [-0.3, 0.5, 0],
            [-0.42, 0.56, 0],
            [-0.5, 0.66, 0],
          ]),
          (t) => 0.11 * (1 - 0.8 * t),
          { samples: 24, grid: 14, caps: true },
        ),
        { part: P.tail, ...ice() },
      );
      const neck = spline([
        [0.26, 0.52, 0],
        [0.36, 0.64, 0],
        [0.4, 0.8, 0],
        [0.33, 0.95, 0],
        [0.3, 1.07, 0],
        [0.36, 1.16, 0],
        [0.45, 1.17, 0],
      ]);
      // The neck breaks where it is thinnest between its curves.
      both(
        k.tube(neck, (t) => 0.075 - 0.035 * t, { samples: 96, grid: 24 }),
        {
          part: (c) => (c.p[1] < ICE_NECK_BREAK ? P.neckLo : P.neckHi),
          ...ice(),
        },
      );
      both(k.ellipsoid(0.075, 0.058, 0.052), { pos: [0.46, 1.165, 0], part: P.head, ...ice() });
      both(k.cone(0.032, 0.004, 0.13), {
        pos: [0.57, 1.14, 0],
        rot: [0, 0, -105],
        part: P.beak,
        ...ice(),
      });
      for (const side of [-1, 1]) {
        const near = side > 0;
        both(
          k.param(
            (u, v) => {
              // u runs along the wing (front to back), v from its root up
              // to the feathered edge.
              const x = 0.18 - 0.55 * u;
              const lift = 0.36 * v * Math.sin(Math.PI * (0.25 + 0.75 * u)) + 0.12 * v * u;
              const feather = 0.035 * Math.abs(Math.sin(u * Math.PI * 6)) * v * v;
              return [
                x - 0.1 * v * u,
                0.55 + lift + feather,
                side * (0.17 + 0.1 * v - 0.12 * v * v),
              ];
            },
            { grid: 24 },
          ),
          {
            // The arched top of the wing is what cracks off.
            part: (c) =>
              c.p[1] > ICE_WING_BREAK
                ? P[near ? "tipNear" : "tipFar"]
                : P[near ? "wingNear" : "wingFar"],
            ...ice(),
          },
        );
      }
      // Frost specks drifting about it while it is cold.
      const frost = k.part("frost", { pivot: [0, 0.5, 0] });
      k.cloud({ share: 0.003, size: 0.6, pattern: false }, (r) => ({
        p: [(r() - 0.5) * 1.1, 0.3 + r() * 0.9, (r() - 0.5) * 0.7],
        color: "#ffffff",
        opacity: 0.85,
        kind: "rise",
        params: [0.14, r()],
        part: frost,
      }));
      // Drops of meltwater: each a token that beads at a low point of a
      // piece (or the pedestal's edge) and falls to the pedestal's top or
      // the ground. Big enough to show on a phone.
      const r = lcg(33);
      const byName = Object.fromEntries(ICE_PIECES.map((pc) => [pc.name, pc]));
      const drops = ICE_DROPS.map(([piece, p], i) => {
        const over = Math.abs(p[0]) < 0.49 && Math.abs(p[2]) < 0.3 && p[1] > 0.31;
        const tok = { kind: "token", params: [i, 0], pattern: false };
        k.add(k.ellipsoid(0.017, 0.026, 0.017), {
          ...tok,
          pos: p,
          weight: 3,
          size: 1.3,
          color: (c) => mix("#e4f6ff", "#ffffff", Math.max(0, dot(c.n, LIGHT))),
          opacity: 0.85,
        });
        return {
          p,
          piece,
          pv: byName[piece]?.pivot || p,
          to: over ? 0.31 : 0.01,
          period: 0.7 + 0.5 * r(),
          phase: r(),
        };
      });
      // The puddle: flat splats lying on the ground in a sunflower spiral
      // (evenly spread, so it is smooth water, not blotches), a little
      // uneven at its rim, spread out by its part's scale.
      const puddle = k.part("puddle", { pivot: [0, 0, 0] });
      k.cloud({ share: 0.012, size: 8, pattern: false }, (r2, i, n) => {
        const a = i * 2.399963;
        const rr = 0.86 * Math.sqrt((i + 0.5) / n) * (0.93 + 0.07 * Math.sin(a * 5 + 1));
        return {
          p: [Math.cos(a) * rr, 0.004, Math.sin(a) * rr * 0.9],
          n: [0, 1, 0],
          flat: 0.2,
          color: mix("#cdeefb", "#86c6e4", rr / 0.86),
          opacity: 0.32,
          part: puddle,
        };
      });
      k.data = { drops };
    }

drive:
drive(t, c, out, info) {
      const m = mem(c);
      const s = since(c.thaw, ICE_SECS);
      const tap =
        s === null
          ? 0
          : ICE_TOP * Math.pow(band(s, 0.1, ICE_MELT), 1.6) * (1 - ease(band(s, ICE_MELT + 0.3, ICE_MELT + 1.6))); // prettier-ignore
      const e = Math.max(clamp(c.temp ?? 0, 0, 1), tap);
      if (e < 0.002) m.maxL = 0;
      else m.maxL = Math.max(m.maxL ?? 0, e);
      const cooling = e < (m.maxL ?? 0) - 0.004;
      const pieces = icePose(e, (pc) => cooling && (m.maxL ?? 0) >= pc.end);
      for (const [name, st] of Object.entries(pieces)) {
        const { attached, ...part } = st;
        out.parts[name] = part;
      }
      // Water: a puddle spreading out from under the pedestal, and drops
      // (tokens) that bead at the low points and fall while it melts, more
      // of them the more it has melted.
      const pool = smoothstep(0.01, 0.8, e);
      out.parts.puddle = { scale: 0.3 + 0.7 * pool, visible: pool > 0.002 ? 1 : 0 };
      const melting = e > 0.02 && !cooling;
      const drops = info?.data?.drops || [];
      out.tokens = drops.map((d, i) => {
        const pc = pieces[d.piece];
        const onIt = !pc || (pc.attached && (pc.scale ?? 1) > 0.25);
        if (!melting || !onIt || i / drops.length > 0.25 + 1.3 * e)
          return { base: d.p, visible: 0 };
        const u = (((t + d.phase * d.period) % d.period) + d.period) % d.period;
        const from = pc ? add(add(d.pv, pc.offset ?? [0, 0, 0]), mul(sub(d.p, d.pv), pc.scale ?? 1)) : d.p; // prettier-ignore
        if (u < ICE_HANG) {
          // Beading up at the edge.
          return { base: d.p, offset: sub(from, d.p), visible: 0.35 + 0.65 * (u / ICE_HANG) };
        }
        const f = u - ICE_HANG;
        const drop = 0.5 * ICE_G * f * f;
        if (drop > from[1] - d.to) return { base: d.p, visible: 0 };
        return { base: d.p, offset: [from[0] - d.p[0], from[1] - drop - d.p[1], from[2] - d.p[2]] };
      });
      out.parts.frost = { visible: 1 - smoothstep(0, 0.3, e) };
      // The frost front: the coat shows (coloured as the ice) just before
      // it and the band of light runs up it on channel 0.
      const F = ICE_MELT + 1.5;
      const front = s === null ? 0 : bump(s, F, F + 0.15, F + 1.4, F + 1.6);
      out.parts.coat = { visible: e < 0.01 ? front : 0 };
      out.morph = [s === null ? -0.3 : -0.25 + 1.5 * band(s, F + 0.15, F + 1.35)];
      const g = s === null ? 0 : bump(s, F + 0.1, F + 0.25, F + 1.15, F + 1.4);
      out.glow = [0.72, 0.9, 1, 1.1 * g];
      // A crack as each piece breaks off, and the crackle of refreezing.
      if (s !== null) {
        const at = (L) => 0.1 + (ICE_MELT - 0.1) * Math.pow(L / ICE_TOP, 1 / 1.6);
        const cues = ICE_PIECES.filter((pc) => pc.fall).map((pc, n) => [
          at(pc.detach),
          { voice: "crack", f: 2400 - 250 * n, decay: 0.35, vol: 0.75 },
        ]);
        cues.push([ICE_MELT + 0.35, { voice: "crackle", f: 4600, n: 14, decay: 1.2, vol: 0.6 }]);
        cues.push([F + 0.1, { voice: "sparkle", f: 3400, n: 8, decay: 1.3 }]);
        cuesAt(m, s, cues, out);
      } else cuesAt(m, null, [], out);
    }

build:
build(k, o) {
      const wax = o.wax;
      const H = 0.95;
      const R = 0.26;
      const waxCol = (c) => {
        const glow = smoothstep(H - 0.35, H, c.p[1]);
        const col = mix(wax, mix(wax, "#ffcf8a", 0.6), glow);
        return lit(col, c.n, 0.35);
      };
      k.add(
        k.lathe(
          [
            [R, 0],
            [R, H - 0.06],
            [R * 0.97, H - 0.01],
            [R * 0.85, H],
            [R * 0.4, H - 0.03],
            [0, H - 0.04],
          ],
          { thick: 0.1 },
        ),
        {
          even: true,
          opacity: 1,
          jitter: 0.015,
          flat: 0.25,
          interior: 0.1,
          core: shade(wax, 0.92),
          color: waxCol,
        },
      );
      // Drips of wax down the side.
      for (let i = 0; i < 8; i++) {
        const a = (i / 8) * TAU + k.rand() * 0.5;
        const len = 0.15 + 0.3 * k.rand();
        const d = [Math.sin(a), 0, Math.cos(a)];
        const top = [d[0] * R * 1.0, H - 0.02, d[2] * R * 1.0];
        const bot = [d[0] * R * 1.02, H - len, d[2] * R * 1.02];
        k.add(
          k.tube(spline([top, lerp3(top, bot, 0.5), bot]), (t) => 0.022 + 0.012 * t * t, {
            samples: 16,
            grid: 10,
            caps: true,
          }),
          { opacity: 1, jitter: 0.015, color: waxCol },
        );
      }
      // The wick.
      k.add(
        k.tube(
          spline([
            [0, H - 0.04, 0],
            [0.005, H + 0.02, 0],
            [0.015, H + 0.06, 0],
          ]),
          0.008,
          { samples: 8, grid: 6 },
        ),
        { opacity: 1, jitter: 0.015, weight: 3, color: "#1a1410" },
      );
      // The flame: a steady core, flickering tongues and a warm halo.
      const flame = k.part("flame", { pivot: [0, H + 0.05, 0] });
      k.add(
        k.lathe([
          [0, 0],
          [0.03, 0.03],
          [0.038, 0.07],
          [0.028, 0.13],
          [0.012, 0.19],
          [0, 0.23],
        ]),
        {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [0, H + 0.03, 0],
          part: flame,
          weight: 3,
          pattern: false,
          kind: "twinkle",
          params: [0.15, 0],
          color: (c) => {
            const y = (c.p[1] - (H + 0.03)) / 0.2;
            return y < 0.2
              ? mix("#3a6aff", "#ffe8a0", y / 0.2)
              : mix("#fff6d0", "#ffb030", smoothstep(0.5, 1, y));
          },
        },
      );
      k.cloud({ share: 0.03, size: 0.7, pattern: false }, (r) => {
        const a = r() * TAU;
        const rr = 0.028 * Math.sqrt(r());
        return {
          p: [Math.sin(a) * rr, H + 0.08 + r() * 0.04, Math.cos(a) * rr],
          color: mix("#ffb040", "#fff2c0", 1 - rr / 0.028),
          opacity: 0.8,
          kind: "flame",
          params: [0.12 + 0.08 * r(), r()],
          part: flame,
        };
      });
      k.cloud({ share: 0.008, size: 4, pattern: false }, (r) => {
        const d = randDir(r);
        const rr = 0.1 + 0.14 * r();
        return {
          p: [d[0] * rr, H + 0.15 + d[1] * rr * 1.3, d[2] * rr],
          color: "#ffc070",
          opacity: 0.04,
          kind: "twinkle",
          params: [0.3, r() * 6],
          part: flame,
        };
      });
      // A wisp of smoke when it is blown out.
      const smoke = k.part("smoke", { pivot: [0, H + 0.06, 0] });
      k.cloud({ share: 0.01, size: 1.8, pattern: false }, (r) => ({
        p: [0.015 + (r() - 0.5) * 0.02, H + 0.07, (r() - 0.5) * 0.02],
        color: "#bdb8b2",
        opacity: 0.25,
        kind: "rise",
        params: [0.5, r()],
        part: smoke,
      }));
      // A brass dish with a finger ring.
      const brass = (c) => {
        const env = smoothstep(-0.3, 0.9, -0.5 * c.n[0] + 0.6 * c.n[1] + 0.3 * c.n[2]);
        return mix("#6a4a1a", "#f8dc8a", env);
      };
      k.add(
        k.lathe([
          [0, -0.04],
          [0.42, -0.04],
          [0.47, -0.02],
          [0.48, 0.04],
          [0.45, 0.03],
          [0.3, 0.0],
          [0, 0.0],
        ]),
        { even: true, opacity: 1, jitter: 0.015, flat: 0.2, color: brass },
      );
      k.add(k.torus(0.08, 0.018), {
        opacity: 1,
        jitter: 0.015,
        pos: [0.55, 0.02, 0],
        rot: [90, 0, 0],
        color: brass,
      });
      k.reach([0, H + 0.45, 0]);
    }

drive:
drive(t, c, out) {
      out.parts.flame = { visible: c.lit };
      out.parts.smoke = { visible: 1 - c.lit };
      out.amount = 0.6 + 0.4 * c.lit;
    }

build:
build(k) {
      const H = TW_H;
      const rad = twRad;
      // The funnel: dust whirling fastest near the ground, in five bands
      // (parts) that widen and spin up on a tap. The bottom band grows up
      // from the ground and the top one down from the cloud.
      const bands = Array.from({ length: TW_BANDS }, (_, i) => {
        const y = i === 0 ? 0 : i === TW_BANDS - 1 ? H : ((i + 0.5) / TW_BANDS) * H;
        return k.part(`band${i}`, { pivot: [0, y, 0] });
      });
      k.cloud({ share: 0.55, size: 2.3, pattern: false }, (r) => {
        const y = H * Math.pow(r(), 0.8);
        const a = r() * TAU;
        const rr = rad(y) * (0.82 + 0.22 * Math.sqrt(r()));
        const streak = 0.5 + 0.5 * Math.sin(a * 3 + y * 9);
        const v = clamp(0.25 + 0.5 * (y / H) + 0.25 * streak + 0.1 * (r() - 0.5), 0, 1);
        return {
          p: [Math.sin(a) * rr, y, Math.cos(a) * rr],
          dir: [Math.cos(a), 0.15, -Math.sin(a)],
          stretch: 1.8,
          color: ramp(["#4a3e34", "#66584a", "#847a70", "#a09a94", "#c0bcb8"], v),
          opacity: 0.55 + 0.3 * (1 - y / H),
          kind: "orbit",
          params: [2.2, 0.6],
          part: bands[twBand(y)],
        };
      });
      // Debris caught in the wind.
      k.cloud({ share: 0.0006, size: 1.0, pattern: false }, (r) => {
        const y = 0.1 + r() * (H - 0.3);
        const a = r() * TAU;
        const rr = rad(y) * (1.1 + 0.5 * r());
        return {
          p: [Math.sin(a) * rr, y, Math.cos(a) * rr],
          n: randDir(r),
          color: mix("#2a2018", "#5a4a38", r()),
          kind: "orbit",
          params: [1.3, 0.3],
          part: bands[twBand(y)],
        };
      });
      // Dust boiling up around the foot.
      const dust = k.part("dust", { pivot: [0, 0, 0] });
      k.cloud({ share: 0.025, size: 2.2, pattern: false }, (r) => {
        const a = r() * TAU;
        const rr = 0.06 + 0.26 * r();
        return {
          p: [Math.sin(a) * rr, 0.03, Math.cos(a) * rr],
          color: mix("#8a7866", "#b8a894", r()),
          opacity: 0.2,
          kind: "rise",
          params: [0.4 + 0.3 * r(), r()],
          part: dust,
        };
      });
      // Planks, clods and leaves lying on the field in front, each a token
      // (built ahead of the funnel for the draw order; see TW_AHEAD).
      TW_DEBRIS.forEach((d, i) => {
        const pos = add([Math.sin(d.a) * d.r0, d.h, Math.cos(d.a) * d.r0], TW_AHEAD);
        const token = { kind: "token", params: [i, 0], pattern: false, fit: false, flat: 0.3 };
        if (d.type === "plank")
          k.add(k.box(0.13, 0.018, 0.036), {
            ...token,
            pos,
            rot: [0, d.yaw, 0],
            count: 110,
            color: (c) =>
              lit(
                mix("#8a5a30", "#5a3a1e", 0.5 + 0.5 * Math.sin(c.lp[0] * 90 + 3 * d.tone)),
                c.n,
                0.4,
              ),
          });
        else if (d.type === "clod")
          k.add(k.sphere(0.024), {
            ...token,
            pos,
            scale: [1.2, 0.8, 1],
            count: 60,
            color: (c) => lit(mix("#4a3624", "#6a5238", c.rand()), c.n, 0.4),
          });
        else
          k.add(k.ellipsoid(0.036, 0.005, 0.021), {
            ...token,
            pos,
            rot: [0, d.yaw, 0],
            count: 50,
            color: (c) => lit(ramp(["#4a8a2a", "#9aa830", "#e0a020", "#c8601a"], d.tone), c.n, 0.3),
          });
      });
      // The storm cloud it hangs from, turning slowly: soft puffs, lit on top.
      const puffs = [];
      for (let i = 0; i < 34; i++) {
        const a = i * 2.39996;
        const rr = 1.05 * Math.sqrt((i + 0.5) / 34);
        const s = 0.2 + 0.12 * ((i * 0.37) % 1) + 0.08 * (1 - rr);
        puffs.push({
          c: [
            Math.sin(a) * rr,
            H + 0.05 + 0.12 * (1 - rr) + 0.05 * Math.cos(i * 1.7),
            Math.cos(a) * rr,
          ],
          s,
        });
      }
      for (const pf of puffs) {
        k.add(k.sphere(pf.s), {
          pos: pf.c,
          scale: [1, 0.7, 1],
          size: 2.4,
          flat: 1,
          opacity: 0.75,
          pattern: false,
          kind: "orbit",
          params: [0.25, 0],
          color: (c) => {
            for (const q of puffs) {
              if (q === pf) continue;
              const d = Math.hypot(c.p[0] - q.c[0], (c.p[1] - q.c[1]) / 0.7, c.p[2] - q.c[2]);
              if (d < q.s * 0.85) return null;
            }
            const v = clamp(
              0.3 +
                0.35 * c.n[1] +
                0.25 * dot(c.n, LIGHT) +
                0.12 * c.fbm(c.p[0] * 3, c.p[1] * 3, c.p[2] * 3),
              0,
              1,
            );
            return ramp(["#1e2026", "#34373f", "#50545e", "#7a7f8a", "#a8acb4"], v);
          },
        });
      }
      // Flat fields below.
      k.add(k.disc(1.05), {
        pos: [0, 0, 0],
        color: (c) => {
          if (c.n[1] < 0) return "#3a2e20";
          const r = Math.hypot(c.p[0], c.p[2]);
          const g = c.fbm(c.p[0] * 5, 0, c.p[2] * 5);
          let col = mix("#5a7a2a", "#8a9a3a", 0.5 + 0.5 * g);
          if (Math.abs(Math.sin(c.p[0] * 14)) < 0.15) col = mix(col, "#6a5a3a", 0.4);
          return mix(col, "#6a5a44", smoothstep(0.45, 0.1, r));
        },
      });
    }

drive:
drive(t, c, out) {
      const s = since(c.whirl, TW_SECS);
      const grow = s === null ? 0 : ease(band(s, 0.05, 1.0)) * (1 - ease(band(s, 2.9, 4.3)));
      const weak = s === null ? 0 : bump(s, 3.8, 4.3, 4.7, 5.3);
      const q = quatAxisAngle([0, 1, 0], s === null ? 0 : TAU * 2 * ease(band(s, 0.05, 4.6)));
      for (let i = 0; i < TW_BANDS; i++)
        out.parts[`band${i}`] = { quat: q, scale: 1 + (TW_GROW[i] - 1) * grow - 0.14 * weak };
      out.parts.dust = { scale: 1 + 0.5 * grow };
      out.amount = 0.4 + 1.2 * c.power + 0.5 * grow;
      out.tokens = TW_DEBRIS.map((d) => {
        const rest = [Math.sin(d.a) * d.r0, d.h, Math.cos(d.a) * d.r0];
        const base = add(rest, TW_AHEAD);
        if (s === null) return { base, offset: mul(TW_AHEAD, -1) };
        const [p, u] = twDebrisAt(d, s, grow);
        // Hidden while it passes behind the funnel (seen from the front).
        const y = p[1];
        const fr = twRad(Math.min(TW_H, y)) * (1 + (TW_GROW[twBand(y)] - 1) * grow);
        const behind = smoothstep(0.04, -0.06, dot(p, TW_CAM));
        const across = smoothstep(fr * 1.05, fr * 0.8, Math.abs(dot(p, TW_RIGHT)));
        return {
          base,
          offset: sub(p, base),
          quat: quatAxisAngle(d.axis, TAU * d.spin * ease(u)),
          visible: 1 - behind * across,
        };
      });
    }

build:
build(k) {
      const bands = RB_COLS;
      const R = RB_R;
      const w = RB_W;
      // The arc: each splat fades out as channel 0 passes its place (its
      // band, then how far along it is).
      k.add(evenTorus(k, R, w), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        rot: [90, 0, 0],
        scale: [1, 0.3, 1],
        flat: 0.25,
        kind: "fade",
        channel: 0,
        params: (c) => {
          const d = Math.hypot(c.p[0], c.p[1]) - R;
          const f = clamp(0.5 - d / (2 * w), 0, 0.999);
          return [rbAt(Math.floor(f * 7), Math.atan2(c.p[1], c.p[0])), 0.012];
        },
        color: (c) => {
          if (c.p[1] < -0.02) return null;
          const d = Math.hypot(c.p[0], c.p[1]) - R;
          const f = clamp(0.5 - d / (2 * w), 0, 0.999);
          const col = ramp(bands, f);
          return lit(col, c.n, 0.2);
        },
      });
      // Fluffy clouds at both feet (a part each, to puff up).
      for (const side of [-1, 1]) {
        const cloud = k.part(side < 0 ? "cloudL" : "cloudR", { pivot: [side * R, 0.02, 0] });
        for (let i = 0; i < 7; i++) {
          const s = 0.13 + 0.07 * k.rand();
          const pos = [
            side * R + (k.rand() - 0.5) * 0.45,
            0.02 + k.rand() * 0.12,
            (k.rand() - 0.5) * 0.25,
          ];
          k.add(k.sphere(s), {
            even: true,
            opacity: 1,
            jitter: 0.015,
            pos,
            size: 1.8,
            flat: 0.8,
            kind: "breathe",
            params: [0.015, side],
            part: cloud,
            color: (c) =>
              mix("#c8d4e4", "#ffffff", clamp(0.4 + 0.6 * dot(c.n, LIGHT) + 0.3 * c.n[1], 0, 1)),
          });
        }
      }
      // Sparkles (they go while the arc is wiped).
      const glitter = k.part("glitter", { pivot: [0, 0.5, 0] });
      k.cloud({ share: 0.01, size: 0.9, pattern: false }, (r) => {
        const a = r() * Math.PI;
        const rr = R + (r() - 0.5) * 0.7;
        return {
          p: [Math.cos(a) * rr, Math.sin(a) * rr + 0.05, (r() - 0.5) * 0.2],
          color: "#ffffff",
          opacity: 0.9,
          kind: "twinkle",
          params: [0.45, r() * 6],
          part: glitter,
        };
      });
      // The pens, one per band (token i), built at the top of the arc just
      // in front of it: a bright core and a soft halo.
      RB_COLS.forEach((col, i) => {
        const at = [0, rbRadius(i), 0.075];
        k.cloud({ count: 70, size: 0.8, pattern: false }, (r) => {
          const d = randDir(r);
          const rr = 0.022 * Math.cbrt(r());
          return {
            p: add(at, mul(d, rr)),
            color: mix(col, "#ffffff", 0.55 + 0.4 * (1 - rr / 0.022)),
            opacity: 1,
            kind: "token",
            params: [i, 0],
          };
        });
        k.cloud({ count: 16, size: 3.2, pattern: false }, (r) => ({
          p: add(at, mul(randDir(r), 0.02 * r())),
          color: mix(col, "#ffffff", 0.35),
          opacity: 0.25,
          kind: "token",
          params: [i, 0],
        }));
      });
      // Bursts of sparkles from both clouds, built packed at each foot and
      // spread by their part's scale.
      for (const side of [-1, 1]) {
        // In front of the cloud, so they draw over it.
        const foot = [side * (R - 0.02), 0.2, 0.3];
        const part = k.part(side < 0 ? "burstL" : "burstR", { pivot: foot });
        k.cloud({ share: 0.0016, size: 1.9, pattern: false }, (r) => {
          const d = randDir(r);
          const up = [d[0] * 1.1, Math.abs(d[1]) * 0.8 + 0.55, d[2] * 0.3];
          return {
            p: add(foot, mul(up, 0.06 * (0.3 + 0.7 * r()))),
            color: r() < 0.6 ? "#ffffff" : mix(RB_COLS[Math.floor(r() * 7)], "#ffffff", 0.35),
            opacity: 1,
            part,
          };
        });
      }
    }

drive:
drive(t, c, out) {
      const s = since(c.draw, RB_SECS);
      const ch = rbChannel(s);
      out.morph = [ch];
      // The pen rides the drawing front: band i, from the left foot (f = 1)
      // to the right (f = 0).
      const x = ch * 7;
      const drawing = s !== null && s > 0.8 && s < 3.6;
      out.tokens = RB_COLS.map((_, i) => {
        const base = [0, rbRadius(i), 0.075];
        const f = x - (6 - i);
        if (!drawing || f < 0 || f > 1) return { base, visible: 0 };
        const a = Math.PI * f;
        const r = rbRadius(i);
        return {
          base,
          offset: sub([Math.cos(a) * r, Math.sin(a) * r, 0.075], base),
          visible: smoothstep(0, 0.05, f) * smoothstep(1, 0.95, f),
        };
      });
      const burst = s === null ? 0 : band(s, 3.5, 4.7);
      const grow = 1 + 6 * easeOut(burst);
      const fade = s === null || s < 3.5 ? 0 : 1 - band(s, 4.1, 4.8);
      for (const side of ["L", "R"]) {
        out.parts[`burst${side}`] = {
          scale: grow,
          offset: [0, -0.12 * burst * burst, 0],
          visible: fade / grow,
        };
        out.parts[`cloud${side}`] = {
          scale: 1 + 0.1 * (s === null ? 0 : bump(s, 3.45, 3.65, 3.8, 4.6)),
        };
      }
      out.parts.glitter = { visible: 1 - clamp01(ch) };
    }

build:
build(k) {
      const n = k.noise;
      const shapeR = (d) => {
        const up = smoothstep(-0.25, 0.25, d[1]);
        const a = 0.82 - 0.3 * up;
        const b = 1.0 - 0.25 * smoothstep(-0.1, 0.1, d[1]);
        const base = 1 / Math.hypot(Math.hypot(d[0], d[2]) / a, d[1] / b);
        const bump = Math.max(0, n(d[0] * 1.6 + 5, d[1] * 1.6, d[2] * 1.6));
        const peaks = 0.9 * bump * bump * Math.max(0, d[1]);
        return base * (1 + 0.1 * n.fbm(d[0] * 2, d[1] * 2, d[2] * 2, 3) + peaks);
      };
      const shape = k.radial(shapeR, { grid: 96 });
      const ch = icebergChunk(shapeR);
      k.data = { chunk: ch };
      const inChunk = (p) => dot(p, IB_N) > ch.h && p[1] > IB_FLOOR;
      const berg = k.part("berg", { pivot: [0, 0, 0] });
      const chunk = k.part("chunk", { pivot: ch.hinge });
      k.add(shape, {
        flat: 0.25,
        interior: 0.12,
        // The chunk is hollow (its inside would draw over it as it turns).
        core: (c) => (inChunk(c.p) ? null : "#8fd0ee"),
        part: (c) => (inChunk(c.p) ? chunk : berg),
        color: (c) => {
          const y = c.p[1];
          const g = c.fbm(c.p[0] * 5, c.p[1] * 5, c.p[2] * 5);
          if (y < 0) {
            const depth = clamp(-y / 1.1, 0, 1);
            return mix(mix("#5fb8d8", "#2a7fae", depth), "#1a4a78", 0.4 * depth + 0.15 * g);
          }
          const crack = Math.abs(g) < 0.04;
          let col = mix("#a8dcf2", "#ffffff", clamp(0.45 + 0.6 * dot(c.n, LIGHT) + 0.2 * g, 0, 1));
          if (crack) col = mix(col, "#6ab8e0", 0.6);
          return col;
        },
      });
      // The broken faces, on the two cuts, inside until it breaks: fresh
      // ice, paler and glassier than the weathered surface. One set stays
      // on the berg and one goes with the chunk.
      const e1 = unit(cross(IB_N, [0, 1, 0]));
      const e2 = cross(IB_N, e1);
      const Q = mul(IB_N, ch.h);
      const inside = (p) => len(p) < shapeR(unit(p)) * 0.995;
      // A point on the steep cut (above the floor) or on the floor (outside
      // the cut), with the face's normal out of the berg.
      const onCut = (r) => {
        for (let tries = 0; tries < 80; tries++) {
          if (r() < 0.7) {
            const p = add(Q, add(mul(e1, (r() - 0.5) * 1.4), mul(e2, (r() - 0.5) * 1.4)));
            if (p[1] > IB_FLOOR && inside(p)) return [p, IB_N];
          } else {
            const p = [(r() - 0.5) * 1.8, IB_FLOOR, (r() - 0.5) * 1.8];
            if (dot(p, IB_N) > ch.h && inside(p)) return [p, [0, 1, 0]];
          }
        }
        return null;
      };
      for (const side of [1, -1]) {
        k.cloud({ share: 0.03, size: 1.15, pattern: false }, (r) => {
          const hit = onCut(r);
          if (!hit) return null;
          const p = hit[0];
          const nn = mul(hit[1], side);
          const vein = n(p[0] * 7, p[1] * 7, p[2] * 7);
          const col = mix("#e6f7ff", "#9fd6f2", 0.5 + 0.5 * vein);
          return {
            p: add(p, mul(nn, 0.004)),
            n: nn,
            flat: 0.2,
            color: lit(Math.abs(vein) < 0.05 ? "#ffffff" : col, nn, 0.35),
            opacity: 0.97,
            part: side > 0 ? berg : chunk,
          };
        });
      }
      // The sea: see-through and rippling, with foam at the waterline,
      // fading out towards its edge.
      k.cloud({ share: 0.14, size: 1.7, flat: 0.3, pattern: false }, (r) => {
        const a = r() * TAU;
        const rr = Math.sqrt(0.2 + r() * (1.9 - 0.2));
        const x = Math.sin(a) * rr;
        const z = Math.cos(a) * rr;
        const g = n.fbm(x * 3, 0, z * 3, 3);
        const foam = rr < 0.64 + 0.06 * g;
        return {
          p: [x, 0, z],
          n: [0, 1, 0],
          color: foam ? "#f2fbff" : mix("#6cc0e0", "#2a86b8", clamp(rr / 1.3 + 0.3 * g, 0, 1)),
          opacity: foam ? 0.85 : 0.5 * (1 - smoothstep(0.75, 1.38, rr)) + 0.04,
          kind: "wave",
          params: [0.006, 0],
        };
      });
      // Where the chunk lands.
      const fall = ch.Ti - ch.T1;
      const Ci = add(add(ch.C1, mul(ch.V1, fall)), [0, -0.5 * IB_G * fall * fall, 0]);
      const W = [Ci[0], 0.012, Ci[2]];
      // The splash: drops built packed at the landing point (a little
      // towards the camera, to draw over the chunk) and thrown up by their
      // part's scale; the drive adds the fall (see splash in drive).
      const W1 = add(W, mul(IB_CAM, 0.3));
      const splash = k.part("splash", { pivot: W1 });
      k.cloud({ share: 0.008, size: 1.15, pattern: false }, (r) => {
        const a = r() * TAU;
        // A crown thrown out and up, and a jet up the middle.
        const crown = r() < 0.65;
        const vr = crown ? 0.55 + 0.4 * r() : 0.25 * r();
        const vy = crown ? 1.5 + 0.5 * r() : 1.9 + 0.5 * r();
        const v = [Math.cos(a) * vr, vy, Math.sin(a) * vr];
        return {
          p: add(W1, mul(v, 0.06)),
          color: mix("#d8f2ff", "#ffffff", r()),
          opacity: 0.9,
          part: splash,
        };
      });
      // Ripples: two rings and a patch of foam, built small and spread by
      // their part's scale, fading in and out on channel 1.
      const ripple = k.part("ripple", { pivot: W });
      k.cloud({ share: 0.005, size: 0.8, pattern: false }, (r) => {
        const a = r() * TAU;
        const pick = r();
        const rr = pick < 0.4 ? 0.05 : pick < 0.7 ? 0.03 : 0.018 * Math.sqrt(r());
        const ring = pick < 0.7;
        return {
          p: add(W, [Math.cos(a) * rr, 0, Math.sin(a) * rr]),
          dir: ring ? [-Math.sin(a), 0, Math.cos(a)] : undefined,
          n: ring ? undefined : [0, 1, 0],
          stretch: 2.5,
          color: mix("#e2f5ff", "#ffffff", r()),
          opacity: ring ? 0.75 : 0.85,
          kind: "fade",
          channel: 1,
          params: [0, -0.99],
          part: ripple,
        };
      });
      // Two little floes.
      for (const [x, z, s] of [
        [0.95, 0.35, 0.12],
        [-0.85, 0.6, 0.09],
      ]) {
        k.add(k.ellipsoid(s * 1.4, s * 0.45, s), {
          pos: [x, 0.0, z],
          kind: "wave",
          params: [0.006, 0],
          color: (c) => (c.p[1] < 0 ? "#6ab8d8" : lit("#f2fbff", c.n, 0.3)),
        });
      }
    }

drive:
drive(t, c, out, info) {
      const ch = info?.data?.chunk;
      if (!ch) return;
      const s = since(c.calve, IB_SECS);
      const m = mem(c);
      cuesAt(m, s, [[ch.Ti, { voice: "splash", f: 1100, decay: 1.6, vol: 0.9 }]], out);
      const P = ch.hinge;
      if (s === null) {
        out.parts.chunk = {};
        out.parts.berg = {};
        out.parts.splash = { visible: 0 };
        out.parts.ripple = { visible: 0 };
        out.morph = [0, 0];
        return;
      }
      const pose = icebergPose(ch, s);
      if (pose.regrow !== undefined) {
        const k = pose.regrow;
        out.parts.chunk = { scale: k, offset: mul(sub(ch.F, P), 1 - k), visible: k > 0.01 ? 1 : 0 };
      } else {
        const q = quatAxisAngle(IB_AXIS, pose.th);
        const off = sub(sub(pose.C, P), quatRotate(q, mul(sub(ch.C0, P), pose.k)));
        // A jolt as it cracks, before it starts to tip.
        const jolt = 0.012 * bump(s, 0, 0.03, 0.06, 0.12);
        out.parts.chunk = {
          quat: q,
          scale: pose.k,
          offset: add(off, mul(IB_OUT, jolt)),
          visible: pose.k > 0.01 ? 1 : 0,
        };
      }
      // The berg, lighter, bobs up and rocks after the chunk goes.
      const u = Math.max(0, s - 0.45);
      const damp = Math.exp(-u / 1.0) * (1 - band(s, 3.6, 4.6)) * (s > 0.45 ? 1 : 0);
      const rockAxis = unit(cross([0, 1, 0], IB_OUT));
      out.parts.berg = {
        offset: [0, 0.035 * damp * Math.sin((TAU * u) / 1.4), 0],
        quat: quatAxisAngle(rockAxis, -0.07 * damp * Math.sin((TAU * u) / 1.7)),
      };
      // The splash: a crown of drops thrown up from where it lands, and
      // rings of ripples and foam spreading on the sea (channel 1 fades
      // them in and out).
      const w = s - ch.Ti;
      if (w > 0 && w < 0.85) {
        const kk = w / 0.06;
        out.parts.splash = {
          scale: kk,
          offset: add(mul(IB_CAM, -0.3), [0, -0.5 * IB_G * w * w, 0]),
          visible: (Math.min(1, kk * 0.3) / kk) * (1 - band(w, 0.55, 0.8)),
        };
      } else out.parts.splash = { visible: 0 };
      const kr = 1 + 11 * easeOut(band(w, 0, 1.6));
      out.parts.ripple = { scale: kr, visible: w > 0 && w < 1.8 ? Math.pow(kr, -0.45) : 0 };
      out.morph = [0, w > 0 ? band(w, 0, 0.12) * (1 - ease(band(w, 0.5, 1.7))) : 0];
    }

build:
build(k) {
      const rand = k.rand;
      const TOP = WF_TOP;
      const LIP = WF_LIP;
      // The cliff: a rock wall with strata and moss on its ledges.
      const rock = (c) => {
        const g = c.fbm(c.p[0] * 4, c.p[1] * 4, c.p[2] * 4);
        const strata = Math.abs(Math.sin(c.p[1] * 22 + g * 3));
        let col = mix("#6a6258", "#3e3832", 0.4 + 0.5 * g);
        col = shade(col, 0.85 + 0.2 * strata);
        if (c.n[1] > 0.6) col = mix(col, mix("#3f6a24", "#6a8a34", c.rand()), 0.85);
        return lit(col, c.n, 0.5);
      };
      k.add(k.box(1.6, TOP, 0.6), {
        pos: [0, TOP / 2, -0.05],
        color: (c) => (c.s.face === 3 ? null : rock(c)),
      });
      for (let i = 0; i < 12; i++) {
        const x = (rand() - 0.5) * 1.7;
        if (Math.abs(x) < 0.35) continue;
        const s = 0.12 + 0.12 * rand();
        k.add(k.ellipsoid(s * 1.2, s, s * 0.8), {
          pos: [x, rand() * TOP, 0.25 + rand() * 0.05],
          color: rock,
        });
      }
      // The surge's front glows white as it passes (channel 0: the time
      // it gets there over WF_FRONT).
      const front = (at) => ({ kind: "band", channel: 0, params: [at / WF_FRONT, 0.045] });
      // The river on top, running to the lip.
      k.add(
        k.param((u, v) => [(u - 0.5) * 0.6, TOP + 0.005, -0.34 + v * (LIP + 0.34)], {
          grid: 12,
          flip: true,
        }),
        {
          pattern: false,
          color: (c) => mix("#4aa0c8", "#bfe8f6", 0.5 + 0.5 * Math.sin(c.p[2] * 40 + c.p[0] * 5)),
          ...front(0),
          params: (c) => [wfRiver(c.p[2]) / WF_FRONT, 0.045],
        },
      );
      // The falling curtain, curving out from the lip. It swells in a surge
      // (wider, further out and thicker: its splats spread to the front and
      // back of the thicker sheet).
      const sheet = (c) => {
        const s = 0.5 + 0.5 * Math.sin(c.u * 70 + c.noise(c.u * 8, c.v * 3, 0) * 4);
        return mix("#7ec4e4", "#ffffff", 0.35 + 0.5 * s);
      };
      k.add(k.param(wfFall, { grid: 24 }), {
        opacity: 0.8,
        flat: 0.25,
        pattern: false,
        color: sheet,
        ...front(0),
        params: (c) => [wfDrop(c.v) / WF_FRONT, 0.045],
      });
      // The surge's sheet: built rolled up along the lip and unrolled down
      // the curtain by channel 1, wider, further out and thicker than it.
      const surge = k.part("surge", { pivot: [0, TOP, LIP] });
      k.cloud({ share: 0.05, size: 1.25, pattern: false }, (r) => {
        const u = r();
        const v = r();
        const q = wfSurge(u, v, 2 * r() - 1);
        const s = 0.5 + 0.5 * Math.sin(u * 70 + 3 * r());
        return {
          p: [q[0], TOP - 0.004, LIP + 0.01],
          to: q,
          channel: 1,
          n: unit([0, 0.2, 1]),
          flat: 0.35,
          // Softer towards its foot, so its leading edge is ragged water.
          size: 1 + 0.6 * smoothstep(0.75, 1, v),
          color: mix("#a8dcf2", "#ffffff", 0.5 + 0.5 * s),
          opacity: 0.55 * (1 - 0.65 * smoothstep(0.8, 1, v + 0.1 * (r() - 0.5))),
          part: surge,
        };
      });
      k.cloud({ share: 0.12, size: 0.8, pattern: false }, (r) => {
        const u = r();
        const v = r() * 0.92;
        const p = wfFall(u, v);
        return {
          p: [p[0], p[1], p[2] + 0.015],
          dir: [0, -1, 0.1],
          stretch: 4,
          color: mix("#dff4ff", "#ffffff", r()),
          opacity: 0.8,
          kind: "fall",
          params: [0.22, r()],
        };
      });
      // Streaks pouring down the surge's sheet once it is down (falling
      // streaks cannot morph).
      const streaks = k.part("streaks", { pivot: [0, TOP, LIP] });
      k.cloud({ share: 0.04, size: 0.95, pattern: false }, (r) => {
        const p = wfSurge(r(), r() * 0.94, 2 * r() - 1);
        return {
          p: [p[0], p[1], p[2] + 0.02],
          dir: [0, -1, 0.12],
          stretch: 5,
          color: mix("#e6f7ff", "#ffffff", r()),
          opacity: 0.85,
          kind: "fall",
          params: [0.28, r()],
          part: streaks,
        };
      });
      // The pool, with foam where the water lands and drifting mist.
      k.add(k.disc(0.75), {
        pos: [0, 0.04, 0.55],
        scale: [1.1, 1, 0.75],
        pattern: false,
        kind: "wave",
        params: [0.005, 0],
        color: (c) => {
          const d = Math.hypot(c.p[0], (c.p[2] - 0.5) * 1.6);
          if (d < 0.32 + 0.06 * c.noise(c.p[0] * 12, 0, c.p[2] * 12))
            return mix("#e8f6ff", "#ffffff", c.rand());
          return mix("#2a8ab8", "#15557a", clamp(d / 0.9, 0, 1));
        },
      });
      k.cloud({ share: 0.05, size: 2.8, pattern: false }, (r) => ({
        p: [(r() - 0.5) * 0.7, 0.08 + r() * 0.1, 0.45 + (r() - 0.5) * 0.25],
        color: "#f4fbff",
        opacity: 0.22,
        kind: "rise",
        params: [0.45 + 0.3 * r(), r()],
      }));
      // The surge's foam: built over the foam patch at the curtain's foot
      // and spread by its part's scale, coming and going in lacy patches
      // (channel 2, as the mist).
      const foot = [0, 0.05, 0.44];
      const foamPart = k.part("foam", { pivot: foot });
      k.cloud({ share: 0.02, size: 1.5, pattern: false }, (r) => {
        const a = r() * TAU;
        const rr = Math.sqrt(r());
        const x = Math.cos(a) * rr * 0.34;
        const z = 0.52 + Math.sin(a) * rr * 0.2;
        const lace = k.noise(x * 9, 3, z * 9);
        return {
          p: [x, 0.047 + 0.004 * r(), z],
          n: [0, 1, 0],
          flat: 0.2,
          color: mix("#e2f4fc", "#ffffff", r()),
          opacity: 0.85,
          kind: "fade",
          channel: 2,
          params: [clamp01(0.45 * rr + 0.35 * (0.5 + 0.5 * lace)), -0.12],
          part: foamPart,
        };
      });
      // A cloud of mist that billows up from the pool: built small at the
      // foot and grown by its part (channel 2 brings it in and out).
      const mist = k.part("mist", { pivot: [0, 0.06, 0.5] });
      // Faint, so the rocks and the pool show through it.
      k.cloud({ share: 0.012, size: 3.6, pattern: false }, (r) => {
        const d = randDir(r);
        const rr = Math.cbrt(r());
        const p = [d[0] * 0.2 * rr, 0.06 + Math.abs(d[1]) * 0.14 * rr, 0.52 + d[2] * 0.12 * rr];
        return {
          p,
          color: mix("#e4f2fa", "#ffffff", r()),
          opacity: 0.09 + 0.06 * rr,
          kind: "fade",
          channel: 2,
          params: [0.75 * r() * (0.4 + 0.6 * rr), -0.2],
          part: mist,
        };
      });
      // Mossy boulders around the pool.
      for (let i = 0; i < 9; i++) {
        const a = -0.4 + (i / 8) * (Math.PI + 0.8);
        const s = 0.08 + 0.08 * rand();
        k.add(k.ellipsoid(s * 1.3, s * 0.8, s), {
          pos: [Math.cos(a) * 0.85, 0.05, 0.55 + Math.sin(a) * 0.55],
          rot: [0, rand() * 180, 0],
          color: rock,
        });
      }
      k.add(k.box(2.0, 0.08, 1.7), {
        pos: [0, 0, 0.2],
        color: (c) =>
          c.s.face === 2 ? lit(mix("#4a6a2a", "#6a8a34", c.rand()), c.n, 0.3) : "#4a3a2a",
      });
    }

drive:
drive(t, c, out) {
      const s = since(c.surge, WF_SECS);
      if (s === null) {
        out.morph = [-0.3, 0, 0, 0];
        out.parts.surge = { visible: 0 };
        out.parts.streaks = { visible: 0 };
        out.parts.foam = {};
        out.parts.mist = {};
        return;
      }
      const calm = 1 - ease(band(s, 3.0, 4.4));
      const pool = band(s, 0.82, 1.5) * (1 - band(s, 3.2, 4.9));
      out.morph = [s / WF_FRONT, wfDown(s), pool, 0];
      out.glow = [0.8, 0.9, 0.95, 1.2 * (1 - band(s, 1.9, 2.3))];
      out.parts.surge = { visible: band(s, 0.26, 0.34) * calm };
      out.parts.streaks = { visible: ease(band(s, 0.62, 1.0)) * calm };
      const gone = band(s, 4.95, 5.15);
      out.parts.foam = { scale: 1 + 0.85 * easeOut(band(s, 0.82, 2.7)) * (1 - gone) };
      const billow = easeOut(band(s, 0.85, 4.6));
      out.parts.mist = {
        scale: 1 + 1.6 * billow * (1 - gone),
        offset: [0, 0.3 * billow * (1 - gone), 0.04 * billow * (1 - gone)],
        quat: quatAxisAngle([0, 1, 0], 0.5 * billow * (1 - gone)),
      };
    }

build:
build(k) {
      const water = (c, s, isBack) => {
        const hgt = clamp(c.p[1] / 0.95, 0, 1);
        const g = c.fbm(c.p[0] * 4, c.p[1] * 4, c.p[2] * 4);
        let tone = hgt * 0.95 + (isBack ? -0.25 : 0.05) + 0.1 * g;
        let col = ramp(["#062f58", "#0b4f82", "#1582a4", "#35b2c2", "#8ae0dc"], clamp(tone, 0, 1));
        const foamN = c.noise(c.p[0] * 12, c.p[1] * 12, c.p[2] * 5);
        if (!isBack && s > 0.62 && foamN > 0.35 - (s - 0.62) * 3)
          return keep(mix("#e4f6ff", "#ffffff", c.rand()));
        if (isBack && s < 0.14 && foamN > -0.1) return keep("#eef9ff");
        if (foamN > 0.5) col = mix(col, "#dff4ff", 0.55);
        return lit(col, c.n, 0.25);
      };
      // The sea and the wave thin out towards their ends, so they fade into
      // the water round them instead of stopping at a straight edge.
      const frayed = (c) => {
        const z = Math.abs(c.p[2]);
        const edge = Math.max(
          band(z, 0.6, OW_Z1),
          band(c.p[0], 1.02, 1.3),
          1 - band(c.p[0], -1.0, -0.72),
        );
        return c.rand() < edge * 0.92;
      };
      const on = (curve) => (u, v) => {
        const p = curve(u);
        return [p[0], p[1], owZ(v)];
      };
      // Each splat follows the two control points either side of it.
      const skin = (first, n) => (c) => {
        const x = clamp01(c.u) * (n - 1);
        const i = Math.min(n - 2, Math.floor(x));
        return [first + i, first + i + 1, x - i];
      };
      // The main sheet: the sea in front, the face, the crest, the back.
      k.add(k.param(on(OW_REST_M), { grid: 110 }), {
        flat: 0.42,
        size: 1.15,
        weight: 1.4,
        skin: skin(0, OW_NM),
        color: (c) =>
          frayed(c)
            ? null
            : c.u < OW_CREST
              ? water(c, (0.62 * c.u) / OW_CREST, false)
              : water(c, (c.u - OW_CREST) / (1 - OW_CREST), true),
      });
      // The lip (denser, since it stretches as it is thrown, and it fades
      // away by size while the wave is low).
      k.add(k.param(on(OW_REST_L), { grid: 64 }), {
        flat: 0.42,
        weight: 2.2,
        size: 1.3,
        skin: skin(OW_NM, OW_NL),
        color: (c) => {
          if (frayed(c)) return null;
          // White only towards its tip, where it breaks.
          const foamN = c.noise(c.p[0] * 12, c.p[1] * 12, c.p[2] * 5);
          if (foamN > 0.95 - 1.7 * c.u * c.u) return keep(mix("#e4f6ff", "#ffffff", c.rand()));
          return water(c, 0.5, false);
        },
      });
      // White water: a rolling wall of foam round the barrel as it
      // collapses, built at its fullest. It froths up out of the place the
      // lip plunged in and climbs over the roll as channel 0 rises, then
      // sinks away from the top as it falls again (a fade, so it never
      // shrinks to speckle), leaving the lace on the water. It rolls
      // forward a little as it goes.
      const OW_PLUNGE = [1.2, 0];
      const bore = k.part("bore", { pivot: [1.05, 0, 0] });
      k.cloud({ share: 0.07, size: 1.6, pattern: false }, (r) => {
        const z = owZ(r());
        // A lumpy half round, highest over the roll, lower to the front.
        const a = Math.PI * (0.02 + 0.96 * r());
        const lump = 0.5 + 0.5 * k.noise(Math.cos(a) * 3, Math.sin(a) * 3, z * 4);
        const rr = (0.2 + 0.08 * lump) * (1 - 0.35 * r() * r());
        const p = [1.0 + 0.1 * Math.cos(a) + Math.cos(a) * rr, Math.sin(a) * rr * 0.95, z];
        if (p[1] < 0.01) return null;
        // Thinner towards the wave's ends.
        const l = 0.5 + 0.5 * k.noise(p[0] * 14, p[1] * 14, z * 6);
        if (r() < band(Math.abs(z), 0.4, OW_Z1) * (1.2 - 0.4 * l)) return null;
        const d = Math.hypot(p[0] - OW_PLUNGE[0], p[1] - OW_PLUNGE[1]) / 0.5;
        return {
          p,
          n: unit([Math.cos(a), Math.sin(a), 0]),
          flat: 0.6,
          color: mix("#cfeaf5", "#ffffff", l),
          opacity: 0.9,
          kind: "fade",
          channel: 0,
          params: [clamp(0.04 + 0.35 * d + 0.45 * (p[1] / 0.3) + 0.1 * (1 - l), 0, 0.92), -0.08],
          part: bore,
        };
      });
      // Spray flying off the lip at rest (it goes while the wave breaks),
      // and foam churning at the foot of the face.
      const spray = k.part("spray", { pivot: [0.7, 0.7, 0] });
      k.cloud({ share: 0.04, size: 0.8, pattern: false }, (r) => {
        const p = OW_REST_L(0.3 + 0.65 * r());
        return {
          p: [p[0] + 0.02, p[1] + 0.02, owZ(0.05 + 0.9 * r())],
          color: "#ffffff",
          opacity: 0.8,
          kind: "rise",
          params: [0.2 + 0.2 * r(), r()],
          part: spray,
        };
      });
      const churn = k.part("churn", { pivot: [0.75, 0.03, 0] });
      k.cloud({ share: 0.03, size: 1.2, pattern: false }, (r) => {
        const v = r();
        const z = owZ(v);
        const x = 0.62 + 0.3 * r();
        // Lacy, thicker where the lip lands, thinning to the ends.
        const l = 0.5 + 0.5 * k.noise(x * 8, 0, z * 5);
        if (l < 0.45 + 0.4 * band(Math.abs(z), 0.4, OW_Z1)) return null;
        return {
          p: [x, 0.015 + 0.05 * r() * l, z],
          color: mix("#dff4ff", "#ffffff", r()),
          opacity: 0.75,
          kind: "twinkle",
          params: [0.3, r() * 6],
          part: churn,
        };
      });
      // The crash's foam: lace over the water, spreading out from where
      // the lip lands (ragged, thinning away from it and to the ends),
      // faded in and out on channel 2.
      const lace = (p) => 0.5 + 0.5 * k.noise(p[0] * 9, p[1] * 9, p[2] * 4);
      k.cloud({ share: 0.045, size: 1.5, pattern: false }, (r) => {
        const z = owZ(r());
        const reach = 0.28 + 0.14 * k.noise(3, 0, z * 3);
        const x = 1.12 + (r() * 2 - 1) * 0.5;
        const d = Math.abs(x - 1.12) / reach;
        const p = [x, 0.012, z];
        const l = lace(p);
        if (d > 1 || l < 0.25 + 0.5 * d * d + 0.5 * band(Math.abs(z), 0.55, OW_Z1)) return null;
        return {
          p,
          n: [0, 1, 0],
          flat: 0.2,
          color: mix("#d4eef8", "#ffffff", l),
          opacity: 0.9,
          kind: "fade",
          channel: 2,
          params: [clamp01(0.05 + 0.5 * d + 0.25 * (1 - l)), -0.12],
        };
      });
      // Clumps of spray, one per token, built where they are thrown from.
      OW_SPRAY.forEach((d, i) => {
        k.cloud({ count: 40, size: 0.9, pattern: false }, (r) => {
          const d0 = randDir(r);
          // Drawn out a little along its flight.
          const q = [d0[0] * 0.8, d0[1] * 1.5, d0[2] * 0.8];
          return {
            p: add(d.base, mul(q, 1.6 * d.size * Math.sqrt(r()))),
            color: mix("#d8f0fa", "#ffffff", r()),
            size: 0.6 + 0.8 * r(),
            opacity: 0.95,
            kind: "token",
            params: [OW_NM + OW_NL + i, 0],
          };
        });
      });
    }

drive:
drive(t, c, out) {
      const s = since(c.crash, OW_SECS);
      const pose = owPose(s === null ? 0 : Math.min(s, OW_KEYS[OW_KEYS.length - 1].at));
      const rest = OW_CTL[0];
      const ctl = pose.pts.map((p, i) => ({
        base: [rest[i][0], rest[i][1], 0],
        offset: [p[0] - rest[i][0], p[1] - rest[i][1], 0],
        visible: i < OW_NM ? 1 : pose.w,
      }));
      const spray = OW_SPRAY.map((d) => {
        const u = s === null ? -1 : s - d.at;
        if (u < 0 || u > d.dur) return { base: d.base, visible: 0 };
        const off = [d.vel[0] * u, d.vel[1] * u - 0.5 * OW_G * u * u, d.vel[2] * u];
        return {
          base: d.base,
          offset: off,
          quat: quatAxisAngle(d.axis, d.spin * u),
          visible: band(u, 0, 0.04) * (1 - band(u, d.dur - 0.1, d.dur)),
        };
      });
      out.tokens = [...ctl, ...spray];
      // The new swell rising, and its lip curling over (later sounds).
      cuesAt(
        mem(c),
        s,
        [
          [3.1, { voice: "wave", decay: 1.2, vol: 0.45 }],
          [4.5, { voice: "whoosh", f: 260, to: 2, decay: 0.5, vol: 0.4 }],
        ],
        out,
      );
      if (s === null) {
        out.morph = [0, 0, 0, 0];
        out.parts.bore = {};
        out.parts.spray = {};
        out.parts.churn = {};
        return;
      }
      // The white water froths up round the roll, then sinks into the
      // lace of foam spread over the water.
      const froth = easeOut(band(s, OW_HIT - 0.05, 1.45)) * (1 - ease(band(s, 1.55, 2.35)));
      const foam = band(s, OW_HIT, 1.7) * (1 - band(s, 2.9, 4.6));
      out.morph = [froth, 0, foam, 0];
      // It drifts forward, and goes home once it has sunk away.
      out.parts.bore = {
        offset: [0.07 * ease(band(s, OW_HIT, 2.2)) * (1 - band(s, 2.4, 2.6)), 0, 0],
      };
      // The spray off the lip goes as it is thrown and comes back once the
      // lip has curled over again, rising off it (the behaviours' amount
      // grows back from 0, so it starts on the lip).
      out.parts.spray = { visible: s < 0.3 ? 1 - ease(band(s, 0, 0.3)) : ease(band(s, 5.2, 5.7)) };
      out.parts.churn = { visible: 1 - band(s, 0.3, 0.8) + ease(band(s, 4.9, 5.6)) };
      out.amount = s < 0.4 ? 1 - band(s, 0, 0.4) : ease(band(s, 5.0, 5.7));
    }

build:
build(k) {
      // Terraced sinter mound with coloured mats around a blue pool.
      const mound = k.lathe(
        [
          [1.0, 0],
          [0.95, 0.04],
          [0.8, 0.06],
          [0.74, 0.1],
          [0.55, 0.12],
          [0.5, 0.16],
          [0.34, 0.18],
          [0.3, 0.19],
        ],
        { thick: 0.1 },
      );
      k.add(mound, {
        even: true,
        opacity: 1,
        jitter: 0.015,
        flat: 0.25,
        interior: 0.08,
        core: "#b8a890",
        color: (c) => {
          const r = Math.hypot(c.p[0], c.p[2]);
          const g = c.fbm(c.p[0] * 6, c.p[1] * 6, c.p[2] * 6);
          let col = ramp(
            ["#e8a030", "#d8702a", "#c8b8a0", "#e8e0d0", "#b8a890"],
            clamp((r - 0.3) / 0.7 + 0.1 * g, 0, 1),
          );
          if (c.n[1] < 0.7) col = shade(col, 0.8);
          return lit(col, c.n, 0.4);
        },
      });
      k.add(k.disc(0.3), {
        opacity: 1,
        jitter: 0.015,
        pos: [0, 0.185, 0],
        pattern: false,
        kind: "wave",
        params: [0.004, 0],
        color: (c) => {
          const r = Math.hypot(c.p[0], c.p[2]) / 0.3;
          return ramp(["#0a3a7a", "#1a6ab8", "#3ab0d8", "#8ad8d0", "#e8d070"], r);
        },
      });
      // The plume: water shooting up, steam billowing around it.
      k.cloud({ share: 0.18, size: 0.8, pattern: false }, (r) => {
        const a = r() * TAU;
        const rr = 0.05 * Math.sqrt(r());
        return {
          p: [Math.sin(a) * rr, 0.2, Math.cos(a) * rr],
          dir: [0, 1, 0],
          stretch: 2.5,
          color: mix("#cfeaf8", "#ffffff", r()),
          opacity: 0.85,
          kind: "rise",
          params: [1.6 + 1.2 * r(), r()],
        };
      });
      k.cloud({ share: 0.14, size: 3.4, pattern: false }, (r) => {
        const a = r() * TAU;
        const rr = 0.12 * Math.sqrt(r());
        return {
          p: [Math.sin(a) * rr, 0.25 + r() * 0.3, Math.cos(a) * rr],
          color: mix("#e8eef2", "#ffffff", r()),
          opacity: 0.2,
          kind: "rise",
          params: [1.2 + 1.0 * r(), r()],
        };
      });
      // Rocks around the rim.
      for (let i = 0; i < 8; i++) {
        const a = (i / 8) * TAU + k.rand() * 0.5;
        const s = 0.05 + 0.05 * k.rand();
        k.add(evenEllipsoid(k, s * 1.3, s * 0.7, s), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [Math.sin(a) * 0.85, 0.05, Math.cos(a) * 0.85],
          color: (c) => lit(mix("#8a8070", "#b8ac98", c.rand()), c.n, 0.4),
        });
      }
      k.reach([0, 1.5, 0]);
    }

drive:
drive(t, c, out) {
      // It bubbles on its own, with a big eruption on a slow cycle.
      const cycle = Math.max(0, Math.sin(t * 0.45)) ** 6;
      out.amount = 0.6 + 0.5 * cycle + 1.2 * c.erupt;
    }

build:
build(k, o) {
      const W = 1.2;
      const H = 0.6;
      const D = 0.74;
      const top = H / 2 - 0.2;
      const wood = o.wood;
      const gold = "#d4a63c";
      const planks = (c) => {
        const band = Math.abs((((c.p[1] + 1) * 7.5) % 1) - 0.5) > 0.46;
        const grain = c.fbm(c.p[0] * 3, c.p[1] * 30, c.p[2] * 3);
        return shade(mix(wood, shade(wood, 0.6), 0.5 + 0.5 * grain), band ? 0.55 : 1);
      };
      // The body: an open-topped box (the top face is left out).
      k.add(k.box(W, H, D), {
        pos: [0, -0.2, 0],
        flat: 0.2,
        color: (c) => (c.s.face === 2 ? null : planks(c)),
      });
      // Metal bands and corners.
      for (const x of [-0.36, 0.36]) {
        k.add(k.box(0.08, H + 0.02, D + 0.02), {
          pos: [x, -0.2, 0],
          flat: 0.2,
          weight: 1.5,
          color: (c) =>
            c.s.face === 2
              ? null
              : mix(gold, "#8a6a1f", 0.3 + 0.3 * c.fbm(c.p[0] * 20, c.p[1] * 20, 0)),
        });
      }
      // The lid: a half cylinder along X, hinged at the back edge.
      const lid = k.part("lid", { pivot: [0, top, -D / 2], axis: [1, 0, 0] });
      const R = D / 2;
      const arc = k.param(
        (u, v) => {
          const a = v * Math.PI;
          return [(u - 0.5) * W, top + Math.sin(a) * R * 0.75, Math.cos(a) * R];
        },
        { grid: 48, flip: true },
      );
      k.add(arc, { part: lid, flat: 0.2, color: planks });
      for (const x of [-0.36, 0.36]) {
        const strap = k.param(
          (u, v) => {
            const a = v * Math.PI;
            const rr = R + 0.012;
            return [x + (u - 0.5) * 0.08, top + Math.sin(a) * rr * 0.75, Math.cos(a) * rr];
          },
          { grid: 24, flip: true },
        );
        k.add(strap, { part: lid, flat: 0.2, weight: 1.5, color: gold });
      }
      for (const side of [-1, 1]) {
        const end = k.param(
          (u, v) => {
            const a = u * Math.PI;
            return [(side * W) / 2, top + Math.sin(a) * R * 0.75 * v, Math.cos(a) * R * v];
          },
          { grid: 24 },
        );
        k.add(end, { part: lid, flat: 0.2, color: planks });
      }
      // The lid's flat underside, so the open lid is not hollow.
      k.add(k.box(W, 0.01, D), {
        pos: [0, top + 0.005, 0],
        part: lid,
        flat: 0.2,
        color: shade(wood, 0.7),
      });
      // The lock plate on the front of the lid.
      k.add(k.box(0.16, 0.2, 0.03), {
        pos: [0, top - 0.02, D / 2 + 0.01],
        part: lid,
        flat: 0.2,
        weight: 2,
        color: gold,
      });
      k.add(k.box(0.12, 0.08, 0.03), {
        pos: [0, top - 0.16, D / 2 + 0.01],
        flat: 0.2,
        weight: 2,
        color: shade(gold, 0.85),
      });
      // Treasure heaped inside: coins that glint and gems that sparkle when open.
      k.cloud({ share: 0.1, size: 0.9, flat: 0.15 }, (rand) => {
        const x = (rand() - 0.5) * (W - 0.12);
        const z = (rand() - 0.5) * (D - 0.1);
        const heap = 0.08 * (1 - (x / (W / 2)) ** 2) * (1 - (z / (D / 2)) ** 2);
        const tilt = [(rand() - 0.5) * 0.8, 1, (rand() - 0.5) * 0.8];
        return {
          p: [x, top - 0.05 + heap * (0.3 + 0.7 * rand()), z],
          n: tilt,
          color: mix("#f2c94c", "#b8860b", rand() * 0.5),
          pattern: false,
          kind: "glint",
          params: [0.7, 0],
        };
      });
      const gems = ["#e0115f", "#2ecc71", "#3a7bd5", "#9b59b6", "#f1c40f"];
      for (let i = 0; i < 9; i++) {
        const x = (k.rand() - 0.5) * (W - 0.3);
        const z = (k.rand() - 0.5) * (D - 0.25);
        const s = 0.035 + k.rand() * 0.03;
        k.add(k.ellipsoid(s, s * 0.8, s), {
          pos: [x, top + 0.03, z],
          weight: 3,
          flat: 0.3,
          pattern: false,
          kind: "twinkle",
          params: [0.9, k.rand() * 6],
          color: (c) => mix(gems[i % gems.length], "#ffffff", 0.35 * smoothstep(0.3, 1, c.n[1])),
        });
      }
      // Room for the open lid.
      k.reach([0, top + D * 0.95, -D / 2 - 0.1]);
    }

drive:
drive(t, c, out) {
      const o = easeInOut(c.open);
      out.parts.lid = { angle: -1.95 * o };
      out.amount = o;
    }

build:
build(k, o) {
      const { W, H, ct, leaves, lt, T } = BOOK;
      const cover = o.color;
      const gold = "#d9b45a";
      const paper = "#f6efdf";
      const endpaper = mix(cover, "#f3e6cf", 0.72);
      const pivot = [0, T / 2, 0];
      const coverPart = k.part("cover", { pivot, axis: [0, 0, 1] });
      const spinePart = k.part("spine", { pivot, axis: [0, 0, 1] });
      // Book cloth: a fine, even weave (lit, no random speckle).
      const cloth = (c) => {
        const weave = 0.985 + 0.02 * Math.sin(c.p[0] * 260) * Math.sin(c.p[2] * 260);
        return lit(shade(cover, weave), c.n, { amb: 0.66, dif: 0.42, spec: 0.12 });
      };
      // The page block's edge: soft cream with faint, even page lines (at a
      // spacing splats can show, so they read as paper, not noise).
      const pageEdge = (y) => shade(paper, 0.86 + 0.05 * Math.sin(y * 260));
      // Words on a page. x is measured from the spine, z across the page
      // (the top of the page is at -z). A page that faces down while the
      // book is closed reads the right way once its leaf has turned over, so
      // its lines run from the outer edge towards the spine.
      const PX = 0.0082; // one font pixel
      const margin = 0.1;
      const perLine = Math.floor((W - 2 * margin) / (6 * PX));
      const pages = new Map();
      const pageText = (seed, picture) => {
        const key = `${seed}${picture}`;
        if (!pages.has(key)) {
          const rows = Math.floor((H - 2 * 0.12) / (10 * PX));
          const skip = picture ? Math.ceil((H / 2 - 0.12 + 0.03) / (10 * PX)) : 0;
          pages.set(key, { lines: storyLines(perLine, seed * 23, rows - skip), skip });
        }
        return pages.get(key);
      };
      const text = (x, z, seed, flipped, picture) => {
        const ax = Math.abs(x);
        const s = (flipped ? W - margin - ax : ax - margin) / PX;
        const page = pageText(seed, picture);
        const t = (z + H / 2 - 0.12) / PX - page.skip * 10;
        return inked(page.lines, s, t);
      };
      const ink = "#2f2a26";
      const pageCol = (c, x, z, seed, picture = false, flipped = false) => {
        if (
          picture &&
          Math.abs(x) > 0.18 &&
          Math.abs(x) < W - 0.14 &&
          z > -H / 2 + 0.16 &&
          z < -0.02
        ) {
          // A little picture: sun, sky and hills.
          const u = (Math.abs(x) - 0.18) / (W - 0.32);
          const v = (z + H / 2 - 0.16) / (H / 2 - 0.18);
          const hill = 0.62 + 0.12 * Math.sin(u * 7) + 0.06 * Math.sin(u * 15 + 1);
          let col = mix("#7fc8f8", "#fef3c7", v);
          if (Math.hypot(u - 0.72, v - 0.3) < 0.12) col = "#ffb627";
          if (v > hill) col = mix("#5aa469", "#2f7a4a", (v - hill) * 3);
          const edge = Math.min(u, 1 - u, v, 1 - v);
          return keep(edge < 0.02 ? "#5b4a3a" : col);
        }
        if (text(x, z, seed, flipped, picture)) return keep(ink, 0.8);
        // A turned page is lit as it lies once turned over.
        const n = flipped ? [-c.n[0], -c.n[1], c.n[2]] : c.n;
        return lit(shade(paper, 0.985 + 0.015 * c.noise(x * 12, z * 12, seed)), n, {
          amb: 0.8,
          dif: 0.25,
          spec: 0,
        });
      };
      // Back cover, spine and front cover.
      k.add(roundBox(W, ct, H, 0.012), {
        pos: [W / 2, ct / 2, 0],
        flat: 0.15,
        weight: 1.6,
        even: true,
        jitter: 0.01,
        size: 0.8,
        color: (c) => (c.s.face === 2 ? lit(endpaper, c.n, { spec: 0 }) : cloth(c)),
      });
      k.add(
        k.param(
          (u, v) => {
            const a = Math.PI / 2 + u * Math.PI;
            return [Math.cos(a) * 0.07, T / 2 + Math.sin(a) * (T / 2), (v - 0.5) * H];
          },
          { grid: 32 },
        ),
        {
          part: spinePart,
          flat: 0.15,
          weight: 2,
          even: true,
          jitter: 0.01,
          size: 0.8,
          color: (c) => {
            const z = Math.abs(c.p[2]);
            if (Math.abs(z - H * 0.38) < 0.015 || Math.abs(z - H * 0.3) < 0.01) return keep(gold);
            return cloth(c);
          },
        },
      );
      // The front cover: its cloth face is a part of its own that hides once
      // the cover lies open (splats keep the order of the closed book).
      k.add(roundBox(W, ct, H, 0.012, { top: false, bottom: false }), {
        pos: [W / 2, T - ct / 2, 0],
        part: coverPart,
        flat: 0.15,
        weight: 1.6,
        even: true,
        jitter: 0.01,
        size: 0.8,
        color: cloth,
      });
      // The cover's inside, its own part so it can hide under the turned pages.
      const coverIn = k.part("coverIn", { pivot, axis: [0, 0, 1] });
      k.add(quad(W - 0.024, H - 0.024, -1), {
        pos: [W / 2, T - ct, 0],
        part: coverIn,
        flat: 0.15,
        color: (c) => lit(endpaper, c.n, { spec: 0 }),
      });
      const coverTop = k.part("coverTop", { pivot, axis: [0, 0, 1] });
      k.add(quad(W - 0.024, H - 0.024), {
        pos: [W / 2, T, 0],
        part: coverTop,
        flat: 0.15,
        weight: 5,
        even: true,
        jitter: 0.01,
        size: 0.8,
        color: (c) => {
          // Gold border, title bands and an emblem on the front.
          const x = c.p[0] - W / 2;
          const z = c.p[2];
          const bx = W / 2 - 0.07 - Math.abs(x);
          const bz = H / 2 - 0.07 - Math.abs(z);
          if (Math.abs(Math.min(bx, bz)) < 0.008) return keep(lit(gold, c.n, { spec: 0.5 }));
          const r = Math.hypot(x, z - 0.12);
          if (Math.abs(r - 0.16) < 0.012 || r < 0.05) return keep(lit(gold, c.n, { spec: 0.5 }));
          if (
            Math.abs(x) < 0.26 &&
            (Math.abs(z + 0.25) < 0.02 || (Math.abs(z + 0.33) < 0.012 && Math.abs(x) < 0.17))
          )
            return keep(lit(gold, c.n, { spec: 0.5 }));
          return cloth(c);
        },
      });
      // The pages that stay on the right, with a picture on top. The two
      // pages seen when the book lies open (this one and the underside of the
      // last leaf) get most of the splats, so their words stay sharp; hidden
      // page faces get few.
      const PW = W - 0.035;
      const PH = H - 0.05;
      const block = BOOK.pb - leaves * lt;
      const sides = (face) => (face === 2 || face === 3 ? null : keep(shade(paper, 0.84)));
      k.add(evenBox(PW, block, PH), {
        pos: [PW / 2 + 0.005, ct + block / 2, 0],
        flat: 0.15,
        weight: 1.8,
        even: true,
        jitter: 0,
        size: 1.1,
        color: (c) => {
          if (c.s.face === 2 || c.s.face === 3) return null;
          if (c.s.face === 1) return shade(paper, 0.8);
          return keep(pageEdge(c.p[1]));
        },
      });
      k.add(quad(PW, PH), {
        pos: [PW / 2 + 0.005, ct + block, 0],
        flat: 0.15,
        weight: 6,
        even: true,
        jitter: 0.01,
        size: 1.25,
        color: (c) => pageCol(c, c.p[0], c.p[2], 3, true),
      });
      // Leaves that flip one after another.
      for (let i = 0; i < leaves; i++) {
        const part = k.part("leaf" + i, { pivot, axis: [0, 0, 1] });
        const y = T - ct - (i + 0.5) * lt;
        const pos = [PW / 2 + 0.005, y, 0];
        k.add(evenBox(PW, lt * 0.8, PH), {
          pos,
          part,
          flat: 0.15,
          weight: 0.25,
          even: true,
          jitter: 0,
          size: 0.6,
          color: (c) => sides(c.s.face),
        });
        for (const up of [1, -1]) {
          const last = i === leaves - 1;
          // The last leaf's upper face would draw over its turned-up
          // underside, so it is left out (it only shows mid-turn).
          if (last && up > 0) continue;
          const shown = up < 0 && last;
          k.add(quad(PW, PH, up), {
            pos: [pos[0], y + up * lt * 0.4, 0],
            part,
            flat: 0.15,
            weight: shown ? 6 : 0.35,
            even: true,
            jitter: 0.01,
            size: 1.25,
            color: (c) => pageCol(c, c.p[0], c.p[2], i * 2 + (up < 0 ? 1 : 0), false, up < 0),
          });
        }
      }
      // The left pile's edges, shown once the leaves under the top one hide.
      const pileH = (leaves - 1) * lt;
      k.add(evenBox(PW, pileH, PH), {
        pos: [-PW / 2 - 0.005, ct + pileH / 2, 0],
        part: k.part("pile"),
        flat: 0.15,
        weight: 1,
        even: true,
        jitter: 0,
        size: 1.1,
        color: (c) => {
          if (c.s.face === 2 || c.s.face === 3) return null;
          return keep(pageEdge(c.p[1]));
        },
      });
      k.reach([-W, 0, H / 2]);
      k.reach([-W, 0, -H / 2]);
    }

drive:
drive(t, c, out) {
      const o = c.open;
      const lift = [0, 0, 0, 0, 0, 0, 0, 0.012, 0.03, 0.06];
      const cover = Math.PI * ease3(window01(o, 0, 0.42));
      out.parts.cover = { angle: cover };
      out.parts.coverTop = { angle: cover, visible: 1 - smoothstep(0.3, 0.4, o) };
      out.parts.spine = {
        angle: (Math.PI / 2) * ease3(window01(o, 0, 0.42)),
        visible: 1 - smoothstep(0.3, 0.4, o),
      };
      // Splats keep the draw order of the closed book, where the front cover
      // and the first leaves lie above the last leaf. Once a leaf has landed
      // on the left, the one it covers (and the cover's inside, under them
      // all) hides, so the page on top reads cleanly.
      const turned = (i) => ease3(window01(o, 0.1 + i * 0.05, 0.5 + i * 0.05));
      const landed = (i) => (i < BOOK.leaves ? smoothstep(0.9, 1, turned(i)) : 0);
      out.parts.coverIn = { angle: cover, visible: 1 - landed(0) };
      // Stands in for the hidden leaves at the left pile's edges.
      out.parts.pile = { visible: landed(1) };
      for (let i = 0; i < BOOK.leaves; i++) {
        out.parts["leaf" + i] = {
          angle: (Math.PI - lift[i]) * turned(i),
          visible: 1 - landed(i + 1),
        };
      }
    }

build:
build(k, o) {
      const alu = o.color;
      const { W, D, hb, hl } = LAPTOP;
      // Bead-blasted aluminium: smooth, lit, a faint soft grain (no speckle).
      const metal = (c) => {
        const grain = 0.985 + 0.02 * c.noise(c.p[0] * 20, c.p[1] * 20, c.p[2] * 20);
        return lit(shade(alu, grain), c.n, { amb: 0.66, dif: 0.4, spec: 0.35, pow: 20 });
      };
      const shell = { flat: 0.15, even: true, size: 1.1, jitter: 0.006 };
      // Base; the deck with the keys is its own part so it can hide under
      // the closed lid (splats are ordered by their modelled positions).
      // Thin sides get small, dense splats so the edges stay crisp.
      k.add(roundBox(W, hb, D, 0.02, { bottom: false, top: false }), {
        ...shell,
        even: false,
        size: 1.4,
        weight: 3,
        opacity: 1,
        pos: [0, hb / 2, 0],
        color: metal,
      });
      const deck = k.part("deck", { pivot: [0, hb, 0] });
      k.add(quad(W - 0.04, D - 0.04), {
        ...shell,
        pos: [0, hb, 0],
        part: deck,
        weight: 1.3,
        color: (c) => {
          const [x, , z] = c.p;
          // Under a key there is nothing (the key covers it); round the keys,
          // the dark well they sit in.
          for (const key of LAPTOP_KEYS) {
            if (Math.abs(x - key.x) < key.w / 2 - 0.004 && Math.abs(z - key.z) < key.d / 2 - 0.004) return null; // prettier-ignore
          }
          if (Math.abs(x) < 0.66 && z > -0.41 && z < 0.08) return keep(lit("#50555d", c.n, { spec: 0.05 }), 0.8); // prettier-ignore
          if (onPad(c.p)) {
            const e = Math.min(PAD.w / 2 - Math.abs(x - PAD.x), PAD.d / 2 - Math.abs(z - PAD.z));
            return keep(e < 0.006 ? shade(metal(c), 0.8) : lit(shade(alu, 1.03), c.n, { amb: 0.7, spec: 0.15 }), 1.1); // prettier-ignore
          }
          return metal(c);
        },
      });
      // Key caps: dark and raised. Each one goes down when pressed
      // (behaviour "key").
      const legendDots = [];
      LAPTOP_KEYS.forEach((key, i) => {
        const legend = key.label;
        k.add(k.box(key.w, 0.012, key.d), {
          pos: [key.x, hb + 0.006, key.z],
          part: deck,
          kind: "key",
          params: [i, 0],
          flat: 0.15,
          even: true,
          weight: 3.2,
          size: 0.8,
          jitter: 0,
          pattern: false,
          color: (c) => {
            if (c.n[1] < -0.5) return null;
            const cap = "#2a2d33";
            if (c.n[1] > 0.5) return keep(lit(cap, c.n, { amb: 0.9, dif: 0.25, spec: 0.12 }), 0.9); // prettier-ignore
            return keep(lit(shade(cap, 0.8), c.n, { amb: 0.9, dif: 0.25, spec: 0 }));
          },
        });
        // Its letters' pixels (5 x 7 font), each filled by a 3 x 3 grid of
        // dots, just above the cap.
        if (!legend) return;
        const gp = Math.min(0.006, (0.78 * key.w) / (6 * legend.length - 1));
        const gw = (6 * legend.length - 1) * gp;
        for (let t = 0; t < 7; t++) {
          for (let s = 0; s < 6 * legend.length; s++) {
            if (!inked([legend], s + 0.5, t + 0.5)) continue;
            for (let a = 0; a < 3; a++) {
              for (let b = 0; b < 3; b++) {
                legendDots.push({
                  key: i,
                  x: key.x - gw / 2 + (s + (a + 0.5) / 3) * gp,
                  z: key.z - 3.5 * gp + (t + (b + 0.5) / 3) * gp,
                });
              }
            }
          }
        }
      });
      // The letters: sharp because every dot sits on its pixel (random
      // splats on the caps made them blurry). A dot is about a third of a
      // font pixel across (0.0022 / the laptop's base splat size, which
      // goes as 1 / sqrt(budget)); on a small budget there are fewer dots
      // (the list is sampled) and they are bigger.
      const dotSize = 0.0022 / (0.0056 * Math.sqrt(200000 / k.count));
      k.cloud({ count: legendDots.length, pattern: false, part: deck }, (rand, j, n) => {
        const dot = legendDots[Math.floor((j * legendDots.length) / n)];
        return {
          p: [dot.x, hb + 0.0126, dot.z],
          n: [0, 1, 0],
          flat: 0.2,
          color: "#eef1f5",
          opacity: 1,
          size: dotSize * Math.sqrt(Math.max(1, legendDots.length / n)),
          kind: "key",
          params: [dot.key, 0],
        };
      });
      // The lid, hinged along the back edge and modelled standing open.
      const pivot = [0, hb + hl / 2, -D / 2 + 0.01];
      const q = quatAxisAngle([1, 0, 0], -LAPTOP.open);
      const place = (p) => add(pivot, quatRotate(q, sub(p, pivot)));
      const lid = k.part("lid", { pivot, axis: [1, 0, 0] });
      const bezel = k.part("bezel", { pivot, axis: [1, 0, 0] });
      const screen = k.part("screen", { pivot, axis: [1, 0, 0] });
      const lidY = hb + hl / 2 + 0.002;
      k.add(roundBox(W, hl, D, 0.012, { bottom: false }), {
        ...shell,
        even: false,
        size: 1.3,
        weight: 1.6,
        opacity: 1,
        pos: place([0, lidY, 0]),
        quat: q,
        part: lid,
        color: metal,
      });
      const SW = W - 0.14;
      const SD = D - 0.16;
      // The black bezel only round the screen: under the screen there is
      // nothing, so the two never sort through each other (that was the
      // speckle on the old screen).
      k.add(quad(W - 0.03, D - 0.03, -1), {
        pos: place([0, lidY - hl / 2 - 0.001, 0]),
        quat: q,
        part: bezel,
        flat: 0.12,
        even: true,
        size: 1.1,
        jitter: 0,
        pattern: false,
        color: (c) => {
          const [x, , z] = c.lp;
          if (Math.abs(x) < SW / 2 - 0.004 && Math.abs(z - 0.005) < SD / 2 - 0.004) return null;
          if (Math.hypot(x, z - (D - 0.03) / 2 + 0.035) < 0.01) return keep("#3a4250");
          // Smaller splats at the outer edge, so the bezel stops at the case.
          const inner = Math.max(Math.abs(x) - SW / 2, Math.abs(z - 0.005) - SD / 2);
          const edge = Math.min(
            (W - 0.03) / 2 - Math.abs(x),
            (D - 0.03) / 2 - Math.abs(z),
            inner + 0.004,
          );
          const col = mix("#0b0e13", "#1a1f27", 0.5 + 0.4 * (z / D));
          return keep(col, 0.35 + 0.65 * clamp(edge / 0.03, 0, 1));
        },
      });
      // The screen: every splat shows the live picture (behaviour "screen").
      k.add(quad(SW, SD, -1), {
        pos: place([0, lidY - hl / 2 - 0.002, 0.005]),
        quat: q,
        part: screen,
        kind: "screen",
        params: (c) => [c.u, 1 - c.v],
        flat: 0.08,
        even: true,
        weight: 7,
        size: 1.05,
        jitter: 0,
        pattern: false,
        color: () => keep("#202838"),
      });
    }

drive:
drive(t, c, out, info) {
      const st = LAPTOP_STATE;
      st.open = c.open > 0.9;
      // Modelled open; closing turns the lid back down onto the keys.
      const a = LAPTOP.open * (1 - ease3(c.open));
      out.parts.lid = { angle: a };
      out.parts.bezel = { angle: a, visible: smoothstep(0.02, 0.3, c.open) };
      out.parts.screen = { angle: a, visible: smoothstep(0.72, 1, c.open) };
      out.parts.deck = { visible: smoothstep(0.02, 0.2, c.open) };
      for (const ev of st.queue.splice(0)) {
        if (ev.pick !== undefined) {
          const k = LAPTOP_KEYS[ev.pick];
          typeInto(st, k, ev.typed);
          st.pressKey = ev.pick;
          st.pressAt = info.time;
          out.cues.push(k.id === "SPACE" ? { voice: "keytap", f: 1500, vol: 0.9 } : { voice: "keytap", f: 2200 + 60 * (ev.pick % 7) }); // prettier-ignore
        } else if (ev.pad) {
          // A tap on the trackpad: the pointer jumps to the matching spot
          // and clicks there.
          st.target = padUV(ev.pad);
          st.clickAt = info.time + 0.2;
          out.cues.push({ voice: "click", f: 900, decay: 1.5, vol: 0.8 });
        }
      }
      // The pointer glides to its target.
      const k = 1 - Math.exp(-(info.time - (st.lastTime ?? info.time)) * 14);
      st.lastTime = info.time;
      st.pointer = [st.pointer[0] + (st.target[0] - st.pointer[0]) * k, st.pointer[1] + (st.target[1] - st.pointer[1]) * k]; // prettier-ignore
      const since = info.time - st.pressAt;
      if (since >= 0 && since < 0.2) out.press = st.pressKey + 0.999 * Math.sin((Math.PI * since) / 0.2); // prettier-ignore
    }

build:
build(k, o) {
      const wood = o.wood;
      const gold = "#d8b25a";
      const velvet = "#9e1b32";
      const W = 1.1;
      const H = 0.5;
      const D = 0.76;
      const top = H;
      const grain = (c) => {
        const g = c.fbm(c.p[0] * 3, c.p[1] * 26, c.p[2] * 3);
        return lit(mix(wood, shade(wood, 0.62), 0.5 + 0.45 * g), c.n, {
          amb: 0.66,
          dif: 0.42,
          spec: 0.35,
        });
      };
      k.add(roundBox(W, H, D, 0.03, { top: false, bottom: false, even2d: true }), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [0, H / 2, 0],
        flat: 0.15,
        color: (c) => {
          if (Math.abs(c.p[1] - 0.12) < 0.012 || Math.abs(c.p[1] - (H - 0.05)) < 0.01)
            return keep(lit(gold, c.n, { spec: 0.5 }));
          return grain(c);
        },
      });
      // Velvet lining and the floor the dancer stands on.
      k.add(evenBox(W - 0.07, H - 0.06, D - 0.07), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [0, H / 2 + 0.03, 0],
        flat: 0.3,
        color: (c) => (c.s.face === 2 ? null : shade(velvet, 0.7 + 0.25 * c.rand())),
      });
      // The lid with a mirror inside, hinged at the back. Its top is a part
      // of its own that hides while the lid stands open, so the mirror shows
      // (splats keep the order of the closed box).
      const lid = k.part("lid", { pivot: [0, top, -D / 2], axis: [1, 0, 0] });
      const lidTop = k.part("lidTop", { pivot: [0, top, -D / 2], axis: [1, 0, 0] });
      k.add(roundBox(W, 0.1, D, 0.03, { top: false, even2d: true }), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [0, top + 0.05, 0],
        part: lid,
        flat: 0.15,
        color: (c) => {
          const [x, , z] = c.p;
          if (c.s.face === 3) {
            const inM = Math.abs(x) < W / 2 - 0.1 && Math.abs(z) < D / 2 - 0.1;
            if (inM) return keep(mix("#c9d3de", "#f4f7fb", 0.5 + 0.5 * Math.sin((x - z) * 5)));
            return shade(velvet, 0.8);
          }
          return grain(c);
        },
      });
      k.add(quad(W - 0.06, D - 0.06), {
        opacity: 1,
        jitter: 0.015,
        pos: [0, top + 0.1, 0],
        part: lidTop,
        flat: 0.15,
        color: (c) => {
          const [x, , z] = c.p;
          const r = Math.hypot(x, z);
          if (
            Math.abs(r - 0.2) < 0.012 ||
            Math.abs(Math.max(Math.abs(x) / (W / 2 - 0.08), Math.abs(z) / (D / 2 - 0.08)) - 1) <
              0.02
          )
            return keep(lit(gold, c.n, { spec: 0.5 }));
          return grain(c);
        },
      });
      // The dancer on her turntable (she rises as the lid opens).
      const base = 0.06;
      const dancer = k.part("dancer", { pivot: [0, base, 0.02] });
      const skin = "#f3cfb3";
      const pink = "#ff8fb8";
      const d = (shape, opts) =>
        k.add(shape, {
          opacity: 1,
          jitter: 0.015,
          part: dancer,
          flat: 0.25,
          weight: 2.2,
          pattern: false,
          ...opts,
        });
      d(k.cylinder(0.12, 0.02), {
        pos: [0, top - 0.05, 0.02],
        color: (c) => lit(gold, c.n, { spec: 0.5 }),
      });
      for (const s of [-1, 1])
        d(k.cylinder(0.011, 0.2, { caps: false }), {
          pos: [s * 0.015, top + 0.06, 0.02],
          rot: [0, 0, s * 4],
          color: (c) => lit(skin, c.n),
        });
      d(k.cone(0.13, 0.02, 0.06), {
        pos: [0, top + 0.17, 0.02],
        color: (c) =>
          lit(mix(pink, "#ffffff", 0.3 * ((c.u * 18) % 1 < 0.5)), c.n, { amb: 0.75, dif: 0.35 }),
      });
      d(k.ellipsoid(0.035, 0.06, 0.03), {
        pos: [0, top + 0.23, 0.02],
        color: (c) => lit(pink, c.n),
      });
      d(k.sphere(0.033), { pos: [0, top + 0.315, 0.02], color: (c) => lit(skin, c.n) });
      d(k.sphere(0.018), { pos: [0, top + 0.35, 0.005], color: (c) => lit("#4a2c1d", c.n) });
      d(
        k.tube(
          (tt) => {
            const a = Math.PI * (0.1 + 0.8 * tt);
            return [Math.cos(a) * 0.07, top + 0.26 + Math.sin(a) * 0.13, 0.02];
          },
          0.008,
          { samples: 48, grid: 24 },
        ),
        { color: (c) => lit(skin, c.n) },
      );
      // The crank on the side.
      const crank = k.part("crank", { pivot: [W / 2 + 0.03, H / 2, 0], axis: [1, 0, 0] });
      k.add(evenCylinder(0.02, 0.02, 0.06), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [W / 2 + 0.03, H / 2, 0],
        rot: [0, 0, 90],
        part: crank,
        weight: 2,
        color: (c) => lit(gold, c.n, { spec: 0.5 }),
      });
      k.add(evenCylinder(0.015, 0.015, 0.14), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [W / 2 + 0.06, H / 2 + 0.06, 0],
        part: crank,
        weight: 2,
        color: (c) => lit(gold, c.n, { spec: 0.5 }),
      });
      k.add(k.sphere(0.03), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [W / 2 + 0.06, H / 2 + 0.13, 0],
        part: crank,
        weight: 2,
        color: (c) => lit("#f4efe6", c.n),
      });
      // Musical notes that float up while it plays.
      NOTE_PATHS.forEach((n, i) => {
        const part = k.part("note" + i, { pivot: [n.x, top + 0.2, n.z] });
        const col = ["#f2c14e", "#ff8fb8", "#8ecae6"][i];
        const at = [n.x, top + 0.25, n.z];
        k.add(evenEllipsoid(k, 0.04, 0.03, 0.02), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: at,
          rot: [0, 0, 25],
          part,
          weight: 3,
          pattern: false,
          color: (c) => keep(lit(col, c.n, { spec: 0.5 })),
        });
        k.add(evenCylinder(0.008, 0.008, 0.14, false), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [at[0] + 0.035, at[1] + 0.07, at[2]],
          part,
          weight: 3,
          pattern: false,
          color: col,
        });
        k.add(evenEllipsoid(k, 0.035, 0.012, 0.01), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [at[0] + 0.06, at[1] + 0.125, at[2]],
          rot: [0, 0, -30],
          part,
          weight: 3,
          pattern: false,
          color: col,
        });
      });
      k.reach([0, top + 1.0, 0]);
    }

