build:
build(k, o) {
      const R = 1;
      const rock = (d) =>
        R *
        (1 + 0.07 * k.noise.fbm(d[0] * 2 + 7, d[1] * 2, d[2] * 2, 3)) *
        (d[1] < -0.6 ? 0.96 : 1);
      const cav = (phi) => 0.62 + 0.06 * k.noise(Math.cos(phi) * 2, Math.sin(phi) * 2, 3);
      const hinge = [-R * 1.02, 0, 0];
      const lidShut = k.part("lidShut", { pivot: hinge, axis: [0, 1, 0] });
      const lidOpen = k.part("lidOpen", { pivot: hinge, axis: [0, 1, 0] });
      // The violet light that fills the two halves as it opens.
      const glowParts = [k.part("glow"), k.part("glowLid", { pivot: hinge, axis: [0, 1, 0] })];
      const openQ = quatAxisAngle([0, 1, 0], -GEODE_SWING);
      const purple = o.color;
      const halves = [
        { side: -1, part: 0, open: false, crystals: true },
        { side: 1, part: lidShut, open: false, crystals: false },
        { side: 1, part: lidOpen, open: true, crystals: true },
      ];
      for (const half of halves) {
        const { side, part } = half;
        const inPart = part;
        // The open copy of the front half is turned to its open place.
        const T = (p) => (half.open ? add(hinge, quatRotate(openQ, sub(p, hinge))) : p);
        const TV = (v) => (half.open ? quatRotate(openQ, v) : v);
        // The rough outside: a half shell.
        const shell = k.param(
          (u, v) => {
            const phi = u * TAU;
            const th = v * (Math.PI / 2);
            const d = [
              Math.sin(th) * Math.cos(phi),
              Math.sin(th) * Math.sin(phi),
              side * Math.cos(th),
            ];
            return T(mul(d, rock(d)));
          },
          { grid: 64, thick: 0.35, flip: side > 0 },
        );
        k.add(shell, {
          part,
          flat: 0.2,
          // (Only the back half is solid: the front one closes over it.)
          interior: side > 0 ? 0 : 0.1,
          core: "#cfd3dc",
          color: (c) => rockColor(c),
        });
        // The cut face: bands of agate round the cavity.
        const ring = k.param(
          (u, v) => {
            const phi = u * TAU;
            const d = [Math.cos(phi), Math.sin(phi), 0];
            const r0 = cav(phi);
            const r1 = rock(d) * 0.995;
            const r = r0 + (r1 - r0) * v;
            return T([r * Math.cos(phi), r * Math.sin(phi), side * 0.001]);
          },
          { grid: 64, thick: 0.02, flip: side < 0 },
        );
        k.add(ring, {
          part: inPart,
          flat: 0.15,
          color: (c) => {
            const v = c.v;
            const wob = 0.04 * c.noise(c.p[0] * 6, c.p[1] * 6, 1);
            const x = v + wob;
            let col;
            if (x > 0.9) col = "#6b6259";
            else if (x > 0.72) col = mix("#f4f1ec", "#d8d2ca", c.rand() * 0.4);
            else if (x > 0.55) col = "#9fb3c8";
            else if (x > 0.42) col = "#ece8f2";
            else if (x > 0.2) col = mix("#b9a8cf", "#d9cfe6", 0.5 + 0.5 * Math.sin(x * 60));
            else col = shade(purple, 0.8);
            return keep(shade(col, 0.95 + 0.1 * c.rand()));
          },
        });
        // The cavity wall, deep purple, and crystal points growing inwards.
        const wall = k.param(
          (u, v) => {
            const phi = u * TAU;
            const th = v * (Math.PI / 2);
            const r = cav(phi) * (0.92 + 0.08 * Math.cos(th));
            return T([
              r * Math.sin(th) * Math.cos(phi),
              r * Math.sin(th) * Math.sin(phi),
              side * r * 0.75 * Math.cos(th),
            ]);
          },
          { grid: 48, thick: 0.02, flip: side < 0 },
        );
        k.add(wall, {
          part: inPart,
          flat: 0.2,
          color: (c) => lit(shade(purple, 0.45), c.n, 0.7, 0.3),
        });
        if (!half.crystals) continue;
        const crystals = [];
        for (let i = 0; i < 170; i++) {
          const phi = k.rand() * TAU;
          const th = Math.acos(1 - k.rand() * 0.97) * 0.98;
          const r = cav(phi) * (0.92 + 0.08 * Math.cos(th));
          const base = [
            r * Math.sin(th) * Math.cos(phi),
            r * Math.sin(th) * Math.sin(phi),
            side * r * 0.75 * Math.cos(th),
          ];
          const inward = unit(add(mul(base, -1), [0, 0, side * 0.35]));
          const axis = unit(add(inward, mul(randDir(k.rand), 0.25)));
          const L = 0.12 + 0.16 * k.rand();
          crystals.push({
            base: T(add(base, mul(axis, -0.02))),
            axis: TV(axis),
            w: L * 0.3,
            L,
            twist: k.rand(),
            part: inPart,
          });
        }
        crystalCloud(k, crystals, 0.22, (n, t, rand) => {
          const col = mix(shade(purple, 0.55), mix(purple, "#f3e3ff", 0.6), Math.pow(t, 1.3));
          const b = 0.55 + 0.5 * studio(n);
          return {
            color: shade(col, clamp(b, 0.4, 1.3)),
            kind: "glint",
            params: [rand() < 0.3 ? 1 : 0.2, 0],
          };
        });
        // The glow (hidden until it opens): a violet haze in the cavity and
        // bright points on the crystal tips.
        const gp = glowParts[half.open ? 1 : 0];
        k.cloud({ share: 0.012, size: 2.6, pattern: false }, (rand) => {
          const d = randDir(rand);
          const r = 0.55 * Math.cbrt(rand());
          return {
            p: T([d[0] * r, d[1] * r, side * Math.abs(d[2]) * r * 0.7]),
            color: mix("#b25cff", "#f0d6ff", rand() * 0.4),
            opacity: 0.08,
            part: gp,
          };
        });
        k.cloud({ share: 0.01, size: 1.1, pattern: false }, (rand) => {
          const cr = crystals[Math.floor(rand() * crystals.length)];
          return {
            p: add(cr.base, mul(cr.axis, cr.L * (0.7 + 0.35 * rand()))),
            color: mix("#d9a6ff", "#ffffff", 0.3 + 0.5 * rand()),
            opacity: 0.9,
            kind: "twinkle",
            params: [0.5, rand() * TAU],
            part: gp,
          };
        });
      }
      // Room for the front half as it swings shut.
      k.reach([0, 0, R * 1.05]);
    }

drive:
drive(t, c, out, info) {
      const e = c.open * c.open * (3 - 2 * c.open);
      const openNow = e >= 0.5 ? 1 : 0;
      if (geode.prev !== null && c.open > geode.prev && !geode.rising) geode.openedAt = info.time;
      if (geode.prev !== null && c.open !== geode.prev) geode.rising = c.open > geode.prev;
      geode.prev = c.open;
      const a = info.time - geode.openedAt;
      const wide = GEODE_WIDE * smoothstep(0.5, 1.3, a) * (1 - smoothstep(2.4, 3.8, a));
      const glow = e * smoothstep(0.2, 0.9, a) * (1 - smoothstep(2.8, 4.6, a));
      out.parts.lidShut = { angle: -GEODE_SWING * e, visible: 1 - openNow };
      const apart = [-GEODE_APART * (wide / GEODE_WIDE), 0, 0];
      out.parts.lidOpen = { angle: GEODE_SWING * (1 - e) - wide, offset: apart, visible: openNow };
      out.parts.glow = { visible: glow };
      out.parts.glowLid = { angle: -wide, offset: apart, visible: glow * openNow };
      out.amount = 1;
    }

build:
build(k, o) {
      // A cushion: a square with softly rounded sides.
      const cushion = (phi) => {
        const c = Math.abs(Math.cos(phi));
        const s = Math.abs(Math.sin(phi));
        return 1 / Math.pow(Math.pow(c, 3.2) + Math.pow(s, 3.2), 1 / 3.2);
      };
      const table = 0.55;
      const crown = 35 * DEG;
      addGem(k, brilliant(cushion, { table, crown: 35, pavilion: 42 }), o.color, {
        size: 1.3,
        glint: 0.25,
        opacity: 1,
        jitter: 0.015,
        quat: SAPPHIRE_Q,
        fire: 0.08,
        dark: 0.22,
        light: "#dfe8ff",
      });
      // The star (hidden until a tap): a soft bright centre and six rays of
      // light lying on the top of the stone, dipping down its crown past the
      // table's edge and ending at the girdle. Each ray grows out from the
      // centre (grow) as the star is caught.
      const top = 0.02 + (1 - table) * Math.tan(crown);
      const onTop = (x, z) => {
        const r = Math.hypot(x, z);
        const edge = table * cushion(Math.atan2(z, x));
        return [x, top + 0.006 - Math.max(0, r - edge) * Math.tan(crown), z];
      };
      const inside = (x, z) => Math.hypot(x, z) < 0.95 * cushion(Math.atan2(z, x));
      const normal = quatRotate(SAPPHIRE_Q, [0, 1, 0]);
      const rays = [0, 1, 2, 3, 4, 5].map((i) => (i / 6) * TAU + 0.26);
      for (let f = 0; f < SAPPHIRE_FRAMES; f++) {
        const [cx, cz] = sapphirePath(f / (SAPPHIRE_FRAMES - 1));
        // How far each ray runs before it reaches the girdle.
        const reach = rays.map((a) => {
          let d = 0;
          while (d < 2 && inside(cx + Math.cos(a) * (d + 0.01), cz + Math.sin(a) * (d + 0.01)))
            d += 0.01;
          return d;
        });
        const part = k.part(`star${f}`);
        // (Splats drawn out along the rays, so each ray is a smooth streak.)
        k.cloud({ share: 0.008, pattern: false, part }, (rand) => {
          let x;
          let z;
          let t;
          let dir;
          if (rand() < 0.14) {
            // The bright centre.
            const r = 0.07 * Math.sqrt(rand());
            const a = rand() * TAU;
            t = r / 0.6;
            x = cx + Math.cos(a) * r;
            z = cz + Math.sin(a) * r;
          } else {
            const i = Math.floor(rand() * 6);
            const a = rays[i];
            t = Math.pow(rand(), 1.25);
            const d = t * reach[i];
            const w = (0.008 + 0.014 * t) * gauss(rand);
            x = cx + Math.cos(a) * d - Math.sin(a) * w;
            z = cz + Math.sin(a) * d + Math.cos(a) * w;
            t = Math.min(1, d / 0.9);
            dir = quatRotate(SAPPHIRE_Q, [Math.cos(a), 0, Math.sin(a)]);
          }
          return {
            p: quatRotate(SAPPHIRE_Q, onTop(x, z)),
            n: normal,
            flat: 0.2,
            ...(dir ? { dir, stretch: 2.6 } : {}),
            color: mix("#ffffff", "#c4d2ff", t),
            opacity: 0.1 + 0.6 * (1 - t),
            size: 1.2 * (1 - 0.4 * t),
            kind: "grow",
            params: [0.9 * t, 0],
          };
        });
      }
    }

drive:
drive(t, c, out) {
      const p = progress(c.star);
      const on = c.star > 0 ? 1 : 0;
      const u = ease(band(p, 0.02, 0.95));
      out.grow = on * 1.1 * ease(band(p, 0.02, 0.22)) * (1 - ease(band(p, 0.76, 0.97)));
      const shown = Math.round(u * (SAPPHIRE_FRAMES - 1));
      const [x, z] = sapphirePath(u);
      for (let i = 0; i < SAPPHIRE_FRAMES; i++) {
        const [x0, z0] = sapphirePath(i / (SAPPHIRE_FRAMES - 1));
        out.parts[`star${i}`] = {
          offset: quatRotate(SAPPHIRE_Q, [x - x0, 0, z - z0]),
          visible: on && i === shown ? 1 : 0,
        };
      }
    }

build:
build(k, o) {
      const tint = o.color;
      // A lumpy rock base.
      k.add(
        k.radial((d) => 1 + 0.12 * k.noise.fbm(d[0] * 2, d[1] * 2 + 3, d[2] * 2, 3), { grid: 48 }),
        {
          scale: [1, 0.36, 0.85],
          pos: [0, -0.62, 0],
          flat: 0.2,
          interior: 0.1,
          core: "#6d655c",
          color: (c) => rockColor(c, "#8d8274", "#5d544b"),
        },
      );
      // Crystals: long six-sided prisms with points, leaning out from the rock.
      const list = [
        [0, 1.25, 0.2, 0, 0],
        [0.4, 0.95, 0.15, -22, 12],
        [-0.42, 1.0, 0.16, 20, -8],
        [0.2, 0.7, 0.12, -10, -32],
        [-0.15, 0.62, 0.11, 8, 30],
        [0.62, 0.6, 0.11, -40, 5],
        [-0.65, 0.55, 0.1, 42, 10],
        [0.05, 0.5, 0.09, -5, 45],
        [-0.35, 0.45, 0.09, 30, 38],
        [0.45, 0.42, 0.08, -35, -35],
      ];
      // The crystals light up from left to right (drive's point0 is the
      // leftmost).
      const order = list.map((c, i) => i).sort((a, b) => list[a][0] - list[b][0]);
      list.forEach(([x, L, w, rz, rx], i) => {
        const planes = crystalPoint(w, L, w * 1.6, k.rand() * 0.5);
        const shape = polytope(planes);
        const pos = [x, -0.55, (i % 3) * 0.08 - 0.08];
        const rot = [rx, k.rand() * 40, rz];
        shape.opts = { pos, quat: quatEuler(...rot) };
        const part = k.part(`point${order.indexOf(i)}`);
        // Its glow (hidden until its turn): the faces lit from within,
        // brightest towards the point, and a star at the tip.
        // (Bigger, fainter splats than the crystal's own, so the light
        // reads as a glow, not as dots.)
        overlay(k, shape, {
          share: 0.018,
          size: 2.2,
          part,
          lift: 0.005,
          col: (c, s) => ({
            color: mix(mix(tint, "#e8dcff", 0.5), "#ffffff", clamp(s.p[1] / L, 0, 1)),
            opacity: 0.3 + 0.35 * clamp(s.p[1] / L, 0, 1),
          }),
        });
        // The star: a glint with a long and a short spike and four faint
        // ones between, each point's turned its own way (not a row of
        // upright crosses).
        const tip = add(quatRotate(shape.opts.quat, [0, L, 0]), pos);
        const right = unit(cross([0, 1, 0], VIEW));
        const up = cross(VIEW, right);
        const spin = 0.3 + 1.0 * ((i * 0.618034) % 1);
        const spikes = [
          [spin, 0.18],
          [spin + Math.PI / 2, 0.11],
          [spin + Math.PI / 4, 0.055],
          [spin - Math.PI / 4, 0.055],
        ];
        k.cloud({ count: 300, size: 1, pattern: false, part }, (rand) => {
          const r = rand();
          const [a, len] = spikes[r < 0.45 ? 0 : r < 0.75 ? 1 : r < 0.875 ? 2 : 3];
          const dir = add(mul(right, Math.cos(a)), mul(up, Math.sin(a)));
          const u = rand() * 2 - 1;
          return {
            p: add(add(tip, mul(VIEW, 0.03)), mul(dir, u * len)),
            dir,
            stretch: 3,
            size: 1.2 * (1 - 0.8 * Math.abs(u)) * Math.sqrt(len / 0.18),
            color: "#ffffff",
            opacity: 0.95,
          };
        });
        k.add(shape, {
          pos,
          rot,
          flat: 0.12,
          weight: 1.3,
          opacity: 0.9,
          kind: "glint",
          params: (c) => [c.rand() < 0.15 ? 0.9 : 0.05, 0],
          pattern: false,
          color: (c) => {
            const t = clamp((c.lp[1] + 0) / L, 0, 1);
            const base = mix(shade(tint, 0.75), tint, t);
            let col = gemColor(c, base, { fire: 0.06, dark: 0.45, edgeW: 0.01 });
            if (c.s.tag === "side") {
              // Fine growth lines across the prism faces.
              if (Math.abs(Math.sin(c.lp[1] * 90)) > 0.93) col = shade(col, 0.9);
            }
            return col;
          },
        });
      });
    }

drive:
drive(t, c, out) {
      const p = progress(c.light);
      const on = c.light > 0 ? 1 : 0;
      for (let i = 0; i < 10; i++) {
        const t0 = 0.03 + 0.066 * i;
        out.parts[`point${i}`] = {
          visible: on * 1.3 * bump(p, t0, t0 + 0.035, t0 + 0.12, t0 + 0.34),
        };
      }
