build:
build(k, o) {
      const body = { white: "#e6edf5", black: "#1b2340", fire: "#f28c28" }[o.type] || "#e6edf5";
      const hues = {
        white: [0.33, 0.5, 0.6, 0.08, 0.9],
        black: [0.33, 0.5, 0.62, 0.02, 0.8],
        fire: [0.0, 0.05, 0.1, 0.14, 0.95],
      }[o.type] || [0.33, 0.5];
      // A cabochon: a smooth oval dome on a flat back.
      const prof = [];
      for (let i = 0; i <= 16; i++) {
        const a = (i / 16) * (Math.PI / 2);
        prof.push([Math.cos(a) * (i === 16 ? 0 : 1), -0.05 + 0.5 * Math.sin(a)]);
      }
      prof.unshift([0.96, -0.1], [0.6, -0.12], [0, -0.12]);
      prof.sort((a, b) => a[1] - b[1] || a[0] - b[0]);
      // Patches of colour: cells round random points.
      const cells = [];
      for (let i = 0; i < 120; i++) {
        cells.push({
          p: [(k.rand() * 2 - 1) * 1.4, k.rand() * 0.5 - 0.1, (k.rand() * 2 - 1) * 1.05],
          h: hues[Math.floor(k.rand() * hues.length)] + (k.rand() - 0.5) * 0.06,
          s: 0.5 + 0.5 * k.rand(),
        });
      }
      const cellOf = (lp) => {
        let b1 = Infinity;
        let b2 = Infinity;
        let cell = cells[0];
        for (const cl of cells) {
          const d = (lp[0] - cl.p[0]) ** 2 + (lp[1] - cl.p[1]) ** 2 * 3 + (lp[2] - cl.p[2]) ** 2;
          if (d < b1) {
            b2 = b1;
            b1 = d;
            cell = cl;
          } else if (d < b2) b2 = d;
        }
        return { cell, b1, b2 };
      };
      const opalColor = (c) => {
        const lp = [c.lp[0] * 1.35, c.lp[1], c.lp[2]];
        const { cell, b1, b2 } = cellOf(lp);
        const edge = smoothstep(0, 0.02, Math.sqrt(b2) - Math.sqrt(b1));
        // Play of colour: the hue shifts with the facing, as if with the light.
        const h = (cell.h + 0.08 * c.n[0] + 0.05 * c.n[2] + 1) % 1;
        const flash = hue(h, 0.85, 1);
        const glow = 0.35 + 0.65 * smoothstep(-0.3, 0.6, c.noise(lp[0] * 7, lp[1] * 7, lp[2] * 7));
        const amount = cell.s * glow * (0.3 + 0.7 * edge);
        let col = mix(body, flash, clamp(amount * (o.type === "black" ? 0.95 : 0.7), 0, 0.9));
        col = lit(col, c.n, 0.72, 0.35);
        return gloss(col, c.n, 0.5, 30);
      };
      const lathe = k.lathe(prof, { grid: 72, thick: 0.25 });
      const stone = k.part("stone");
      const opalQ = quatEuler(24, 20, 0);
      k.add(lathe, {
        scale: [1.35, 1, 1],
        quat: opalQ,
        part: stone,
        flat: 0.15,
        interior: 0.08,
        core: body,
        kind: "glint",
        params: (c) => [c.rand() < 0.5 ? 1 : 0.3, 0],
        color: (c) => opalColor(c),
      });
      // Play of colour: points over the dome coloured as the stone is
      // there, which flash as a running glow of changing colour rolls
      // across the stone, patch by patch (drive).
      lathe.opts = { scale: [1.35, 1, 1], quat: opalQ };
      overlay(k, lathe, {
        share: 0.1,
        size: 2,
        part: stone,
        lift: 0.003,
        keep: (s) => s.p[1] > -0.02,
        col: (c, s) => {
          const lp = [s.p[0] * 1.35, s.p[1], s.p[2]];
          const { cell } = cellOf(lp);
          return {
            color: opalColor({ lp: s.p, n: c.n, noise: k.noise }),
            opacity: 0.55,
            kind: "pulse",
            params: [clamp((lp[0] + 1.35) / 2.9 + 0.1 * (cell.h % 1) - 0.05, 0, 0.999), 0],
          };
        },
      });
    }

drive:
drive(t, c, out) {
      const p = progress(c.play);
      const on = c.play > 0 ? 1 : 0;
      const u = band(p, 0, 1);
      out.parts.stone = { angle: on * 0.35 * Math.sin(TAU * u) * (1 - 0.5 * u) };
      out.glow = [...hue((t * 0.45) % 1, 0.9, 1), on * 1.8 * bump(p, 0.02, 0.12, 0.72, 1)];
    }

build:
build(k, o) {
      const pearlCol = o.color;
      const pearlAt = o.shell ? [0, -0.02, 0.1] : [0, 0, 0];
      const pr = o.shell ? 0.31 : 1;
      k.add(k.sphere(pr), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: pearlAt,
        flat: 0.15,
        weight: o.shell ? 2 : 1,
        interior: 0.1,
        core: "#efe4d4",
        pattern: false,
        kind: "glint",
        params: (c) => [c.rand() < 0.25 ? 0.8 : 0.1, 0],
        color: (c) => {
          // Lustre: soft shading, a pink and green orient, a crisp highlight.
          const f = dot(c.n, VIEW);
          let col = mix(shade(pearlCol, 0.78), pearlCol, smoothstep(-0.2, 0.9, dot(c.n, LIGHT)));
          col = mix(
            col,
            hue((0.9 + 0.3 * f + 0.1 * c.n[1]) % 1, 0.25, 1),
            0.18 * (1 - Math.abs(f)),
          );
          col = mix(col, "#ffffff", 0.9 * Math.pow(Math.max(0, dot(c.n, HALF)), 60));
          col = mix(col, "#ffffff", 0.25 * Math.pow(Math.max(0, dot(c.n, HALF)), 6));
          return col;
        },
      });
      if (!o.shell) return;
      // An oyster: a rough cupped lower shell and a hinged lid, pearly inside.
      const hinge = [0, 0.02, -0.72];
      const lidShut = k.part("lidShut", { pivot: hinge, axis: [1, 0, 0] });
      const lidOpen = k.part("lidOpen", { pivot: hinge, axis: [1, 0, 0] });
      const openQ = quatAxisAngle([1, 0, 0], -PEARL_SWING);
      const valve = (up, lift, open) => {
        const outline = (a) => 1 + 0.08 * Math.sin(a * 5 + 1) + 0.05 * Math.sin(a * 11);
        return k.param(
          (u, v) => {
            const a = u * TAU;
            const r = v * outline(a);
            const x = r * Math.cos(a) * 1.05;
            const z = r * Math.sin(a) * 0.82;
            const depth = 0.3 * (1 - v * v) + 0.015 * Math.sin(a * 22) * v;
            const p = [x, (up ? depth * 1.05 : -depth) + lift, z];
            return open ? add(hinge, quatRotate(openQ, sub(p, hinge))) : p;
          },
          { grid: 64, thick: 0.05, flip: up },
        );
      };
      // Patterns from the shell's own (u, v): angle round it and distance out.
      const outside = (c) => {
        const rib = Math.abs(Math.sin(c.u * TAU * 22));
        const ring = Math.abs(Math.sin(c.v * 30 + c.fbm(c.u * 20, 0, c.v * 3) * 3));
        const col = mix("#7d746a", "#b3a898", 0.5 * rib + 0.3 * ring);
        return lit(col, mul(c.n, -1), 0.6, 0.45);
      };
      const nacre = (c) => {
        const r = c.v;
        let col = mix("#f6f3f8", "#c9d6ea", smoothstep(0.2, 0.9, r));
        col = mix(col, hue((Math.cos(c.u * TAU) * 0.6 + r * 0.8 + 2) % 1, 0.35, 1), 0.24);
        if (r > 0.92) col = mix(col, "#5c544b", 0.6);
        return gloss(col, c.n, 0.3, 12);
      };
      for (const [up, part, open] of [
        [false, 0, false],
        [true, lidShut, false],
        [true, lidOpen, true],
      ]) {
        // Inside (pearly) and outside (rough) of the same shell.
        k.add(valve(up, 0, open), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          part,
          flat: 0.2,
          color: nacre,
        });
        k.add(valve(up, up ? 0.025 : -0.025, open), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          part,
          flat: 0.2,
          color: outside,
        });
      }
    }

drive:
drive(t, c, out) {
      const e = c.open * c.open * (3 - 2 * c.open);
      const openNow = e >= 0.5 ? 1 : 0;
      out.parts.lidShut = { angle: -PEARL_SWING * e, visible: 1 - openNow };
      out.parts.lidOpen = { angle: PEARL_SWING * (1 - e), visible: openNow };
    }

build:
build(k, o) {
      const R = 1;
      const cy = 0.35;
      const mist = o.color;
      // The glass: nearly clear, bright at the rim, with a window highlight.
      k.add(k.sphere(R), {
        even: true,
        jitter: 0.015,
        pos: [0, cy, 0],
        flat: 0.1,
        opacity: 0.22,
        share: 0.22,
        pattern: false,
        color: (c) => {
          // (Hidden where it sits down in its cup.)
          if (c.ln[1] < -0.82) return null;
          const f = Math.abs(dot(c.n, VIEW));
          let col = mix("#e8f1ff", "#ffffff", 0.4);
          col = mix(shade("#b8c8e8", 0.9), col, 1 - f);
          const hl = Math.pow(Math.max(0, dot(c.n, unit([-0.35, 0.6, 0.72]))), 40);
          return keep(mix(col, "#ffffff", hl));
        },
      });
      k.add(k.sphere(R * 1.002), {
        even: true,
        jitter: 0.015,
        pos: [0, cy, 0],
        share: 0.02,
        opacity: 0.9,
        pattern: false,
        kind: "glint",
        params: [0.3, 0],
        color: (c) => {
          const hl = Math.pow(Math.max(0, dot(c.n, unit([-0.35, 0.6, 0.72]))), 50);
          const rim = Math.pow(1 - Math.abs(dot(c.n, VIEW)), 6);
          if (hl < 0.2 && rim < 0.35) return null;
          return keep("#ffffff");
        },
      });
      // Swirling mist inside: slow turns, faster near the middle.
      // Three spiral arms of mist that curl up and down as they wind round.
      const mistPart = k.part("mist", { pivot: [0, cy, 0], axis: [0, 1, 0] });
      k.cloud({ share: 0.26, size: 1.7, pattern: false }, (rand) => {
        const arm = Math.floor(rand() * 3);
        const s = Math.pow(rand(), 0.8);
        const spread = 0.35 * (1 - 0.4 * s);
        const a =
          arm * (TAU / 3) +
          s * 4.6 +
          spread * Math.sqrt(-2 * Math.log(1 - rand())) * Math.cos(TAU * rand());
        const r = 0.08 + 0.74 * s + 0.05 * (rand() - 0.5);
        const y = 0.36 * Math.sin(a * 2 + s * 3 + arm) * s + 0.16 * (rand() - 0.5);
        const tint = [mist, "#ff8fd8", "#8fc8ff"][arm];
        return {
          p: [r * Math.cos(a), cy + y, r * Math.sin(a)],
          color: mix(tint, "#ffffff", 0.15 + 0.35 * (1 - s) * rand()),
          opacity: 0.1 + 0.14 * (1 - s),
          kind: "orbit",
          params: [0.5 + 0.2 * rand(), 0.8],
          part: mistPart,
        };
      });
      // The signs that appear in the mist (hidden until a tap): flat glowing
      // shapes with a little depth, and a soft light round them.
      const inside = {
        star: (x, y) => {
          const a = Math.atan2(y, x) + Math.PI / 2;
          const f = Math.abs((((a / TAU) * 5 + 10.5) % 1) - 0.5) * 2;
          return Math.hypot(x, y) < 0.38 * (0.45 + 0.55 * f * f);
        },
        moon: (x, y) => Math.hypot(x, y) < 0.34 && Math.hypot(x - 0.15, y - 0.07) > 0.28,
        heart: (x, y) => {
          const X = x / 0.3;
          const Y = (y + 0.02) / 0.3;
          const q = X * X + Y * Y - 1;
          return q * q * q - X * X * Y * Y * Y < 0;
        },
      };
      const tints = { star: "#fff0a8", moon: "#dff0ff", heart: "#ffb0dc" };
      for (const name of BALL_SIGNS) {
        const part = k.part(name, { pivot: [0, cy, 0], axis: [0, 1, 0] });
        const test = (x, y) => inside[name](x / 1.25, y / 1.25);
        k.cloud({ share: 0.03, size: 1.3, pattern: false }, (rand) => {
          for (let i = 0; i < 20; i++) {
            const x = (rand() - 0.5) * 1;
            const y = (rand() - 0.5) * 1;
            if (!test(x, y)) continue;
            return {
              p: [x, cy + y, 0.42 + (rand() - 0.5) * 0.04],
              color: mix(tints[name], "#ffffff", 0.35 + 0.4 * rand()),
              opacity: 1,
              part,
            };
          }
          return null;
        });
        // A soft light just behind it, a little larger than the sign.
        k.cloud({ share: 0.006, size: 2.4, pattern: false }, (rand) => {
          for (let i = 0; i < 20; i++) {
            const x = (rand() - 0.5) * 1.2;
            const y = (rand() - 0.5) * 1.2;
            if (!test(x * 0.8, y * 0.8)) continue;
            return {
              p: [x, cy + y, 0.36],
              color: mix(tints[name], mist, 0.3),
              opacity: 0.25,
              part,
            };
          }
          return null;
        });
      }
      // Motes of light: a glow rises through them when you gaze into the ball.
      k.cloud({ share: 0.008, size: 0.9, pattern: false }, (rand) => {
        const p = mul(randDir(rand), 0.85 * Math.cbrt(rand()));
        return {
          p: add(p, [0, cy, 0]),
          color: mix(mist, "#ffffff", 0.6),
          opacity: 0.9,
          kind: "pulse",
          params: [clamp((p[1] + 0.85) / 1.7, 0, 1), 0],
        };
      });
      k.cloud({ share: 0.004, size: 0.9, pattern: false }, (rand) => ({
        p: add(mul(randDir(rand), 0.85 * Math.cbrt(rand())), [0, cy, 0]),
        color: "#fff6d6",
        opacity: 1,
        kind: "twinkle",
        params: [0.45, rand() * TAU],
      }));
      // The stand: a turned base in gold, its cup just below the glass.
      const stand = k.lathe(
        [
          [0, -1.0],
          [0.75, -1.0],
          [0.78, -0.94],
          [0.68, -0.88],
          [0.4, -0.84],
          [0.24, -0.76],
          [0.3, -0.7],
          [0.46, -0.64],
          [0.58, -0.56],
          [0.66, -0.48],
          [0.64, -0.44],
        ],
        { grid: 72, thick: 0.12 },
      );
      k.add(stand, {
        even: true,
        opacity: 1,
        jitter: 0.015,
        flat: 0.2,
        color: (c) => {
          const b = Math.abs(Math.sin(c.p[1] * 40)) > 0.9;
          return gloss(lit(b ? "#a8841e" : "#d4ad3a", c.n, 0.55, 0.55), c.n, 0.6, 14);
        },
      });
      // A velvet lining in the cup, under the ball.
      k.add(
        k.param(
          (u, v) => {
            const a = u * TAU;
            const th = v * 0.63;
            const r = R * 1.01;
            return [
              r * Math.sin(th) * Math.cos(a),
              cy - r * Math.cos(th),
              r * Math.sin(th) * Math.sin(a),
            ];
          },
          { grid: 32, thick: 0.02 },
        ),
        {
          even: true,
          opacity: 1,
          jitter: 0.015,
          flat: 0.2,
          color: (c) => lit("#5b2a86", mul(c.n, -1), 0.7, 0.3),
        },
      );
      // Little claws holding the ball.
      for (let i = 0; i < 4; i++) {
        const a = (i / 4) * TAU + TAU / 8;
        const d = [Math.cos(a), 0, Math.sin(a)];
        k.add(evenEllipsoid(k, 0.07, 0.2, 0.05), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [d[0] * 0.8, -0.28, d[2] * 0.8],
          quat: quatFromTo([0, 1, 0], unit([-d[0] * 0.4, 1, -d[2] * 0.4])),
          weight: 1.5,
          color: (c) => gloss(lit("#d4ad3a", c.n, 0.55, 0.55), c.n, 0.6, 14),
        });
      }
    }

drive:
drive(t, c, out, info) {
      const ball = crystalBall;
      if (c.gaze > ball.prev + 0.3) ball.count++;
      ball.prev = c.gaze;
      const dt = clamp(info.time - ball.last, 0, 0.1);
      ball.last = info.time;
      ball.spin += dt * 9 * Math.sqrt(c.gaze);
      const p = c.gaze > 0 ? 1 - c.gaze : 1;
      const sign = smoothstep(0.08, 0.3, p) * (1 - smoothstep(0.62, 0.95, p));
      out.parts.mist = { angle: ball.spin, visible: 1 - 0.5 * sign };
      BALL_SIGNS.forEach((name, i) => {
        out.parts[name] = {
          angle: 0.55 + 0.9 * (p - 0.5),
          offset: [0, 0.12 * (1 - sign), 0],
          visible: i === ball.count % BALL_SIGNS.length ? sign : 0,
        };
      });
      out.amount = 0.4 + 1.2 * c.swirl + 1.5 * c.gaze;
      out.glow = [0.9, 0.6, 1, 1.4 * c.gaze];
    }

build:
build(k, o) {
      const layer0 = layerIndex(o.layer);
      const parts = Object.fromEntries(LAYERS.map((id) => [id, k.part(id)]));
      const prims = bodyPrims();
      // Each piece's splats: their center, average normal and a few points
      // for finding what was tapped (collected as the splats are made).
      const acc = PIECES.map(() => ({ sum: [0, 0, 0], nsum: [0, 0, 0], n: 0 }));
      const labelPts = LABEL_LIST.map(() => []);
      const seen = (tok, label, c) => {
        if (tok >= 0) {
          const a = acc[tok];
          for (let j = 0; j < 3; j++) {
            a.sum[j] += c.p[j];
            a.nsum[j] += c.n[j];
          }
          a.n++;
        }
        const pts = labelPts[label];
        if (pts.length < 64) pts.push(c.p);
        else if (c.rand() < 0.02) pts[Math.floor(c.rand() * 64)] = c.p;
      };
      const labelOfTok = PIECES.map(([, , name]) => labelIndex(name));

      // The skin: a smooth mannequin, lit with a soft satin sheen.
      const skins = prims.map((P, i) => bodyShape(k, prims, i, 0));
      prims.forEach((P, i) => {
        if (skins[i].none) return;
        skins[i].item = k.add(skins[i], {
          part: parts.skin,
          weight: 0.9,
          kind: "token",
          params: (c) => [c.s.tok ?? 0, 0],
          even: true,
          opacity: 1,
          flat: 0.2,
          jitter: 0.008,
          color: (c) => {
            if (c.s.drop) return null;
            const tok = (c.s.tok = skinPiece(c.p, c.s.prim));
            seen(tok, labelOfTok[tok], c);
            let col = lit(SKIN, c.n, 0.66, 0.4);
            // A calm mannequin face: soft hollows for the eyes.
            if (c.s.prim.kind === "head") {
              for (const s of [-1, 1]) {
                const e = len(sub(c.p, [s * 0.03, 1.668, 0.085]));
                col = shade(col, 1 - 0.1 * sstep(0.022, 0.006, e));
              }
            }
            return { c: sheen(col, c.n, 0.22, 10), size: c.s.mult };
          },
        });
      });

      // The muscles: the same body a few millimeters in, in groups with
      // grooves between them, fibers and pale tendons.
      const groove = (p, n, P, tok) => {
        const t1 = unit(cross(n, Math.abs(n[1]) < 0.9 ? [0, 1, 0] : [1, 0, 0]));
        const t2 = cross(n, t1);
        let edge = 0;
        // Two looks, across each other, 7.5 mm away (enough to find a seam).
        for (const [a, b] of [
          [0.7, 0.7],
          [-0.7, 0.7],
        ]) {
          for (const sgn of [1, -1]) {
            const q = add(p, add(mul(t1, sgn * a * 0.0075), mul(t2, sgn * b * 0.0075)));
            if (muscleAt(q, P).tok !== tok) {
              edge += 2;
              break;
            }
          }
        }
        return edge;
      };
      prims.forEach((P, i) => {
        if (skins[i].none) return;
        const shape = bodyShape(k, prims, i, -0.0045, skins[i]);
        shape.item = k.add(shape, {
          part: parts.muscles,
          weight: 0.9,
          kind: "token",
          params: (c) => [c.s.tok ?? 0, 0],
          even: true,
          opacity: 1,
          flat: 0.22,
          jitter: 0.01,
          color: (c) => {
            if (c.s.drop) return null;
            const m = muscleAt(c.p, c.s.prim);
            c.s.tok = m.tok;
            seen(m.tok, labelOfTok[m.tok], c);
            // Fibers: soft stripes across the fiber direction.
            const across = unit(cross(c.n, m.fib));
            const stripe = Math.sin(dot(c.p, across) * 520 + 3 * c.noise(c.p[0] * 30, c.p[1] * 30, c.p[2] * 30)); // prettier-ignore
            let col = mix(MUSCLE, MUSCLE_DARK, 0.18 + 0.14 * stripe);
            col = mix(col, TENDON, m.tendon);
            const edge = groove(c.p, c.n, c.s.prim, m.tok);
            if (edge) col = mix(col, GROOVE, 0.25 + 0.12 * edge);
            return { c: sheen(lit(col, c.n, 0.62, 0.45), c.n, 0.28, 16), size: c.s.mult };
          },
        });
      });

      // The skeleton and the organs.
      buildSkeleton(k, parts.skeleton, (tok, colorFn) => (c) => {
        seen(tok, labelOfTok[tok], c);
        return typeof colorFn === "function" ? colorFn(c) : lit(colorFn, c.n);
      });
      buildOrgans(k, parts.organs, (label) => (colorFn) => (c) => {
        const col = typeof colorFn === "function" ? colorFn(c) : (colorFn ?? "#cccccc");
        if (col !== null) seen(-1, labelIndex(label), c);
        return col;
      });

      k.data = { layer0, acc, labelPts, motion: null };
      // The pieces' motions are set once the splats exist (their centers).
      Object.defineProperty(k.data, "motion", {
        get() {
          return this._motion || (this._motion = pieceMotions(acc));
        },
      });
    }

drive:
drive(t, c, out, info) {
      const d = info.data;
      if (!d) return;
      const n = info.tap?.n ?? 0;
      const cur = (d.layer0 + n) % 4;
      const prev = (cur + 3) % 4;
      const s = c.peel > 0 && n > 0 ? 1 - c.peel : 1; // 1 when still
      const moving = s < 1;
      const back = moving && cur === 0; // the return
      const show = [0, 0, 0, 0];
      const tokens = [];
      for (let i = 0; i < PIECES.length; i++) tokens.push({ visible: 1 });
      if (!moving) {
        show[cur] = 1;
        if (cur === 2) show[3] = 1;
        for (let i = 0; i < PIECES.length; i++) if (PIECES[i][1] < cur) tokens[i].visible = 0;
      } else if (!back) {
        // Peeling layer `prev`: its pieces fly off; the next one shows.
        show[prev] = s < 0.985 ? 1 : 0;
        show[cur] = 1;
        if (cur === 2 || prev === 2) show[3] = 1;
        for (let i = 0; i < PIECES.length; i++) {
          const L = PIECES[i][1];
          if (L < prev) tokens[i].visible = 0;
          else if (L === prev) {
            const m = d.motion[i];
            tokens[i] = pieceMotion(m, clamp01((s - m.w0) / (m.w1 - m.w0)));
          }
        }
      } else {
        // The return: the skeleton, then the muscles, then the skin come back.
        for (let L = 0; L < 4; L++) show[L] = L === 0 || s < 0.985 ? 1 : 0;
        for (let i = 0; i < PIECES.length; i++) {
          const L = PIECES[i][1];
          const m = d.motion[i];
          const span = [
            [0.5, 1.0],
            [0.25, 0.8],
            [0, 0.55],
          ][L];
          const u = clamp01((s - span[0]) / (span[1] - span[0]));
          const local = clamp01((1 - u - m.w0 * 0.5) / (1 - m.w0 * 0.5));
          tokens[i] = pieceMotion(m, local);
        }
      }
      LAYERS.forEach((id, L) => (out.parts[id] = { visible: show[L] }));
      out.tokens = tokens;
      // Sort again as the pieces fly (docs/PACKS.md 7b, rule 12 and 13).
      const m = mem(c);
      const step = moving ? Math.floor(s * 8) : -1;
      if (step !== m.step) {
        out.resort = true;
        m.step = step;
      }
      // A low chime as the last pieces of skin settle back.
      if (back && s > 0.93 && m.chimed !== n) {
        m.chimed = n;
        out.cues.push({ voice: "bell", f: "G3", decay: 1.6, vol: 0.45, bright: 0.3 });
      }
      // The labels: every layer's name, the shown layer's parts, and the
      // part last tapped highlighted.
      if (c.labels > 0.5) {
        if (m.tapN !== n) {
          m.tapN = n;
          m.hi = info.tap?.point ? nearestLabel(d, info.tap.point, cur) : -1;
        }
        out.legend = legend(cur, m.hi);
      }
    }

build:
build(k, o) {
      reseed(k, o);
      const rand = k.rand;
      const winter = o.season === "winter";
      const tree = growTree(rand, {
        length: 0.62,
        radius: 0.16,
        depth: 4,
        kids: [
          [4, 5],
          [2, 3],
          [2, 3],
          [2, 2],
        ],
        spread: [1.05, 0.7, 0.65, 0.7],
        ratio: [0.95, 0.66, 0.66, 0.6],
        radRatio: [0.66, 0.66, 0.65, 0.6],
        from: [0.72, 0.4, 0.35, 0.3],
        wobble: [0.12, 0.45, 0.65, 0.8],
        up: [0, 0.06, 0.06, 0.08],
        taper: 0.62,
        tipTaper: 0.4,
      });
      // The crown rocks on its trunk when shaken (the roots stay put).
      const crown = k.part("crown", { pivot: [0, 0, 0], axis: SHAKE_AXIS });
      const SW = { ...sway(0.008, 0), part: crown };
      const bark = barkColor("#5d4632", "#2b1f16", { snow: winter ? 0.9 : 0 });
      addBranches(k, tree.branches, {
        color: bark,
        flare: 0.6,
        gnarl: 0.07,
        extra: SW,
        clip: winter ? null : within([0, 1.28, 0], [1.02, 0.62, 1.02]),
      });
      addRoots(k, 6, 0.1, 0, bark);
      grassMound(k, 1.0, 0, {
        h: 0.1,
        snow: winter ? 0.95 : 0,
        colors: o.season === "autumn" ? ["#5b5a22", "#7a7630", "#9a8a3a"] : undefined,
      });
      if (winter) {
        // A few dead brown leaves still cling to the twigs (oaks keep some
        // through the winter); a shake brings them down.
        const tips = tree.tips.filter((tp) => tp.p[1] > 0.9);
        const spots = [];
        for (let i = 0; i < 20 && tips.length; i++) {
          const tp = tips[Math.floor(rand() * tips.length)];
          spots.push({
            p: add(tp.p, [0, -0.03, 0]),
            n: unit([tp.d[0] + rand() - 0.5, 0.2, tp.d[2] + rand() - 0.5]),
            roll: Math.PI + (rand() - 0.5) * 1.2,
          });
        }
        tokenLeaves(k, spots, {
          size: 0.15,
          part: crown,
          color: (i) => mix("#7a4a22", "#b8803a", (i * 0.37) % 1),
        });
        k.data = { leaves: planFalls(k, spots, { t0: [0.1, 1.0] }) };
        // Snow resting on the bare crown.
        const clumps = tipClumps(tree, rand, { r: 0.07, squash: 0.45 });
        foliage(k, clumps, {
          share: 0.05,
          size: 1.1,
          depth: 0.2,
          pattern: false,
          ...SW,
          color: (t, r, info) =>
            info.d[1] < 0 ? null : mix("#c9d6e6", "#ffffff", clamp(t + 0.2, 0, 1)),
        });
        return;
      }
      const pal = LEAF_PALETTES[o.season] || LEAF_PALETTES.summer;
      const clumps = domeClumps(k, {
        c: [0, 1.28, 0],
        r: [1.02, 0.62, 1.02],
        n: 46,
        size: [0.24, 0.32],
        below: -0.5,
        tips: tree.tips,
      });
      foliage(k, clumps, {
        share: 0.64,
        size: 1.3,
        tilt: 1.4,
        ...SW,
        color: (t, r) => {
          const col = ramp(pal, t);
          return o.season === "autumn" && r() < 0.15 ? mix(col, "#b8331a", 0.5) : col;
        },
      });
      // Loose leaves in the crown that a shake brings down.
      const spots = canopySpots(k, { c: [0, 1.28, 0], r: [1.02, 0.62, 1.02], n: 40, below: -0.7 });
      tokenLeaves(k, spots, {
        size: 0.17,
        part: crown,
        // Paler than the grass, so they show where they land.
        color: (i) => mix(ramp(pal, 0.55 + 0.45 * ((i * 0.618) % 1)), "#e8e27a", 0.3),
      });
      k.data = { leaves: planFalls(k, spots, {}) };
      if (o.season === "autumn") {
        // Leaves that drift down, and a few on the grass.
        k.cloud({ share: 0.012, size: 1.3, pattern: false }, (r) => {
          const a = r() * TAU;
          const rr = 0.95 * Math.sqrt(r());
          return {
            p: [Math.sin(a) * rr, 0.75 + r() * 0.4, Math.cos(a) * rr],
            n: randDir(r),
            color: ramp(pal, 0.3 + 0.7 * r()),
            kind: "fall",
            params: [0.7 + 0.2 * r(), r()],
          };
        });
        k.cloud({ share: 0.02, size: 1.2, flat: 0.15 }, (r) => {
          const a = r() * TAU;
          const rr = 0.25 + 0.72 * Math.sqrt(r());
          return {
            p: [Math.sin(a) * rr, 0.1 * (1 - (rr / 1.0) ** 2) + 0.012, Math.cos(a) * rr],
            n: [(r() - 0.5) * 0.4, 1, (r() - 0.5) * 0.4],
            color: ramp(pal, 0.2 + 0.8 * r()),
          };
        });
      }
    }

