        from: [0.65, 0.4, 0.35, 0.3],
        wobble: [0.1, 0.35, 0.5, 0.7],
        up: [0, 0.1, 0.1, 0.1],
        taper: 0.62,
        tipTaper: 0.4,
      });
      const bark = barkColor("#6b5a4c", "#3a2e26", { furrows: 5 });
      addBranches(k, tree.branches, {
        color: bark,
        flare: 0.5,
        extra: SW,
        clip: within([0, 1.42, 0], [0.92, 0.78, 0.92]),
      });
      addRoots(k, 5, 0.08, 0, bark);
      const PAL = {
        fire: ["#4a0c0a", "#8e1512", "#c62a18", "#e8561f", "#f7a23a"],
        orange: ["#5a220a", "#a4400f", "#dd6a17", "#f29a2e", "#fbd35a"],
        gold: ["#6a4a0c", "#a87812", "#dca51c", "#f2cb3a", "#fbe98a"],
        green: LEAF_PALETTES.summer,
      };
      const pal = PAL[o.color] || PAL.fire;
      const clumps = domeClumps(k, {
        c: [0, 1.42, 0],
        r: [0.92, 0.78, 0.92],
        n: 48,
        size: [0.22, 0.3],
        below: -0.55,
        tips: tree.tips,
      });
      const autumn = o.color !== "green";
      foliage(k, clumps, {
        share: 0.62,
        size: 1.25,
        tilt: 1.5,
        ...SW,
        color: (t, r, info) => {
          let col = ramp(pal, t);
          // Autumn trees are a mix: the odd clump turns early or late.
          if (autumn && info.cl.tint > 0.05) col = mix(col, ramp(PAL.orange, t), 0.5);
          if (autumn && r() < 0.06) col = mix(col, "#f7d04a", 0.6);
          return col;
        },
      });
      // Loose leaves that the gust tears off.
      const spots = canopySpots(k, { c: [0, 1.42, 0], r: [0.92, 0.78, 0.92], n: 44, below: -0.7 });
      tokenLeaves(k, spots, {
        shape: "maple",
        size: 0.22,
        part: crown,
        // Lighter than the crown, so they show against it as they whirl.
        color: (i) => mix(ramp(pal, 0.7 + 0.3 * ((i * 0.618) % 1)), autumn ? "#ffd84a" : "#e8e27a", 0.35), // prettier-ignore
      });
      k.data = {
        leaves: spots.map((sp, i) => {
          const r1 = 0.4 + 0.5 * k.rand();
          return {
            p: sp.p,
            n: sp.n,
            t0: 0.15 + (1.3 * (i + k.rand())) / spots.length,
            dur: 2.6 + 0.8 * k.rand(),
            gone: 5.2 + 0.4 * k.rand(),
            back: 6.5 - 0.2 * k.rand(),
            how: {
              turns: 0.8 + 0.6 * k.rand(),
              r1,
              mid: 0.45 + 0.25 * k.rand(),
              ground: moundTop(1, 0, 0.08, r1) + 0.012,
              tumble: (k.rand() < 0.5 ? -1 : 1) * (4 + 4 * k.rand()),
              axis: unit([k.rand() - 0.5, 0, k.rand() - 0.5]),
            },
          };
        }),
      };
      if (autumn) {
        const drift = k.part("drift");
        k.cloud({ share: 0.015, size: 1.4, flat: 0.15, pattern: false, part: drift }, (r) => {
          const a = r() * TAU;
          const rr = 1.0 * Math.sqrt(r());
          return {
            p: [Math.sin(a) * rr, 0.2 + r() * 0.8, Math.cos(a) * rr],
            n: randDir(r),
            color: ramp(pal, 0.3 + 0.7 * r()),
            kind: "fall",
            params: [0.25 + 0.15 * r(), r()],
          };
        });
      }
      grassMound(k, 1.0, 0, {
        h: 0.08,
        tint: autumn
          ? (c, col) =>
              c.noise(c.p[0] * 14, 1, c.p[2] * 14) + 0.4 * (c.rand() - 0.5) > 0
                ? ramp(pal, 0.2 + 0.8 * c.rand())
                : col
          : null,
      });
    }

drive:
drive(t, c, out, info) {
      const s = progress(c.gust) * MAPLE_SECS;
      const on = c.gust > 0;
      const lean = on ? 0.09 * ease(band(s, 0, 0.5)) * (1 - ease(band(s, 0.9, 2.4))) : 0;
      out.parts.crown = { angle: -lean + (on ? 0.02 * shake(s - 0.9, 2, 8) : 0) };
      // The gust sweeps away the leaves drifting down under the crown.
      out.parts.drift = { visible: on ? 1 - bump(s, 0.2, 0.7, 5.6, 6.6) : 1 };
      out.tokens = (info.data?.leaves || []).map((lf) => {
        if (!on || s < lf.t0) return { base: lf.p };
        if (s < lf.gone + 0.3) {
          const sw = swirlDown(lf.p, lf.n, band(s, lf.t0, lf.t0 + lf.dur), lf.how);
          return { base: lf.p, ...sw, visible: 1 - band(s, lf.gone, lf.gone + 0.3) };
        }
        return { base: lf.p, visible: ease(band(s, lf.back - 0.5, lf.back)) };
      });
    }

build:
build(k, o) {
      const rand = k.rand;
      const SW = sway(0.004, 0);
      // A shallow glazed pot on little feet.
      const potCol = o.pot;
      const glaze = (c, f = 1) => {
        const g = c.fbm(c.p[0] * 5, c.p[1] * 5, c.p[2] * 5);
        let col = mix(
          shade(potCol, 0.8),
          mix(potCol, "#ffffff", 0.15),
          smoothstep(-0.3, 0, c.p[1]),
        );
        col = shade(col, f * (0.95 + 0.1 * g));
        const hi = Math.pow(Math.max(0, dot(c.n, unit([-0.3, 0.45, 0.85]))), 10);
        return mix(lit(col, c.n, 0.4), "#ffffff", 0.25 * hi);
      };
      k.add(k.box(1.6, 0.28, 1.0), {
        pos: [0, -0.16, 0],
        color: (c) => (c.s.face === 2 ? null : glaze(c)),
      });
      for (const [sx, sz, x, z] of [
        [1.68, 0.06, 0, 0.5],
        [1.68, 0.06, 0, -0.5],
        [0.06, 1.0, 0.81, 0],
        [0.06, 1.0, -0.81, 0],
      ]) {
        k.add(k.box(sx, 0.05, sz), {
          pos: [x, -0.02, z],
          weight: 1.5,
          color: (c) => glaze(c, c.s.face === 3 ? 0.6 : 1.05),
        });
      }
      for (const [x, z] of [
        [-0.62, -0.36],
        [0.62, -0.36],
        [-0.62, 0.36],
        [0.62, 0.36],
      ]) {
        k.add(k.box(0.16, 0.08, 0.12), {
          pos: [x, -0.32, z],
          weight: 2,
          color: (c) => lit(shade(potCol, 0.7), c.n, 0.4),
        });
      }
      // Soil with moss, and a few pebbles.
      k.add(
        k.param((u, v) => [(u - 0.5) * 1.52, -0.015, (v - 0.5) * 0.92], { grid: 8, flip: true }),
        {
          color: (c) => {
            const m = c.fbm(c.p[0] * 6, 0, c.p[2] * 6);
            return m > -0.3
              ? mix("#4c7a2c", "#77a342", 0.5 + 0.5 * c.noise(c.p[0] * 40, 0, c.p[2] * 40))
              : mix("#4a3322", "#2e2016", c.rand());
          },
        },
      );
      for (let i = 0; i < 7; i++) {
        const s = 0.022 + rand() * 0.018;
        k.add(k.ellipsoid(s * 1.3, s * 0.6, s), {
          pos: [0.3 + rand() * 0.4, -0.012, (rand() - 0.5) * 0.7],
          rot: [0, rand() * 180, 0],
          weight: 2,
          color: (c) => lit(mix("#6f6a62", "#a8a296", c.rand() * 0.5 + 0.2), c.n, 0.4),
        });
      }
      // The trunk: a twisting S with a fat foot and surface roots.
      const trunkPts = [
        [-0.1, -0.02, 0],
        [0.1, 0.22, 0.04],
        [-0.12, 0.48, -0.02],
        [-0.02, 0.72, 0.02],
        [0.18, 0.9, -0.02],
        [0.22, 1.02, 0],
      ];
      const bark = barkColor("#6a5444", "#3a2a20", { furrows: 5 });
      const trunk = spline(trunkPts);
      k.add(
        k.tube(trunk, (t) => 0.13 * (1 - 0.72 * t) * (1 + 0.6 * Math.exp(-t * 12)), {
          samples: 96,
          grid: 36,
        }),
        { flat: 0.3, color: bark, ...SW },
      );
      addRoots(k, 6, 0.1, -0.02, bark);
      // Branches reach out sideways to cloud-like foliage pads.
      const limbs = [
        { t: 0.3, dir: [-1, 0.12, 0.25], L: 0.55 },
        { t: 0.45, dir: [0.9, 0.18, 0.3], L: 0.5 },
        { t: 0.6, dir: [-0.5, 0.25, -0.8], L: 0.42 },
        { t: 0.72, dir: [-0.8, 0.35, 0.3], L: 0.38 },
        { t: 0.82, dir: [0.8, 0.3, -0.3], L: 0.36 },
      ];
      const pads = [];
      limbs.forEach((l, i) => {
        const tree = growTree(rand, {
          base: trunk(l.t),
          dir: unit(l.dir),
          length: l.L,
          radius: 0.05 * (1 - 0.35 * l.t),
          depth: 2,
          kids: [
            [2, 2],
            [2, 3],
          ],
          spread: [0.8, 0.8],
          ratio: [0.6, 0.6],
          radRatio: [0.7, 0.7],
          from: [0.4, 0.4],
          wobble: [0.4, 0.5],
          up: [-0.02, 0.02],
          taper: 0.6,
        });
        addBranches(k, tree.branches, { color: bark, extra: SW });
        const end = tree.branches[0].pts[4];
        const rr = 0.24 + 0.05 * (i === 0);
        pads.push({ c: add(end, [0, 0.06, 0]), r: [rr, 0.1, rr * 0.8], tint: 0.05 });
        for (const tp of tree.tips)
          pads.push({
            c: add(tp.p, [0, 0.05, 0]),
            r: [0.16, 0.08, 0.14],
            tint: (rand() - 0.5) * 0.1,
          });
      });
      const top = trunk(1);
      pads.push({ c: add(top, [0, 0.08, 0]), r: [0.26, 0.14, 0.22], tint: 0.1 });
      pads.push({ c: add(top, [-0.18, 0.02, 0.05]), r: [0.2, 0.1, 0.18], tint: 0.05 });
      foliage(k, pads, {
        share: 0.42,
        size: 0.95,
        tilt: 1.2,
        depth: 0.4,
        ...SW,
        color: (t) => ramp(["#10301a", "#1d4a24", "#2f6a2e", "#4f8f3a", "#8cbf5a"], t),
      });
      // The new branch (hidden until a tap): a stub that stays on the trunk
      // and the piece beyond the cut, with a pad of leaves on its end.
      const T0 = trunk(0.24);
      const dir = unit([0.9, 0.32, 0.32]);
      const stub = k.part("stub", { pivot: T0 });
      const along = (u) => add(T0, add(mul(dir, 0.5 * u), [0, 0.07 * u * u, 0]));
      const shoot = k.part("shoot", {
        pivot: along(BONSAI_CUT),
        axis: unit(cross(dir, [0, 1, 0])),
      });
      k.data = { stub: sub(along(BONSAI_CUT), T0) };
      const rOf = (u) => 0.04 * (1 - 0.55 * u);
      k.add(
        k.tube(along, (u) => rOf(u), { samples: 8, grid: 10 }),
        {
          flat: 0.3,
          color: (c) => lit(mix("#7a6a44", "#5a4a32", c.rand()), c.n, 0.4),
          part: (c) => (dot(sub(c.p, T0), dir) < BONSAI_CUT * 0.46 ? stub : shoot),
        },
      );
      const tip = along(1);
      foliage(
        k,
        [
          { c: add(tip, [0, 0.05, 0]), r: [0.17, 0.08, 0.15], tint: 0.05 },
          { c: add(tip, [-0.1, 0.03, 0.02]), r: [0.12, 0.07, 0.11], tint: -0.05 },
        ],
        {
          share: 0.03,
          size: 0.95,
          tilt: 1.2,
          depth: 0.4,
          part: shoot,
          color: (t) => ramp(["#10301a", "#1d4a24", "#2f6a2e", "#4f8f3a", "#8cbf5a"], t),
        },
      );
      // Bonsai scissors: long blades and big black finger loops, closing
      // across the branch at the cut (the blades turn about the screw).
      const cutAt = along(BONSAI_CUT);
      const AIM = [-0.35, 0.55, -0.75];
      const X = unit(sub(AIM, mul(dir, dot(AIM, dir))));
      const Y = cross(dir, X);
      const pivot = sub(cutAt, mul(X, 0.17));
      const toW = (p) => add(pivot, add(add(mul(X, p[0]), mul(Y, p[1])), mul(dir, p[2])));
      const Q = frameQuat(X, Y, dir);
      const steel = (c) => {
        const hi = Math.pow(Math.max(0, dot(c.n, unit([-0.3, 0.6, 0.75]))), 12);
        return mix(lit("#8a9098", c.n, 0.5), "#f4f6fa", 0.6 * hi);
      };
      for (const [name, side] of [
        ["bladeA", 1],
        ["bladeB", -1],
      ]) {
        const part = k.part(name, { pivot, axis: dir });
        const z = side * 0.009;
        // The blade, tapering to a point, its cutting edge towards the other.
        k.add(k.ellipsoid(0.17, 0.03, 0.008), {
          pos: toW([0.16, side * 0.012, z]),
          quat: Q,
          weight: 3,
          part,
          pattern: false,
          color: steel,
        });
        // The shank and the finger loop.
        k.add(k.tube(spline([toW([0, 0, z]), toW([-0.1, -side * 0.035, z]), toW([-0.19, -side * 0.1, z])]), 0.012, { samples: 12, grid: 8 }), { weight: 3, part, pattern: false, color: steel }); // prettier-ignore
        k.add(k.torus(0.065, 0.016), {
          pos: toW([-0.25, -side * 0.15, z]),
          quat: quatMul(Q, quatEuler(90, 0, 0)),
          weight: 3,
          part,
          pattern: false,
          color: (c) => lit("#1a1a1c", c.n, 0.5),
        });
      }
      k.add(k.cylinder(0.012, 0.024), {
        pos: pivot,
        quat: quatMul(Q, quatEuler(90, 0, 0)),
        weight: 3,
        part: k.partIndex.get("bladeA"),
        pattern: false,
        color: "#b8bcc4",
      });
    }

drive:
drive(t, c, out, info) {
      const s = progress(c.trim) * BONSAI_SECS;
      const on = c.trim > 0;
      const grow = on ? 0.02 + 0.98 * ease(band(s, 0, 1.3)) : 0;
      const cut = 2.35;
      // The cut piece: grows, then falls (tipping over) onto the moss.
      const f = band(s, cut, cut + 0.42);
      const drop = f * f;
      const bounce = 0.02 * Math.sin(Math.PI * band(s, cut + 0.42, cut + 0.62));
      // It grows about the trunk (the piece beyond the cut turns about the
      // cut, so it is moved to stay on the end of the growing stub).
      const g = (info.data?.stub || [0, 0, 0]).map((x) => x * (grow - 1));
      out.parts.shoot = {
        scale: grow,
        visible: on ? 1 - ease(band(s, 4.0, 4.4)) : 0,
        offset: [g[0] + 0.05 * f, g[1] - BONSAI_DROP * drop + bounce, g[2] + 0.03 * f],
        angle: BONSAI_TIP * ease(f),
      };
      out.parts.stub = {
        scale: on ? grow * (1 - ease(band(s, 4.1, 4.8))) : 0,
        visible: on ? 1 : 0,
      };
      // The scissors slide in open, snip shut, open a little and leave.
      const slide = 1 - ease(band(s, 1.45, 2.0)) + ease(band(s, 2.9, 3.5));
      const open = 0.42 * ease(band(s, 1.5, 2.0)) * (1 - band(s, cut - 0.18, cut)) + 0.2 * ease(band(s, 2.6, 2.9)); // prettier-ignore
      const shown = on && s > 1.4 && s < 3.5 ? 1 : 0;
      for (const [name, sign] of [
        ["bladeA", 1],
        ["bladeB", -1],
      ])
        out.parts[name] = { angle: sign * open, offset: mul(SCISSORS_OUT, slide), visible: shown };
    }

build:
build(k, o) {
      reseed(k, o);
      const rand = k.rand;
      const crown = k.part("crown", { pivot: [0, 0, 0], axis: SHAKE_AXIS });
      const SW = { ...sway(0.014, 0), part: crown };
      const tree = growTree(rand, {
        length: 0.5,
        radius: 0.15,
        depth: 3,
        kids: [
          [3, 4],
          [2, 3],
          [2, 2],
        ],
        spread: [0.9, 0.7, 0.7],
        ratio: [1.2, 0.7, 0.6],
        radRatio: [0.62, 0.62, 0.6],
        from: [0.8, 0.45, 0.4],
        wobble: [0.15, 0.4, 0.5],
        up: [0, 0.08, 0.02],
        taper: 0.6,
      });
      const bark = barkColor("#5a4a3a", "#2a2018", { furrows: 8 });
      addBranches(k, tree.branches, { color: bark, flare: 0.6, gnarl: 0.08, extra: SW });
      addRoots(k, 6, 0.1, 0, bark);
      const C = [0, 1.18, 0];
      const RX = 1.0;
      const RY = 0.5;
      // A crown of leaves over the top.
      const clumps = domeClumps(k, {
        c: C,
        r: [RX * 0.9, RY, RX * 0.9],
        n: 30,
        size: [0.2, 0.26],
        below: 0.05,
        tips: [],
      });
      const greens = ["#3a5a1c", "#5a7f26", "#86a83a", "#b4cc5c", "#dfe89a"];
      foliage(k, clumps, {
        share: 0.2,
        size: 1.0,
        tilt: 1.4,
        ...SW,
        color: (t) => ramp(greens, t),
      });
      // Strands hang in curtains from the crown, with gaps between them where
      // the trunk shows through; the curtains facing the viewer are shorter.
      const strands = [];
      let tot = 0;
      const CURTAINS = 15;
      for (let ci = 0; ci < CURTAINS; ci++) {
        const ac = (ci / CURTAINS) * TAU + (rand() - 0.5) * 0.2;
        const front = Math.max(0, Math.cos(ac - 0.5));
        const lo = 0.2 + rand() * 0.25 + front * front * 0.35;
        const tone = rand();
        for (let i = 0; i < 30; i++) {
          const y = 0.05 + 0.85 * Math.pow(rand(), 1.3);
          const a = ac + (rand() - 0.5) * 0.3;
          const rr = Math.sqrt(1 - y * y);
          const start = [C[0] + Math.sin(a) * rr * RX, C[1] + y * RY, C[2] + Math.cos(a) * rr * RX];
          const end = lo + rand() * 0.15 + (1 - rr) * 0.3;
          const len = start[1] - end;
          // Which band of curtains across the tree (left to right on screen).
          const across = (start[0] * WIND[0] + start[2] * WIND[2]) / (RX * 1.05);
          const band4 = clamp(Math.floor(((across + 1) / 2) * 4), 0, 3);
          strands.push({ start, a, len, out: 0.08 + 0.12 * rr, tone: tone + 0.3 * (rand() - 0.5), band: band4 }); // prettier-ignore
          tot += len;
        }
      }
      const cum = [];
      let acc = 0;
      for (const s of strands) cum.push((acc += s.len));
      k.cloud({ share: 0.5, size: 0.85 }, (r) => {
        const x = r() * tot;
        let lo = 0;
        let hi = cum.length - 1;
        while (lo < hi) {
          const mid = (lo + hi) >> 1;
          if (cum[mid] < x) lo = mid + 1;
          else hi = mid;
        }
        const s = strands[lo];
        const u = r();
        const bow = Math.sin(Math.min(1, u * 3) * Math.PI * 0.5);
        const p = [
          s.start[0] + Math.sin(s.a) * s.out * bow + (r() - 0.5) * 0.018,
          s.start[1] - s.len * u,
          s.start[2] + Math.cos(s.a) * s.out * bow + (r() - 0.5) * 0.018,
        ];
        const facing = dot(unit([Math.sin(s.a), 0.2, Math.cos(s.a)]), LIGHT);
        const tone = clamp(0.2 + 0.3 * facing + 0.3 * u + 0.35 * (s.tone - 0.5) + 0.1 * r(), 0, 1);
        // Bent by the breeze: further the lower it hangs, lifting a little.
        const drop = s.len * u;
        const bend = WILLOW_BEND * Math.pow(drop, 1.5);
        return {
          p,
          dir: [
            Math.sin(s.a) * 0.3 + (r() - 0.5) * 0.4,
            -1,
            Math.cos(s.a) * 0.3 + (r() - 0.5) * 0.4,
          ],
          stretch: 2.6,
          color: ramp(greens, tone),
          part: crown,
          to: [
            p[0] + WIND[0] * bend,
            p[1] + (0.45 * bend * bend) / Math.max(0.2, drop),
            p[2] + WIND[2] * bend,
          ],
          channel: s.band,
        };
      });
      grassMound(k, 1.05, 0, { h: 0.07 });
      k.fitMorphs = false;
    }

drive:
drive(t, c, out) {
      const s = progress(c.breeze) * WILLOW_SECS;
      const on = c.breeze > 0;
      out.morph = [0, 1, 2, 3].map((g) => {
        const idle = 0.16 * Math.sin(t * 0.9 + g * 0.8);
        if (!on) return idle;
        const tau = s - (0.15 + 0.32 * g);
        let push = 0;
        if (tau > 0 && tau < 0.5) push = Math.sin((Math.PI / 2) * (tau / 0.5));
        else if (tau >= 0.5) push = Math.cos(3.6 * (tau - 0.5)) * Math.exp(-(tau - 0.5) / 0.9);
        return idle + push * (1 - band(s, WILLOW_SECS - 0.6, WILLOW_SECS));
      });
      out.parts.crown = { angle: on ? -0.025 * bump(s, 0.3, 0.9, 1.4, 2.6) : 0 };
    }

build:
build(k) {
      const rand = k.rand;
      const SW = sway(0.01, 0);
      const H = [0, 1.28, 0];
      const F = unit([0.28, 0.42, 1]);
      const Q = quatFromTo([0, 1, 0], F);
      // The head turns about the top of the stem (it no longer sways; it
      // nods, and turns to the sun).
      const pivot = add(H, quatRotate(Q, [0, -0.12, 0]));
      const head = k.part("head", { pivot });
      const HD = { part: head };
      const toW = (p) => add(H, quatRotate(Q, p));
      const Rd = 0.34;
      // The seed head: seeds on a golden-angle spiral, florets in the middle.
      const N = 1150;
      const spacing = Rd * Math.sqrt(Math.PI / N);
      k.cloud({ share: 0.2, size: 0.8, flat: 0.3 }, (r) => {
        const j = Math.floor(r() * N);
        const rr0 = Rd * Math.sqrt((j + 0.5) / N);
        const a0 = j * GOLDEN;
        const jr = spacing * 0.42 * Math.sqrt(r());
        const ja = r() * TAU;
        const x = Math.cos(a0) * rr0 + Math.cos(ja) * jr;
        const z = Math.sin(a0) * rr0 + Math.sin(ja) * jr;
        const f = rr0 / Rd;
        const y = 0.05 * (1 - f * f) + 0.006 * (1 - jr / spacing);
        const edge = jr / (spacing * 0.42);
        const seed = ((j * 7919) % 97) / 97;
        let col;
        if (f < 0.26) col = mix("#6f7a22", "#a8a032", seed * 0.6 + 0.4 * (1 - edge));
        else if (f < 0.42)
          col = seed > 0.55 ? mix("#e8a817", "#f6cf3a", r()) : mix("#6a3a12", "#8a5018", seed);
        else if (f > 0.93) col = mix("#b8620e", "#e39a1c", seed);
        else col = mix(mix("#2c1a0c", "#4a2c12", seed), "#140c06", 0.6 * edge);
        const nrm = quatRotate(Q, unit([x * 0.25, 1, z * 0.25]));
        return { p: toW([x, y, z]), n: nrm, color: lit(col, nrm, 0.35), ...HD };
      });
      k.add(k.disc(Rd * 1.02), {
        pos: H,
        quat: Q,
        ...HD,
        color: (c) => (c.n[1] > 0 && dot(c.n, F) > 0 ? "#24160a" : "#4f7a2a"),
      });
      // The back of the head, and green bracts around it.
      k.add(k.ellipsoid(Rd * 1.05, 0.1, Rd * 1.05), {
        pos: toW([0, -0.07, 0]),
        quat: Q,
        ...HD,
        color: (c) =>
          dot(c.n, F) > 0.3 ? null : lit(mix("#3f6a22", "#5f8a30", c.rand()), c.n, 0.4),
      });
      // Two rings of golden ray petals.
      const petal = (L, W) =>
        blade(k, {
          L,
          W,
          cup: -0.35,
          grid: 12,
          width: (v) => Math.sin(Math.PI * Math.pow(Math.min(v, 1), 0.7)) ** 0.8,
          bend: (v) => 0.05 * v * v,
        });
      // Two rings of 24 petals: 48 tokens.
      const rings = [
        { n: 24, L: 0.34, W: 0.078, lift: 12, off: 0, rr: Rd * 0.94, tone: 0.9 },
        { n: 24, L: 0.3, W: 0.076, lift: 24, off: 0.5, rr: Rd * 0.9, tone: 1 },
      ];
      const petals = [];
      const bracts = blade(k, { L: 0.12, W: 0.04, grid: 6 });
      for (const ring of rings) {
        for (let i = 0; i < ring.n; i++) {
          const th = ((i + ring.off) / ring.n) * TAU + (rand() - 0.5) * 0.08;
          const q = quatMul(
            Q,
            quatEuler(-90 + ring.lift + (rand() - 0.5) * 10, (th * 180) / Math.PI + 180, 0),
          );
          const base = toW([Math.sin(th) * ring.rr, 0.01, Math.cos(th) * ring.rr]);
          const L = ring.L * (0.9 + 0.2 * rand());
          const warm = rand();
          petals.push({
            base,
            axis: quatRotate(Q, [Math.cos(th), 0, -Math.sin(th)]),
            lift: (ring.lift * Math.PI) / 180,
          });
          k.add(ring === rings[0] ? petal(L, ring.W) : petal(L * 0.95, ring.W), {
            pos: base,
            quat: q,
            flat: 0.25,
            kind: "token",
            params: [petals.length - 1, 0],
            color: (c) => {
              const vein = Math.abs(Math.sin(c.u * Math.PI * 9)) < 0.18 ? 0.88 : 1;
              let col = mix("#d9820a", "#f7b818", smoothstep(0, 0.35, c.v));
              col = mix(col, "#ffd84a", 0.5 * smoothstep(0.5, 1, c.v) + 0.15 * warm);
              return lit(shade(col, vein * ring.tone), c.n, 0.3);
            },
          });
        }
      }
      for (let i = 0; i < 22; i++) {
        const th = (i / 22) * TAU;
        k.add(bracts, {
          pos: toW([Math.sin(th) * Rd, -0.05, Math.cos(th) * Rd]),
          quat: quatMul(Q, quatEuler(-120, (th * 180) / Math.PI + 180, 0)),
          weight: 1.5,
          ...HD,
          color: (c) => lit(mix("#3a6a20", "#6a9a38", c.v), c.n, 0.3),
        });
      }
      // The stem, and big heart-shaped leaves.
      const back = toW([0, -0.12, 0]);
      const stemPts = [
        [0.02, 0, 0.02],
        [0.04, 0.35, 0],
        [0.01, 0.75, -0.04],
        [back[0] * 0.5, back[1] - 0.25, back[2] - 0.12],
        back,
      ];
      const stem = spline(stemPts);
      k.add(
        k.tube(stem, (t) => 0.04 * (1 - 0.3 * t), { samples: 64, grid: 20 }),
        {
          flat: 0.3,
          jitter: 0.1,
          color: (c) => lit(mix("#4a7a26", "#6a9a36", c.fbm(c.p[0] * 30, c.p[1] * 8, 0)), c.n, 0.4),
        },
      );
      const leaf = (L) =>
        blade(k, {
          L,
          W: L * 0.42,
          cup: 0.25,
          grid: 16,
          width: (v) => Math.sin(Math.PI * Math.pow(Math.min(v, 1), 0.6)) ** 0.9 * (1.1 - 0.3 * v),
          bend: (v) => 0.25 * v * v,
        });
      for (const [t, az, L] of [
        [0.28, 1.9, 0.42],
        [0.46, -1.2, 0.46],
        [0.62, 0.9, 0.36],
      ]) {
        const at = stem(t);
        const d = [Math.sin(az), 0, Math.cos(az)];
        const tip = add(at, [d[0] * 0.08, 0.02, d[2] * 0.08]);
        k.add(k.tube(spline([at, tip]), 0.012, { samples: 8, grid: 6 }), {
          ...SW,
          color: "#5a8a30",
        });
        k.add(leaf(L), {
          pos: tip,
          rot: [-62, (az * 180) / Math.PI, 0],
          flat: 0.25,
          ...SW,
          color: (c) => {
            const mid = Math.abs(c.u - 0.5) < 0.025;
            const vein = Math.abs(Math.sin((c.v * 7 + Math.abs(c.u - 0.5) * 5) * Math.PI)) < 0.12;
            const col = mix(
              "#2e5a1c",
              "#4f7f2a",
              0.5 + 0.5 * c.fbm(c.p[0] * 8, c.p[1] * 8, c.p[2] * 8),
            );
            return lit(mid || vein ? mix(col, "#8ab050", 0.5) : col, c.n, 0.35);
          },
        });
      }
      grassMound(k, 0.42, 0, { h: 0.05, blades: 0.02, bladeLen: 0.12 });
      // The sun (hidden until a tap), up at the top left, in front.
      const sunAt = [-0.42, 1.66, 0.55];
      const sun = k.part("sun", { pivot: sunAt });
      k.add(k.sphere(0.09), {
        pos: sunAt,
        part: sun,
        fit: false,
        weight: 4,
        pattern: false,
        color: (c) =>
          mix("#fff2a0", "#ffa81a", smoothstep(0.1, 1, 1 - dot(c.n, [0.43, 0.3, 0.85]))),
      });
      k.cloud({ share: 0.012, size: 1.6, pattern: false, part: sun, fit: false }, (r) => {
        const d = randDir(r);
        const ray = r() < 0.55;
        const a = Math.floor(r() * 12) * (TAU / 12);
        const dir = ray ? quatRotate(quatFromTo([0, 0, 1], [0.43, 0.3, 0.85]), [Math.cos(a), Math.sin(a), 0]) : d; // prettier-ignore
        const far = ray ? 0.12 + 0.1 * r() : 0.1 + 0.05 * r();
        return {
          p: add(sunAt, mul(dir, far)),
          dir: ray ? dir : undefined,
          stretch: ray ? 2.5 : undefined,
          color: ray ? "#ffc21a" : "#ffd860",
          opacity: ray ? 0.95 : 0.3,
        };
      });
      k.data = { pivot, face: F, toSun: unit(sub(sunAt, H)), petals };
    }

drive:
drive(t, c, out, info) {
      const s = progress(c.sun) * SUN_SECS;
      const on = c.sun > 0;
      const d = info.data;
      if (!d) return;
      const turn = on ? ease(band(s, 0.3, 1.6)) * (1 - ease(band(s, 3.7, 5.0))) : 0;
      const open = on ? ease(band(s, 0.6, 1.8)) * (1 - ease(band(s, 3.9, 5.1))) : 0;
      const nod = quatAxisAngle([1, 0, 0], 0.03 * Math.sin(t * 0.9));
      const Qh = quatMul(turnPart(d.face, d.toSun, 0.6 * turn), nod);
      out.parts.head = { quat: Qh };
      const shine = on ? ease(band(s, 0, 0.7)) * (1 - ease(band(s, 4.2, 5.2))) : 0;
      out.parts.sun = { scale: 0.01 + 0.99 * shine, offset: [0, -0.25 * (1 - shine), 0] };
      out.tokens = d.petals.map((pt) => {
        const q = quatMul(Qh, quatAxisAngle(pt.axis, (pt.lift + 0.3) * open));
        const b = pt.base;
        const rb = quatRotate(Qh, sub(b, d.pivot));
        return { base: b, quat: q, offset: sub(add(d.pivot, rb), b) };
      });
    }

build:
build(k, o) {
      const rand = k.rand;
      const SW = sway(0.008, 0);
      const base = o.color;
      const C = [0, 1.02, 0];
      const A = unit([0.15, 1, 0.62]);
      const Q = quatFromTo([0, 1, 0], A);
      // The bloom nods on its stem (the petals are tokens, the sepals and
      // hip a part, turned together about the top of the stem).
      const pivot = add(C, quatRotate(Q, [0, -0.14, 0]));
      const head = k.part("head", { pivot });
      const HD = { part: head };
      const petals = [];
      const VIEWH = unit([0.43, 0, 0.9]);
      // Petals on a spiral: a tight bud in the middle, cupped petals around
      // it, and outer petals whose rims roll back.
      const N = 30;
      for (let i = 0; i < N; i++) {
        const f = i / (N - 1);
        const th = i * GOLDEN;
        const L = 0.13 + 0.2 * Math.pow(f, 0.6);
        const span = 3.4 - 1.4 * f;
        const rho = 0.008 + 0.045 * f;
        const tilt = 0.03 + 0.34 * Math.pow(f, 1.6);
        const curl = 0.28 * smoothstep(0.45, 1, f);
        const bow = 0.3 * (0.25 + f);
        const h0 = 0.05 * (1 - f) - 0.06 * f;
        const shape = k.param(
          (u, v) => {
            const x = 2 * u - 1;
            const vv = v * (1 - 0.22 * x * x);
            const wf = 0.45 + 0.55 * Math.sin(Math.min(1, vv * 1.7) * Math.PI * 0.5);
            const a = th + x * 0.5 * span * wf;
            const v4 = vv * vv * vv * vv;
            const rad =
              rho + L * (Math.sin(tilt) * vv + bow * Math.sin(Math.PI * vv)) + curl * L * v4;
            const y = h0 + L * Math.cos(tilt) * vv - curl * 0.45 * L * v4;
            return [rad * Math.sin(a), y, rad * Math.cos(a)];
          },
          { grid: 18 },
        );
        const depth = 0.62 + 0.38 * f;
        const out = quatRotate(Q, [Math.sin(th), 0, Math.cos(th)]);
        petals.push({
          base: add(C, quatRotate(Q, [rho * Math.sin(th), h0, rho * Math.cos(th)])),
          axis: quatRotate(Q, [Math.cos(th), 0, -Math.sin(th)]),
          open: 0.05 + 0.55 * Math.pow(f, 1.3),
          // Its outer face (the petal leans out from the axis by about tilt).
          face: unit(sub(mul(out, Math.cos(tilt + 0.3)), mul(A, Math.sin(tilt + 0.3)))),
          front: f > 0.7 ? dot(out, VIEWH) : -2,
        });
        k.add(shape, {
          pos: C,
          quat: Q,
          flat: 0.22,
          kind: "token",
          params: [i, 0],
          color: (c) => {
            const x = Math.abs(2 * c.u - 1);
            const top = 1 - 0.22 * x * x;
            const edge = smoothstep(top - 0.14, top, c.v);
            let col = mix(shade(base, 0.45), base, smoothstep(0, 0.5, c.v));
            col = mix(col, mix(base, "#ffe0e6", 0.45), 0.8 * edge);
            const vein = 0.94 + 0.06 * Math.sin(c.u * 40 + c.fbm(c.p[0] * 20, c.p[1] * 20, 0) * 3);
            return lit(shade(col, depth * vein), c.n, 0.35);
          },
        });
      }
      // Sepals curling down under the bloom, and the hip.
      const sepal = blade(k, { L: 0.16, W: 0.03, grid: 8, bend: (v) => -0.3 * v * v });
      for (let i = 0; i < 5; i++) {
        const th = (i / 5) * TAU + 0.3;
        k.add(sepal, {
          pos: add(C, quatRotate(Q, [Math.sin(th) * 0.05, -0.06, Math.cos(th) * 0.05])),
          quat: quatMul(Q, quatEuler(110, (th * 180) / Math.PI, 0)),
          weight: 1.5,
          ...HD,
          color: (c) => lit(mix("#2f5a1e", "#5a8a30", c.v), c.n, 0.3),
        });
      }
      k.add(k.ellipsoid(0.055, 0.07, 0.055), {
        pos: add(C, quatRotate(Q, [0, -0.1, 0])),
        quat: Q,
        ...HD,
        color: (c) => lit("#3f6a22", c.n, 0.4),
      });
      // Stem with thorns and compound leaves.
      const top = add(C, quatRotate(Q, [0, -0.14, 0]));
      const stem = spline([[0.03, 0, 0], [-0.02, 0.35, 0.02], [0.02, 0.7, 0.04], top]);
      k.add(k.tube(stem, 0.022, { samples: 64, grid: 16 }), {
        flat: 0.3,
        color: (c) =>
          lit(mix("#2f5a1c", "#4f7a2a", c.fbm(c.p[0] * 20, c.p[1] * 20, 0) * 0.5 + 0.5), c.n, 0.4),
      });
      for (let i = 0; i < 9; i++) {
        const t = 0.08 + i * 0.09;
        const p = stem(t);
        const a = i * 2.4;
        const d = [Math.sin(a), 0.4, Math.cos(a)];
        k.add(k.cone(0.012, 0.0005, 0.045, { caps: false }), {
          pos: add(p, mul(unit(d), 0.03)),
          quat: quatFromTo([0, 1, 0], d),
          weight: 3,
          color: (c) => lit(mix("#6a3a22", "#a05a3a", c.v), c.n, 0.3),
        });
      }
      const leaflet = blade(k, {
        L: 0.13,
        W: 0.045,
        cup: 0.2,
        grid: 10,
        width: (v) =>
          Math.sin(Math.PI * v) ** 0.7 * (1 - 0.1 * Math.abs(Math.sin(v * Math.PI * 7))),
        bend: (v) => 0.1 * v * v,
      });
      for (const [t, az] of [
        [0.32, 1.7],
        [0.55, -1.4],
        [0.74, 0.4],
      ]) {
        const p0 = stem(t);
        const d = [Math.sin(az), 0.35, Math.cos(az)];
        const end = add(p0, mul(unit(d), 0.2));
        k.add(k.tube(spline([p0, end]), 0.006, { samples: 8, grid: 6 }), {
          ...SW,
          color: "#3f6a22",
        });
        // Leaflets in pairs along the petiole, one at the tip.
        for (const [s, side] of [
          [0.4, -1],
          [0.4, 1],
          [0.75, -1],
          [0.75, 1],
          [1, 0],
        ]) {
          const q = lerp3(p0, end, s);
          const yaw = (az + side * 1.1) * (180 / Math.PI);
          k.add(leaflet, {
            pos: q,
            rot: [-70 + 10 * Math.abs(side), yaw, 0],
            ...SW,
            color: (c) => {
              const mid = Math.abs(c.u - 0.5) < 0.04;
              const col = mix(
                "#1f4a1a",
                "#3f7a2a",
                c.fbm(c.p[0] * 30, c.p[1] * 30, c.p[2] * 30) * 0.5 + 0.5,
              );
              return lit(mid ? mix(col, "#7aa04a", 0.4) : col, c.n, 0.4);
            },
          });
        }
      }
      grassMound(k, 0.36, 0, { h: 0.04, blades: 0.015, bladeLen: 0.1 });
      // The petal that drops: the outer one facing the camera most.
      let drop = 0;
      petals.forEach((pt, i) => {
        if (pt.front > petals[drop].front) drop = i;
      });
      const lx = -0.06;
      const lz = 0.1;
      k.data = { pivot, petals, drop, land: [lx, moundTop(0.36, 0, 0.04, Math.hypot(lx, lz)) + 0.01, lz] }; // prettier-ignore
    }

drive:
drive(t, c, out, info) {
      const s = progress(c.bloom) * ROSE_SECS;
      const on = c.bloom > 0;
      const d = info.data;
      if (!d) return;
      const open = on ? ease(band(s, 0.1, 1.4)) * (1 - ease(band(s, 3.8, 5.0))) : 0;
      const Qh = quatAxisAngle([1, 0, 0], 0.03 * Math.sin(t * 0.8));
      out.parts.head = { quat: Qh };
      out.tokens = d.petals.map((pt, i) => {
        const q = quatMul(Qh, quatAxisAngle(pt.axis, pt.open * open));
        const off = sub(add(d.pivot, quatRotate(Qh, sub(pt.base, d.pivot))), pt.base);
        if (i !== d.drop || !on || s < 1.5) return { base: pt.base, quat: q, offset: off };
        if (s > 4.5)
          return { base: pt.base, quat: q, offset: off, visible: ease(band(s, 4.7, 5.3)) };
        // Loose, it keeps the turn it had when it let go.
        const q0 = quatAxisAngle(pt.axis, pt.open);
        const fl = flutterDown(pt.base, d.land, quatRotate(q0, pt.face), band(s, 1.5, 3.7), { swings: 2.5, width: 0.1, spin: 1.5, rock: 0.6 }); // prettier-ignore
        return {
          base: pt.base,
          quat: quatMul(fl.quat, q0),
          offset: fl.offset,
          visible: 1 - ease(band(s, 4.0, 4.5)),
        };
      });
      // Sound C: the daisy's soft tap as the loose petal lands.
      crossing(c, "rose", on ? s : 0, [3.7 - LEAD], () =>
        out.cues.push({ ...PETAL_LAND, at: Math.max(0, 3.7 - s) }),
      );
    }

build:
build(k) {
      const rand = k.rand;
      const SW = sway(0.012, 0);
      const H = [0.05, 1.3, 0];
      const stem = spline([
        [0, 0, 0],
        [0.04, 0.45, 0.02],
        [0.07, 0.9, 0],
        [H[0], H[1] - 0.04, H[2]],
      ]);
      k.add(
        k.tube(stem, (t) => 0.016 * (1 - 0.25 * t), { samples: 48, grid: 12 }),
        {
          flat: 0.3,
          ...SW,
          color: (c) => lit(mix("#6f9a3a", "#a8b870", c.t * 0.6), c.n, 0.4),
        },
      );
      k.add(k.sphere(0.045), {
        pos: H,
        weight: 3,
        ...SW,
        color: (c) => lit(mix("#b89a5a", "#8a6a3a", c.rand()), c.n, 0.3),
      });
      // Seeds on a sphere, in twelve groups that fly off separately.
      const dirs = [];
      const n = 190;
      for (let i = 0; i < n; i++) {
        const y = 1 - ((i + 0.5) / n) * 2;
        if (y < -0.8) continue;
        const r = Math.sqrt(1 - y * y);
        dirs.push([Math.cos(i * GOLDEN) * r, y, Math.sin(i * GOLDEN) * r]);
      }
      const centres = SEED_GROUPS;
      const groupOf = dirs.map((d) => {
        let best = 0;
        let bd = -2;
        centres.forEach((c, g) => {
          const v = dot(c, d);
          if (v > bd) {
            bd = v;
            best = g;
          }
        });
        return best;
      });
      const parts = centres.map((c, g) => k.part(`seeds${g}`, { pivot: H }));
      const R0 = 0.05;
      const R1 = 0.3;
      k.cloud({ share: 0.5, size: 0.55, pattern: false }, (r) => {
        const j = Math.floor(r() * dirs.length);
        const d = dirs[j];
        const part = parts[groupOf[j]];
        const u = r();
        if (u < 0.3) {
          // The beak: a fine stalk from the seed to the tuft.
          const s = R0 + 0.03 + (R1 - R0 - 0.03) * r();
          return {
            p: add(H, mul(d, s)),
            dir: d,
            stretch: 3,
            color: "#f2efe6",
            opacity: 0.8,
            part,
            ...SW,
          };
        }
        if (u < 0.36) {
          // The seed itself.
          return {
            p: add(H, mul(d, R0 + 0.02 * r())),
            dir: d,
            stretch: 2,
            size: 1.3,
            color: "#7a5a32",
            part,
            ...SW,
          };
        }
        // The pappus: fine hairs fanning out from the tip.
        const [e1, e2] = perp(d);
        const a = r() * TAU;
        const spread = 0.35 + 0.6 * r();
        const hair = unit(
          add(
            mul(d, Math.cos(spread)),
            add(mul(e1, Math.cos(a) * Math.sin(spread)), mul(e2, Math.sin(a) * Math.sin(spread))),
          ),
        );
        const along = 0.075 * r();
        return {
          p: add(add(H, mul(d, R1)), mul(hair, along)),
          dir: hair,
          stretch: 2.5,
          color: mix("#ffffff", "#e8e4da", r() * 0.5),
          opacity: 0.55 + 0.35 * r(),
          part,
          ...SW,
        };
      });
      // A few loose seeds drifting away.
      k.cloud({ share: 0.003, size: 1.4, pattern: false }, (r) => ({
        p: add(H, [0.25 + r() * 0.3, (r() - 0.3) * 0.4, (r() - 0.5) * 0.4]),
        color: "#ffffff",
        opacity: 0.7,
        kind: "rise",
        params: [0.9, r()],
      }));
      // A yellow flower still in bloom, lower down.
      const Y = [-0.36, 0.52, 0.12];
      const ystem = spline([[-0.1, 0, 0.05], [-0.2, 0.25, 0.1], [-0.3, 0.45, 0.12], Y]);
      k.add(k.tube(ystem, 0.013, { samples: 32, grid: 10 }), {
        ...SW,
        color: (c) => lit("#6f9a3a", c.n, 0.4),
      });
      const YF = unit([0.25, 0.8, 0.6]);
      const YQ = quatFromTo([0, 1, 0], YF);
      k.cloud({ share: 0.06, size: 0.8, flat: 0.3 }, (r) => {
        const a = r() * TAU;
        const rr = 0.13 * Math.sqrt(r());
        const f = rr / 0.13;
        const local = [Math.sin(a) * rr, 0.05 * (1 - f * f) + 0.02, Math.cos(a) * rr];
        const nrm = quatRotate(YQ, unit([Math.sin(a) * f, 1, Math.cos(a) * f]));
        return {
          p: add(Y, quatRotate(YQ, local)),
          dir: quatRotate(YQ, [Math.sin(a), 0.2, Math.cos(a)]),
          stretch: 1.8,
          color: lit(mix("#e8a810", "#ffe04a", f * 0.8 + 0.2 * r()), nrm, 0.3),
          ...SW,
        };
      });
      k.add(k.ellipsoid(0.07, 0.04, 0.07), {
        pos: add(Y, quatRotate(YQ, [0, -0.02, 0])),
        quat: YQ,
        ...SW,
        color: (c) => lit("#4f7a2a", c.n, 0.4),
      });
      // Toothed leaves in a rosette at the foot.
      const leaf = blade(k, {
        L: 0.42,
        W: 0.07,
        grid: 16,
        width: (v) =>
          Math.sin(Math.PI * Math.pow(v, 0.8)) ** 0.8 *
          (0.45 + 0.55 * Math.abs(Math.sin(v * Math.PI * 4.5))),
        bend: (v) => -0.05 * v,
      });
      for (let i = 0; i < 7; i++) {
        const az = (i / 7) * TAU + rand() * 0.4;
        k.add(leaf, {
          pos: [0, 0.03, 0],
          rot: [-78 + rand() * 10, (az * 180) / Math.PI, 0],
          ...SW,
          color: (c) => {
            const mid = Math.abs(c.u - 0.5) < 0.05;
            return lit(mid ? "#8aa860" : mix("#2f5a1c", "#4a7a2a", c.rand()), c.n, 0.4);
          },
        });
      }
      grassMound(k, 0.55, 0, { h: 0.05, blades: 0.02, bladeLen: 0.1 });
    }

drive:
drive(t, c, out) {
      const s = 1 - c.blow;
      // A gust bends the stalk while the seeds fly.
      out.amount = 1 + 10 * c.blow * (1 - c.blow);
      for (let g = 0; g < 12; g++) {
        const delay = (g / 12) * 0.22;
        const q = clamp((s - delay) / 0.6, 0, 1);
        const e = 1 - (1 - q) * (1 - q);
        const dir = BLOW[g];
        let vis = 1 - smoothstep(0.55, 0.95, q);
        let off = [dir[0] * 1.6 * e, dir[1] * 1.6 * e + 0.5 * q * q, dir[2] * 1.6 * e];
        if (s > 0.82) {
          // Home again, growing back.
          off = [0, 0, 0];
          vis = smoothstep(0.84, 1, s);
        }
        if (c.blow === 0) {
          off = [0, 0, 0];
          vis = 1;
        }
        const spin = quatAxisAngle(cross(dir, [0, 1, 0]), -1.2 * e);
        out.parts[`seeds${g}`] = { offset: off, quat: spin, visible: vis };
      }
    }

build:
build(k, o) {
      const rand = k.rand;
      const SW = sway(0.01, 0);
      const cup = (R, Hh) => (u, v, th, span) => {
        const x = 2 * u - 1;
        const vv = v * (1 - 0.32 * Math.pow(Math.abs(x), 1.6));
        const r =
          R *
          (0.25 + 0.75 * Math.sin(Math.min(1, vv * 1.25) * Math.PI * 0.62)) *
          (1 - 0.12 * vv * vv);
        const a = th + x * span * 0.5;
        return [r * Math.sin(a), Hh * vv, r * Math.cos(a)];
      };
      const petals = [];
      const flowers = [
        { x: 0, z: 0, h: 1.2, lean: [0.08, 1, 0.12], s: 1 },
        { x: -0.32, z: -0.15, h: 0.95, lean: [-0.3, 1, 0.1], s: 0.9 },
        { x: 0.3, z: -0.05, h: 0.82, lean: [0.3, 1, 0.2], s: 0.85 },
      ];
      flowers.forEach((fl, fi) => {
        const A = unit(fl.lean);
        const Q = quatFromTo([0, 1, 0], A);
        const top = [fl.x + A[0] * 0.3, fl.h, fl.z + A[2] * 0.3];
        const stem = spline([
          [fl.x * 0.3, 0, fl.z * 0.3],
          [fl.x * 0.7, fl.h * 0.5, fl.z * 0.7],
          top,
        ]);
        k.add(k.tube(stem, 0.022 * fl.s, { samples: 48, grid: 14 }), {
          color: (c) => lit(mix("#4f7f3a", "#7aa050", c.t), c.n, 0.4),
        });
        const R = 0.17 * fl.s;
        const Hh = 0.34 * fl.s;
        const f = cup(R, Hh);
        const tint = fi === 0 ? o.color : mix(o.color, fi === 1 ? "#ffffff" : "#000000", 0.12);
        for (let i = 0; i < 6; i++) {
          const inner = i % 2;
          const th = (i / 6) * TAU + rand() * 0.1;
          const span = inner ? 1.25 : 1.45;
          const shape = k.param((u, v) => f(u, v, th, span), { grid: 16 });
          const sc = inner ? 0.97 : 1;
          petals.push({
            flower: fi,
            base: add(top, quatRotate(Q, [R * 0.25 * sc * Math.sin(th), 0, R * 0.25 * sc * Math.cos(th)])), // prettier-ignore
            axis: quatRotate(Q, [Math.cos(th), 0, -Math.sin(th)]),
            angle: inner ? 0.95 : 1.15,
          });
          k.add(shape, {
            pos: top,
            quat: Q,
            scale: sc,
            flat: 0.22,
            kind: "token",
            params: [petals.length - 1, 0],
            color: (c) => {
              const x = Math.abs(2 * c.u - 1);
              let col = mix(shade(tint, 0.55), tint, smoothstep(0, 0.35, c.v));
              if (c.v < 0.12) col = mix(col, "#e8c23a", 0.5 * (1 - c.v / 0.12));
              col = mix(
                col,
                mix(tint, "#ffffff", 0.3),
                0.35 * smoothstep(0.2, 0.9, 1 - x) * smoothstep(0.4, 0.9, c.v),
              );
              return lit(shade(col, inner ? 0.85 : 1), c.n, 0.4);
            },
          });
        }
        // Inside: six dark stamens round a pale three-lobed pistil.
        const inside = (p) => add(top, quatRotate(Q, p));
        k.add(k.cylinder(0.02 * fl.s, 0.14 * fl.s), {
          pos: inside([0, 0.07 * fl.s, 0]),
          quat: Q,
          weight: 3,
          color: (c) => lit("#a8b868", c.n, 0.4),
        });
        for (let m = 0; m < 3; m++) {
          const a = (m / 3) * TAU;
          k.add(k.ellipsoid(0.018 * fl.s, 0.012 * fl.s, 0.018 * fl.s), {
            pos: inside([Math.sin(a) * 0.015 * fl.s, 0.145 * fl.s, Math.cos(a) * 0.015 * fl.s]),
            quat: Q,
            weight: 3,
            color: (c) => lit("#d0d088", c.n, 0.4),
          });
        }
        for (let m = 0; m < 6; m++) {
          const a = (m / 6) * TAU + 0.5;
          const foot = [Math.sin(a) * 0.03 * fl.s, 0.01, Math.cos(a) * 0.03 * fl.s];
          const head = [Math.sin(a) * 0.05 * fl.s, 0.12 * fl.s, Math.cos(a) * 0.05 * fl.s];
          k.add(
            k.tube(spline([inside(foot), inside(head)]), 0.005 * fl.s, { samples: 8, grid: 5 }),
            {
              weight: 3,
              color: "#3a2a3a",
            },
          );
          k.add(k.ellipsoid(0.01 * fl.s, 0.03 * fl.s, 0.01 * fl.s), {
            pos: inside([head[0], head[1] + 0.02 * fl.s, head[2]]),
            quat: Q,
            weight: 4,
            color: (c) => lit("#1e1420", c.n, 0.3),
          });
        }
        // Two broad leaves from the base.
        for (let j = 0; j < 2; j++) {
          const az = rand() * TAU;
          const L = 0.55 * fl.s + 0.1 * rand();
          k.add(
            blade(k, {
              L,
              W: 0.085 * fl.s,
              cup: 0.5,
              grid: 16,
              width: (v) => Math.sin(Math.PI * Math.pow(v, 0.75)) ** 0.7,
              bend: (v) => 0.35 * v * v,
            }),
            {
              pos: [fl.x * 0.3, 0.03, fl.z * 0.3],
              rot: [-12 - 12 * rand(), (az * 180) / Math.PI, 0],
              ...SW,
              color: (c) => lit(mix("#3f6f44", "#6a9a5a", c.v * 0.6 + 0.2 * c.rand()), c.n, 0.4),
            },
          );
        }
      });
      grassMound(k, 0.62, 0, { h: 0.05, blades: 0.02, bladeLen: 0.1 });
      k.data = { petals };
    }

