drive(t, c, out) {
      const s = progress(c.puff) * SPORE_SECS;
      const on = c.puff > 0;
      const dip = on ? -0.05 * Math.exp(-(((s - 0.1) / 0.09) ** 2)) + 0.02 * shake(s - 0.2, 1.2, 14) : 0; // prettier-ignore
      out.parts.cap = { offset: [0, dip, 0] };
      out.morph = [on ? easeOut(band(s, 0.12, 3.6)) : 0, 0, 0, 0];
      out.parts.spores = {
        visible: on ? ease(band(s, 0.1, 0.3)) * (1 - ease(band(s, 2.4, 3.8))) : 0,
      };
    }

build:
build(k, o) {
      reseed(k, o);
      const rand = k.rand;
      const SW = sway(0.016, 0);
      const fronds = [];
      const NF = 12;
      for (let i = 0; i < NF; i++) {
        const az = i * GOLDEN * 1.0 + (rand() - 0.5) * 0.4;
        const L = 0.9 + 0.35 * rand();
        const lift = 0.95 + 0.45 * rand();
        const h = [Math.sin(az), 0, Math.cos(az)];
        const at = (s) => [
          h[0] * L * 0.82 * s,
          0.1 + L * (lift * s - 0.75 * s * s),
          h[2] * L * 0.82 * s,
        ];
        const pinnae = [];
        const P = 26;
        for (let j = 0; j < P; j++) {
          const s = 0.1 + (0.88 * (j + 0.5)) / P;
          const T = unit(sub(at(s + 0.01), at(s - 0.01)));
          const Sr = unit(cross(T, [0, 1, 0]));
          const Np = unit(cross(Sr, T));
          const len = 0.3 * L * Math.sin(Math.PI * Math.min(1, s * 1.15)) ** 0.8 * (1 - 0.55 * s);
          for (const side of [-1, 1]) {
            const pd = unit(
              add(add(mul(Sr, side * Math.cos(0.5)), mul(T, Math.sin(0.5))), mul(Np, -0.2)),
            );
            pinnae.push({ base: at(s + side * 0.006), pd, Np, len, s });
          }
        }
        fronds.push({ at, pinnae, L });
        k.add(
          k.tube(at, (t) => 0.012 * (1 - 0.8 * t), { samples: 32, grid: 8 }),
          {
            ...SW,
            color: (c) => lit(mix("#5a6a2a", "#7a9a3a", c.t), c.n, 0.3),
          },
        );
      }
      const greens = ["#1f4a18", "#2f6a22", "#4a8a2e", "#7ab244", "#b0d46a"];
      k.cloud({ share: 0.62, size: 0.62, flat: 0.25 }, (r) => {
        const f = fronds[Math.floor(r() * NF)];
        const pn = f.pinnae[Math.floor(r() * f.pinnae.length)];
        const u = r();
        const side2 = r() < 0.5 ? -1 : 1;
        const pp = unit(add(mul(unit(cross(pn.Np, pn.pd)), side2), mul(pn.pd, 0.55)));
        const lp = 0.32 * pn.len * (1 - 0.75 * u);
        const v = r();
        const across = unit(cross(pp, pn.Np));
        const w = lp * 0.28 * Math.sin(Math.PI * v) * (r() - 0.5) * 2;
        const p = add(add(add(pn.base, mul(pn.pd, pn.len * u)), mul(pp, lp * v)), mul(across, w));
        const tone = clamp(
          0.3 + 0.3 * dot(pn.Np, LIGHT) + 0.25 * v + 0.2 * u - 0.1 * pn.s + 0.12 * (r() - 0.5),
          0,
          1,
        );
        return { p, n: pn.Np, color: ramp(greens, tone), ...SW };
      });
      // Two young fronds in the middle, built open but rolled up into
      // fiddleheads at rest (their leaflets hidden); a tap unrolls them.
      const young = [];
      [
        [0.06, 0.04, 1.3],
        [-0.07, -0.02, -0.9],
      ].forEach(([x, z, a], n) => {
        const h = [Math.sin(a), 0, Math.cos(a)];
        const L = 1.25;
        // Taller and more upright than the grown fronds: they stand above them.
        const at = (s) => [x + h[0] * L * 0.55 * s, 0.08 + L * (1.6 * s - 0.9 * s * s), z + h[2] * L * 0.55 * s]; // prettier-ignore
        const seg = (s) => Math.min(5, Math.floor(s * 6));
        k.add(
          k.tube(at, (t) => 0.02 * (1 - 0.5 * t), { samples: 48, grid: 10 }),
          {
            weight: 1.5,
            kind: "token",
            params: (c) => [n * 12 + seg(c.t), 0],
            color: (c) => lit(mix("#6a9a3a", "#9ac050", c.t), c.n, 0.4),
          },
        );
        const pinnae = [];
        for (let jn = 0; jn < 24; jn++) {
          const s = 0.18 + (0.8 * (jn + 0.5)) / 24;
          const T = unit(sub(at(s + 0.01), at(s - 0.01)));
          const Sr = unit(cross(T, [0, 1, 0]));
          const Np = unit(cross(Sr, T));
          const len = 0.3 * L * Math.sin(Math.PI * Math.min(1, s * 1.1)) ** 0.8 * (1 - 0.5 * s);
          for (const side of [-1, 1]) {
            const pd = unit(add(mul(Sr, side * Math.cos(0.5)), mul(T, Math.sin(0.5))));
            pinnae.push({ base: at(s), pd, Np, len, s });
          }
        }
        k.cloud({ share: 0.07, size: 0.62, flat: 0.25 }, (r) => {
          const pn = pinnae[Math.floor(r() * pinnae.length)];
          const u = r();
          const v = r();
          const across = unit(cross(pn.pd, pn.Np));
          const w = pn.len * 0.24 * Math.sin(Math.PI * u) * (r() - 0.5) * 2;
          const p = add(add(pn.base, mul(pn.pd, pn.len * u)), mul(across, w));
          const tone = clamp(0.45 + 0.3 * dot(pn.Np, LIGHT) + 0.25 * v + 0.12 * (r() - 0.5), 0, 1);
          return {
            p,
            n: pn.Np,
            color: ramp(["#2f6a22", "#4a8a2e", "#7ab244", "#b0d46a", "#d0e88a"], tone),
            kind: "token",
            params: [n * 12 + 6 + seg(pn.s), 0],
          };
        });
        young.push({
          J: [0, 1, 2, 3, 4, 5].map((q) => at(q / 6)),
          A: unit(cross(h, [0, 1, 0])),
        });
      });
      k.data = { young };
      grassMound(k, 0.72, 0, {
        h: 0.07,
        colors: ["#2f4a1a", "#46662a", "#6a8a3a"],
        soil: "#4a3220",
      });
      for (let i = 0; i < 4; i++) {
        const a = rand() * TAU;
        const s = 0.06 + rand() * 0.05;
        k.add(k.ellipsoid(s * 1.3, s * 0.7, s), {
          pos: [Math.sin(a) * 0.55, 0.03, Math.cos(a) * 0.55],
          rot: [0, rand() * 180, 0],
          color: (c) => {
            const moss = c.n[1] > 0.4 && c.noise(c.p[0] * 30, c.p[1] * 30, c.p[2] * 30) > -0.1;
            return lit(moss ? "#5a7a2a" : mix("#6f6a62", "#9a948a", c.rand()), c.n, 0.4);
          },
        });
      }
    }

drive:
drive(t, c, out, info) {
      const s = progress(c.unfurl) * FERN_SECS;
      const on = c.unfurl > 0;
      out.tokens = [];
      (info.data?.young || []).forEach((f, n) => {
        const d = 0.35 * n;
        const opened = (jn) =>
          on
            ? ease(band(s, 0.1 + d + 0.28 * jn, 0.9 + d + 0.28 * jn)) *
              (1 - ease(band(s, 4.2 + 0.08 * (5 - jn), 5.1 + 0.08 * (5 - jn))))
            : 0;
        const bend = FERN_CURL.map((b, jn) => b * (1 - opened(jn)));
        // Forward along the chain: each joint turns everything beyond it.
        let q = [0, 0, 0, 1];
        let shift = [0, 0, 0];
        for (let jn = 0; jn < 6; jn++) {
          const J = f.J[jn];
          const moved = add(add(f.J[0], quatRotate(q, sub(J, f.J[0]))), shift);
          q = quatMul(quatAxisAngle(f.A, bend[jn]), q);
          const piece = { base: J, quat: q, offset: sub(moved, J) };
          out.tokens[n * 12 + jn] = piece;
          out.tokens[n * 12 + 6 + jn] = { ...piece, visible: ease(band(opened(jn), 0.2, 0.9)) };
          shift = sub(moved, add(f.J[0], quatRotate(q, sub(J, f.J[0]))));
        }
      });
    }

build:
build(k, o) {
      reseed(k, o);
      const rand = k.rand;
      const H = 1.85;
      const R = 0.19;
      const RIBS = 16;
      const prof = (y) => {
        const top = H - R;
        const d = y > top ? Math.sqrt(Math.max(0, 1 - ((y - top) / R) ** 2)) : 1;
        return d * (1 + 0.06 * (1 - y / H));
      };
      const ribCol = (rib, c) => {
        let col = mix("#2c5a2a", "#5f8f42", smoothstep(-0.6, 0.9, rib));
        col = shade(col, 0.95 + 0.1 * c.noise(c.p[0] * 5, c.p[1] * 30, c.p[2] * 5));
        return lit(col, c.n, 0.45);
      };
      // The wedge that slides out for a look inside: towards the camera,
      // below the arms.
      const W0 = 0.45;
      const WW = 0.75;
      const Y0 = 0.1;
      const Y1 = 0.88;
      const wedge = k.part("wedge", { pivot: [0, Y0, 0], axis: [0, 1, 0] });
      const inWedge = (p) => {
        const a = Math.atan2(p[0], p[2]);
        return p[1] > Y0 && p[1] < Y1 && Math.abs(Math.atan2(Math.sin(a - W0), Math.cos(a - W0))) < WW; // prettier-ignore
      };
      const cutPart = (c) => (inWedge(c.p) ? wedge : 0);
      const edgeR = (a, y) => R * prof(y) * (1 + 0.07 * Math.cos(RIBS * a));
      k.add(
        k.param(
          (u, v) => {
            const a = u * TAU;
            const y = v * H;
            const rr = edgeR(a, y);
            return [Math.sin(a) * rr, y, Math.cos(a) * rr];
          },
          { grid: 72 },
        ),
        {
          interior: 0.1,
          core: "#b8c890",
          part: cutPart,
          color: (c) => ribCol(Math.cos(RIBS * c.u * TAU), c),
        },
      );
      // The cut faces, inside at rest: the trunk's (facing into the gap)
      // and the wedge's own. Wet pale flesh, a ring of woody ribs, pith.
      const flesh = (f, c, key) => {
        if (f > 0.93) return "#2c5a2a";
        if (f > 0.87) return "#5f8f42";
        if (Math.abs(f - 0.56) < 0.035 && key) return mix("#b89868", "#d8b888", c.rand());
        if (c.rand() < 0.05) return "#f4fff0";
        if (f < 0.14) return "#eef6d8";
        return mix(
          "#c8e4a0",
          "#a8d088",
          0.5 + 0.5 * c.noise(c.p[0] * 30, c.p[1] * 30, c.p[2] * 30),
        );
      };
      for (const part of [0, wedge]) {
        for (const a of [W0 - WW, W0 + WW]) {
          k.add(
            k.param(
              (u, v) => {
                const y = Y0 + v * (Y1 - Y0);
                const rr = u * edgeR(a, y) * 0.995;
                return [Math.sin(a) * rr, y, Math.cos(a) * rr];
              },
              { grid: 16 },
            ),
            { part, weight: 1.2, flat: 0.2, pattern: false, color: (c) => flesh(c.u, c, true) },
          );
        }
        for (const y of [Y0, Y1]) {
          k.add(
            k.param(
              (u, v) => {
                const a = W0 - WW + v * 2 * WW;
                const rr = u * edgeR(a, y) * 0.995;
                return [Math.sin(a) * rr, y, Math.cos(a) * rr];
              },
              { grid: 16 },
            ),
            {
              part,
              weight: 1.2,
              flat: 0.2,
              pattern: false,
              // The woody ribs show as a ring of dots across the cut.
              color: (c) => {
                const a = W0 - WW + c.v * 2 * WW;
                const rib = Math.cos(RIBS * a) > 0.6;
                return flesh(c.u, c, rib);
              },
            },
          );
        }
      }
      // Drops of water running from the cut (only while it is open).
      const drips = k.part("drips");
      k.cloud({ share: 0.002, size: 0.8, pattern: false, part: drips }, (r) => {
        const a = W0 + (r() < 0.5 ? -WW : WW);
        const y = Y0 + r() * (Y1 - Y0);
        const rr = r() * R;
        return {
          p: [Math.sin(a) * rr, y, Math.cos(a) * rr],
          color: "#e8fbff",
          opacity: 0.9,
          kind: "fall",
          params: [0.25, r()],
        };
      });
      const spines = [];
      for (let i = 0; i < RIBS; i++) {
        for (let y = 0.05; y < H - 0.02; y += 0.055) {
          const a = (i / RIBS) * TAU;
          const rr = R * prof(y) * 1.07;
          if (rr < 0.02) continue;
          const d = [Math.sin(a), 0, Math.cos(a)];
          spines.push({ p: [d[0] * rr, y, d[2] * rr], d });
        }
      }
      const tips = [[0, H + 0.01, 0]];
      const ARM = [
        { a: 1.3, y: 0.62, h: 0.62 },
        { a: -1.9, y: 0.82, h: 0.5 },
        { a: 0.1, y: 1.02, h: 0.38 },
        { a: 3.1, y: 0.5, h: 0.45 },
      ];
      for (let i = 0; i < o.arms; i++) {
        const A = ARM[i];
        const d = [Math.sin(A.a), 0, Math.cos(A.a)];
        const out = 0.36 + 0.04 * rand();
        const pts = [
          [d[0] * 0.05, A.y, d[2] * 0.05],
          [d[0] * 0.25, A.y + 0.02, d[2] * 0.25],
          [d[0] * out, A.y + 0.1, d[2] * out],
          [d[0] * (out + 0.03), A.y + 0.3, d[2] * (out + 0.03)],
          [d[0] * (out + 0.03), A.y + A.h, d[2] * (out + 0.03)],
        ];
        const ar = 0.115;
        const arm = k.tube(spline(pts), ar, { samples: 64, grid: 32 });
        k.add(arm, { color: (c) => ribCol(Math.cos(12 * c.u * TAU), c) });
        const end = pts[4];
        k.add(k.sphere(ar), {
          pos: end,
          scale: [1, 0.9, 1],
          color: (c) => {
            const a = Math.atan2(c.lp[0], c.lp[2]);
            return ribCol(Math.cos(12 * a) * (1 - c.ln[1] * 0.8), c);
          },
        });
        tips.push([end[0], end[1] + ar * 0.85, end[2]]);
        for (let j = 0; j < 12; j++) {
          const al = (j / 12) * TAU;
          for (let t = 0.12; t < 1; t += 0.05) {
            const f = arm.frame(t);
            const dd = add(mul(f.n, Math.cos(al)), mul(f.b, Math.sin(al)));
            spines.push({ p: add(f.p, mul(dd, ar * 1.05)), d: dd });
          }
        }
      }
      // Spines: each shoots out along its own line as channel 0 rises.
      k.cloud({ share: 0.015, size: 0.45, pattern: false }, (r) => {
        const s = spines[Math.floor(r() * spines.length)];
        const dd = unit(add(s.d, [(r() - 0.5) * 1.2, (r() - 0.3) * 1.2, (r() - 0.5) * 1.2]));
        const p = add(s.p, mul(dd, 0.012 * r()));
        return {
          p,
          dir: dd,
          stretch: 3,
          color: r() < 0.3 ? "#8a7a5a" : mix("#c8bc94", "#efe4c0", r()),
          to: add(p, mul(dd, 0.07 + 0.05 * r())),
          channel: 0,
          part: inWedge(s.p) ? wedge : 0,
        };
      });
      k.fitMorphs = false;
      if (o.flowers) {
        for (const tp of tips) {
          for (let f = 0; f < 3; f++) {
            const a = f * 2.1 + rand();
            const c = add(tp, [Math.sin(a) * 0.05, -0.01, Math.cos(a) * 0.05]);
            k.cloud({ share: 0.006, size: 0.7, flat: 0.3, pattern: false }, (r) => {
              const b = r() * TAU;
              const rr = 0.045 * Math.sqrt(r());
              const centre = rr < 0.015;
              return {
                p: add(c, [Math.sin(b) * rr, 0.02 + 0.02 * (rr / 0.045), Math.cos(b) * rr]),
                n: [Math.sin(b) * 0.4, 1, Math.cos(b) * 0.4],
                color: centre ? "#f2c230" : mix("#fbf8ee", "#f0e6cc", r()),
              };
            });
          }
        }
      }
      // A little barrel cactus, stones and desert sand.
      const bx = 0.48;
      const bz = 0.35;
      k.add(
        k.param(
          (u, v) => {
            const a = u * TAU;
            const y = v * 0.2;
            const rr =
              0.13 *
              Math.sin(Math.PI * (0.15 + 0.85 * v * 0.92)) ** 0.5 *
              (1 + 0.08 * Math.cos(14 * a));
            return [bx + Math.sin(a) * rr, y, bz + Math.cos(a) * rr];
          },
          { grid: 36 },
        ),
        { color: (c) => ribCol(Math.cos(14 * c.u * TAU), c) },
      );
      k.cloud({ share: 0.005, size: 0.7, flat: 0.3, pattern: false }, (r) => {
        const b = r() * TAU;
        const rr = 0.05 * Math.sqrt(r());
        return {
          p: [bx + Math.sin(b) * rr, 0.21 + 0.01 * (rr / 0.05), bz + Math.cos(b) * rr],
          n: [0, 1, 0],
          color: rr < 0.015 ? "#f2c230" : mix("#f0508a", "#ff8ab0", r()),
        };
      });
      for (let i = 0; i < 5; i++) {
        const a = rand() * TAU;
        const s = 0.05 + rand() * 0.06;
        k.add(k.ellipsoid(s * 1.3, s * 0.6, s), {
          pos: [Math.sin(a) * (0.45 + rand() * 0.25), 0.02, Math.cos(a) * (0.45 + rand() * 0.25)],
          rot: [0, rand() * 180, 0],
          color: (c) => lit(mix("#9a6a4a", "#c89a6a", c.rand() * 0.6), c.n, 0.4),
        });
      }
      grassMound(k, 0.82, 0, {
        h: 0.06,
        colors: ["#c89a62", "#dcb47a", "#ecd09a"],
        soil: "#9a6a42",
      });
    }

drive:
drive(t, c, out, info) {
      const s = progress(c.poke) * SAGUARO_SECS;
      const on = c.poke > 0;
      const cut = on && (info.tap?.n ?? 1) % 2 === 0;
      const spines = on && !cut ? easeOut(band(s, 0, 0.22)) * (1 - ease(band(s, 0.9, 1.7))) + 0.08 * shake(s - 1.7, 0.8, 30) : 0; // prettier-ignore
      out.morph = [spines, 0, 0, 0];
      const open = cut ? ease(band(s, 0.1, 0.8)) * (1 - ease(band(s, 3.3, 4.3))) : 0;
      out.parts.wedge = { offset: mul(SAGUARO_OUT, open) };
      out.parts.drips = { visible: cut && s > 0.8 && s < 3.4 ? 1 : 0 };
      crossing(c, "saguaro", on ? s : 0, [0.02, 0.9], (i) => {
        if (cut && i === 0) out.cues.push({ voice: "squish", f: 200, decay: 1.4, vol: 0.8 });
        if (cut && i === 1) out.cues.push({ voice: "drip", f: 1100, n: 3, rate: 2.5 });
        if (!cut && i === 0) out.cues.push({ voice: "zap", f: 3200, to: 0.7, decay: 1.2 });
      });
    }

build:
build(k, o) {
      reseed(k, o);
      const rand = k.rand;
      const polypSites = [];
      // The reef: a lumpy dark base crusted with pink and green.
      k.add(k.ellipsoid(0.95, 0.22, 0.72), {
        pos: [0, 0, 0],
        color: (c) => {
          if (c.n[1] < -0.2) return null;
          const n = c.fbm(c.p[0] * 5, c.p[1] * 5, c.p[2] * 5);
          let col = mix("#4a4250", "#6f6470", 0.5 + 0.5 * n);
          const crust = c.noise(c.p[0] * 9 + 3, c.p[1] * 9, c.p[2] * 9);
          if (crust > 0.35) col = mix(col, "#d86a8a", 0.5);
          else if (crust < -0.4) col = mix(col, "#6a8a3a", 0.5);
          return lit(col, c.n, 0.45);
        },
      });
      for (let i = 0; i < 9; i++) {
        const a = rand() * TAU;
        const rr = 0.3 + 0.5 * rand();
        const s = 0.1 + 0.1 * rand();
        k.add(k.ellipsoid(s * 1.3, s * 0.8, s), {
          pos: [Math.sin(a) * rr * 0.95, 0.1, Math.cos(a) * rr * 0.72],
          color: (c) =>
            lit(
              mix("#4a4250", "#7a6a78", c.fbm(c.p[0] * 8, c.p[1] * 8, c.p[2] * 8) * 0.5 + 0.5),
              c.n,
              0.45,
            ),
        });
      }
      const SW = sway(0.03, 0.15);
      // Staghorn coral: orange branches with pale growing tips.
      for (const [x, z, s, hue] of [
        [0.35, -0.12, 1, 0],
        [0.62, 0.22, 0.7, 0],
        [-0.12, -0.05, 0.8, 1],
      ]) {
        const tree = growTree(rand, {
          base: [x, 0.18, z],
          dir: [0, 1, 0],
          length: 0.22 * s,
          radius: 0.045 * s,
          depth: 3,
          kids: [
            [3, 3],
            [2, 3],
            [2, 2],
          ],
          spread: [0.75, 0.6, 0.55],
          ratio: [1.1, 0.85, 0.8],
          radRatio: [0.85, 0.85, 0.85],
          from: [0.8, 0.5, 0.5],
          wobble: [0.3, 0.4, 0.4],
          up: [0.15, 0.2, 0.2],
          taper: 0.85,
          tipTaper: 0.7,
        });
        for (const b of tree.branches) {
          const last = b.level === 3;
          if (b.level >= 2) {
            const curve = spline(b.pts);
            for (let q = 0; q < 7; q++) {
              const t = 0.15 + 0.8 * rand();
              const p0 = curve(t);
              const tg = unit(sub(curve(Math.min(1, t + 0.02)), curve(Math.max(0, t - 0.02))));
              const [e1, e2] = perp(tg);
              const a = rand() * TAU;
              const nrm = add(mul(e1, Math.cos(a)), mul(e2, Math.sin(a)));
              polypSites.push({ p: add(p0, mul(nrm, lerp(b.r0, b.r1, t))), n: nrm });
            }
          }
          k.add(
            k.tube(spline(b.pts), (t) => lerp(b.r0, b.r1, t), {
              samples: 16,
              grid: 10,
              caps: last,
            }),
            {
              flat: 0.35,
              color: (c) => {
                const tip = last ? smoothstep(0.55, 1, c.t) : 0;
                let col = mix(
                  "#d8702a",
                  "#f09a4a",
                  c.noise(c.p[0] * 60, c.p[1] * 60, c.p[2] * 60) * 0.5 + 0.5,
                );
                col = mix(col, "#fbe0c0", tip);
                return lit(col, c.n, 0.35);
              },
            },
          );
        }
      }
      // Polyps (hidden until a tap): little eight-armed stars on the
      // staghorn branches, drawn in to their cups (a morph) until they open.
      const polyps = k.part("polyps");
      k.cloud({ share: 0.05, size: 0.6, pattern: false, part: polyps }, (r) => {
        const st = polypSites[Math.floor(r() * polypSites.length)];
        const [e1, e2] = perp(st.n);
        const arm = Math.floor(r() * 8);
        const a = (arm / 8) * TAU + 0.2 * (r() - 0.5);
        const along = r();
        const d = unit(add(add(mul(e1, Math.cos(a)), mul(e2, Math.sin(a))), mul(st.n, 0.9)));
        return {
          p: add(st.p, mul(d, 0.045 * along + 0.006)),
          dir: d,
          stretch: 1.6,
          color: along > 0.75 ? "#fff6c8" : mix("#f6d890", "#fbe8b0", r()),
          to: add(st.p, mul(st.n, 0.004)),
          channel: 0,
        };
      });
      // Brain coral.
      k.add(k.sphere(0.3), {
        pos: [-0.32, 0.12, 0.22],
        scale: [1, 0.72, 1],
        interior: 0.08,
        core: "#c8b070",
        color: (c) => {
          if (c.ln[1] < -0.1) return null;
          const g = c.fbm(c.lp[0] * 7, c.lp[1] * 7, c.lp[2] * 7, 3);
          const groove = Math.abs(g) < 0.07;
          return lit(groove ? "#6a6a28" : mix("#b8b850", "#e0dc80", c.rand() * 0.4), c.n, 0.45);
        },
      });
      // A purple sea fan at the back: a lattice of fine branches.
      const fanC = [-0.05, 0.16, -0.4];
      k.add(
        k.param(
          (u, v) => {
            const a = (u - 0.5) * 2.3;
            const r = 0.08 + 0.75 * v;
            return [
              fanC[0] + Math.sin(a) * r,
              fanC[1] + Math.cos(a) * r * 0.95,
              fanC[2] + 0.06 * Math.sin(a * 3) * v,
            ];
          },
          { grid: 48 },
        ),
        {
          flat: 0.3,
          ...SW,
          color: (c) => {
            const n = c.noise(c.u * 9, c.v * 9, 1) * 0.25;
            const ray = Math.abs(((c.u * 26 + n + c.v * 1.5) % 1) - 0.5) > 0.4;
            const ring = Math.abs(((c.v * 18 + n * 2) % 1) - 0.5) > 0.44;
            const edge = c.v > 0.97 && Math.cos((c.u - 0.5) * 7) > 0;
            if (!ray && !ring && !edge) return null;
            return lit(mix("#7a2a8a", "#c060c8", c.v * 0.7 + 0.2 * c.rand()), c.n, 0.3);
          },
        },
      );
      // A sea anemone: a pink column crowned with swaying tentacles.
      const an = [0.1, 0.22, 0.4];
      k.add(k.cylinder(0.09, 0.14, { caps: false }), {
        pos: [an[0], an[1], an[2]],
        color: (c) => lit(mix("#e06080", "#f08aa0", c.rand() * 0.5), c.n, 0.4),
      });
      k.cloud({ share: 0.08, size: 0.7, pattern: false }, (r) => {
        const a = r() * TAU;
        const rr = 0.03 + 0.07 * Math.sqrt(r());
        const t = r();
        const out = [Math.sin(a), 0, Math.cos(a)];
        const p = [
          an[0] + out[0] * (rr + 0.12 * t),
          an[1] + 0.07 + 0.16 * t - 0.08 * t * t * (rr / 0.1),
          an[2] + out[2] * (rr + 0.12 * t),
        ];
        return {
          p,
          dir: [out[0] * 0.8, 1 - t, out[2] * 0.8],
          stretch: 2.2,
          color: mix("#f79ab8", "#b048c0", smoothstep(0.6, 1, t)),
          kind: "sway",
          params: [0.05, an[1]],
        };
      });
      // Yellow tube sponges.
      for (const [x, z, h, r] of [
        [-0.62, -0.15, 0.36, 0.06],
        [-0.5, -0.28, 0.26, 0.05],
        [-0.72, 0.02, 0.22, 0.045],
      ]) {
        k.add(k.cylinder(r, h, { caps: false }), {
          pos: [x, 0.14 + h / 2, z],
          color: (c) => {
            const inner = dot(c.n, [x, 0, z]) < -0.9 * Math.hypot(x, z) ? 1 : 0;
            return lit(mix("#e8b020", "#f7d040", c.rand() * 0.4), c.n, 0.4 + 0.1 * inner);
          },
        });
        k.add(k.disc(r * 0.85), {
          pos: [x, 0.14 + h - 0.02, z],
          color: "#5a3a10",
        });
      }
      // Two little fish circling the reef.
      for (let f = 0; f < 2; f++) {
        const a = f * Math.PI + 0.6;
        const rr = 0.78 - f * 0.1;
        const p = [Math.sin(a) * rr, 0.7 + f * 0.18, Math.cos(a) * rr];
        const tangent = [Math.cos(a), 0, -Math.sin(a)];
        const q = quatFromTo([1, 0, 0], tangent);
        const fish = { kind: "orbit", params: [0.45, 0], pattern: false };
        k.add(k.ellipsoid(0.075, 0.045, 0.025), {
          pos: p,
          quat: q,
          weight: 3,
          ...fish,
          color: (c) => {
            const x = c.lp[0] / 0.075;
            const band = Math.abs(x - 0.3) < 0.12 || Math.abs(x + 0.35) < 0.1;
            if (x > 0.72 && Math.abs(c.lp[2]) > 0.012 && Math.abs(c.lp[1]) < 0.012)
              return "#111111";
            return band ? "#ffffff" : lit("#f2701a", c.n, 0.3);
          },
        });
        k.add(k.ellipsoid(0.03, 0.035, 0.008), {
          pos: add(p, quatRotate(q, [-0.085, 0, 0])),
          quat: q,
          weight: 3,
          ...fish,
          color: "#e85a10",
        });
      }
      // Six little fish hiding in the reef (hidden until a tap). Each is
      // built where it hovers when it has darted out, in front (so it draws
      // over the reef), and turned to face along its path.
      const FISH = [
        {
          home: [0.35, 0.35, -0.1],
          out: [0.55, 0.62, 0.55],
          body: "#ffd11a",
          fin: "#ffb000",
          stripe: null,
        },
        {
          home: [-0.1, 0.35, 0.0],
          out: [-0.55, 0.7, 0.5],
          body: "#2a6fff",
          fin: "#ffd11a",
          stripe: null,
        },
        {
          home: [0.6, 0.3, 0.2],
          out: [0.85, 0.45, 0.62],
          body: "#ff7a1a",
          fin: "#ff7a1a",
          stripe: "#ffffff",
        },
        {
          home: [-0.3, 0.3, 0.2],
          out: [-0.75, 0.42, 0.62],
          body: "#a040e0",
          fin: "#ffd11a",
          stripe: null,
        },
        {
          home: [0.3, 0.4, 0.1],
          out: [0.2, 0.95, 0.5],
          body: "#20c8c0",
          fin: "#20a8a0",
          stripe: null,
        },
        {
          home: [-0.05, 0.3, 0.3],
          out: [-0.2, 0.55, 0.78],
          body: "#ffe040",
          fin: "#1a1a1a",
          stripe: "#1a1a1a",
        },
      ];
      FISH.forEach((f, i) => {
        const fishy = { kind: "token", params: [i, 0], pattern: false, fit: false, weight: 3 };
        k.add(k.ellipsoid(0.06, 0.036, 0.018), {
          ...fishy,
          pos: f.out,
          color: (c) => {
            const x = c.lp[0] / 0.06;
            if (x > 0.6 && Math.abs(c.lp[1]) < 0.01 && Math.abs(c.lp[2]) > 0.008) return "#111111";
            if (f.stripe && Math.abs(x - 0.1) < 0.14) return f.stripe;
            return lit(f.body, c.n, 0.3);
          },
        });
        k.add(k.ellipsoid(0.022, 0.028, 0.006), {
          ...fishy,
          pos: add(f.out, [-0.07, 0, 0]),
          color: f.fin,
        });
      });
      k.data = { fish: FISH.map((f) => ({ home: f.home, out: f.out })) };
      k.fitMorphs = false;
      // Bubbles.
      k.cloud({ share: 0.004, size: 1.2, pattern: false }, (r) => ({
        p: [0.1 + (r() - 0.5) * 0.15, 0.45, 0.4 + (r() - 0.5) * 0.15],
        color: "#e6f6ff",
        opacity: 0.5,
        kind: "rise",
        params: [1.2, r()],
      }));
      k.reach([0, 1.2, 0]);
    }

