drive(t, c, out, info) {
      const s = progress(c.bloom) * CORAL_SECS;
      const on = c.bloom > 0;
      const open = on ? easeOut(band(s, 0.1, 1.0)) * (1 - ease(band(s, 3.8, 4.8))) : 0;
      out.parts.polyps = { visible: on ? band(s, 0, 0.12) * (1 - band(s, 4.7, 4.9)) : 0 };
      out.morph = [1 - open, 0, 0, 0];
      out.tokens = (info.data?.fish || []).map((f, i) => {
        if (!on) return { base: f.out, visible: 0 };
        const t0 = 0.35 + 0.18 * i;
        const back = 2.6 + 0.12 * i;
        let p;
        let dir;
        if (s < t0) return { base: f.out, visible: 0 };
        if (s < t0 + 0.45) {
          const g = easeOut(band(s, t0, t0 + 0.45));
          p = lerp3(f.home, f.out, g);
          dir = sub(f.out, f.home);
        } else if (s < back) {
          // Hovering: a little wander and a flick of the tail.
          const w = s - t0 - 0.45;
          p = add(f.out, [0.03 * Math.sin(w * 3 + i), 0.02 * Math.sin(w * 4.1 + i), 0.03 * Math.cos(w * 2.6 + i)]); // prettier-ignore
          const turn = ease(band(s, back - 0.4, back));
          dir = lerp3(sub(f.out, f.home), sub(f.home, f.out), turn);
          dir = add(dir, [0.15 * Math.cos(w * 3 + i), 0, -0.15 * Math.sin(w * 3 + i)]);
        } else {
          const g = ease(band(s, back, back + 0.45));
          p = lerp3(f.out, f.home, g);
          dir = sub(f.home, f.out);
        }
        const flat = unit([dir[0], dir[1] * 0.4, dir[2]]);
        return {
          base: f.out,
          offset: sub(p, f.out),
          quat: quatFromTo([1, 0, 0], flat),
          visible: band(s, t0, t0 + 0.12) * (1 - band(s, back + 0.35, back + 0.45)),
        };
      });
    }

build:
build(k) {
      const rand = k.rand;
      const N = 120;
      const Y0 = -0.62;
      const HT = 1.35;
      const radius = (h) => 0.36 * Math.sin(Math.PI * (0.06 + 0.9 * h)) ** 0.7 * (1 - 0.25 * h);
      k.add(k.ellipsoid(0.16, HT * 0.46, 0.16), {
        pos: [0, Y0 + HT * 0.48, 0],
        color: "#3a2412",
      });
      // The scales that break off (tokens): every scale in a window on the
      // side facing the home camera, the ones facing it most squarely, so
      // none is left standing on the bare core. The rest only open.
      const VH = [Math.sin(0.45), Math.cos(0.45)];
      const facing = [];
      for (let i = 0; i < N; i++) {
        const h = (i + 0.5) / N;
        const th = i * GOLDEN;
        if (h > 0.06 && h < 0.94) facing.push([i, Math.sin(th) * VH[0] + Math.cos(th) * VH[1]]);
      }
      facing.sort((a, b) => b[1] - a[1]);
      const pick = new Set(facing.slice(0, CONE_LOOSE).map(([i]) => i));
      const loose = [];
      for (let i = 0; i < N; i++) {
        const h = (i + 0.5) / N;
        const th = i * GOLDEN;
        const R = radius(h);
        const e = (-35 + 95 * h) * (Math.PI / 180);
        const len = 0.1 + 0.11 * Math.sin(Math.PI * Math.min(1, 0.1 + h)) ** 0.6;
        const wid = 0.06 + 0.06 * Math.sin(Math.PI * h) ** 0.5;
        const d = [Math.sin(th) * Math.cos(e), Math.sin(e), Math.cos(th) * Math.cos(e)];
        const centre = [
          Math.sin(th) * (R - len * 0.45) + d[0] * len * 0.5,
          Y0 + HT * h + d[1] * len * 0.3,
          Math.cos(th) * (R - len * 0.45) + d[2] * len * 0.5,
        ];
        const rot = [-(e * 180) / Math.PI, (th * 180) / Math.PI, 0];
        const tone = 0.9 + 0.2 * rand();
        // Opening: the scale tips out about its root (away from the tip).
        const hinge = sub(centre, mul(d, len * 0.5));
        const tip = [Math.cos(th), 0, -Math.sin(th)];
        const ang = CONE_OPEN * (0.6 + 0.4 * Math.sin(Math.PI * h));
        const q = quatAxisAngle(tip, ang);
        const own = pick.has(i)
          ? { kind: "token", params: [loose.length, 0] }
          : { channel: 0, to: (c) => add(hinge, quatRotate(q, sub(c.p, hinge))) };
        if (pick.has(i)) {
          loose.push({ p: centre, hinge, tip, ang, th, h, up: quatRotate(quatEuler(...rot), [0, 1, 0]) }); // prettier-ignore
          // The broken stub it leaves on the core (under the scale at rest).
          k.add(k.ellipsoid(wid * 0.32, 0.018, 0.03), {
            pos: add(hinge, mul(d, 0.012)),
            rot,
            flat: 0.3,
            color: (c) => lit(shade("#6a4424", tone), c.n, 0.5),
          });
        }
        k.add(k.ellipsoid(wid, 0.028, len * 0.55), {
          pos: centre,
          rot,
          flat: 0.25,
          ...own,
          color: (c) => {
            const along = c.lp[2] / (len * 0.55);
            let col = mix("#3a2212", "#8a5a2e", smoothstep(-0.8, 0.4, along));
            col = mix(col, "#c09060", smoothstep(0.5, 0.95, along) * (c.lp[1] > 0 ? 1 : 0.5));
            if (along > 0.72 && Math.abs(c.lp[0]) < wid * 0.5 && c.lp[1] > 0)
              col = mix(col, "#5a3a1e", 0.7);
            return lit(shade(col, tone), c.n, 0.5);
          },
        });
      }
      // A short woody stalk.
      k.add(k.cylinder(0.035, 0.12), {
        pos: [0, Y0 - 0.04, 0],
        color: (c) => lit("#4a2e18", c.n, 0.4),
      });
      // Where each loose scale lands on the ground under the cone (flat,
      // clear of the others), and when it breaks off and comes back: from
      // the bottom up, and back top first.
      const floor = Y0 - 0.14;
      const spots = [];
      loose.forEach((sc, n) => {
        const rank = n / loose.length;
        let best = null;
        let bestGap = -Infinity;
        for (let tries = 0; tries < 40; tries++) {
          const a = sc.th + (rand() - 0.5) * 1.4;
          const r = 0.3 + 0.24 * rand();
          const p = [Math.sin(a) * r, 0, Math.cos(a) * r];
          let gap = Infinity;
          for (const q of spots) gap = Math.min(gap, Math.hypot(p[0] - q[0], p[2] - q[2]));
          if (gap > bestGap) {
            bestGap = gap;
            best = p;
          }
          if (gap > 0.13) break;
        }
        // A scale that lands on others lies a little higher, on top of them.
        const under = spots.filter((q) => Math.hypot(best[0] - q[0], best[2] - q[2]) < 0.1).length;
        spots.push(best);
        sc.land = [best[0], floor + 0.015 + 0.022 * Math.min(3, under), best[2]];
        sc.tb = 1.35 + 1.8 * rank + 0.06 * rand();
        sc.fall = 0.3 + 0.35 * Math.sqrt(Math.max(0, sc.p[1] - floor));
        sc.back = 4.3 + 1.2 * (1 - rank) + 0.05 * rand();
        sc.spin = rand() * TAU;
        sc.tumble = unit([rand() - 0.5, 0, rand() - 0.5]);
        sc.flip = rand() < 0.5;
      });
      // Winged seeds (hidden until the scales open): a dark seed on a
      // papery wing, each a token, built on the cone where it slips out.
      const seeds = [];
      for (let i = 0; i < CONE_SEEDS; i++) {
        const h = 0.3 + 0.5 * rand();
        const a = rand() * TAU;
        const r0 = radius(h) + 0.03;
        const p = [Math.sin(a) * r0, Y0 + HT * h, Math.cos(a) * r0];
        const tok = { kind: "token", params: [loose.length + i, 0], pattern: false, weight: 4 };
        const out = [Math.sin(a), 0, Math.cos(a)];
        k.add(k.ellipsoid(0.022, 0.012, 0.016), {
          ...tok,
          pos: p,
          color: (c) => lit("#3a2414", c.n, 0.4),
        });
        k.add(k.ellipsoid(0.055, 0.004, 0.026), {
          ...tok,
          pos: add(p, mul(out, 0.05)),
          quat: quatFromTo([1, 0, 0], out),
          color: (c) => lit(mix("#c8a070", "#e0c090", c.rand()), c.n, 0.3),
        });
        seeds.push({
          p,
          a,
          r0,
          r1: 0.5 + 0.3 * rand(),
          y1: -0.78 + 0.1 * rand(),
          dur: 2.4 + 0.6 * rand(),
          dir: rand() < 0.5 ? -1 : 1,
        });
      }
      k.data = { seeds, loose };
      k.fitMorphs = false;
    }

