build(k, o) {
      const caps = [];
      const acorn = (pos, rot, s, land) => {
        const q = quatEuler(...rot);
        const at = (p) => add(pos, quatRotate(q, mul(p, s)));
        const n = caps.length;
        const cap = k.part(`cap${n}`, {
          pivot: at([0, 0.2, 0]),
          axis: quatRotate(q, [1, 0, 0.3]),
        });
        caps.push({ land: sub(land, at([0, 0.2, 0])) });
        k.add(
          k.lathe([
            [0, -0.56],
            [0.03, -0.52],
            [0.12, -0.44],
            [0.24, -0.3],
            [0.3, -0.1],
            [0.31, 0.08],
            [0.29, 0.18],
          ]),
          {
            even: true,
            opacity: 1,
            jitter: 0.015,
            pos,
            quat: q,
            scale: s,
            flat: 0.2,
            interior: 0.12,
            // (None from the narrow tip, where they would poke out.)
            core: (c) => (c.lp[1] < -0.36 ? null : "#f0e2c0"),
            color: (c) => {
              const y = c.lp[1];
              if (y < -0.5) return "#3a2412";
              let col = mix("#5a3212", "#a8642a", smoothstep(-0.5, 0.1, y));
              col = shade(col, 0.94 + 0.06 * Math.sin(c.u * TAU * 16));
              const hi = Math.pow(Math.max(0, dot(c.n, unit([-0.4, 0.5, 0.75]))), 22);
              return mix(lit(col, c.n, 0.4), "#fff4e0", 0.55 * hi);
            },
          },
        );
        k.add(
          k.lathe([
            [0.3, 0.05],
            [0.345, 0.12],
            [0.34, 0.24],
            [0.26, 0.33],
            [0.12, 0.37],
            [0, 0.38],
          ]),
          {
            even: true,
            opacity: 1,
            jitter: 0.015,
            pos,
            quat: q,
            scale: s,
            flat: 0.3,
            part: cap,
            color: (c) => {
              const row = Math.floor(c.v * 9);
              const f = (c.u * 30 + row * 0.5) % 1;
              const g = (c.v * 9) % 1;
              const gap = Math.abs(f - 0.5) > 0.4 || g < 0.12;
              const col = gap ? "#4a3420" : mix("#8a6a42", "#c0a070", g);
              return lit(col, c.n, 0.45);
            },
          },
        );
        const tip = at([0, 0.37, 0]);
        k.add(
          k.tube(spline([tip, at([0.03, 0.46, 0]), at([0.08, 0.52, 0.02])]), 0.025 * s, {
            samples: 12,
            grid: 8,
          }),
          {
            even: true,
            opacity: 1,
            jitter: 0.015,
            weight: 2,
            part: cap,
            color: (c) => lit("#5a3e22", c.n, 0.4),
          },
        );
        // The sprout (hidden until the cap is off): a pale green shoot
        // curling up out of the top with two tiny oak leaves.
        const base = at([0, 0.08, 0]);
        const sprout = k.part(`sprout${n}`, { pivot: base });
        const sp = [base, at([0.02, 0.3, 0]), at([0.08, 0.55, 0.04]), at([0.2, 0.68, 0.06])];
        k.add(
          k.tube(spline(sp), (t) => 0.035 * s * (1 - 0.5 * t), { samples: 24, grid: 10 }),
          {
            even: true,
            opacity: 1,
            jitter: 0.015,
            part: sprout,
            weight: 2,
            color: (c) => lit(mix("#e8f0c0", "#8ac050", c.t), c.n, 0.4),
          },
        );
        const shootTip = sp[3];
        for (const side of [-1, 1]) {
          k.add(
            k.param(
              (u, v) => {
                const x = (u - 0.5) * 2;
                return [x * 0.06 * s * oakLobes(v), v * 0.16 * s, 0.02 * s * x * x];
              },
              { grid: 10 },
            ),
            {
              even: true,
              opacity: 1,
              jitter: 0.015,
              pos: shootTip,
              quat: quatMul(q, quatEuler(-30, side * 50, side * 60)),
              part: sprout,
              weight: 2.5,
              flat: 0.2,
              color: (c) =>
                Math.abs(c.u - 0.5) * 2 > oakLobes(c.v)
                  ? null
                  : lit(mix("#6aa83a", "#a8d060", c.v), c.n, 0.3),
            },
          );
        }
      };
      // An oak leaf with rounded lobes behind the acorns.
      const autumn = o.leaf === "autumn";
      const L = 1.5;
      const W = 0.42;
      const outline = (v) =>
        (0.42 + 0.58 * Math.abs(Math.sin(v * Math.PI * 3.6 + 0.4)) ** 0.7) *
        Math.sin(Math.PI * Math.min(1, v)) ** 0.55;
      k.add(
        k.param(
          (u, v) => {
            const x = (u - 0.5) * 2 * W;
            return [x, v * L, 0.08 * x * x - 0.12 * Math.sin(v * Math.PI)];
          },
          { grid: 40 },
        ),
        {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [0.05, -0.5, -0.25],
          rot: [-72, 25, 0],
          flat: 0.2,
          color: (c) => {
            const x = Math.abs(c.u - 0.5) * 2;
            if (x > outline(c.v)) return null;
            if (c.v < 0.02 && x > 0.05) return null;
            const mid = x < 0.03;
            const side =
              Math.abs(Math.sin((c.v * 3.6 + x * 0.9) * Math.PI)) < 0.07 && x < outline(c.v) * 0.85;
            let col = autumn
              ? mix("#b8601a", "#e8a030", 0.5 + 0.5 * c.fbm(c.p[0] * 4, c.p[1] * 4, c.p[2] * 4))
              : mix("#3f6f24", "#5f8f34", 0.5 + 0.5 * c.fbm(c.p[0] * 4, c.p[1] * 4, c.p[2] * 4));
            if (autumn && x > outline(c.v) * 0.8) col = mix(col, "#7a3a12", 0.5);
            if (mid || side) col = mix(col, autumn ? "#f0c070" : "#9ac060", 0.5);
            return lit(col, c.n, 0.3);
          },
        },
      );
      // A leaf stem.
      k.add(
        k.tube(
          spline([
            [0.05, -0.5, -0.25],
            [0.02, -0.6, -0.05],
            [0.0, -0.62, 0.1],
          ]),
          0.015,
          { samples: 12, grid: 6 },
        ),
        {
          even: true,
          opacity: 1,
          jitter: 0.015,
          color: autumn ? "#8a5a22" : "#4f7a2a",
        },
      );
      // Each cap lands upside down on the leaf: a point on its surface
      // (the leaf's own u, v), lifted by the cap's height.
      const leafQ = quatEuler(-72, 25, 0);
      const onLeaf = (u, v) => {
        const x = (u - 0.5) * 2 * W;
        const lp = [x, v * L, 0.08 * x * x - 0.12 * Math.sin(v * Math.PI)];
        const up = quatRotate(leafQ, [0, 0, 1]);
        return add(add([0.05, -0.5, -0.25], quatRotate(leafQ, lp)), mul(up[1] > 0 ? up : mul(up, -1), 0.12)); // prettier-ignore
      };
      const spots = [onLeaf(0.15, 0.55), onLeaf(0.88, 0.62)];
      acorn([-0.28, -0.08, 0.2], [0, 0, 18], 0.95, spots[0]);
      acorn([0.34, -0.22, 0.28], [0, 40, -35], 0.8, spots[1]);
      k.data = { caps };
    }

drive:
drive(t, c, out, info) {
      const s = progress(c.sprout) * ACORN_SECS;
      const on = c.sprout > 0;
      (info.data?.caps || []).forEach((cp, i) => {
        const d = 0.22 * i;
        const go = on ? band(s, 0.05 + d, 0.65 + d) : 0;
        const home = on ? band(s, 4.05 + d, 4.6 + d) : 0;
        const f = home > 0 ? 1 - home : go;
        const arc = 0.42 * Math.sin(Math.PI * f);
        const bump = home > 0 ? 0 : 0.03 * Math.sin(Math.PI * band(s, 0.65 + d, 0.85 + d));
        out.parts[`cap${i}`] = {
          offset: [cp.land[0] * f, cp.land[1] * f + arc + bump, cp.land[2] * f],
          angle: Math.PI * f,
        };
        const grow = on ? easeOut(band(s, 0.55 + d, 1.9 + d)) * (1 - ease(band(s, 3.4 + d, 4.0 + d))) : 0; // prettier-ignore
        out.parts[`sprout${i}`] = { scale: 0.01 + 0.99 * grow, visible: grow > 0.005 ? 1 : 0 };
      });
    }

build:
build(k, o) {
      const rand = k.rand;
      // A terracotta pot with a rim, and gravel on top.
      k.add(
        k.lathe([
          [0.27, -0.5],
          [0.3, -0.47],
          [0.36, -0.16],
          [0.38, -0.1],
          [0.43, -0.1],
          [0.44, 0.0],
          [0.41, 0.02],
          [0.38, 0.0],
        ]),
        {
          flat: 0.25,
          color: (c) => {
            const g = c.fbm(c.p[0] * 10, c.p[1] * 10, c.p[2] * 10);
            const rim = c.p[1] > -0.13;
            const col = mix("#b85a32", "#d8804a", 0.5 + 0.4 * g);
            return lit(rim ? shade(col, 1.08) : col, c.n, 0.45);
          },
        },
      );
      k.add(k.disc(0.39), {
        pos: [0, -0.02, 0],
        color: (c) =>
          c.n[1] < 0
            ? "#6a3a20"
            : mix("#d8d0c0", "#8a8478", c.noise(c.p[0] * 60, 0, c.p[2] * 60) * 0.5 + 0.5),
      });
      // The rosette: thick pointed leaves on a golden-angle spiral, flat
      // outside and cupped upright in the middle.
      const leafShape = (L, W) =>
        k.param(
          (u, v) => {
            const a = u * TAU;
            const w = W * Math.sin(Math.PI * Math.pow(Math.min(v, 0.999), 0.62)) ** 0.7;
            const t = w * 0.42;
            const y = Math.sin(a) * t + (Math.sin(a) > 0 ? -0.35 * t : 0) + 0.12 * L * v * v;
            return [Math.cos(a) * w, y, L * v];
          },
          { grid: 18 },
        );
      const NL = 52;
      for (let i = 0; i < NL; i++) {
        const f = i / (NL - 1);
        const th = i * GOLDEN;
        const L = 0.6 * (1 - 0.7 * f);
        const W = 0.17 * (1 - 0.5 * f);
        const e = 8 + 72 * Math.pow(f, 0.8);
        const tone = 0.9 + 0.15 * rand();
        const hinge = [0, 0.02 + 0.12 * f, 0];
        const q = quatAxisAngle([Math.cos(th), 0, -Math.sin(th)], ((e * Math.PI) / 180) * 0.45);
        k.add(leafShape(L, W), {
          pos: hinge,
          rot: [-e, (th * 180) / Math.PI, 0],
          flat: 0.25,
          channel: 0,
          to: (c) => add(hinge, quatRotate(q, sub(c.p, hinge))),
          color: (c) => {
            let col = mix("#3f7468", "#6fa08c", smoothstep(0.05, 0.75, c.v));
            col = mix(col, "#a8c8b8", 0.2 * smoothstep(0.3, 1, Math.sin(c.u * TAU)));
            col = mix(col, o.tint, smoothstep(0.72, 1, c.v) * 0.9);
            return lit(shade(col, tone * (0.72 + 0.28 * (1 - f))), c.n, 0.35);
          },
        });
      }
      // The flower stalk (hidden until a tap): it arches up out of the
      // middle with little coral bells along its top.
      const foot = [0, 0.14, 0];
      const stalk = k.part("stalk", { pivot: foot });
      const stem = spline([foot, [0.02, 0.4, 0.02], [0.1, 0.62, 0.06], [0.26, 0.66, 0.12], [0.36, 0.56, 0.16]]); // prettier-ignore
      k.add(
        k.tube(stem, (t) => 0.02 * (1 - 0.5 * t), { samples: 40, grid: 10 }),
        {
          part: stalk,
          weight: 2,
          color: (c) => lit(mix("#8aa878", "#d8906a", c.t), c.n, 0.4),
        },
      );
      for (let b = 0; b < 6; b++) {
        const t = 0.42 + 0.11 * b;
        const at = stem(t);
        // Each bell hangs on a short stalk below the arch, alternating sides.
        const side = b % 2 ? 1 : -1;
        const hang = unit([0.35 * side, -1, -0.3 * side]);
        const bell = add(at, mul(hang, 0.045));
        k.add(k.tube(spline([at, bell]), 0.006, { samples: 6, grid: 5 }), {
          part: stalk,
          weight: 3,
          color: "#c88a6a",
        });
        k.add(
          k.lathe([
            [0.0, 0],
            [0.016, 0.005],
            [0.022, 0.022],
            [0.025, 0.042],
            [0.019, 0.046],
          ]),
          {
            pos: bell,
            quat: quatFromTo([0, 1, 0], hang),
            part: stalk,
            weight: 3,
            pattern: false,
            color: (c) =>
              lit(c.lp[1] > 0.05 ? "#ffd24a" : mix("#ff7a4a", "#ff9a6a", c.v), c.n, 0.3),
          },
        );
      }
    }

