      const on = c.bloom > 0;
      out.morph = [on ? ease(band(s, 0.1, 1.2)) * (1 - ease(band(s, 4.0, 5.2))) : 0, 0, 0, 0];
      const g = on ? easeOut(band(s, 0.6, 2.2)) * (1 - ease(band(s, 3.7, 4.5))) : 0;
