build:
build(k) {
      const rand = k.rand;
      const SW = sway(0.012, 0);
      const culms = [
        { x: 0, z: 0, h: 2.2, r: 0.055, lean: [0.05, 1, 0.02] },
        { x: -0.2, z: -0.12, h: 1.9, r: 0.05, lean: [-0.12, 1, -0.04] },
        { x: 0.2, z: -0.08, h: 2.05, r: 0.05, lean: [0.1, 1, -0.06] },
        { x: 0.1, z: 0.2, h: 1.55, r: 0.045, lean: [0.08, 1, 0.14] },
        { x: -0.14, z: 0.16, h: 1.35, r: 0.04, lean: [-0.1, 1, 0.12] },
      ];
      const leaves = [];
      for (const cm of culms) {
        const d = unit(cm.lean);
        const base = [cm.x, 0, cm.z];
        const at = (t) =>
          add(base, add(mul(d, cm.h * t), [0.04 * t * t * d[0], 0, 0.04 * t * t * d[2]]));
        const seg = 0.24;
        const nodes = Math.floor(cm.h / seg);
        k.add(
          k.tube(at, (t) => cm.r * (1 - 0.25 * t), { samples: 64, grid: 28, caps: true }),
          {
            flat: 0.3,
            ...SW,
            color: (c) => {
              const y = c.t * cm.h;
              const f = (y / seg) % 1;
              let col = mix(
                "#5a8a2a",
                "#9ab040",
                c.t * 0.6 + 0.2 * c.noise(c.p[0] * 20, c.p[1] * 3, c.p[2] * 20),
              );
              col = shade(col, 0.95 + 0.05 * Math.sin(c.u * TAU * 9));
              if (f < 0.035 || f > 0.985) col = mix(col, "#3a5a1a", 0.7);
              else if (f < 0.07) col = mix(col, "#d8d8a0", 0.5);
              return lit(col, c.n, 0.45);
            },
          },
        );
        // Twigs and leaves from the upper nodes.
        for (let n = Math.floor(nodes * 0.4); n < nodes; n++) {
          const t = (n * seg) / cm.h;
          const p = at(t);
          const tw = 1 + (rand() < 0.5 ? 1 : 0);
          for (let j = 0; j < tw; j++) {
            const a = rand() * TAU;
            const dir = unit([Math.sin(a), 0.9, Math.cos(a)]);
            const L = 0.15 + 0.2 * rand() * (1 - t * 0.3);
            const end = add(p, mul(dir, L));
            k.add(
              k.tube(spline([p, add(p, mul(dir, L * 0.5)), end]), 0.006, { samples: 8, grid: 5 }),
              {
                ...SW,
                color: "#6a8a2a",
              },
            );
            const nl = 3 + Math.floor(rand() * 3);
            for (let m = 0; m < nl; m++) {
              const b = a + (m - nl / 2) * 0.8 + (rand() - 0.5) * 0.4;
              const ld = unit([Math.sin(b), -0.35 - 0.4 * rand(), Math.cos(b)]);
              leaves.push({ p: end, d: ld, L: 0.18 + 0.08 * rand(), W: 0.022, tone: rand() });
            }
          }
        }
      }
      k.cloud({ share: 0.38, size: 0.8, flat: 0.25 }, (r) => {
        const lf = leaves[Math.floor(r() * leaves.length)];
        const u = r();
        const side = unit(cross(lf.d, [0, 1, 0]));
        const w = lf.W * Math.sin(Math.PI * Math.pow(u, 0.7)) * (r() - 0.5) * 2;
        const droop = -0.08 * u * u;
        const p = add(add(add(lf.p, mul(lf.d, lf.L * u)), mul(side, w)), [0, droop, 0]);
        const nrm = unit(cross(side, lf.d));
        const tone = clamp(
          0.3 + 0.35 * lf.tone + 0.2 * u + 0.2 * dot(nrm, LIGHT) * (nrm[1] < 0 ? -1 : 1),
          0,
          1,
        );
        return {
          p,
          n: nrm[1] < 0 ? mul(nrm, -1) : nrm,
          color: ramp(["#2f5a1a", "#4a7f26", "#6fa532", "#a4c850"], tone),
          ...SW,
        };
      });
      grassMound(k, 0.6, 0, {
        h: 0.05,
        colors: ["#4a5a2a", "#6a7a3a", "#8a8a4a"],
        blades: 0.015,
        bladeLen: 0.1,
      });
      // Three young shoots (tokens): sections built where they end up,
      // each a little thinner than the one below, a pointed sheathed tip,
      // and a tuft of leaves (hidden until grown).
      const shoots = [];
      let tok = 0;
      for (const [x, z, n] of [
        [0.3, 0.3, 6],
        [-0.32, 0.28, 5],
        [0.42, -0.1, 4],
      ]) {
        const g = moundTop(0.6, 0, 0.05, Math.hypot(x, z)) - 0.01;
        const at = [x, g, z];
        const first = tok;
        const rOf = (j) => 0.042 * (1 - 0.05 * j);
        for (let j = 0; j < n; j++) {
          k.add(k.cylinder(rOf(j), BAMBOO_SEG, { caps: false }), {
            pos: [x, g + (j + 0.5) * BAMBOO_SEG, z],
            weight: 1.5,
            flat: 0.3,
            kind: "token",
            params: [tok, 0],
            color: (c) => {
              const f = (c.p[1] - g - j * BAMBOO_SEG) / BAMBOO_SEG;
              let col = mix("#6aa83a", "#9ac850", 0.5 + 0.4 * c.noise(c.p[0] * 30, c.p[1] * 4, c.p[2] * 30)); // prettier-ignore
              if (f < 0.06) col = "#4a7a2a";
              else if (f < 0.18) col = mix(col, "#e0e8c0", 0.6);
              if (f > 0.82 && c.noise(c.p[0] * 20, c.p[1] * 20, c.p[2] * 20) > -0.1) col = mix("#a8804a", "#c8a060", c.rand()); // prettier-ignore
              return lit(col, c.n, 0.45);
            },
          });
          tok++;
        }
        // The tip: a pointed shoot in brown sheaths (all that shows at rest).
        k.add(k.cone(rOf(n) * 1.15, 0.004, 0.2), {
          pos: [x, g + n * BAMBOO_SEG + 0.1, z],
          weight: 2,
          kind: "token",
          params: [tok, 0],
          color: (c) =>
            lit(mix("#7a5a2a", "#b08a4a", 0.5 + 0.5 * Math.sin(c.p[1] * 90)), c.n, 0.45),
        });
        tok++;
        const top = [x, g + n * BAMBOO_SEG + 0.12, z];
        for (let m = 0; m < 5; m++) {
          const a = (m / 5) * TAU + rand();
          const d = unit([Math.sin(a), 0.25 + 0.3 * rand(), Math.cos(a)]);
          k.add(blade(k, { L: 0.2, W: 0.022, grid: 8, bend: (v) => -0.2 * v * v }), {
            pos: top,
            quat: quatFromTo([0, 1, 0], d),
            weight: 2,
            kind: "token",
            params: [tok, 0],
            color: (c) => lit(mix("#4a8a2a", "#8ac04a", c.v), c.n, 0.3),
          });
        }
        shoots.push({ at, top, n, first, leaves: tok });
        tok++;
      }
      k.data = { shoots };
      for (let i = 0; i < 6; i++) {
        const a = rand() * TAU;
        const s = 0.04 + rand() * 0.04;
        k.add(k.ellipsoid(s * 1.3, s * 0.6, s), {
          pos: [Math.sin(a) * 0.45, 0.02, Math.cos(a) * 0.45],
          rot: [0, rand() * 180, 0],
          color: (c) => lit(mix("#7a7468", "#aaa498", c.rand() * 0.5), c.n, 0.4),
        });
      }
    }

drive:
drive(t, c, out, info) {
      const s = progress(c.grow) * BAMBOO_SECS;
      const on = c.grow > 0;
      const shoots = info.data?.shoots || [];
      out.tokens = [];
      const knocks = [];
      shoots.forEach((sh, n) => {
        const t0 = 0.15 + 0.25 * n;
        const e = [];
        for (let j = 0; j < sh.n; j++) {
          if (n === 0) knocks.push(t0 + 0.3 * j + 0.22);
          const up = on ? easeOut(band(s, t0 + 0.3 * j, t0 + 0.3 * j + 0.26)) : 0;
          const down = on ? ease(band(s, 4.1 + 0.1 * (sh.n - j), 4.35 + 0.1 * (sh.n - j))) : 0;
          e.push(up * (1 - down));
        }
        // The top of section j is where the extended sections below it end.
        let h = 0;
        for (let j = 0; j < sh.n; j++) {
          h += e[j] * BAMBOO_SEG;
          out.tokens[sh.first + j] = {
            base: sh.at,
            offset: [0, h - (j + 1) * BAMBOO_SEG, 0],
            visible: ease(Math.min(1, e[j] * 1.6)),
          };
        }
        out.tokens[sh.first + sh.n] = { base: sh.at, offset: [0, h - sh.n * BAMBOO_SEG, 0] };
        const leaves = on ? easeOut(band(s, t0 + 0.3 * sh.n, t0 + 0.3 * sh.n + 0.6)) * (1 - ease(band(s, 3.8, 4.2))) : 0; // prettier-ignore
        out.tokens[sh.first + sh.n + 1] = { base: sh.top, offset: [0, h - sh.n * BAMBOO_SEG, 0], visible: leaves }; // prettier-ignore
      });
      crossing(c, "bamboo", on ? s : 0, knocks, (i) =>
        out.cues.push({ voice: "hollow", f: 330 * 2 ** ((i % 6) / 7), decay: 0.6, vol: 0.5 }),
      );
    }

build:
build(k, o) {
      reseed(k, o);
      const rand = k.rand;
      const stones = [];
      const kinds = [
        { base: "#8a8a86", dark: "#5a5a58", speck: 0.2, vein: 0.1 },
        { base: "#b8a48a", dark: "#8a7458", speck: 0.1, vein: 0 },
        { base: "#9a5a44", dark: "#6a3a2a", speck: 0.05, vein: 0.05 },
        { base: "#6f7a86", dark: "#46505a", speck: 0.1, vein: 0.15 },
        { base: "#d8d2c6", dark: "#a8a296", speck: 0.3, vein: 0 },
        { base: "#4a4a4a", dark: "#2a2a2a", speck: 0.05, vein: 0.3 },
      ];
      const stone = (pos, size, rot, kind, moves = true) => {
        const kd = kinds[kind % kinds.length];
        const va = randDir(rand);
        stones.push({ home: pos, size, rot, moves });
        k.add(k.sphere(1), {
          pos,
          rot,
          scale: size,
          kind: "token",
          params: [stones.length - 1, 0],
          flat: 0.2,
          interior: 0.1,
          core: shade(kd.base, 0.8),
          color: (c) => {
            const n = c.fbm(c.lp[0] * 2.5, c.lp[1] * 2.5, c.lp[2] * 2.5);
            let col = mix(kd.base, kd.dark, 0.5 + 0.6 * n);
            if (c.noise(c.lp[0] * 40, c.lp[1] * 40, c.lp[2] * 40) > 0.62 - kd.speck)
              col = mix(col, "#2a2a28", 0.5);
            if (kd.vein && Math.abs(Math.sin(dot(c.lp, va) * 9 + n * 3)) < kd.vein * 0.3)
              col = mix(col, "#f2eee6", 0.8);
            const hi = Math.pow(Math.max(0, dot(c.n, unit([-0.4, 0.7, 0.6]))), 14);
            return mix(lit(col, c.n, 0.5), "#ffffff", 0.18 * hi);
          },
        });
      };
      if (o.style === "cairn") {
        let y = 0;
        const n = 7;
        for (let i = 0; i < n; i++) {
          const f = i / (n - 1);
          const w = 0.5 * (1 - 0.6 * f) * (0.9 + 0.2 * rand());
          const h = 0.1 + 0.04 * rand();
          stone(
            [(rand() - 0.5) * 0.08, y + h, (rand() - 0.5) * 0.08],
            [w, h, w * (0.75 + 0.2 * rand())],
            [(rand() - 0.5) * 8, rand() * 180, (rand() - 0.5) * 8],
            i + 1,
            i >= 3,
          );
          y += h * 1.85;
        }
        for (let i = 0; i < 12; i++) {
          const a = rand() * TAU;
          const rr = 0.45 + rand() * 0.35;
          const s = 0.05 + rand() * 0.07;
          stone(
            [Math.sin(a) * rr, s * 0.5, Math.cos(a) * rr],
            [s * 1.3, s * 0.7, s],
            [0, rand() * 180, 0],
            Math.floor(rand() * 6),
            false,
          );
        }
        // The cairn's top four stones topple off and are stacked again.
        k.data = planStones(k, stones, stones.slice(3, n), 1.1);
        return;
      }
      // A heap: big pebbles below, smaller ones resting higher.
      const placed = [];
      const heap = (x, z) => 0.78 * Math.max(0, 1 - (x * x + z * z) / 0.6);
      for (let i = 0; i < 34; i++) {
        let best = null;
        for (let t = 0; t < 30; t++) {
          const a = rand() * TAU;
          const rr = Math.sqrt(rand()) * 0.8;
          const x = Math.sin(a) * rr;
          const z = Math.cos(a) * rr;
          const s = (0.12 + 0.14 * rand()) * (1 - 0.4 * (i / 34));
          let ok = true;
          for (const q of placed) {
            if (
              Math.hypot(q.x - x, q.z - z) < (q.s + s) * 0.9 &&
              Math.abs(q.y - heap(x, z)) < (q.s + s) * 0.7
            )
              ok = false;
          }
          if (ok) {
            best = { x, z, s, y: heap(x, z) };
            break;
          }
        }
        if (!best) continue;
        placed.push(best);
        stone(
          [best.x, best.y + best.s * 0.45, best.z],
          [best.s * 1.25, best.s * 0.7, best.s],
          [(rand() - 0.5) * 30, rand() * 180, (rand() - 0.5) * 30],
          Math.floor(rand() * 6),
        );
      }
      // Five stones of shrinking size make the cairn, biggest at the bottom.
      const pick = [];
      for (const want of [0.3, 0.25, 0.2, 0.16, 0.12]) {
        let best = null;
        for (const st of stones) {
          if (pick.includes(st)) continue;
          if (!best || Math.abs(st.size[0] - want) < Math.abs(best.size[0] - want)) best = st;
        }
        pick.push(best);
      }
      let y = 0.005;
      for (const st of pick) {
        const h = st.size[1];
        st.cairnAt = [(rand() - 0.5) * 0.04, y + h * 0.9, (rand() - 0.5) * 0.04];
        y += h * 1.75;
      }
      k.data = planStones(k, stones, pick);
      k.add(k.disc(1.05), {
        pos: [0, 0.005, 0],
        color: (c) =>
          c.n[1] < 0
            ? "#5a5244"
            : mix("#b8ab90", "#8a7e66", c.noise(c.p[0] * 50, 0, c.p[2] * 50) * 0.5 + 0.5),
      });
    }

drive:
drive(t, c, out, info) {
      const s = progress(c.stack) * STONE_SECS;
      const on = c.stack > 0;
      const d = info.data;
      if (!d) return;
      out.tokens = d.stones.map((st) => {
        if (!on || !st.moves) return { base: st.home };
        // Where it is and how it is turned at each stage.
        const poses = [
          { p: st.home, q: [0, 0, 0, 1] },
          { p: st.scatter, q: st.scatterQ },
        ];
        if (st.cairn) poses.push({ p: st.cairn, q: st.cairnQ });
        let a = poses[0];
        let b = poses[0];
        let f = 0;
        let hop = 0;
        if (s < st.t0) a = b = poses[0];
        else if (s < st.t0 + 0.75) {
          // Tumbling out: it drops and rolls, with a bounce at the end.
          [a, b, f] = [poses[0], poses[1], band(s, st.t0, st.t0 + 0.75)];
          hop = 0.05 * Math.sin(Math.PI * band(f, 0.6, 1));
        } else if (st.cairn && s >= st.t1 && s < st.t1 + 0.4) {
          [a, b, f] = [poses[1], poses[2], band(s, st.t1, st.t1 + 0.4)];
          hop = 0.28 * Math.sin(Math.PI * f);
        } else if (s >= STONE_BACK && s < STONE_BACK + 0.8) {
          [a, b, f] = [poses[poses.length - 1], poses[0], band(s, STONE_BACK + st.lag, STONE_BACK + st.lag + 0.6)]; // prettier-ignore
          hop = 0.22 * Math.sin(Math.PI * f);
        } else if (s >= STONE_BACK + 0.8) a = b = poses[0];
        else a = b = poses[st.cairn && s >= st.t1 + 0.4 ? 2 : 1];
        const e = ease(f);
        const p = lerp3(a.p, b.p, e);
        return { base: st.home, offset: sub([p[0], p[1] + hop, p[2]], st.home), quat: slerpQ(a.q, b.q, e) }; // prettier-ignore
      });
      const clacks = d.stones.filter((st) => st.cairn && st.moves).map((st) => st.t1 + 0.4);
      crossing(c, "rocks", on ? s : 0, [0.5, ...clacks, STONE_BACK + 0.6], (n) =>
        out.cues.push(
          n === 0 || n === clacks.length + 1
            ? { voice: "pebble", f: 2300, n: 5, vol: 0.8 }
            : { voice: "stone", f: 380 + 40 * n, decay: 0.8, vol: 0.8 },
        ),
      );
    }

build:
build(k) {
      const rand = k.rand;
      // The kelp bends away from the nibbling fish (a morph towards +x, more
      // the higher it is), one channel per band of stalks from left to right.
      const bent = (p, g) => {
        const f = Math.pow(Math.max(0, (p[1] - 0.05) / 2.3), 1.7);
        return { to: [p[0] + 0.42 * f, p[1] - 0.12 * f * f, p[2] + 0.08 * f], channel: g };
      };
      // Sandy sea floor with rocks.
      grassMound(k, 0.85, 0, {
        h: 0.06,
        colors: ["#b8a070", "#d0bc8c", "#e2d4aa"],
        soil: "#7a6444",
      });
      for (let i = 0; i < 7; i++) {
        const a = rand() * TAU;
        const s = 0.07 + rand() * 0.08;
        k.add(k.ellipsoid(s * 1.3, s * 0.7, s), {
          pos: [Math.sin(a) * (0.25 + rand() * 0.45), 0.04, Math.cos(a) * (0.25 + rand() * 0.45)],
          rot: [0, rand() * 180, 0],
          color: (c) => {
            const alga = c.n[1] > 0.3 && c.noise(c.p[0] * 25, c.p[1] * 25, c.p[2] * 25) > 0;
            return lit(alga ? "#b0508a" : mix("#5a5650", "#7a766e", c.rand()), c.n, 0.4);
          },
        });
      }
      const amber = ["#22220e", "#3a3a16", "#56521e", "#766c28", "#968834", "#b4a44a"];
      const current = unit([0.8, 1, 0.2]);
      const stipes = [
        { x: 0, z: 0, h: 2.35 },
        { x: -0.16, z: -0.08, h: 2.05 },
        { x: 0.15, z: -0.12, h: 2.15 },
        { x: 0.06, z: 0.16, h: 1.75 },
        { x: -0.12, z: 0.14, h: 1.55 },
        { x: 0.22, z: 0.1, h: 1.35 },
        { x: -0.24, z: 0.02, h: 1.2 },
      ];
      const blades = [];
      for (const st of stipes) {
        const g = clamp(Math.floor(((st.x + 0.26) / 0.5) * 4), 0, 3);
        const SW = { channel: g, to: (c) => bent(c.p, g).to };
        const lean = [current[0] * 0.35, 0, current[2] * 0.35];
        const pts = [];
        for (let i = 0; i <= 6; i++) {
          const t = i / 6;
          pts.push([
            st.x + lean[0] * t * t * st.h + 0.035 * Math.sin(t * 8 + st.x * 10),
            0.05 + st.h * t,
            st.z + lean[2] * t * t * st.h + 0.035 * Math.cos(t * 7 + st.z * 10),
          ]);
        }
        const stem = spline(pts);
        k.add(
          k.tube(stem, (t) => 0.014 * (1 - 0.4 * t), { samples: 48, grid: 8 }),
          {
            ...SW,
            color: (c) => lit(amber[2], c.n, 0.3),
          },
        );
        // Holdfast roots.
        for (let r = 0; r < 5; r++) {
          const a = rand() * TAU;
          const b = [st.x, 0.05, st.z];
          const root = spline([
            add(b, [0, 0.06, 0]),
            add(b, [Math.sin(a) * 0.05, 0.02, Math.cos(a) * 0.05]),
            add(b, [Math.sin(a) * 0.11, -0.01, Math.cos(a) * 0.11]),
          ]);
          k.add(k.tube(root, 0.011, { samples: 8, grid: 6 }), { color: amber[1] });
        }
        // Blades along the stipe, each on a gas float, streaming with the
        // current; a spray of them at the top floats in the canopy.
        const nb = Math.floor(st.h / 0.2);
        for (let j = 1; j <= nb; j++) {
          const t = Math.min(1, j / nb);
          const p = stem(t);
          const a = j * 2.4 + rand();
          const out = [Math.sin(a), 0, Math.cos(a)];
          const dir = unit(add(add(mul(out, 0.7), mul(current, 1.1)), [0, 0.2 * t, 0]));
          blades.push({
            p: add(p, mul(out, 0.018)),
            dir,
            L: 0.45 + 0.3 * rand(),
            W: 0.09 + 0.04 * rand(),
            g,
          });
          k.add(k.ellipsoid(0.02, 0.028, 0.02), {
            pos: add(p, mul(out, 0.018)),
            weight: 2,
            ...SW,
            color: (c) => lit(amber[4], c.n, 0.4),
          });
        }
      }
      for (const b of blades) {
        const side = unit(vec.cross(b.dir, [0, 1, 0]));
        const nrm = unit(vec.cross(side, b.dir));
        const shape = k.param(
          (u, v) => {
            const x = (u - 0.5) * 2;
            const w = b.W * Math.sin(Math.PI * Math.pow(Math.min(v, 1), 0.55)) ** 0.7;
            const ruffle = 0.018 * Math.sin(v * 26 + x * 2.5) * Math.abs(x) ** 1.5;
            const off = ruffle - 0.12 * b.L * v * v;
            return [
              b.p[0] + side[0] * x * w + b.dir[0] * v * b.L + nrm[0] * off,
              b.p[1] + side[1] * x * w + b.dir[1] * v * b.L + nrm[1] * off,
              b.p[2] + side[2] * x * w + b.dir[2] * v * b.L + nrm[2] * off,
            ];
          },
          { grid: 14 },
        );
        k.add(shape, {
          opacity: 0.9,
          flat: 0.2,
          channel: b.g,
          to: (c) => bent(c.p, b.g).to,
          color: (c) => {
            const mid = Math.abs(c.u - 0.5) < 0.05;
            const edge = Math.abs(c.u - 0.5) * 2;
            const tone = clamp(
              0.3 + 0.45 * c.v + 0.2 * edge + 0.1 * c.rand() - (mid ? 0.2 : 0),
              0,
              1,
            );
            return lit(ramp(amber, tone), c.n, 0.25);
          },
        });
      }
      // Three fish that come to nibble (hidden until a tap): each built at
      // the blade it nibbles, in front, and turned to face along its path.
      const nibbles = blades
        .filter((b) => b.p[0] < 0.05 && b.p[1] > 0.7 && b.p[1] < 1.7)
        .sort((a, b) => b.p[2] - a.p[2])
        .slice(0, 3);
      const fish = nibbles.map((b, i) => {
        const at = add(b.p, mul(b.dir, b.L * 0.45));
        const nib = add(at, [-0.13, 0, 0.14]);
        const f = {
          from: [-1.15, nib[1] + 0.2 * (i - 1), nib[2] + 0.3],
          nib,
          peck: unit(sub(at, nib)),
          to: [1.1, nib[1] + 0.3, nib[2] - 0.4],
        };
        const cols = [
          ["#3a8aff", "#ffd11a"],
          ["#ffd11a", "#ff9a1a"],
          ["#ff5a8a", "#ffe0e8"],
        ][i];
        const tok = { kind: "token", params: [i, 0], pattern: false, weight: 3, fit: false };
        k.add(k.ellipsoid(0.085, 0.052, 0.028), {
          ...tok,
          pos: nib,
          color: (c) =>
            c.lp[0] > 0.058 && Math.abs(c.lp[1]) < 0.01 && Math.abs(c.lp[2]) > 0.012 ? "#111111" : lit(cols[0], c.n, 0.3), // prettier-ignore
        });
        k.add(k.ellipsoid(0.034, 0.042, 0.009), {
          ...tok,
          pos: add(nib, [-0.098, 0, 0]),
          color: cols[1],
        });
        return f;
      });
      k.data = { fish };
      k.fitMorphs = false;
      // Two bright fish nosing about, and bubbles drifting up.
      for (let f = 0; f < 2; f++) {
        const a = f * 2.8 + 0.4;
        const rr = 0.62 - f * 0.12;
        const p = [Math.sin(a) * rr, 0.9 + f * 0.55, Math.cos(a) * rr];
        const q = quatFromTo([1, 0, 0], [Math.cos(a), 0, -Math.sin(a)]);
        const fish = { kind: "orbit", params: [0.35, 0], pattern: false, weight: 3 };
        k.add(k.ellipsoid(0.07, 0.045, 0.025), {
          pos: p,
          quat: q,
          ...fish,
          color: (c) =>
            c.lp[0] > 0.05 && Math.abs(c.lp[1]) < 0.01 ? "#1a1a1a" : lit("#ff7a1a", c.n, 0.3),
        });
        k.add(k.ellipsoid(0.028, 0.035, 0.008), {
          pos: add(p, quatRotate(q, [-0.08, 0, 0])),
          quat: q,
          ...fish,
          color: "#f06010",
        });
      }
      k.cloud({ share: 0.004, size: 1.1, pattern: false }, (r) => ({
        p: [(r() - 0.5) * 0.5, 0.2 + r() * 0.5, (r() - 0.5) * 0.5],
        color: "#e8f6ff",
        opacity: 0.5,
        kind: "rise",
        params: [1.3, r()],
      }));
    }

drive:
drive(t, c, out, info) {
      const s = progress(c.nibble) * KELP_SECS;
      const on = c.nibble > 0;
      out.morph = [0, 1, 2, 3].map((g) => {
        const idle = 0.35 * Math.sin(t * 0.8 + g * 0.9);
        if (!on) return idle;
        const tau = s - (1.8 + 0.18 * g);
        let push = 0;
        if (tau > 0 && tau < 0.6) push = Math.sin((Math.PI / 2) * (tau / 0.6));
        else if (tau >= 0.6) push = Math.cos(2.6 * (tau - 0.6)) * Math.exp(-(tau - 0.6) / 1.1);
        return idle + 1.1 * push * (1 - band(s, KELP_SECS - 0.6, KELP_SECS));
      });
      out.tokens = (info.data?.fish || []).map((f, i) => {
        if (!on) return { base: f.nib, visible: 0 };
        const t0 = 0.2 * i;
        let p;
        let dir;
        if (s < t0 + 1.2) {
          const g = easeOut(band(s, t0, t0 + 1.2));
          p = lerp3(f.from, f.nib, g);
          p = add(p, [0, 0.04 * Math.sin(g * 9 + i), 0]);
          dir = sub(f.nib, f.from);
        } else if (s < 2.6 + 0.15 * i) {
          // Nibbling: quick little pecks at the blade.
          const w = s - t0 - 1.2;
          p = add(f.nib, mul(f.peck, 0.035 * Math.max(0, Math.sin(w * 16))));
          dir = f.peck;
        } else {
          const g = ease(band(s, 2.6 + 0.15 * i, 3.9 + 0.15 * i));
          p = lerp3(f.nib, f.to, g);
          dir = lerp3(f.peck, sub(f.to, f.nib), Math.min(1, g * 4));
        }
        const flat = unit([dir[0], dir[1] * 0.3, dir[2]]);
        return {
          base: f.nib,
          offset: sub(p, f.nib),
          quat: quatFromTo([1, 0, 0], flat),
          visible: band(s, t0, t0 + 0.3) * (1 - band(s, 3.6 + 0.15 * i, 3.9 + 0.15 * i)),
        };
      });
    }

build:
build(k, o) {
      const H = ICE_RIM;
      const R = 0.47;
      const coneR = (y) => 0.025 + (R - 0.025) * (y / H);
      const flavours = [o.f1, o.f2, o.f3].map((f) => FLAVOURS[f] || FLAVOURS.vanilla);
      const n = clamp(Math.round(o.scoops), 1, 3);
      // The waffle cone: a diamond lattice of grooves on a toasted cone.
      k.add(k.cone(0.025, R, H, { caps: false }), {
        pos: [0, H / 2, 0],
        flat: 0.22,
        interior: 0.08,
        core: flavours[0].deep,
        color: (c) => {
          const y = c.lp[1] + H / 2;
          const f1 = c.u * 11 + y * 5.2;
          const f2 = c.u * 11 - y * 5.2;
          const g = Math.min(Math.abs(f1 - Math.round(f1)), Math.abs(f2 - Math.round(f2)));
          let col = mix("#e4ad66", "#c98a44", 0.5 + 0.6 * c.noise(c.p[0] * 9, y * 9, c.p[2] * 9));
          if (g < 0.075) col = mix("#9a5a26", col, (g / 0.075) * 0.5);
          else col = shade(col, 0.96 + 0.16 * smoothstep(0.1, 0.45, g));
          return lit(c, col, 0.74, 0.38);
        },
      });
      // Its rolled rim.
      k.add(k.torus(R + 0.005, 0.045), {
        pos: [0, H, 0],
        flat: 0.25,
        weight: 1.5,
        color: (c) =>
          lit(c, mix("#eab676", "#c78a45", 0.5 + 0.5 * c.noise(c.p[0] * 30, 0, c.p[2] * 30))),
      });
      // Scoops stacked on the cone, each with a ruffled lip.
      const radii = [0.5, 0.46, 0.42];
      const scoops = k.part("scoops", { pivot: [0, H, 0] });
      const melt = (c) => [ICE_MELT + 0.2 * c.noise(c.p[0] * 3, c.p[1] * 3, c.p[2] * 3), 0];
      let y = H + 0.2;
      let top = null;
      for (let i = 0; i < n; i++) {
        const r = radii[i];
        const seed = 3 + i * 7.3;
        const shape = scoopShape(k, r, seed);
        const pos = [0.015 * (i % 2 ? 1 : -1), y, 0];
        k.add(shape, {
          pos,
          rot: [0, i * 47, 0],
          flat: 0.3,
          interior: 0.1,
          core: flavours[i].base,
          part: scoops,
          kind: "melt",
          params: melt,
          color: scoopColor(flavours[i], seed),
        });
        top = { pos, r };
        y += r * 1.28;
      }
      const tipY = top.pos[1] + top.r * 1.02;
      if (o.sprinkles) {
        sprinkles(
          k,
          0.018,
          (rand) => {
            const d = randDir(rand);
            if (d[1] < 0.15) return null;
            return { p: add(top.pos, mul(d, top.r * 1.04)), n: d };
          },
          { kind: "melt", params: [ICE_MELT + 0.05, 0], part: scoops },
        );
      }
      if (o.cherry) {
        const cp = [top.pos[0], tipY + 0.09, top.pos[2]];
        k.add(k.sphere(0.12), {
          pos: cp,
          scale: [1, 0.92, 1],
          flat: 0.25,
          weight: 2.5,
          pattern: false,
          part: scoops,
          kind: "melt",
          params: [ICE_MELT + 0.05, 0],
          color: (c) =>
            glossy(c, mix("#d0102a", "#8e0718", smoothstep(0.3, -0.8, c.n[1])), 0.9, 36),
        });
        k.add(
          k.tube(
            spline([add(cp, [0, 0.09, 0]), add(cp, [0.03, 0.2, 0.01]), add(cp, [0.1, 0.29, 0.02])]),
            0.014,
          ),
          {
            flat: 0.3,
            weight: 3,
            pattern: false,
            part: scoops,
            kind: "melt",
            params: [ICE_MELT + 0.05, 0],
            color: (c) => lit(c, "#6b8a2a"),
          },
        );
      }
      // A melted collar round the rim and drips that run down the cone as it
      // warms (they grow in with Warmth).
      const drip = (c) => glossy(c, flavours[0].base, 0.5, 20, 0.78, 0.3);
      const ph = k.rand() * TAU;
      k.add(
        k.param(
          (u, v) => {
            const a = u * TAU;
            const depth = 0.13 + 0.05 * Math.sin(a * 5 + ph) + 0.03 * Math.sin(a * 11);
            const yy = H + 0.03 - v * depth;
            const rr = coneR(yy) + 0.018;
            return [rr * Math.sin(a), yy, rr * Math.cos(a)];
          },
          { grid: 48 },
        ),
        {
          flat: 0.3,
          weight: 1.5,
          kind: "grow",
          params: (c) => [0.04 + 0.3 * c.v, 0],
          color: drip,
        },
      );
      const drips = 11;
      for (let i = 0; i < drips; i++) {
        const a0 = (i / drips) * TAU + k.rand() * 0.4;
        const L = 0.25 + k.rand() * 0.55;
        const y0 = H - 0.06;
        const curve = (t) => {
          const yy = y0 - L * t;
          const a = a0 + 0.06 * Math.sin(t * 5 + i);
          const rr = coneR(yy) + 0.02;
          return [rr * Math.sin(a), yy, rr * Math.cos(a)];
        };
        k.add(
          k.tube(curve, (t) => 0.03 + 0.022 * smoothstep(0.7, 0.97, t) * (1 - t * 0.3), {
            caps: true,
            samples: 64,
            grid: 24,
          }),
          {
            flat: 0.3,
            weight: 2,
            kind: "grow",
            params: (c) => [0.15 + 0.8 * (c.t ?? 0) * (L / 0.8), 0],
            color: drip,
          },
        );
      }
    }

drive:
drive(t, c, out) {
      // A tap warms it up quickly, so the scoops slump and drips run down the
      // cone, holds for a moment, then it refreezes.
      const p = c.thaw > 0 ? 1 - c.thaw : 1;
      const warm = 1 - Math.pow(1 - clamp(p / 0.28, 0, 1), 2);
      const tap = c.thaw > 0 ? 0.85 * warm * (1 - smoothstep(0.55, 0.95, p)) : 0;
      const w = Math.max(c.warmth, tap);
      out.energy = w;
      out.grow = w;
      // Melt slumps everything towards the floor (the cone's tip), so the
      // scoops rise by what the rim would sink: they flatten onto the cone
      // and ooze over its edge instead of sinking through it.
      out.parts.scoops = { offset: [0, ICE_RIM * 0.895 * ICE_MELT * w, 0] };
    }

build:
build(k, o) {
      // Seeds: one teardrop per cell of a grid, in a band of the flesh.
      const seedAt = (p, rho) => {
        if (rho < 0.35 || rho > 0.74) return false;
        const S = 0.16;
        const ix = Math.floor(p[0] / S);
        const iy = Math.floor(p[1] / S);
        const iz = Math.floor(p[2] / S);
        if (hash3(ix, iy, iz) > 0.55) return false;
        const sc = [
          (ix + 0.3 + 0.4 * hash3(iy, iz, ix)) * S,
          (iy + 0.3 + 0.4 * hash3(iz, ix, iy)) * S,
          (iz + 0.3 + 0.4 * hash3(ix + 7, iy, iz)) * S,
        ];
        const dp = sub(p, sc);
        const r = unit(sc);
        const along = dot(dp, r);
        const perp = len(sub(dp, mul(r, along)));
        return (along / 0.05) ** 2 + (perp / 0.028) ** 2 < 1;
      };
      // The whole melon is six slices (pieces) across its length, each its
      // band of rind and its cut faces; a knife (one copy per cut) chops it.
      const slices = [];
      const knives = [];
      let hinge = [0, 0, 1];
      let axis = [1, 0, 0];
      const whole = (pos, yaw) => {
        const A = 1.2;
        const B = 0.92;
        const q = quatEuler(0, yaw, 0);
        const qi = [-q[0], -q[1], -q[2], q[3]];
        const local = (p) => quatRotate(qi, sub(p, pos));
        hinge = quatRotate(q, [0, 0, 1]);
        axis = quatRotate(q, [1, 0, 0]);
        const n = 6;
        const xs = [];
        for (let i = 0; i <= n; i++) xs.push(-A + (2 * A * i) / n);
        const rAt = (x) => B * Math.sqrt(Math.max(0, 1 - (x / A) ** 2));
        const flesh = (c) => {
          const lp = local(c.p);
          const rho = Math.hypot(lp[0] / A, lp[1] / B, lp[2] / B);
          if (seedAt(lp, rho)) return keep(MELON.seed);
          const col = melonFlesh(rho, c);
          return c.noise(c.p[0] * 40, c.p[1] * 40, c.p[2] * 40) > 0.55 ? mix(col, "#ffffff", 0.3) : col; // prettier-ignore
        };
        for (let i = 0; i < n; i++) {
          const token = slices.length;
          const piece = { kind: "token", params: [token, 0] };
          const [x0, x1] = [xs[i], xs[i + 1]];
          slices.push({ foot: add(pos, quatRotate(q, [(x0 + x1) / 2, -B * 0.98, 0])) });
          k.add(
            k.param(
              (u, v) => {
                const x = x0 + u * (x1 - x0);
                const r = rAt(x);
                const th = v * TAU;
                return [x, r * Math.cos(th), r * Math.sin(th)];
              },
              {
                grid: 40,
                normal: (u, v) => {
                  const x = x0 + u * (x1 - x0);
                  const r = rAt(x);
                  const th = v * TAU;
                  return unit([x / (A * A), (r * Math.cos(th)) / (B * B), (r * Math.sin(th)) / (B * B)]); // prettier-ignore
                },
              },
            ),
            {
              even: true,
              opacity: 1,
              jitter: 0.015,
              pos,
              quat: q,
              flat: 0.2,
              ...piece,
              color: (c) => {
                const [x, y, z] = c.lp;
                let col = melonSkin(c, Math.atan2(z, y), x);
                col = mix(col, "#d8d27c", 0.7 * smoothstep(-0.7, -0.95, c.ln[1]));
                if (x > A * 0.97) col = mix(col, "#6b5a2a", smoothstep(0.97, 0.995, x / A));
                return col;
              },
            },
          );
          for (const [x, sgn] of [
            [x0, -1],
            [x1, 1],
          ]) {
            if ((i === 0 && sgn < 0) || (i === n - 1 && sgn > 0)) continue;
            const r = rAt(x) * 0.995;
            k.add(
              k.param(
                (u, v) => {
                  const a = u * TAU;
                  return [x, Math.cos(a) * v * r, Math.sin(a) * v * r];
                },
                { grid: 40, normal: () => [sgn, 0, 0] },
              ),
              {
                even: true,
                opacity: 1,
                jitter: 0.015,
                pos,
                quat: q,
                flat: 0.15,
                weight: 1.3,
                ...piece,
                color: flesh,
              },
            );
          }
        }
        // The knife: a steel blade across the melon with a dark handle
        // towards you, built down in each cut and lifted clear at rest.
        const lift = B * 2 + 0.12;
        const H = 0.5;
        for (let i = 0; i < n - 1; i++) {
          const x = xs[n - 1 - i];
          const part = k.part(`knife${i}`, { pivot: add(pos, quatRotate(q, [x, 0, 0])) });
          knives.push({ lift });
          k.add(
            k.param((u, v) => [x, -B + v * H, (u - 0.5) * 1.95], {
              grid: 24,
              normal: () => [1, 0, 0],
            }),
            {
              even: true,
              pos,
              quat: q,
              part,
              share: 0.02,
              flat: 0.3,
              size: 1.3,
              jitter: 0.005,
              opacity: 1,
              pattern: false,
              fit: false,
              // Brushed steel, bright along the edge and the spine.
              color: (c) => {
                const h = c.v;
                const col = h < 0.1 ? "#eef1f4" : h > 0.94 ? "#b8bec6" : mix("#aeb4bc", "#d5d9de", 0.5 + 0.5 * Math.sin(c.u * 9)); // prettier-ignore
                return keep(col);
              },
            },
          );
          k.add(evenCylinder(0.055, 0.055, 0.45), {
            even: true,
            opacity: 1,
            jitter: 0.015,
            pos: add(pos, quatRotate(q, [x, -B + H * 0.75, 1.2])),
            quat: quatMul(q, quatEuler(90, 0, 0)),
            part,
            share: 0.002,
            flat: 0.3,
            pattern: false,
            fit: false,
            color: (c) => keep(lit(c, mix("#3a2418", "#24160e", c.rand()), 0.8, 0.35)),
          });
        }
        // (No reach for the raised knife: it may pass the frame's top for a
        // moment rather than shrink the melon at rest.)
      };
      // A wedge cut from a round slice: apex up, rind at the bottom.
      const wedge = (pos, yaw, R, T, span = 1.05) => {
        const a0 = -span / 2;
        const q = quatEuler(0, yaw, 0);
        const place = { pos, quat: q, part: k.part("wedge", { pivot: add(pos, [0, -R, 0]) }) };
        const rows = [
          [0.5, 4, 0.1],
          [0.66, 5, 0.0],
        ];
        const seed = (rho, a) => {
          for (const [rr, cnt, off] of rows) {
            const dr = (rho - rr) * R;
            if (Math.abs(dr) > 0.06) continue;
            const step = span / cnt;
            const j = Math.round((a - a0) / step - 0.5 - off);
            const aj = a0 + (j + 0.5 + off) * step;
            const dt = (a - aj) * rho * R;
            const w = 0.022 * (1 - 0.45 * clamp(dr / 0.045, -1, 1));
            if ((dr / 0.045) ** 2 + (dt / w) ** 2 < 1) return true;
          }
          return false;
        };
        const face = (rho, a, c) => {
          if (seed(rho, a)) return keep(mix(MELON.seed, "#4a3326", 0.3 * c.rand()));
          const col = melonFlesh(rho, c);
          // Juicy glints on the cut face.
          return c.noise(c.p[0] * 40, c.p[1] * 40, c.p[2] * 40) > 0.55
            ? mix(col, "#ffffff", 0.3)
            : col;
        };
        for (const side of [1, -1]) {
          k.add(
            k.param(
              (u, v) => {
                const a = a0 + u * span;
                return [v * R * Math.sin(a), -v * R * Math.cos(a), (side * T) / 2];
              },
              { grid: 48, normal: () => [0, 0, side], thick: T },
            ),
            {
              even: true,
              opacity: 1,
              jitter: 0.015,
              ...place,
              flat: 0.15,
              interior: side > 0 ? 0.12 : 0,
              core: (c) => melonFlesh(c.v, c),
              color: (c) => face(c.v, a0 + c.u * span, c),
            },
          );
        }
        // The rind along the arc, striped like the whole melon.
        k.add(
          k.param(
            (u, v) => {
              const a = a0 + u * span;
              return [R * Math.sin(a), -R * Math.cos(a), (v - 0.5) * T];
            },
            { grid: 48, normal: (u) => [Math.sin(a0 + u * span), -Math.cos(a0 + u * span), 0] },
          ),
          {
            even: true,
            opacity: 1,
            jitter: 0.015,
            ...place,
            flat: 0.2,
            color: (c) => melonSkin(c, (a0 + c.u * span) * 1.6, 0),
          },
        );
        // The two cut sides.
        for (const [a, s] of [
          [a0, -1],
          [-a0, 1],
        ]) {
          k.add(
            k.param((u, v) => [u * R * Math.sin(a), -u * R * Math.cos(a), (v - 0.5) * T], {
              grid: 32,
              normal: () => [s * Math.cos(a), s * Math.sin(a), 0],
            }),
            {
              even: true,
              opacity: 1,
              jitter: 0.015,
              ...place,
              flat: 0.15,
              color: (c) => melonFlesh(c.u, c),
            },
          );
        }
      };
      // The whole melon lies at an angle, so its cut faces turn towards you.
      if (o.style === "whole") whole([0, 0, 0], WM_YAW);
      else if (o.style === "wedge") wedge([0, 0.3, 0], 28, 1.1, 0.34);
      else {
        whole([-0.45, 0, -0.6], WM_YAW);
        wedge([0.72, -0.92 + 0.78, 0.6], 30, 0.78, 0.26);
      }
      k.data = { slices, knives, hinge, axis };
    }

drive:
drive(t, c, out, info) {
      const s = since(c.chop, WM_SECS);
      const d = info.data;
      if (!d) return;
      const on = s >= 0;
      const fan = on ? easeOut(band(s, WM_FAN, WM_FAN + 0.5)) * (1 - smooth(band(s, 2.8, 3.4))) : 0;
      const n = d.slices.length;
      out.tokens = d.slices.map((sl, i) => {
        const f = (i - (n - 1) / 2) / ((n - 1) / 2);
        const settle = on ? 0.05 * wobble(s - WM_FAN - 0.5, 0.6, 13) * f : 0;
        const q = quatAxisAngle(d.hinge, -f * 0.75 * fan - settle);
        return { base: sl.foot, quat: q, offset: mul(d.axis, f * 0.18 * fan) };
      });
      // The knife: one copy per cut (each drawn in its own place), shown in
      // turn as it chops.
      d.knives.forEach((kn, i) => {
        const t0 = WM_CHOP0 + WM_CHOP * i;
        const u = on ? s - t0 : -1;
        const down = u < 0 ? 0 : u < 0.1 ? easeIn(u / 0.1) : u < 0.14 ? 1 : 1 - smooth((u - 0.14) / 0.1); // prettier-ignore
        // One knife at a time: each shows from its own chop until the next.
        const last = i === d.knives.length - 1;
        const shown = on && u >= (i ? 0 : -0.06) && (last ? u < 0.4 : u < WM_CHOP);
        const up = i === d.knives.length - 1 && u > 0.24 ? 0.6 * smooth(band(u, 0.24, 0.4)) : 0;
        out.parts[`knife${i}`] = {
          offset: [0, (1 - down) * kn.lift + up, 0],
          visible: shown ? 1 : 0,
        };
      });
      out.parts.wedge = { quat: quatAxisAngle([1, 0, 0], d.slices.length ? 0 : 0.1 * wobble(s, 1.2, 9)) }; // prettier-ignore
      const list = d.knives.map((kn, i) => [WM_CHOP0 + WM_CHOP * i + 0.09, [{ voice: "slap", f: 800 + 60 * i, vol: 0.8 }, { voice: "crack", f: 1200, bright: 0.2, decay: 0.7, vol: 0.4 }]]); // prettier-ignore
      if (d.slices.length) list.push([WM_FAN + 0.05, { voice: "squish", pitch: 1.1, bright: 0.7, decay: 1.2 }]); // prettier-ignore
      cuesAt(c, "watermelon", s, list, out);
    }

build:
build(k, o) {
      const R = 0.8;
      const H = 0.7;
      const sponge = {
        vanilla: "#f3d28c",
        chocolate: "#5e3522",
        velvet: "#a8232f",
        strawberry: "#f6b3b8",
      }[o.sponge];
      // Cake stand: a plate on a pedestal.
      k.add(
        revolve(k, [
          [0.42, -0.5],
          [0.4, -0.47],
          [0.16, -0.42],
          [0.1, -0.3],
          [0.1, -0.14],
          [0.2, -0.08],
          [0.9, -0.05],
          [1.02, -0.02],
          [1.04, 0],
          [0.9, 0.0],
          [0, 0.0],
        ]),
        {
          even: true,
          opacity: 1,
          jitter: 0.015,
          flat: 0.2,
          color: (c) => glossy(c, "#f3f1ee", 0.8, 50, 0.76, 0.3),
        },
      );
      // Drips of ganache from the top edge.
      const drips = [];
      for (let i = 0; i < 17; i++) {
        drips.push({
          a: (i / 17) * TAU + (k.rand() - 0.5) * 0.2,
          L: 0.1 + k.rand() * 0.28,
          w: 0.035 + k.rand() * 0.02,
        });
      }
      const dripAt = (a, y) => {
        const d = H - y;
        if (d < 0.07) return true;
        for (const dr of drips) {
          let da = Math.abs(a - dr.a);
          da = Math.min(da, TAU - da) * R;
          if (da > dr.w) continue;
          const end = dr.L - dr.w + Math.sqrt(Math.max(0, dr.w * dr.w - da * da));
          if (d < end) return true;
        }
        return false;
      };
      k.add(evenCylinder(R, R, H), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [0, H / 2, 0],
        flat: 0.2,
        interior: 0.12,
        color: (c) => {
          const y = c.lp[1] + H / 2;
          if (c.s.cap === "top") return glossy(c, o.drip, 0.6, 30);
          if (c.s.cap) return o.frosting;
          const a = c.u * TAU;
          if (dripAt(a, y)) return glossy(c, o.drip, 0.8, 30, 0.8, 0.3);
          const swirl = 0.04 * Math.sin(y * 60 + 2 * c.noise(a * 3, y * 4, 0));
          return lit(c, shade(o.frosting, 1 + swirl), 0.76, 0.34);
        },
        core: (c) => {
          const y = c.p[1];
          const r = Math.hypot(c.p[0], c.p[2]);
          if (r > R * 0.94) return o.frosting;
          if (y > H - 0.04) return o.drip;
          for (const ly of [0.24, 0.47]) {
            if (Math.abs(y - ly) < 0.012) return "#d6344d";
            if (Math.abs(y - ly) < 0.035) return "#fff4e4";
          }
          return shade(sponge, 0.92 + 0.14 * c.noise(c.p[0] * 30, y * 30, c.p[2] * 30));
        },
      });
      // Whipped rosettes around the top edge.
      const rosette = revolve(
        k,
        [
          [0.1, 0],
          [0.105, 0.03],
          [0.075, 0.075],
          [0.035, 0.11],
          [0, 0.125],
        ],
        (a, y) => 1 + 0.2 * Math.cos(a * 8 + y * 30),
        { grid: 40 },
      );
      const ros = 14;
      for (let i = 0; i < ros; i++) {
        const a = (i / ros) * TAU;
        k.add(rosette, {
          opacity: 1,
          jitter: 0.015,
          pos: [Math.sin(a) * (R - 0.1), H - 0.005, Math.cos(a) * (R - 0.1)],
          rot: [0, i * 23, 0],
          flat: 0.3,
          weight: 1.6,
          color: (c) => lit(c, "#fff8f0", 0.8, 0.3),
        });
      }
      // A beaded border at the foot.
      k.add(
        k.tube(
          (t) => [Math.sin(t * TAU) * (R + 0.01), 0.04, Math.cos(t * TAU) * (R + 0.01)],
          (t) => 0.035 + 0.018 * Math.abs(Math.sin(t * Math.PI * 34)),
          { closed: true },
        ),
        {
          even: true,
          opacity: 1,
          jitter: 0.015,
          flat: 0.3,
          weight: 1.4,
          color: (c) => lit(c, "#fff8f0", 0.8, 0.3),
        },
      );
      // Sprinkles on the top.
      sprinkles(k, 0.02, (rand) => {
        const a = rand() * TAU;
        const r = (R - 0.2) * Math.sqrt(rand());
        return { p: [Math.sin(a) * r, H, Math.cos(a) * r], n: [0, 1, 0] };
      });
      // Candles, with flames on one part and smoke on another.
      const flames = k.part("flames");
      const smoke = k.part("smoke");
      const n = clamp(Math.round(o.candles), 1, 9);
      const colours = ["#6ec6ff", "#ffd23f", "#ff7eb6", "#8be38b", "#b28dff"];
      const ch = 0.3;
      for (let i = 0; i < n; i++) {
        const a = (i / n) * TAU + 0.4;
        const rr = n === 1 ? 0 : n <= 4 ? 0.3 : 0.4;
        const x = Math.sin(a) * rr;
        const z = Math.cos(a) * rr;
        const stripe = colours[i % colours.length];
        k.add(evenCylinder(0.032, 0.032, ch), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [x, H + ch / 2, z],
          flat: 0.3,
          weight: 2.5,
          color: (c) => {
            const f = (c.u * 2 + (c.lp[1] + ch / 2) * 9) % 1;
            return lit(c, f < 0.45 ? stripe : "#fffdf6", 0.8, 0.35);
          },
        });
        const wick = [x, H + ch + 0.02, z];
        k.add(evenCylinder(0.007, 0.007, 0.04), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: wick,
          weight: 3,
          pattern: false,
          color: "#2a211c",
        });
        k.cloud({ share: 0.012, size: 0.75, pattern: false, part: flames }, (rand) => {
          const hot = rand();
          const r = 0.022 * Math.sqrt(rand()) * (1 - 0.5 * hot);
          const aa = rand() * TAU;
          return {
            p: [
              wick[0] + Math.sin(aa) * r,
              wick[1] + 0.01 + rand() * 0.02,
              wick[2] + Math.cos(aa) * r,
            ],
            color: mix("#ff9d2e", "#fff6c8", hot),
            opacity: 0.9,
            kind: "flame",
            params: [0.07 + 0.08 * hot, rand()],
          };
        });
        k.cloud({ share: 0.0025, size: 1.1, pattern: false, part: smoke }, (rand) => ({
          p: [wick[0] + (rand() - 0.5) * 0.02, wick[1] + 0.03, wick[2] + (rand() - 0.5) * 0.02],
          color: shade("#c9c4bf", 0.9 + rand() * 0.2),
          opacity: 0.1,
          kind: "rise",
          params: [0.55 + rand() * 0.2, rand()],
        }));
      }
      k.reach([0, H + ch + 0.3, 0]);
    }

drive:
drive(t, c, out) {
      out.parts.flames = { visible: 1 - smoothstep(0, 0.55, c.out) };
      out.parts.smoke = { visible: smoothstep(0.25, 1, c.out) };
    }

build:
build(k) {
      const H = 1.1;
      const R0 = 0.5;
      const R1 = 0.7;
      // The striped paper bucket, with a star badge on the front.
      const badgeA = 0.09;
      const starDist = (x, y) => {
        const a = Math.atan2(x, y);
        const r = Math.hypot(x, y);
        const seg = TAU / 5;
        const f = Math.abs((((a % seg) + seg) % seg) - seg / 2) / (seg / 2);
        const edge = 0.1 + 0.11 * f * f;
        return r - edge;
      };
      k.add(k.cone(R0, R1, H, { caps: "bottom" }), {
        pos: [0, H / 2, 0],
        flat: 0.2,
        color: (c) => {
          const y = c.lp[1] + H / 2;
          if (c.s.cap) return "#c9c1b4";
          const u = (c.u + 1) % 1;
          const r = R0 + (R1 - R0) * (y / H);
          let du = u - badgeA;
          du -= Math.round(du);
          const sd = starDist(du * TAU * r, y - 0.55);
          if (sd < 0) return keep(lit(c, sd > -0.02 ? "#f08a1c" : "#ffd23f", 0.82, 0.3));
          const stripe = Math.floor(u * 16) % 2;
          const edge = Math.abs(((u * 16) % 1) - 0.5) > 0.47;
          let col = stripe ? "#d9252f" : "#fbf6ec";
          if (edge) col = shade(col, 0.9);
          if (y > H - 0.05) col = "#fbf6ec";
          return lit(
            c,
            shade(col, 0.95 + 0.05 * c.noise(c.p[0] * 12, y * 3, c.p[2] * 12)),
            0.72,
            0.4,
          );
        },
      });
      k.add(k.torus(R1, 0.02), {
        pos: [0, H, 0],
        flat: 0.3,
        weight: 2,
        color: (c) => lit(c, "#fbf6ec"),
      });
      // A buttery heap under the kernels, so gaps never show the inside.
      const heapTop = (r) => H + 0.05 + 0.42 * Math.max(0, 1 - (r / 0.82) ** 2);
      k.add(
        k.param(
          (u, v) => {
            const a = u * TAU;
            const r = v * 0.78;
            return [Math.sin(a) * r, heapTop(r) - 0.08, Math.cos(a) * r];
          },
          { grid: 40 },
        ),
        {
          flat: 0.4,
          size: 1.3,
          color: (c) =>
            shade("#f3dfa6", 0.75 + 0.2 * c.noise(c.p[0] * 12, c.p[1] * 12, c.p[2] * 12)),
        },
      );
      // Kernels: fluffy clusters of lobes, packed over the heap and spilled around.
      const kernels = [];
      const place = (p, r) => {
        for (const q of kernels) if (len(sub(p, q.p)) < (r + q.r) * 0.82) return false;
        const lobes = [];
        const m = 5 + Math.floor(k.rand() * 3);
        for (let j = 0; j < m; j++) {
          const d = randDir(k.rand);
          lobes.push({
            c: add(p, mul(d, r * (j ? 0.5 : 0.1))),
            r: r * (j ? 0.5 + k.rand() * 0.15 : 0.62),
          });
        }
        const hull = randDir(k.rand);
        kernels.push({ p, r, lobes, hull, tint: k.rand(), part: 0 });
        return true;
      };
      for (let i = 0; i < 4000 && kernels.length < 120; i++) {
        const a = k.rand() * TAU;
        const r = 0.84 * Math.sqrt(k.rand());
        const s = 0.085 + k.rand() * 0.03;
        const y = heapTop(r) - 0.02 - k.rand() * 0.09;
        place([Math.sin(a) * r, y, Math.cos(a) * r], s);
      }
      for (let i = 0; i < 400 && kernels.length < 128; i++) {
        const a = 0.2 + (k.rand() - 0.5) * 2.4;
        const r = 0.82 + k.rand() * 0.35;
        const s = 0.08 + k.rand() * 0.02;
        place([Math.sin(a) * r, s * 0.8, Math.cos(a) * r], s);
      }
      // The highest kernels are parts that pop.
      const order = kernels
        .map((q, i) => ({ i, y: q.p[1] + 0.05 * k.rand() }))
        .sort((a, b) => b.y - a.y);
      for (let j = 0; j < POPS.length; j++) {
        const q = kernels[order[j * 2].i];
        q.part = k.part(`k${j}`, { pivot: q.p });
      }
      // Kernels deeper in the heap are in shade.
      for (const q of kernels) {
        const top = heapTop(Math.hypot(q.p[0], q.p[2]));
        q.ao = q.p[1] < 0.5 ? 1 : 0.86 + 0.14 * smoothstep(top - 0.12, top - 0.02, q.p[1]);
      }
      const K = kernels.length;
      const areas = kernels.map((q) => {
        let s = 0;
        const acc = q.lobes.map((l) => (s += l.r * l.r));
        return { acc, s };
      });
      // A point on a kernel's outer skin (a few tries to miss the hidden
      // parts where lobes overlap).
      const onKernel = (rand, q, ar) => {
        for (let tries = 0; tries < 4; tries++) {
          const x = rand() * ar.s;
          let li = 0;
          while (li < q.lobes.length - 1 && ar.acc[li] < x) li++;
          const l = q.lobes[li];
          const d = randDir(rand);
          const p = add(l.c, mul(d, l.r));
          let hidden = false;
          for (let j = 0; j < q.lobes.length && !hidden; j++) {
            if (j !== li && len(sub(p, q.lobes[j].c)) < q.lobes[j].r * 0.92) hidden = true;
          }
          if (!hidden) return { li, d, p };
        }
        return null;
      };
      k.cloud({ share: 0.5, flat: 0.45 }, (rand, i, n) => {
        const ki = Math.min(K - 1, Math.floor((i / n) * K));
        const q = kernels[ki];
        const hit = onKernel(rand, q, areas[ki]);
        if (!hit) return null;
        const { li, d, p } = hit;
        // Light on each lobe, shade in the creases between lobes (closer to
        // the kernel's middle) and deeper in the heap, buttery yellow in the folds.
        const light = Math.max(0, dot(d, LIGHT));
        const crease = smoothstep(1.05, 0.62, len(sub(p, q.p)) / q.r);
        let col = mix("#fffdf5", "#fbeab8", 0.15 + 0.5 * q.tint);
        col = mix(col, "#f4cf6a", crease * (0.35 + 0.4 * q.tint));
        if (li === 0 && dot(d, q.hull) > 0.6) col = mix("#c98a3a", "#8a5a22", rand() * 0.5);
        col = shade(col, (0.8 + 0.28 * light) * (1 - 0.14 * crease) * q.ao);
        return { p, n: d, color: col, part: q.part, opacity: 0.97 };
      });
      k.reach([0, heapTop(0) + 0.4, 0]);
    }

drive:
drive(t, c, out) {
      const p = 1 - c.pop;
      for (let j = 0; j < POPS.length; j++) {
        const k = POPS[j];
        // Idle: now and then a kernel hops.
        const q = (t / k.period + k.phase) % 1;
        let y = q < 0.12 ? 0.09 * hop(q / 0.12) : 0;
        let ang = 0;
        // Pop: every kernel jumps high and tumbles, one after another.
        const s = clamp((p - k.delay) / 0.5, 0, 1);
        if (s > 0 && s < 1) {
          y += k.height * hop(s);
          ang = k.spin * easeInOut(s) * TAU;
        }
        out.parts[`k${j}`] = { offset: [0, y, 0], quat: quatAxisAngle(k.axis, ang) };
      }
      out.body = { squash: p < 0.2 ? -0.05 * Math.sin((p / 0.2) * Math.PI) : 0 };
    }

build:
build(k, o) {
      const JELLY = {
        strawberry: "#e8233f",
        lime: "#52c832",
        orange: "#ff8a1a",
        blueberry: "#4863e6",
        grape: "#8e32c4",
      };
      const BANDS = ["#e8233f", "#ff8a1a", "#ffd21f", "#52c832", "#4863e6", "#8e32c4"];
      const H = 1.0;
      const colAt = (y) =>
        o.flavour === "rainbow"
          ? BANDS[clamp(Math.floor((y / (H + 0.02)) * BANDS.length), 0, BANDS.length - 1)]
          : JELLY[o.flavour] || JELLY.strawberry;
      // A plate.
      k.add(
        revolve(
          k,
          [
            [0, -0.02],
            [0.75, -0.02],
            [1.0, 0.01],
            [1.12, 0.07],
            [1.15, 0.08],
          ],
          null,
          { flip: true },
        ),
        {
          even: true,
          opacity: 1,
          jitter: 0.015,
          flat: 0.2,
          color: (c) => {
            const r = Math.hypot(c.p[0], c.p[2]);
            const band = Math.abs(r - 1.06) < 0.02;
            return glossy(c, band ? "#7fb3e6" : "#f1f4f7", 0.6, 40, 0.8, 0.25);
          },
        },
      );
      const jelly = k.part("jelly", { pivot: [0, 0, 0] });
      const pts = [
        [0.8, 0.0],
        [0.84, 0.1],
        [0.82, 0.26],
        [0.72, 0.42],
        [0.6, 0.52],
        [0.58, 0.6],
        [0.6, 0.72],
        [0.55, 0.86],
        [0.42, 0.96],
        [0.22, 1.01],
        [0, 1.02],
      ];
      const flute = (a, y) => 1 + 0.075 * Math.cos(a * 10) * (1 - smoothstep(0.86, 1.0, y));
      const shape = revolve(k, pts, flute, { grid: 96 });
      // A see-through skin: faint where it faces you, denser (bigger splats)
      // and deeper in colour where it turns away, like light through jelly.
      k.add(shape, {
        part: jelly,
        flat: 0.2,
        opacity: 0.3,
        color: (c) => {
          const base = colAt(c.p[1]);
          const r = rim(c);
          const col = mix(lit(c, base, 0.86, 0.3), shade(base, 0.55), 0.6 * r);
          return { c: mix(col, "#ffffff", 0.3 * spec(c, 10)), size: 1 + 0.7 * r * r };
        },
      });
      // Bright highlights on the glossy surface.
      k.add(shape, {
        part: jelly,
        share: 0.1,
        scale: [1.012, 1.006, 1.012],
        flat: 0.2,
        size: 1.25,
        opacity: 0.9,
        color: (c) => {
          const s = spec(c, 14);
          if (s > 0.55) return keep(mix("#ffffff", colAt(c.p[1]), 0.3 * (1 - s)));
          // A soft sheen along the lit side of each flute.
          const fl = Math.cos(Math.atan2(c.p[0], c.p[2]) * 10 - 0.5);
          if (fl > 0.86 && c.p[1] > 0.1 && c.p[1] < 0.85 && dot(c.n, VIEW) > 0.15)
            return keep(mix("#ffffff", colAt(c.p[1]), 0.4));
          return null;
        },
      });
      // The jelly's body: faint splats through the volume.
      const rAt = radiusAt(pts);
      const inside = (rand, shrink) => {
        const y = rand() * H;
        const a = rand() * TAU;
        const r = rAt(y) * flute(a, y) * shrink * Math.sqrt(rand());
        return [Math.sin(a) * r, y, Math.cos(a) * r];
      };
      k.cloud({ share: 0.14, size: 1.8, part: jelly }, (rand) => {
        const p = inside(rand, 0.95);
        return { p, color: shade(colAt(p[1]), 0.7), opacity: 0.08 };
      });
      if (o.fruit) {
        const FRUIT = [
          { c: "#b5102a", r: 0.075 }, // cherries
          { c: "#ffb020", r: 0.07, s: [1.4, 0.7, 0.8] }, // orange pieces
          { c: "#a7d84a", r: 0.065, s: [1, 1.2, 1] }, // grapes
          { c: "#2c2f7a", r: 0.05 }, // blueberries
          { c: "#fff0d8", r: 0.06, s: [1.3, 0.6, 1] }, // pear
        ];
        const pieces = [];
        for (let i = 0; i < 24; i++) {
          const y = 0.12 + k.rand() * 0.72;
          const a = k.rand() * TAU;
          const r = rAt(y) * (0.55 + 0.28 * k.rand());
          const f = FRUIT[i % FRUIT.length];
          pieces.push({ p: [Math.sin(a) * r, y, Math.cos(a) * r], f: { ...f, r: f.r * 1.25 } });
        }
        k.cloud({ share: 0.12, part: jelly, flat: 0.35, pattern: false }, (rand, i, n) => {
          const q = pieces[Math.floor((i / n) * pieces.length)];
          const d = randDir(rand);
          const s = q.f.s || [1, 1, 1];
          const off = [d[0] * s[0] * q.f.r, d[1] * s[1] * q.f.r, d[2] * s[2] * q.f.r];
          const light = Math.max(0, dot(d, LIGHT));
          return {
            p: add(q.p, off),
            n: d,
            color: shade(q.f.c, 0.7 + 0.45 * light),
            opacity: 0.95,
          };
        });
      }
    }

drive:
drive(t, c, out, info) {
      const w = jiggle(t, info.time, c.poke);
      out.parts.jelly = {
        quat: quatEuler((w.tilt[0] * 180) / Math.PI, 0, (w.tilt[2] * 180) / Math.PI),
      };
      out.body = { squash: w.squash };
    }

build:
build(k, o) {
      const n = clamp(Math.round(o.count), 2, 7);
      const T = 0.15;
      const R = 0.8;
      // A plate.
      k.add(
        revolve(
          k,
          [
            [0, 0],
            [0.82, 0],
            [1.05, 0.04],
            [1.15, 0.09],
            [1.17, 0.1],
          ],
          null,
          { flip: true },
        ),
        {
          even: true,
          opacity: 1,
          jitter: 0.015,
          flat: 0.2,
          color: (c) => {
            const r = Math.hypot(c.p[0], c.p[2]);
            return glossy(c, Math.abs(r - 1.1) < 0.02 ? "#3d7cc9" : "#f5f3ee", 0.6, 40, 0.8, 0.25);
          },
        },
      );
      const cake = [
        [0, -T / 2],
        [0.55, -T / 2],
        [0.72, -T / 2 + 0.008],
        [0.785, -T / 4],
        [0.8, 0],
        [0.785, T / 4],
        [0.72, T / 2 - 0.008],
        [0.55, T / 2],
        [0, T / 2],
      ];
      const top = k.part("top", { pivot: [0, 0.02 + (n - 0.5) * T * 0.93, 0], axis: [1, 0, 0] });
      let topY = 0;
      for (let i = 0; i < n; i++) {
        const ph = k.rand() * TAU;
        const ph2 = k.rand() * TAU;
        const shape = revolve(
          k,
          cake,
          (a) => 1 + 0.02 * Math.sin(a * 3 + ph) + 0.012 * Math.sin(a * 7 + ph2),
          { grid: 64 },
        );
        const y = 0.02 + (i + 0.5) * T * 0.93;
        const last = i === n - 1;
        k.add(shape, {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [(k.rand() - 0.5) * 0.03, y, (k.rand() - 0.5) * 0.03],
          rot: [0, k.rand() * 360, 0],
          flat: 0.22,
          interior: 0.1,
          part: last ? top : 0,
          core: (c) =>
            Math.abs(c.lp[1]) > T * 0.38
              ? "#c98a45"
              : shade("#f4dfa6", 0.92 + 0.12 * c.noise(c.p[0] * 40, c.p[1] * 40, c.p[2] * 40)),
          color: (c) => {
            const face = Math.abs(c.ln[1]) > 0.6;
            const r = Math.hypot(c.lp[0], c.lp[2]) / R;
            let col;
            if (face) {
              const m = smoothstep(-0.3, 0.5, c.fbm(c.p[0] * 4 + i, c.p[2] * 4, i * 3, 4));
              col = mix("#e2ad62", "#a9642a", m * (1 - 0.5 * smoothstep(0.7, 1, r)));
            } else {
              const pore = c.noise(c.p[0] * 60, c.p[1] * 60, c.p[2] * 60) > 0.45;
              col = pore ? "#d6ac66" : "#f2d69c";
              col = mix(col, "#c98a45", smoothstep(0.55, 0.9, Math.abs(c.lp[1]) / (T / 2)));
            }
            return lit(c, col, 0.74, 0.38);
          },
        });
        topY = y + T / 2;
      }
      // A pat of butter.
      k.add(k.roundedBox(0.3, 0.1, 0.26, 5), {
        opacity: 1,
        jitter: 0.015,
        pos: [0.04, topY + 0.045, -0.02],
        rot: [3, 28, -4],
        part: top,
        flat: 0.25,
        weight: 2,
        pattern: false,
        color: (c) => glossy(c, "#fbe28a", 0.7, 30, 0.82, 0.25),
      });
      // A pool of syrup on top that spills into drips down the sides.
      const drips = [];
      for (let i = 0; i < 7; i++) {
        drips.push({ a: (i / 7) * TAU + 0.3 + k.rand() * 0.4, L: 0.18 + k.rand() * 0.55 });
      }
      const poolR = (a) => {
        let r = 0.56 + 0.04 * Math.sin(a * 5 + 1) + 0.03 * Math.sin(a * 9);
        for (const d of drips) {
          let da = Math.abs(a - d.a);
          da = Math.min(da, TAU - da);
          r = Math.max(r, 0.8 - da * 1.8);
        }
        return r;
      };
      const syrup = (c) =>
        mix(
          glossy(c, "#a2541a", 0.9, 30, 0.8, 0.35),
          "#5e2a0a",
          0.3 * smoothstep(0.3, -0.5, c.n[1]),
        );
      k.add(
        k.param(
          (u, v) => {
            const a = u * TAU;
            const r = v * poolR(a);
            return [Math.sin(a) * r, topY + 0.012 + 0.018 * (1 - v * v), Math.cos(a) * r];
          },
          { grid: 64 },
        ),
        {
          even: true,
          jitter: 0.015,
          part: top,
          flat: 0.2,
          opacity: 0.92,
          pattern: false,
          kind: "grow",
          params: [0.02, 0],
          color: syrup,
        },
      );
      const sideR = (y) => {
        const i = clamp(Math.floor((y - 0.02) / (T * 0.93)), 0, n - 1);
        const yl = y - (0.02 + (i + 0.5) * T * 0.93);
        return R * Math.pow(Math.max(0, 1 - (yl / (T * 0.55)) ** 2), 0.18) + 0.022;
      };
      for (const d of drips) {
        const curve = (t) => {
          if (t < 0.15) {
            const f = t / 0.15;
            const r = 0.74 + 0.08 * f;
            const y = topY + 0.01 - 0.04 * f * f;
            return [Math.sin(d.a) * r, y, Math.cos(d.a) * r];
          }
          const f = (t - 0.15) / 0.85;
          const y = topY - 0.03 - d.L * f;
          const r = sideR(y);
          return [Math.sin(d.a) * r, y, Math.cos(d.a) * r];
        };
        k.add(
          k.tube(curve, (t) => 0.03 + 0.022 * smoothstep(0.75, 0.97, t), { caps: true }),
          {
            opacity: 1,
            jitter: 0.015,
            flat: 0.25,
            weight: 2,
            pattern: false,
            kind: "grow",
            params: (c) => [0.05 + 0.9 * (c.t ?? 0) * (d.L / 0.73), 0],
            color: syrup,
          },
        );
      }
      k.reach([0, topY + 0.5, 0]);
    }

drive:
drive(t, c, out) {
      out.grow = c.syrup;
      const s = 1 - c.flip;
      const lift = s < 1 ? hop(s) : 0;
      out.parts.top = {
        offset: [0, 0.6 * lift, 0],
        quat: quatAxisAngle([1, 0, 0.25], TAU * easeInOut(s < 1 ? s : 0)),
      };
    }

build:
build(k, o) {
      const cake = { vanilla: "#e7b466", chocolate: "#6a3b22", velvet: "#9c2530" }[o.cake];
      const LH = 0.62;
      // A pleated paper liner (the pleats catch the light on alternate faces).
      k.add(
        revolve(
          k,
          [
            [0, 0],
            [0.38, 0],
            [0.44, LH * 0.5],
            [0.55, LH],
          ],
          (a) => 1 + 0.035 * Math.abs((((a * 22) / TAU) % 1) - 0.5) * 2,
          { grid: 120, thick: 0.45 },
        ),
        {
          flat: 0.2,
          interior: 0.1,
          core: cake,
          color: (c) =>
            lit(c, mix(o.liner, "#ffffff", 0.12 * c.noise(0, c.p[1] * 30, 0)), 0.7, 0.45),
        },
      );
      // The muffin top peeking over the liner.
      k.add(
        revolve(k, [
          [0.55, LH - 0.03],
          [0.6, LH + 0.05],
          [0.53, LH + 0.13],
          [0.3, LH + 0.19],
          [0, LH + 0.2],
        ]),
        {
          flat: 0.3,
          color: (c) =>
            lit(c, shade(cake, 0.9 + 0.2 * c.noise(c.p[0] * 25, c.p[1] * 25, c.p[2] * 25))),
        },
      );
      // A piped swirl of frosting: a star-tipped rope winding up to a peak.
      const turns = 2.7;
      const curve = (t) => {
        const a = t * turns * TAU;
        const rr = 0.4 * Math.pow(1 - t, 0.85) + 0.015;
        return [Math.sin(a) * rr, LH + 0.2 + t * 0.52, Math.cos(a) * rr];
      };
      const rope = (t) => 0.145 * (1 - 0.72 * Math.pow(t, 1.3)) + 0.012;
      const swirl = k.tube(curve, rope, { caps: true, samples: 420, grid: 96 });
      // The frosting squashes about its base on channel 0: lower and wider.
      const y0 = LH + 0.06;
      const squash = (p) => {
        const h = clamp((p[1] - y0) / 0.8, 0, 1);
        const wide = 1 + CUP_SQUASH * 0.7 * (1 - 0.4 * h);
        return [p[0] * wide, y0 + (p[1] - y0) * (1 - CUP_SQUASH), p[2] * wide];
      };
      k.add(swirl, {
        flat: 0.35,
        interior: 0.06,
        core: o.frosting,
        to: (c) => squash(c.p),
        channel: 0,
        color: (c) => {
          const ridge = Math.cos(c.u * TAU * 8);
          const col = lit(c, shade(o.frosting, 1 + 0.07 * ridge), 0.8, 0.32);
          return mix(col, "#ffffff", 0.35 * spec(c, 20));
        },
      });
      if (o.topping === "both" || o.topping === "sprinkles") {
        // Each sprinkle jumps straight up by its own height (channels 1 to 3,
        // a little apart) and falls back.
        k.cloud({ share: 0.03, size: 0.62, pattern: false }, (rand) => {
          const t = rand() * 0.95;
          const f = swirl.frame(t);
          const a = rand() * TAU;
          const d = add(mul(f.n, Math.cos(a)), mul(f.b, Math.sin(a)));
          if (d[1] < -0.1) return null;
          const p = add(f.p, mul(d, rope(t) + 0.012));
          const h = 0.05 + 0.12 * rand();
          const out = unit([p[0], 0, p[2]]);
          const jumps = rand() < 0.35;
          return {
            p,
            dir: tangentDir(rand, d),
            stretch: 2.7,
            color: SPRINKLES[Math.floor(rand() * SPRINKLES.length)],
            opacity: 1,
            ...(jumps
              ? { to: add(p, [out[0] * h * 0.3, h, out[2] * h * 0.3]), channel: 1 + Math.floor(rand() * 3) } // prettier-ignore
              : {}),
          };
        });
      }
      if (o.topping === "both" || o.topping === "cherry") {
        const cp = add(curve(1), [0, 0.1, 0]);
        const cherry = k.part("cherry", { pivot: cp, axis: [0, 0, 1] });
        k.add(k.sphere(0.12), {
          pos: cp,
          part: cherry,
          flat: 0.25,
          weight: 2.5,
          pattern: false,
          color: (c) =>
            glossy(c, mix("#d0102a", "#7e0616", smoothstep(0.3, -0.8, c.n[1])), 0.9, 36),
        });
        k.add(
          k.tube(
            spline([add(cp, [0, 0.1, 0]), add(cp, [0.04, 0.22, 0]), add(cp, [0.12, 0.3, 0])]),
            0.014,
          ),
          { part: cherry, flat: 0.3, weight: 3, pattern: false, color: (c) => lit(c, "#6b8a2a") },
        );
        k.reach(add(cp, [0, CUP_HIGH + 0.05, 0]));
      }
    }

drive:
drive(t, c, out) {
      const s = since(c.flick, CUP_SECS);
      const on = s >= 0;
      const land = CUP_LAUNCH + CUP_FLIGHT;
      const u = s - land;
      // Channel 0 squashes the frosting (negative stretches it).
      const press = on ? 0.35 * hop(band(s, 0, CUP_LAUNCH + 0.04)) : 0;
      const squash = on && u > 0 ? Math.sin(u * 16) * Math.exp(-u / 0.24) : 0;
      const m0 = press + squash;
      const jump = (at) => (on ? hop(band(s, at, at + 0.55)) : 0);
      out.morph = [m0, jump(land), jump(land + 0.04), jump(land + 0.08)];
      // The cherry rides the frosting's top, and flies in between.
      let y = -CUP_TOP * m0;
      let tilt = 0;
      if (on && s > CUP_LAUNCH && s < land) {
        const f = (s - CUP_LAUNCH) / CUP_FLIGHT;
        y = 4 * CUP_HIGH * f * (1 - f);
        tilt = 0.5 * Math.sin(Math.PI * f);
      } else if (on && u > 0) tilt = 0.25 * wobble(u, 0.8, 13);
      out.parts.cherry = { offset: [0, y, 0], quat: quatAxisAngle([0, 0, 1], tilt) };
      cuesAt(
        c,
        "cupcake",
        s,
        [
          [land, { voice: "thud", f: 150, bright: 0.5, decay: 0.6 }],
          [land + 0.5, { voice: "patter", f: 2900, n: 10, decay: 0.5, vol: 0.6 }],
        ],
        out,
      );
    }

