build:
build(k) {
      const pts = [
        [-0.46, -0.42, 0.08],
        [-0.26, -0.2, 0.08],
        [-0.02, 0.06, 0.1],
        [0.26, 0.32, 0.04],
        [0.5, 0.52, 0],
        [0.78, 0.5, 0],
        [0.93, 0.2, 0],
        [0.86, -0.22, 0],
        [0.55, -0.55, 0],
        [0, -0.68, 0],
        [-0.55, -0.55, 0],
        [-0.86, -0.22, 0],
        [-0.93, 0.2, 0],
        [-0.78, 0.5, 0],
        [-0.5, 0.52, 0],
        [-0.26, 0.32, -0.04],
        [0.02, 0.06, -0.1],
        [0.26, -0.2, 0.08],
        [0.46, -0.42, 0.08],
      ];
      const rad = (t) => 0.085 + 0.06 * Math.exp(-(((t - 0.5) / 0.17) ** 2));
      const P = spline(pts);
      const shape = k.tube(P, rad, { caps: true, samples: 480, grid: 110 });
      const q = quatEuler(-16, 0, 0);
      const qi = [-q[0], -q[1], -q[2], q[3]];
      // The pretzel twisted like a knot: its two sides wring opposite ways
      // about its width, the top turns against the bottom, and the loops fold
      // a little towards you. It is one smooth twist of the whole shape, so
      // wherever the rope crosses or rests on itself it stays joined. A
      // negative channel twists it the other way.
      const y0 = -0.08;
      const twisted = (p) => {
        let [x, y, z] = quatRotate(qi, p);
        const w = 0.42 * Math.tanh(x / 0.45);
        [y, z] = [y0 + (y - y0) * Math.cos(w) - z * Math.sin(w), (y - y0) * Math.sin(w) + z * Math.cos(w)]; // prettier-ignore
        const g = 0.3 * (y - y0);
        [x, y] = [x * Math.cos(g) - (y - y0) * Math.sin(g), y0 + x * Math.sin(g) + (y - y0) * Math.cos(g)]; // prettier-ignore
        const a = x / 1.7;
        [x, z] = [(1.7 - z) * Math.sin(a), 1.7 - (1.7 - z) * Math.cos(a)];
        return quatRotate(q, [x, y, z]);
      };
      k.add(shape, {
        quat: q,
        flat: 0.4,
        interior: 0.1,
        core: "#f0d4a0",
        to: (c) => twisted(c.p),
        channel: 0,
        color: (c) => {
          // The scored belly splits open along its top, showing pale dough.
          const belly = Math.exp(-(((c.t - 0.5) / 0.1) ** 2));
          const up = dot(c.n, unit([0, 0.8, 0.6]));
          const jag = 0.08 * c.noise(c.t * 80, 0, 0);
          if (belly > 0.35 && up > 0.72 + jag)
            return lit(c, mix("#f3d59a", "#e2b36a", c.rand() * 0.6), 0.85, 0.25);
          const col = mix(
            "#96501c",
            "#5e2b0c",
            0.45 + 0.4 * c.fbm(c.p[0] * 6, c.p[1] * 6, c.p[2] * 6, 3),
          );
          return glossy(c, col, 0.55, 22, 0.72, 0.42);
        },
      });
      // Coarse salt on the top side, carried along with the dough.
      k.cloud({ share: 0.012, size: 0.9, flat: 0.7, pattern: false }, (rand) => {
        const t = rand();
        const f = shape.frame(t);
        const a = rand() * TAU;
        const d = add(mul(f.n, Math.cos(a)), mul(f.b, Math.sin(a)));
        const dw = quatRotate(q, d);
        if (dw[2] < 0.25 || rand() < 0.4) return null;
        const p = quatRotate(q, add(f.p, mul(d, rad(t) * 1.02)));
        return {
          p,
          n: dw,
          color: mix("#ffffff", "#e8e4dc", rand()),
          opacity: 1,
          to: twisted(p),
          channel: 0,
        };
      });
    }

