build:
build(k) {
      // A crescent of rolled dough: plump rolls in the middle, thin tips
      // curling in, each roll wrapping slightly on the slant.
      const curve = (t) => {
        const a = (t - 0.5) * 4.0;
        const dip = 0.12 * Math.pow(1 - Math.sin(Math.PI * t), 1.5);
        return [Math.sin(a) * 0.9, -dip, Math.cos(a) * 0.62 - 0.3];
      };
      const bulge = (t, u) =>
        Math.pow(0.5 + 0.5 * Math.cos(TAU * 5 * (t - 0.5 + 0.035 * Math.cos(u * TAU))), 0.6);
      const env = (t) => 0.3 * Math.pow(Math.sin(Math.PI * t), 1.1) + 0.02;
      const frame = levelFrames(curve);
      const shape = k.param(
        (u, v) => {
          const f = frame(v);
          const a = u * TAU;
          const r = env(v) * (0.62 + 0.38 * bulge(v, u));
          const off = add(mul(f.n, Math.cos(a) * r), mul(f.b, Math.sin(a) * r * 0.8));
          return add(f.p, off);
        },
        { grid: 100, thick: 0.25 },
      );
      // It is sliced level at CRO_CUT: everything above is the top (a lid
      // that lifts and tips back about the back of the middle roll).
      const yc = CRO_CUT;
      const lid = k.part("lid", { pivot: [0, yc, -0.12], axis: [1, 0, 0] });
      k.add(shape, {
        opacity: 1,
        jitter: 0.015,
        part: (c) => (c.p[1] > yc ? lid : 0),
        flat: 0.25,
        interior: 0.1,
        core: (c) => {
          // Keep the crumb inside the thin tips.
          if (len(sub(c.p, c.lp)) > env(c.v) * 0.9) return null;
          return c.noise(c.p[0] * 30, c.p[1] * 30, c.p[2] * 30) > 0.1 ? "#f6e2b0" : "#e2bd7c";
        },
        color: (c) => crust(c, c.v, c.u),
      });
      // The crust's colour at (v along, u around).
      function crust(c, cv, cu) {
        const b = bulge(cv, cu);
        const under = smoothstep(-0.2, -0.7, c.n[1]);
        const tip = smoothstep(0.3, 0.05, Math.min(cv, 1 - cv));
        let col = mix("#f4d08e", "#c26a1f", smoothstep(0.2, 0.85, b));
        col = mix(col, "#9a5418", 0.5 * tip);
        col = mix(col, "#e9bb72", under * 0.7);
        col = shade(col, 0.93 + 0.12 * c.noise(c.p[0] * 40, c.p[1] * 40, c.p[2] * 40));
        return glossy(c, col, 0.55 * (1 - under), 20, 0.72, 0.42);
      }
      // The cut faces (the bottom's facing up, the top's facing down): the
      // soft crumb with the laminated layers curving round each roll, inside
      // a thin line of crust. w runs across the roll (-1 .. 1).
      const chord = (v) => {
        const f = frame(v);
        const r = env(v) * (0.62 + 0.38 * 0.5 * (bulge(v, 0) + bulge(v, 0.5)));
        const h = (yc - f.p[1]) / Math.max(0.2, f.b[1]);
        const q = h / (0.8 * r);
        if (Math.abs(q) > 0.97) return null;
        return { f, h, hw: r * Math.sqrt(1 - q * q) * 0.985 };
      };
      const crumb = (c, w, v) => {
        const aw = Math.abs(w);
        if (aw > 0.93) return keep(lit(c, mix("#c98333", "#a8621e", c.rand()), 0.85, 0.2));
        const holes = c.noise(c.p[0] * 34, c.p[2] * 34, 3.1);
        const layer = Math.sin(aw * 17 + 2.2 * c.noise(v * 20, aw * 3, 0.4));
        let col = mix("#f8e7bf", "#f1d49a", 0.5 + 0.5 * c.noise(c.p[0] * 9, c.p[2] * 9, 1.7));
        if (layer > 0.8) col = mix(col, "#d9a860", 0.7);
        if (holes > 0.45) col = shade(mix(col, "#e5c07e", 0.6), 0.86);
        return keep(lit(c, col, 0.86, 0.2));
      };
      for (const [part, up] of [
        [0, 1],
        [lid, -1],
      ]) {
        k.add(
          k.param(
            (u, v) => {
              const ch = chord(v);
              if (!ch) return frame(v).p;
              return add(add(ch.f.p, mul(ch.f.n, (u * 2 - 1) * ch.hw)), mul(ch.f.b, ch.h - 0.003 * up)); // prettier-ignore
            },
            { grid: 64, normal: () => [0, up, 0] },
          ),
          {
            even: true,
            opacity: 1,
            jitter: 0.015,
            part,
            flat: 0.2,
            weight: up > 0 ? 1.3 : 0.5,
            pattern: false,
            color: (c) => (chord(c.v) ? crumb(c, c.u * 2 - 1, c.v) : null),
          },
        );
      }
      // A pat of butter inside, on the bottom half; it melts and spreads
      // (channel 0) while the top is up.
      const pat = [0.02, yc + 0.03, 0.36];
      k.add(k.roundedBox(0.28, 0.055, 0.19, 3), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: pat,
        rot: [0, 12, 0],
        flat: 0.3,
        weight: 2.5,
        pattern: false,
        to: (c) => {
          const d = sub(c.p, pat);
          return add(pat, [d[0] * 1.9, -0.024 + (d[1] + 0.028) * 0.25, d[2] * 1.7]);
        },
        channel: 0,
        color: (c) =>
          keep(glossy(c, mix("#fbe38a", "#f6d466", 0.3 + 0.3 * c.rand()), 0.8, 30, 0.84, 0.3)),
      });
      // A baking tray lined with paper.
      const trayY = -0.33;
      k.add(evenBox(2.3, 0.05, 1.5), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [0, trayY - 0.03, -0.1],
        flat: 0.2,
        weight: 0.6,
        color: (c) => (c.n[1] > 0.5 ? lit(c, "#5a5f66", 0.8, 0.3) : lit(c, "#3c4046", 0.8, 0.3)),
      });
      k.add(
        k.param((u, v) => [(u - 0.5) * 1.9, trayY + 0.004, (v - 0.5) * 1.2 - 0.1], {
          grid: 48,
          normal: () => [0, 1, 0],
        }),
        {
          even: true,
          opacity: 1,
          jitter: 0.015,
          flat: 0.15,
          weight: 0.7,
          color: (c) => {
            const crinkle = c.noise(c.p[0] * 9, c.p[2] * 9, 1.3);
            return lit(c, shade("#efe6d2", 0.94 + 0.1 * crinkle), 0.84, 0.2);
          },
        },
      );
      k.reach([0, 0.55, 0]);
    }

