            const s = Math.abs(c.v * 2 - 1);
            const col = mix("#2f6b3a", "#86bf5c", smoothstep(0.1, 1, c.u));
            return lit(c, s < 0.1 ? shade(col, 0.8) : col, 0.74, 0.38);
