drive(t, c, out) {
      const p = 1 - c.pop;
      const on = c.pop > 0;
      out.grow = on ? clamp((p - 0.22) / 0.72, 0, 1) : 1;
      BURST.forEach((d, i) => {
        const f = clamp(p / 0.28, 0, 1);
        const dist = 0.9 * easeOut(f);
        out.parts["bit" + i] = {
          offset: [d[0] * dist, d[1] * dist - 0.5 * f * f, d[2] * dist],
          visible: on && p < 0.3 ? 1 - smoothstep(0.2, 0.3, p) : 0,
        };
      });
    }

