build(k, o) {
      const { label, fields, prog } = programFor(o);
      NOW.label = `${label}: ${programText(fields)}`;
      NOW.fields = fields;
      const copies = prog.usesT ? KNOTS : 1;
      k.data = { equation: { copies } };
      const budget = Math.floor((k.count * 0.98) / copies);
      const n0 = Math.max(1, Math.min(prog.count, budget));
      // Fine (Lab r2): the same shape from up to four times the splats (as
      // many as the device's budget allows), each smaller in step, so the
      // surface is finer grained. The program's own count stays in its text.
      const n = o.splats === "fine" ? Math.max(n0, Math.min(prog.count * 4, budget)) : n0;
      const fine = Math.sqrt(n0 / n);
      const uv = params(prog, n, () => k.rand());
      const times = Array.from({ length: copies + 1 }, (_, j) => (TAU * j) / copies);
      // Where each splat is at each time (NaN where the equations have no
      // value), and how big the shape gets.
      const vals = { θ: 0, y: 0, t: 0 };
      const place = (u, v, t) => {
        vals.θ = u;
        vals.y = v;
        vals.t = t;
        return [prog.x.f(vals), prog.y.f(vals), prog.z.f(vals)];
      };
      const P = times.map((t) => uv.map(([u, v]) => place(u, v, t)));
      const reach = [];
      for (const row of P) for (const p of row) if (Number.isFinite(p[0] + p[1] + p[2])) reach.push(Math.hypot(...p)); // prettier-ignore
      reach.sort((a, b) => a - b);
      // Points far beyond the rest (an equation that shoots off to
      // infinity) are left out, so the shape still fills the view.
      const far = reach.length ? Math.max(1e-6, reach[Math.floor(reach.length * 0.98)] * 3) : 1;
      const ok = (p) => Number.isFinite(p[0] + p[1] + p[2]) && Math.hypot(...p) <= far;
      const surface = prog.usesU && prog.usesV && prog.spread === "grid";
      // A curve: only one of u and v moves the splats (Lab r2's Solid look).
      const curve = prog.spread === "grid" && prog.usesU !== prog.usesV ? (prog.usesU ? "u" : "v") : null; // prettier-ignore
      const [du, dv] = [(prog.u[1] - prog.u[0]) * 1e-3, (prog.v[1] - prog.v[0]) * 1e-3];
      for (let j = 0; j < copies; j++) {
        const t = times[j];
        const part = copies > 1 ? k.part(`t${j}`) : 0;
        k.cloud({ share: n / k.count, size: 1 }, (rand, i) => {
          const p = P[j][i];
          if (!p || !ok(p)) return null;
          const [u, v] = uv[i];
          vals.θ = u;
          vals.y = v;
          vals.t = t;
          let rgb;
          if (prog.hue) {
            const h = prog.hue.f(vals);
            rgb = Number.isFinite(h) ? hsl(((h % 1) + 1) % 1, 0.72, 0.56) : [0.5, 0.5, 0.5];
          } else rgb = ["r", "g", "b"].map((ch) => clamp01(prog[ch].f(vals) || 0));
          const s = prog.size.f(vals);
          const size = Number.isFinite(s) && s > 0 ? Math.min(s, far) : 0.05 * far;
          // The surface's normal, from its slopes along u and v.
          let nrm = null;
          if (surface) {
            const a = place(u + du, v, t);
            const b = place(u, v + dv, t);
            const pu = [a[0] - p[0], a[1] - p[1], a[2] - p[2]];
            const pv = [b[0] - p[0], b[1] - p[1], b[2] - p[2]];
            const cr = [pu[1] * pv[2] - pu[2] * pv[1], pu[2] * pv[0] - pu[0] * pv[2], pu[0] * pv[1] - pu[1] * pv[0]]; // prettier-ignore
            const l = Math.hypot(...cr);
            if (l > 0 && Number.isFinite(l)) nrm = [cr[0] / l, cr[1] / l, cr[2] / l];
          }
          if (o.shade !== false && nrm) {
            const d = Math.abs(nrm[0] * LIGHT[0] + nrm[1] * LIGHT[1] + nrm[2] * LIGHT[2]);
            const f = 0.62 + 0.48 * d;
            const sp = 0.18 * Math.pow(d, 24);
            rgb = rgb.map((x) => clamp01(x * f + sp));
          }
          // Every splat at full opacity and its exact size (Lab r2). Solid:
          // a surface's splats lie flat along it, and a curve's are drawn out
          // along it, so they close into one clean shape. Dots: each splat
          // you program shows as its own round dot.
          const splat = { p, color: rgb, size: size / 0.01, opacity: 1, jitter: 0, part };
          // Fine: smaller splats, except a curve's, whose size is its thickness.
          if (!curve) splat.size *= fine;
          if (o.splats === "dots") {
            if (prog.spread === "grid") splat.size *= 0.45;
          } else if (nrm) {
            splat.n = nrm;
            splat.flat = 0.12;
          } else if (curve) {
            const a = curve === "u" ? place(u + du, v, t) : place(u, v + dv, t);
            const d = [a[0] - p[0], a[1] - p[1], a[2] - p[2]];
            if (Number.isFinite(d[0] + d[1] + d[2]) && Math.hypot(...d) > 0) {
              // Stretched along the curve; 0.7 across (the kit's), so the
              // tube keeps the program's size as its thickness.
              splat.dir = d;
              splat.stretch = 1.6;
              splat.size /= 0.7;
            }
          }
          if (copies > 1) {
            const q = P[j + 1][i];
            splat.to = ok(q) ? q : p;
            splat.channel = 1;
          } else {
            splat.kind = "fade";
            splat.params = [1.002 - i / n, 0.02];
            splat.channel = 0;
          }
          return splat;
        });
      }
    }

drive:
drive(t, c, out, info) {
      const g = info?.data?.equation;
      if (!g) return;
      const e = since(c, "play", PLAY_SECS);
      const on = e >= 0;
      if (g.copies === 1) {
        out.morph = [on ? 1 - band(e, 0.25, 3.6) : 0, 0, 0, 0];
        return;
      }
      let u = clamp01(c.t ?? 0);
      if (on) u = (u + glide(clamp01(e / PLAY_SECS))) % 1;
      const pos = u * g.copies;
      let j = Math.min(g.copies - 1, Math.floor(pos));
      let frac = pos - j;
      // The last hundredth of a step shows the next copy instead (the same
      // shape), so a cycle ends on copy 0, the rest pose.
      if (frac > 0.99) {
        j = (j + 1) % g.copies;
        frac = 0;
      }
      for (let i = 0; i < g.copies; i++) out.parts[`t${i}`] = { visible: i === j ? 1 : 0 };
      out.morph = [0, frac, 0, 0];
    }

build:
build(k) {
    const scan = SCANS.get("fountain-pen");
    const pen = k.part("pen", { pivot: FP.nib });
    const cap = k.part("cap", { pivot: FP.capC });
    addScan(k, scan, { share: 0.75, parts: [pen, cap] });
    // The notepad: a cream sheet with faint blue rules and a red margin, on a thin block.
    const W = 2.3;
    const D = 1.45;
    const pz = 0.28;
    const nPaper = Math.round(k.count * 0.1);
    addCloud(k, nPaper, (i, n) => {
      const x = -W / 2 + W * ((i * 0.7548776662466927) % 1);
      const z = pz - D / 2 + D * ((i * 0.5698402909980532) % 1);
      const size = Math.sqrt((W * D) / (n * Math.PI)) * 1.3;
      return { p: [x, FP.paper, z], n: [0, 1, 0], size, color: lit([0.96, 0.94, 0.88], [0, 1, 0]), flat: 0.15 }; // prettier-ignore
    });
    // The rules and the margin: fine unbroken lines of small splats just above the sheet.
    const rules = [];
    for (let z = pz - D / 2 + 0.2 + 0.065; z < pz + D / 2 - 0.01; z += 0.13) rules.push(z);
    const step = 0.0028 * Math.max(1, Math.sqrt(300000 / k.count)); // about 2.6% of the splats
    const perRule = Math.floor(W / step);
    const perMargin = Math.floor(D / step);
    const nLines = rules.length * perRule + perMargin;
    addCloud(k, nLines, (i) => {
      const r = Math.floor(i / perRule);
      if (r < rules.length) {
        const x = -W / 2 + ((i % perRule) + 0.5) * step;
        return { p: [x, FP.paper + 0.0015, rules[r]], n: [0, 1, 0], size: 1.5 * step, color: lit([0.72, 0.8, 0.92], [0, 1, 0]), flat: 0.15 }; // prettier-ignore
      }
      const z = pz - D / 2 + (i - rules.length * perRule + 0.5) * step;
      return { p: [-W / 2 + 0.3, FP.paper + 0.0015, z], n: [0, 1, 0], size: 1.6 * step, color: lit([0.9, 0.62, 0.62], [0, 1, 0]), flat: 0.15 }; // prettier-ignore
    });
    // The sheets' edges below it.
    addCloud(k, Math.round(k.count * 0.03), (i, n) => {
      const per = 2 * (W + D);
      const f = ((i * 0.7548776662466927) % 1) * per;
      const y = FP.paper - 0.05 * ((i * 0.5698402909980532) % 1);
      let x;
      let z;
      let nn;
      if (f < W) [x, z, nn] = [-W / 2 + f, pz + D / 2, [0, 0, 1]];
      else if (f < W + D) [x, z, nn] = [W / 2, pz + D / 2 - (f - W), [1, 0, 0]];
      else if (f < 2 * W + D) [x, z, nn] = [W / 2 - (f - W - D), pz - D / 2, [0, 0, -1]];
      else [x, z, nn] = [-W / 2, pz - D / 2 + (f - 2 * W - D), [-1, 0, 0]];
      const line = ((y - FP.paper) * 200) % 1 < 0.3 ? 0.86 : 0.93;
      const size = Math.sqrt((per * 0.05) / (n * Math.PI)) * 1.3;
      return {
        p: [x, y, z],
        n: nn,
        size,
        color: lit([line, line * 0.98, line * 0.93], nn),
        flat: 0.2,
      };
    });
    // The ink: a ribbon along the swirl, a wet layer and a dry one just above it.
    const N = 700;
    const pts = [];
    for (let j = 0; j <= N; j++) pts.push(fpSwirl(j / N));
    const width = 0.016;
    const nInk = Math.round(k.count * 0.035);
    for (const layer of [0, 1]) {
      addCloud(k, nInk, (i, n) => {
        const u = (i + 0.5) / n;
        const j = Math.min(N - 1, Math.floor(u * N));
        const a = pts[j];
        const b = pts[j + 1];
        const f = u * N - j;
        const tx = b[0] - a[0];
        const tz = b[2] - a[2];
        const tl = Math.hypot(tx, tz) || 1;
        const side = (((i * 0.618034) % 1) - 0.5) * width * (0.8 + 0.4 * Math.sin(u * 40));
        const p = [a[0] + tx * f - (tz / tl) * side, FP.paper + 0.003 + layer * 0.0025, a[2] + tz * f + (tx / tl) * side]; // prettier-ignore
        const size = 0.009;
        if (layer === 0) {
          const glint = (i * 0.381966) % 1 < 0.08;
          return { p, n: [0, 1, 0], size, color: glint ? [0.62, 0.72, 1] : [0.14, 0.3, 0.86], opacity: 0.95, kind: "fade", params: [u * 0.99, -0.012], channel: 0 }; // prettier-ignore
        }
        return { p, n: [0, 1, 0], size, color: [0.06, 0.1, 0.34], opacity: 0.97, kind: "fade", params: [u * 0.99, -0.012], channel: 1 }; // prettier-ignore
      });
    }
    // The writing pose: the posted pen's end, up and away.
    k.reach([0.9, 1.3, -1.25]);
  }

