build:
build(k, o) {
      const R = (y) => 0.6 + 0.07 * (y + 0.3);
      const top = (u) => {
        const x = fract(u * 8 + 0.5) - 0.5;
        const d = Math.abs(x) * 2;
        const big = d < 0.5 ? 0.52 * Math.pow(1 - d / 0.5, 1.25) : 0;
        const small = d > 0.78 ? 0.2 * (1 - (1 - d) / 0.22) : 0;
        return 0.06 + Math.max(big, small);
      };
      const bandShape = (inset) =>
        k.param(
          (u, v) => {
            const a = u * TAU;
            const y = -0.3 + v * (top(u) + 0.3);
            const r = R(y) - inset;
            return [Math.sin(a) * r, y, Math.cos(a) * r];
          },
          { grid: 96, flip: inset > 0 },
        );
      k.add(bandShape(0), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        flat: 0.15,
        kind: "glint",
        params: [0.1, 0],
        interior: 0,
        color: (c) => {
          const y = c.lp[1];
          let col = gold(c, undefined, 0.4);
          if (Math.abs(y - 0.04) < 0.012 || Math.abs(y + 0.26) < 0.012)
            col = keep(shade(col, 0.75));
          return col;
        },
      });
      k.add(bandShape(0.03), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        flat: 0.15,
        color: (c) => shade(gold(c), 0.7),
      });
      // Pearls on every point, and a string of small ones round the band.
      for (let i = 0; i < 16; i++) {
        const u = i / 16;
        const a = u * TAU;
        const y = top(u) + (i % 2 ? 0.02 : 0.035);
        const r = R(y);
        k.add(k.sphere(i % 2 ? 0.032 : 0.048), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [Math.sin(a) * r, y, Math.cos(a) * r],
          weight: 3,
          pattern: false,
          kind: "glint",
          params: [0.6, 0],
          color: (c) => lit(c, "#f6efe2", 0.35, 0.6),
        });
      }
      // Gems set round the band.
      const gemCols = [GEMS.ruby, GEMS.sapphire, GEMS.emerald, GEMS.sapphire];
      for (let i = 0; i < 8; i++) {
        const a = (i / 8) * TAU;
        const r = R(-0.13) + 0.012;
        k.add(evenEllipsoid(k, 0.066, 0.08, 0.035), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [Math.sin(a) * r, -0.13, Math.cos(a) * r],
          rot: [0, (a * 180) / Math.PI, 0],
          weight: 4,
          pattern: false,
          // Each jewel flashes white as channel 0 reaches it.
          kind: "band",
          channel: 0,
          params: [0.03 + (i / 8) * 0.85 + 0.04, 0.06],
          color: (c) => gem(c, gemCols[i % 4]),
        });
        k.add(evenTorus(k, 0.075, 0.012), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [Math.sin(a) * r, -0.13, Math.cos(a) * r],
          rot: [90, (a * 180) / Math.PI, 0],
          scale: [1, 1, 1.15],
          weight: 2,
          pattern: false,
          color: (c) => gold(c),
        });
        const a2 = a + TAU / 16;
        const r2 = R(-0.12) + 0.01;
        k.add(k.sphere(0.03), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [Math.sin(a2) * r2, -0.12, Math.cos(a2) * r2],
          weight: 3,
          pattern: false,
          color: (c) => lit(c, "#f6efe2", 0.35, 0.6),
        });
      }
      // Each jewel's light: a glow of its own colour over it that appears
      // as channel 0 passes its turn (hidden at rest).
      k.cloud({ share: 0.012, size: 2, pattern: false }, (rand, j) => {
        const i = j % 8;
        const a = (i / 8) * TAU;
        const r = R(-0.13) + 0.02;
        const d = vec.unit([rand() - 0.5, rand() - 0.5, rand() - 0.5]);
        const q = 0.075 * Math.sqrt(rand());
        return {
          p: vec.add([Math.sin(a) * r, -0.13, Math.cos(a) * r], vec.mul(d, q)),
          color: mix(gemCols[i % 4], "#ffffff", 0.25 + 0.6 * (1 - q / 0.075)),
          opacity: 0.75 * (1 - q / 0.085),
          kind: "fade",
          channel: 0,
          params: [0.03 + (i / 8) * 0.85, -0.08],
        };
      });
      // Golden motes drift up round the crown while it hovers (hidden at
      // rest).
      k.cloud({ share: 0.004, size: 1.1, pattern: false, part: k.part("motes") }, (rand) => {
        const a = rand() * TAU;
        const r = 0.5 + 0.18 * rand();
        return {
          p: [Math.sin(a) * r, -0.3 + rand() * 0.4, Math.cos(a) * r],
          color: mix("#ffd35a", "#fffbe8", rand()),
          opacity: 0.95,
          kind: "rise",
          params: [0.5 + 0.3 * rand(), rand()],
        };
      });
      // The velvet cap and a golden orb on top.
      k.add(evenEllipsoid(k, 0.56, 0.5, 0.56), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [0, -0.08, 0],
        flat: 0.3,
        color: (c) => {
          if (c.lp[1] < 0.1) return null;
          const a = Math.atan2(c.lp[0], c.lp[2]);
          const fold = 0.78 + 0.3 * Math.abs(Math.sin(a * 4));
          return lit(c, shade(o.velvet, fold), 0.4, 0.15);
        },
      });
      k.add(k.sphere(0.09), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [0, 0.46, 0],
        weight: 2,
        kind: "glint",
        params: [0.5, 0],
        color: (c) => gold(c),
      });
      k.add(k.sphere(0.035), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [0, 0.575, 0],
        weight: 3,
        pattern: false,
        color: (c) => lit(c, "#f6efe2", 0.35, 0.6),
      });
      // Ermine trim.
      k.add(evenTorus(k, 0.62, 0.075), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [0, -0.33, 0],
        flat: 0.35,
        pattern: false,
        color: (c) => {
          const a = (Math.atan2(c.lp[0], c.lp[2]) / TAU + 0.5) * 18;
          const odd = Math.floor(a) % 2 === 1;
          const row = odd ? Math.sin(c.v * TAU) : Math.cos(c.v * TAU);
          if (Math.abs(fract(a) - 0.5) < 0.07 && Math.abs(row - 0.75) < 0.2) return "#16161a";
          const fur = c.noise(c.p[0] * 60, c.p[1] * 60, c.p[2] * 60);
          return lit(c, shade("#f7f5ef", 0.92 + 0.08 * fur), 0.3);
        },
      });
    }

drive:
drive(t, c, out, info) {
      // The crown lifts and hovers; its eight jewels light up one after
      // another round the band (channel 0 passing each one, each flashing
      // white as it lights), golden motes drift up round it, then the
      // jewels go out in turn and it settles back down.
      const on = c.rise > 0;
      const s = progress(c.rise) * 4.2;
      const lift = on ? easeInOut(band(s, 0, 0.9)) * (1 - easeInOut(band(s, 3.2, 4.1))) : 0;
      out.body = {
        offset: [0, 0.3 * lift + 0.02 * Math.sin(s * 4) * lift, 0],
        quat: quatAxisAngle([0, 0, 1], 0.03 * Math.sin(s * 3.1) * lift),
      };
      const jewels = on ? (s < 2.6 ? band(s, 0.3, 1.7) : 1 - band(s, 2.6, 3.6)) : 0;
      out.morph = [jewels];
      out.glow = [1, 1, 1, on && s < 2.0 ? 1 : 0];
      out.parts.motes = { visible: lift > 0.02 ? lift : 0 };
    }

build:
build(k, o) {
      const pal = {
        emerald: ["#1c8a5a", "#5fd39a", "#0e4f3a"],
        ruby: ["#b2203a", "#ff7a7a", "#5e0f22"],
        sapphire: ["#2350b8", "#7fb0ff", "#15245e"],
        gold: ["#c99522", "#ffe08a", "#6e4a10"],
      }[o.egg];
      const yc = 0.05;
      const H = 0.68;
      const r = (y) => {
        const t = clamp((y - yc) / H, -1, 1);
        return 0.5 * Math.sqrt(Math.max(0, 1 - t * t)) * (1 - 0.14 * t);
      };
      const ybot = yc - H;
      const ytop = yc + H;
      const zig = (x) => Math.abs(fract(x) - 0.5) * 4 - 1;
      const crack = (u) => 0.18 + 0.045 * zig(u * 15);
      const at = (u, y, s = 1) => {
        const a = u * TAU;
        const rr = r(y) * s;
        return [Math.sin(a) * rr, y, Math.cos(a) * rr];
      };
      const scales = (c, u, y) => {
        const j = Math.floor(y * 16);
        const cu = fract(u * 22 + (j % 2 ? 0.5 : 0));
        const cy = fract(y * 16);
        const e = Math.hypot((cu - 0.5) * 2, cy);
        const shine = 0.5 + 0.5 * Math.sin(u * TAU * 2 + y * 4);
        let col = mix(pal[0], pal[1], 0.25 + 0.45 * shine * (1 - e));
        if (e > 0.88) col = mix(col, pal[2], 0.7);
        return lit(c, col, 0.35, 0.35);
      };
      const cream = (c) =>
        lit(c, mix("#fbf1d6", "#e8d2a0", 0.5 + 0.5 * c.noise(c.p[0] * 20, c.p[1] * 20, 0)), 0.2);
      // The bottom of the shell stays in the nest.
      const cup = (s) =>
        k.param(
          (u, v) => {
            const y = ybot + v * (crack(u) - ybot);
            return at(u, y, s);
          },
          { grid: 64, flip: s < 1 },
        );
      k.add(cup(1), {
        flat: 0.18,
        kind: "glint",
        params: [0.1, 0],
        color: (c) => scales(c, c.u, c.p[1]),
      });
      k.add(cup(0.95), { flat: 0.2, color: cream });
      // Three pieces of the top open like petals.
      for (let i = 0; i < 3; i++) {
        const am = ((i + 0.5) / 3) * TAU;
        const pivot = at((i + 0.5) / 3, 0.18);
        const part = k.part(`shell${i}`, { pivot, axis: [Math.cos(am), 0, -Math.sin(am)] });
        const petal = (s) =>
          k.param(
            (su, w) => {
              const u0 = (i + su) / 3;
              const y0 = crack(u0) + w * (ytop - crack(u0));
              const u = u0 + 0.012 * zig(y0 * 9) * Math.min(1, w * 6);
              const y = crack(u) + w * (ytop - crack(u));
              return at(u, y, s);
            },
            { grid: 48, flip: s < 1 },
          );
        k.add(petal(1), {
          part,
          flat: 0.18,
          kind: "glint",
          params: [0.1, 0],
          color: (c) => scales(c, Math.atan2(c.p[0], c.p[2]) / TAU + 0.5, c.p[1]),
        });
        k.add(petal(0.95), { part, flat: 0.2, color: cream });
      }
      // The nest: a ring of twigs on a bed of straw.
      k.add(k.disc(0.62), {
        pos: [0, ybot + 0.04, 0],
        flat: 0.3,
        color: (c) => mix("#c9a55a", "#8a6a30", 0.5 + 0.5 * c.fbm(c.p[0] * 12, 0, c.p[2] * 12, 2)),
      });
      for (let i = 0; i < 38; i++) {
        const phi = (i / 38) * TAU + k.rand() * 0.3;
        const R0 = 0.52 + k.rand() * 0.18;
        const y0 = ybot + 0.02 + k.rand() * 0.2;
        const dy = (k.rand() - 0.5) * 0.14;
        const len = 0.45 + k.rand() * 0.3;
        const bend = (k.rand() - 0.5) * 0.12;
        const col = mix("#6d4a28", "#a8804f", k.rand());
        k.add(
          k.tube(
            (t) => {
              const a = phi + (t - 0.5) * len;
              const rr = R0 + bend * Math.sin(t * Math.PI) + 0.04 * (t - 0.5);
              return [Math.sin(a) * rr, y0 + dy * (t - 0.5) * 2, Math.cos(a) * rr];
            },
            0.022 + k.rand() * 0.01,
            { grid: 20, samples: 24, caps: true },
          ),
          {
            flat: 0.25,
            color: (c) => lit(c, shade(col, 0.85 + 0.3 * c.noise(c.t * 20, i, 0)), 0.35),
          },
        );
      }
      // The baby dragon, curled up inside until it hatches.
      const dragon = k.part("dragon", { pivot: [0, -0.1, 0], axis: [1, 0, 0] });
      const skin = { emerald: "#46c08c", ruby: "#e0605a", sapphire: "#5b8ee8", gold: "#e8b33a" }[
        o.egg
      ];
      const belly = "#f6dc8c";
      const wing = { emerald: "#8a5cc4", ruby: "#f2a03a", sapphire: "#43c2c9", gold: "#d2553a" }[
        o.egg
      ];
      const D = (shape, opts) =>
        k.add(shape, { part: dragon, pattern: false, flat: 0.25, ...opts });
      D(k.ellipsoid(0.22, 0.24, 0.2), {
        pos: [0, -0.2, 0],
        color: (c) => lit(c, c.lp[2] > 0.08 ? belly : skin, 0.35),
      });
      D(k.sphere(0.2), {
        pos: [0, 0.2, 0.02],
        color: (c) => lit(c, mix(skin, "#ffffff", 0.12 * Math.max(0, c.n[1])), 0.35, 0.2),
      });
      D(k.ellipsoid(0.13, 0.1, 0.12), {
        pos: [0, 0.14, 0.18],
        color: (c) => {
          const nos =
            Math.hypot(Math.abs(c.lp[0]) - 0.045, c.lp[1] - 0.03) < 0.018 && c.lp[2] > 0.09;
          return nos ? "#1e2a22" : lit(c, mix(skin, belly, 0.35), 0.35);
        },
      });
      for (const s of [-1, 1]) {
        D(k.sphere(0.062), {
          pos: [s * 0.095, 0.25, 0.15],
          weight: 3,
          color: (c) => {
            const hl = Math.hypot(c.lp[0] + 0.02, c.lp[1] - 0.025) < 0.018 && c.lp[2] > 0;
            return hl ? "#ffffff" : c.lp[2] > 0.035 ? "#141414" : lit(c, "#ffffff", 0.2);
          },
        });
        D(k.cone(0.04, 0.005, 0.14), {
          pos: [s * 0.1, 0.38, -0.04],
          rot: [-30, 0, s * -25],
          weight: 2,
          color: (c) => lit(c, "#f4e7c6", 0.3),
        });
        D(k.ellipsoid(0.045, 0.035, 0.07), {
          pos: [s * 0.2, 0.0, 0.16],
          weight: 2,
          color: (c) => lit(c, skin, 0.35),
        });
        const wingShape = k.param(
          (u, v) => {
            const a = u * 1.3 + 0.2;
            const scal = 1 - 0.18 * Math.abs(Math.sin(u * Math.PI * 3));
            const rr = v * 0.3 * scal;
            return [s * Math.cos(a) * rr, Math.sin(a) * rr, -0.08 * v];
          },
          { grid: 24 },
        );
        D(wingShape, {
          pos: [s * 0.12, 0.02, -0.14],
          weight: 1.5,
          color: (c) => lit(c, fract(c.u * 3) < 0.08 ? skin : wing, 0.25),
        });
      }
      // Magic sparkles once the egg is open.
      k.cloud({ share: 0.004, size: 0.9, pattern: false }, (rand) => {
        const a = rand() * TAU;
        const rr = 0.2 + rand() * 0.35;
        return {
          p: [Math.sin(a) * rr, 0.25 + rand() * 0.2, Math.cos(a) * rr],
          color: "#ffd23a",
          opacity: 1,
          part: dragon,
          kind: "rise",
          params: [0.6, rand()],
        };
      });
      k.reach([0, ytop + 0.1, 0.9]);
      k.reach([0, ytop + 0.1, -0.9]);
    }

drive:
drive(t, c, out) {
      const o = easeInOut(c.hatch);
      for (let i = 0; i < 3; i++) out.parts[`shell${i}`] = { angle: 1.75 * o };
      const up = easeInOut(band(c.hatch, 0.25, 1));
      out.parts.dragon = {
        offset: [0, 0.2 * up, 0],
        quat: quatAxisAngle([1, 0, 0], up * 0.12 * Math.sin(t * 2.4)),
        visible: smoothstep(0.08, 0.35, c.hatch),
      };
      out.amount = 0.3 + 0.7 * up;
    }

build:
build(k, o) {
      const C = [0, 0.18, 0];
      const R = 0.52;
      const swirl = k.part("swirl", { pivot: C, axis: [0, 1, 0] });
      const bronze = "#9a6a3a";
      // The stand.
      k.add(
        k.lathe(
          [
            [0.0, -0.96],
            [0.5, -0.95],
            [0.55, -0.9],
            [0.5, -0.84],
            [0.3, -0.79],
            [0.17, -0.7],
            [0.11, -0.56],
            [0.13, -0.46],
            [0.22, -0.39],
            [0.32, -0.33],
            [0.3, -0.29],
          ],
          { grid: 72 },
        ),
        {
          even: true,
          opacity: 1,
          jitter: 0.015,
          flat: 0.2,
          interior: 0,
          core: "#4a3320",
          color: (c) => metal(c, bronze, 0.35),
        },
      );
      // Runes round the foot that light up one after another.
      for (let i = 0; i < 12; i++) {
        const a = (i / 12) * TAU;
        const rr = 0.5;
        k.add(evenBox(0.035, 0.035, 0.012), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [Math.sin(a) * rr, -0.87, Math.cos(a) * rr],
          rot: [-18, (a * 180) / Math.PI, i % 2 ? 45 : 0],
          weight: 6,
          pattern: false,
          kind: "pulse",
          params: [i / 12, 0],
          color: mix(o.magic, "#ffffff", 0.35),
        });
      }
      // Claws holding the orb.
      for (let i = 0; i < 4; i++) {
        const a = (i / 4) * TAU + TAU / 8;
        const pt = (r, y) => [Math.sin(a) * r, y, Math.cos(a) * r];
        k.add(
          evenTube(
            k,
            spline([
              pt(0.28, -0.32),
              pt(0.46, -0.22),
              pt(0.56, -0.02),
              pt(0.58, 0.16),
              pt(0.53, 0.3),
            ]),
            (t) => 0.035 - 0.022 * t,
            { caps: true },
          ),
          {
            even: true,
            opacity: 1,
            jitter: 0.015,
            flat: 0.2,
            weight: 1.6,
            color: (c) => metal(c, bronze, 0.35),
          },
        );
      }
      // The glass: faint, brighter at the rim, with a highlight.
      k.add(k.sphere(R), {
        even: true,
        jitter: 0.015,
        pos: C,
        flat: 0.2,
        opacity: 0.2,
        share: 0.1,
        pattern: false,
        color: (c) => {
          const f = 1 - Math.abs(dot(c.n, VIEW));
          return mix(mix(o.magic, "#ffffff", 0.7), "#ffffff", f * f);
        },
      });
      k.cloud({ share: 0.012, size: 0.7, pattern: false }, (rand) => {
        const d = vec.unit([-0.45 + (rand() - 0.5) * 0.35, 0.6 + (rand() - 0.5) * 0.25, 0.65]);
        return { p: vec.add(C, vec.mul(d, R * 1.01)), color: "#ffffff", opacity: 0.55, n: d };
      });
      // Swirling magic inside: twisting ribbons of light round a glowing
      // heart, turning faster near the middle.
      const deep = shade(o.magic, 0.6);
      const pale = mix(o.magic, "#ffffff", 0.55);
      const other = mix(o.magic, "#3fd0ff", 0.75);
      k.cloud({ share: 0.22, size: 1.25, pattern: false }, (rand, i) => {
        const strand = i % 5;
        const h = rand() * 2 - 1;
        const rr =
          (0.12 + 0.3 * (1 - h * h) * (0.7 + 0.3 * Math.sin(strand * 2.1))) *
          (0.92 + 0.16 * rand());
        const a = (strand / 5) * TAU + h * 2.6 + (rand() - 0.5) * 0.35;
        const y = h * R * 0.72 + (rand() - 0.5) * 0.05;
        const col = mix(strand % 2 ? other : pale, deep, 0.6 * Math.abs(h) + 0.25 * rand());
        return {
          p: [C[0] + Math.sin(a) * rr, C[1] + y, C[2] + Math.cos(a) * rr],
          color: col,
          opacity: 0.55,
          kind: "orbit",
          params: [1.1, 0.6],
          part: swirl,
        };
      });
      k.cloud({ share: 0.08, size: 2.2, pattern: false }, (rand) => {
        const d = vec.unit([rand() - 0.5, rand() - 0.5, rand() - 0.5]);
        const rr = R * 0.8 * Math.cbrt(rand());
        return {
          p: vec.add(C, vec.mul(d, rr)),
          color: mix(deep, o.magic, rand()),
          opacity: 0.18,
          kind: "orbit",
          params: [0.5, 0.3],
        };
      });
      k.cloud({ share: 0.03, size: 1.3, pattern: false }, (rand) => {
        const d = vec.unit([rand() - 0.5, rand() - 0.5, rand() - 0.5]);
        const rr = 0.1 * Math.cbrt(rand());
        return {
          p: vec.add(C, vec.mul(d, rr)),
          color: mix("#ffffff", pale, rr * 6),
          opacity: 0.9,
          kind: "twinkle",
          params: [0.3, rand() * TAU],
        };
      });
      k.cloud({ share: 0.015, size: 0.55, pattern: false }, (rand) => {
        const d = vec.unit([rand() - 0.5, rand() - 0.5, rand() - 0.5]);
        const rr = R * 0.85 * Math.cbrt(rand());
        return {
          p: vec.add(C, vec.mul(d, rr)),
          color: rand() < 0.5 ? "#ffffff" : "#bff3ff",
          opacity: 1,
          kind: "twinkle",
          params: [0.45, rand() * TAU],
        };
      });
      // Motes circling outside, and sparks rising from the top.
      k.cloud({ share: 0.01, size: 0.7, pattern: false }, (rand) => {
        const a = rand() * TAU;
        const rr = 0.68 + rand() * 0.1;
        return {
          p: [
            Math.sin(a) * rr,
            C[1] + (rand() - 0.5) * 0.2 + 0.1 * Math.sin(a * 3),
            Math.cos(a) * rr,
          ],
          color: mix(pale, "#ffffff", rand()),
          opacity: 0.9,
          kind: "orbit",
          params: [0.6, 0],
        };
      });
      k.cloud({ share: 0.006, size: 0.6, pattern: false }, (rand) => ({
        p: [(rand() - 0.5) * 0.3, C[1] + R * 0.9, (rand() - 0.5) * 0.3],
        color: mix(pale, "#ffffff", 0.5),
        opacity: 1,
        kind: "rise",
        params: [0.45, rand()],
      }));
      // The spell, hidden until cast. A flash of light filling the glass.
      const flash = k.part("flash", { pivot: C });
      k.cloud({ share: 0.012, size: 3, pattern: false }, (rand) => {
        const d = vec.unit([rand() - 0.5, rand() - 0.5, rand() - 0.5]);
        return {
          p: vec.add(C, vec.mul(d, R * 0.9 * Math.cbrt(rand()))),
          color: mix(pale, "#ffffff", 0.5 + 0.5 * rand()),
          opacity: 0.22,
          part: flash,
        };
      });
      // Sparks spiralling out in five arms, revealed from the glass outwards.
      const sparks = k.part("sparks", { pivot: C, axis: [0, 1, 0] });
      k.cloud({ share: 0.03, size: 0.75, pattern: false }, (rand, i) => {
        const arm = i % 5;
        const f = Math.sqrt(rand());
        const a = (arm / 5) * TAU + f * 2.4 + (rand() - 0.5) * 0.15;
        const rr = R * 1.02 + f * 0.42 + (rand() - 0.5) * 0.03;
        const y = C[1] + (rand() - 0.5) * 0.06 + 0.18 * f * Math.sin(arm * 2.3);
        return {
          p: [Math.sin(a) * rr, y, Math.cos(a) * rr],
          dir: [Math.cos(a), 0, -Math.sin(a)],
          stretch: 1.8,
          size: f > 0.9 ? 1.4 : 1,
          color: mix("#ffffff", arm % 2 ? other : pale, 0.3 + 0.5 * f),
          opacity: 1,
          part: sparks,
          kind: "grow",
          params: [f * 0.85, 0],
        };
      });
      // A ring of glowing runes that rises and circles the orb.
      const runes = k.part("runes", { pivot: C, axis: [0, 1, 0] });
      const glyphs = [
        [
          [0, -1, 0, 1],
          [0, 1, 0.6, 0.4],
          [0, 0.3, 0.6, -0.3],
        ],
        [
          [-0.4, -1, -0.4, 1],
          [-0.4, 1, 0.5, 0],
          [0.5, 0, -0.4, -0.3],
        ],
        [
          [0, -1, 0, 1],
          [-0.6, 0.6, 0.6, -0.2],
        ],
        [
          [-0.5, -1, 0, 1],
          [0, 1, 0.5, -1],
          [-0.3, -0.2, 0.3, -0.2],
        ],
        [
          [0, -1, 0, 1],
          [-0.6, 1, 0, 0.2],
          [0.6, 1, 0, 0.2],
        ],
        [
          [0, 1, 0.5, 0],
          [0.5, 0, 0, -1],
          [0, -1, -0.5, 0],
          [-0.5, 0, 0, 1],
        ],
      ];
      k.cloud({ share: 0.03, size: 0.9, pattern: false }, (rand, i) => {
        const n = i % 10;
        const g = glyphs[(n * 7) % glyphs.length];
        const [x0, y0, x1, y1] = g[Math.floor(rand() * g.length)];
        const f = rand();
        const a = (n / 10) * TAU;
        const out = [Math.sin(a), 0, Math.cos(a)];
        const side = [Math.cos(a), 0, -Math.sin(a)];
        const sz = 0.085;
        const u = (x0 + (x1 - x0) * f) * sz;
        const v = (y0 + (y1 - y0) * f) * sz;
        const rr = 0.8;
        return {
          p: [out[0] * rr + side[0] * u, C[1] + v, out[2] * rr + side[2] * u],
          dir: vec.unit(vec.add(vec.mul(side, x1 - x0), [0, y1 - y0, 0])),
          stretch: 1.6,
          color: mix(pale, "#ffffff", 0.4 + 0.3 * rand()),
          opacity: 1,
          part: runes,
          kind: "twinkle",
          params: [0.35, n * 1.3],
        };
      });
      k.reach([0, C[1] + R + 0.35, 0]);
    }

drive:
drive(t, c, out) {
      // A spell: a flash of light, the swirl spins up, sparks spiral out and a
      // ring of runes rises round the orb, circles it and fades.
      const e = (1 - c.cast) * 3.2;
      const on = c.cast > 0;
      const env = on ? band(e, 0, 0.2) * (1 - band(e, 2.4, 3.2)) : 0;
      out.amount = 0.55 + 1.4 * env;
      out.glow = [0.75, 0.55, 1, 0.7 + 2 * env];
      out.parts.swirl = { angle: on ? TAU * 1.5 * ease(e / 2.6) : 0 };
      out.parts.flash = { visible: on ? 3 * Math.exp(-e * 3) * band(e, 0, 0.06) : 0 };
      out.grow = on ? band(e, 0.08, 1.1) : 0;
      out.parts.sparks = {
        angle: on ? 1.2 * ease(e / 2.2) : 0,
        visible: on ? 1 - band(e, 1.4, 2.4) : 0,
      };
      out.parts.runes = {
        angle: -1.6 * ease(e / 3.2),
        offset: [0, 0.12 * ease(band(e, 0.1, 1)), 0],
        visible: on ? ease(band(e, 0.1, 0.5)) * (1 - band(e, 2.3, 3.1)) : 0,
      };
    }

build:
build(k, o) {
      const pal = JELLY[o.kind];
      const rimY = 0.3;
      const rimR = 0.7;
      const bellProf = [
        [rimR - 0.04, rimY - 0.02],
        [rimR + 0.02, rimY + 0.08],
        [0.68, 0.45],
        [0.58, 0.66],
        [0.4, 0.84],
        [0.2, 0.93],
        [0, 0.96],
      ];
      const pulse = { kind: "breathe", params: [0.05, 0] };
      const gonad = (c) => {
        const x = c.p[0];
        const z = c.p[2];
        for (let i = 0; i < 4; i++) {
          const a = (i / 4) * TAU + TAU / 8;
          const d = Math.hypot(x - Math.sin(a) * 0.24, z - Math.cos(a) * 0.24);
          if (Math.abs(d - 0.1) < 0.032 && c.p[1] > 0.7) return true;
        }
        return false;
      };
      k.add(k.lathe(bellProf, { grid: 72 }), {
        ...pulse,
        flat: 0.2,
        opacity: 0.6,
        color: (c) => {
          const h = band(c.p[1], rimY, 0.96);
          if (gonad(c)) return keep(mix(pal.gonad, "#ffffff", 0.15));
          const a = Math.atan2(c.p[0], c.p[2]) / TAU;
          const canal = Math.abs(fract(a * 16) - 0.5) > 0.46;
          let col = mix(pal.rim, pal.bell, 0.35 + 0.65 * h);
          if (canal) col = mix(col, "#ffffff", 0.3);
          const f = 1 - Math.abs(dot(c.n, VIEW));
          col = mix(col, "#ffffff", 0.35 * f * f);
          return lit(c, col, 0.25, 0.5);
        },
      });
      // The underside of the bell, a little deeper in colour.
      k.add(
        k.lathe(
          bellProf.map(([r, y]) => [r * 0.9, y - 0.05]),
          { grid: 48 },
        ),
        {
          ...pulse,
          flat: 0.25,
          opacity: 0.5,
          color: (c) => mix(pal.rim, pal.bell, 0.4 * band(c.p[1], rimY, 0.9)),
        },
      );
      // A glowing rim with little sense organs.
      k.add(k.torus(rimR, 0.026), {
        ...pulse,
        pos: [0, rimY + 0.01, 0],
        weight: 2.5,
        pattern: false,
        opacity: 0.95,
        color: (c) => {
          const a = Math.atan2(c.p[0], c.p[2]) / TAU;
          return Math.abs(fract(a * 8) - 0.5) < 0.04 ? "#ffffff" : pal.glow;
        },
      });
      k.cloud({ share: 0.01, size: 0.8, pattern: false }, (rand) => {
        const a = rand() * TAU;
        const r = rimR + (rand() - 0.5) * 0.04;
        return {
          p: [Math.sin(a) * r, rimY + (rand() - 0.5) * 0.04, Math.cos(a) * r],
          color: pal.glow,
          opacity: 1,
          kind: "twinkle",
          params: [0.35, rand() * TAU],
        };
      });
      // Oral arms: four frilly ribbons from the middle.
      const armsA = k.part("armsA", { pivot: [0, rimY + 0.05, 0], axis: [1, 0, 0] });
      const armsB = k.part("armsB", { pivot: [0, rimY + 0.05, 0], axis: [0, 0, 1] });
      for (let i = 0; i < 4; i++) {
        const a = (i / 4) * TAU + TAU / 8;
        const out = [Math.sin(a), 0, Math.cos(a)];
        const side = [Math.cos(a), 0, -Math.sin(a)];
        const len = 1.05;
        const arm = k.param(
          (u, v) => {
            const y = rimY + 0.08 - v * len;
            const wig = 0.07 * Math.sin(v * 5 + i);
            const w = 0.1 * (1 - 0.55 * v) * (u - 0.5) * 2;
            const frill = 0.035 * Math.sin(v * 38 + u * 3) * Math.abs(u - 0.5) * 2;
            const r = 0.06 + 0.1 * v + wig;
            return [out[0] * (r + frill) + side[0] * w, y, out[2] * (r + frill) + side[2] * w];
          },
          { grid: 48 },
        );
        k.add(arm, {
          part: i % 2 ? armsA : armsB,
          kind: "breathe",
          params: [0.03, 0],
          flat: 0.25,
          opacity: 0.8,
          color: (c) => {
            const edge = Math.abs(c.u - 0.5) * 2;
            return lit(c, mix(pal.arms, "#ffffff", 0.35 * edge + 0.2 * c.v), 0.25, 0.3);
          },
        });
      }
      // Trailing tentacles in six groups that sway from the rim.
      for (let g = 0; g < 6; g++) {
        const a0 = (g / 6) * TAU;
        const piv = [Math.sin(a0) * rimR * 0.95, rimY, Math.cos(a0) * rimR * 0.95];
        const part = k.part(`t${g}`, { pivot: piv, axis: [Math.cos(a0), 0, -Math.sin(a0)] });
        for (let j = 0; j < 3; j++) {
          const a = a0 + (j - 1) * 0.3 + 0.05 * k.rand();
          const r0 = rimR * 0.93;
          const len = 1.15 + 0.35 * k.rand();
          const ph = k.rand() * TAU;
          const pts = [];
          for (let s = 0; s <= 6; s++) {
            const f = s / 6;
            const rr = r0 - 0.08 * f + 0.06 * Math.sin(f * 5 + ph);
            const aa = a + 0.12 * Math.sin(f * 4 + ph);
            pts.push([Math.sin(aa) * rr, rimY + 0.02 - f * len, Math.cos(aa) * rr]);
          }
          k.add(
            k.tube(spline(pts), (t) => 0.016 * (1 - 0.6 * t), { grid: 24, samples: 64 }),
            {
              part,
              kind: "twinkle",
              params: [0.12, ph],
              flat: 0.3,
              weight: 2.2,
              opacity: 0.85,
              pattern: false,
              color: (c) => mix(pal.glow, pal.bell, 0.3 + 0.5 * c.t),
            },
          );
        }
      }
    }

drive:
drive(t, c, out) {
      // One strong stroke: the bell squeezes tall and narrow and jets the
      // jelly upwards, the tentacles stream behind it, glowing, and it
      // drifts back down.
      const e = (1 - c.pulse) * 3.2;
      const on = c.pulse > 0;
      const env = on ? band(e, 0, 0.1) * (1 - band(e, 1.6, 3.2)) : 0;
      const squeeze = on ? Math.sin(Math.PI * band(e, 0, 0.5)) : 0;
      const relax = on ? Math.sin(Math.PI * band(e, 0.5, 1.2)) : 0;
      const rise = on ? easeInOut(band(e, 0.05, 0.9)) * (1 - easeInOut(band(e, 1.2, 3.2))) : 0;
      const trail = on ? easeInOut(band(e, 0.05, 0.4)) * (1 - easeInOut(band(e, 0.9, 2.6))) : 0;
      out.body = { offset: [0, 0.3 * rise, 0], squash: -0.2 * squeeze + 0.07 * relax };
      out.amount = 1 + 1.6 * env;
      for (let i = 0; i < 6; i++)
        out.parts[`t${i}`] = {
          angle: 0.1 * (1 - trail) * Math.sin(t * 1.3 + i * 1.7) + 0.32 * trail,
          visible: 1 + 0.9 * env,
        };
      out.parts.armsA = { angle: 0.07 * Math.sin(t * 1.1) };
      out.parts.armsB = { angle: 0.07 * Math.sin(t * 1.1 + 2) };
    }

build:
build(k, o) {
      // Fish in three shells round the middle; each fish is a token that
      // drive() orbits with its shell (rigidly, so no fish is stretched).
      const fish = [];
      const shells = [
        { r: 0.36, n: 8, rate: 0.95 },
        { r: 0.62, n: 16, rate: 0.75 },
        { r: 0.88, n: 24, rate: 0.6 },
      ];
      const tropical = ["#ffd23a", "#ff8a2a", "#3fb8ff", "#ff5f8a", "#8be04a"];
      for (const sh of shells) {
        for (let i = 0; i < sh.n; i++) {
          const a = (i / sh.n) * TAU + k.rand() * 0.4;
          const cy = (((i * 7) % sh.n) / sh.n - 0.5) * 1.5 + (k.rand() - 0.5) * 0.15;
          const r = sh.r * (0.95 + 0.1 * k.rand());
          const pos = [
            Math.sin(a) * r * Math.sqrt(1 - cy * cy),
            cy * r,
            Math.cos(a) * r * Math.sqrt(1 - cy * cy),
          ];
          const fwd = vec.unit([Math.cos(a), (k.rand() - 0.5) * 0.25, -Math.sin(a)]);
          const side = vec.unit(vec.cross(fwd, [0, 1, 0]));
          const up = vec.cross(side, fwd);
          fish.push({
            pos,
            fwd,
            up,
            side,
            rate: sh.rate,
            size: 0.85 + 0.3 * k.rand(),
            col: tropical[Math.floor(k.rand() * tropical.length)],
            jit: k.rand(),
            far: k.rand(),
          });
        }
      }
      k.data = { fish: fish.map((f) => ({ pos: f.pos, rate: f.rate, jit: f.jit, far: f.far })) };
      const L = 0.25;
      const D = 0.085;
      const W = 0.044;
      const silver = o.kind !== "tropical";
      k.cloud({ share: 0.97, size: 0.55, flat: 0.3 }, (rand, i) => {
        const fi = i % fish.length;
        const f = fish[fi];
        const s = f.size;
        const pick = rand();
        let lp;
        let ln;
        let col;
        let keepIt = false;
        if (pick < 0.8) {
          // The body: a spindle, blunt at the head (+x).
          let t;
          let rho;
          do {
            t = rand();
            rho = Math.pow(Math.sin(Math.PI * Math.pow(t, 0.75)), 0.8);
          } while (rand() > rho + 0.05);
          const ph = rand() * TAU;
          const x = (t - 0.5) * L;
          lp = [x, Math.cos(ph) * rho * D * 0.5, Math.sin(ph) * rho * W * 0.5];
          ln = vec.unit([0, Math.cos(ph) / D, Math.sin(ph) / W]);
          const back = Math.cos(ph);
          if (silver) {
            col =
              back > 0.35 ? mix("#2d5c86", "#3f78a8", rand()) : mix("#dfe8ee", "#f7fbff", rand());
            if (Math.abs(back - 0.2) < 0.08) col = "#8fb8d6";
          } else {
            col = f.col;
            if (Math.abs(fract(t * 3.2) - 0.5) < 0.1 && t > 0.2) col = "#ffffff";
            if (back < -0.4) col = mix(col, "#ffffff", 0.4);
          }
          // An eye on each side near the head.
          const e = Math.hypot(x - 0.3 * L, lp[1] - 0.12 * D);
          if (e < 0.012 && Math.abs(lp[2]) > W * 0.2) {
            col = e < 0.006 ? "#0c0c10" : "#ffffff";
            keepIt = true;
          }
        } else if (pick < 0.94) {
          // A forked tail.
          const u = rand();
          const v = rand() * 2 - 1;
          const x = -L / 2 - u * 0.075;
          const h = (0.012 + u * 0.05) * v;
          if (u > 0.6 && Math.abs(v) < (u - 0.6) * 1.6) return null;
          lp = [x, h, 0];
          ln = [0, 0, 1];
          col = silver ? mix("#3f6d95", "#b9cfe0", Math.abs(v)) : shade(f.col, 0.8);
        } else {
          // A small fin on the back.
          const u = rand();
          const v = rand();
          lp = [(-0.05 + u * 0.1 - v * 0.03) * 1, D * 0.45 + v * 0.035 * (1 - u), 0];
          ln = [0, 0, 1];
          col = silver ? "#355f86" : shade(f.col, 0.75);
        }
        const p = vec.add(
          f.pos,
          vec.add(
            vec.mul(f.fwd, lp[0] * s),
            vec.add(vec.mul(f.up, lp[1] * s), vec.mul(f.side, lp[2] * s)),
          ),
        );
        const n = vec.add(
          vec.mul(f.fwd, ln[0]),
          vec.add(vec.mul(f.up, ln[1]), vec.mul(f.side, ln[2])),
        );
        const lightF = 1 + 0.25 * (0.9 * dot(n, LIGHT) - 0.15);
        return {
          p,
          n,
          color: shade(col, lightF),
          size: 1,
          opacity: 0.95,
          kind: "token",
          params: [fi, 0],
          pattern: keepIt ? false : undefined,
        };
      });
      // Bubbles drifting up.
      k.cloud({ share: 0.003, size: 0.8, pattern: false }, (rand) => ({
        p: [(rand() - 0.5) * 1.2, -0.7 + rand() * 0.3, (rand() - 0.5) * 1.2],
        color: "#dff4ff",
        opacity: 0.55,
        kind: "rise",
        params: [1.2, rand()],
      }));
    }

drive:
drive(t, c, out, info) {
      // Each fish is its own piece, orbiting with its shell. A tap: the
      // school tightens into a spinning bait ball, then bursts outwards in
      // every direction as if something struck at it, each fish darting
      // away head first, and swims back into its place.
      const F = info.data?.fish;
      if (!F) return;
      const on = c.swirl > 0;
      const s = progress(c.swirl) * FISH_SECS;
      const spin = on ? TAU * easeInOut(band(s, 0.2, 2.4)) : 0;
      out.tokens = F.map((f, i) => {
        const d = f.jit * 0.25;
        const ball = on ? easeInOut(band(s, 0.1 + d, 1.2 + d)) * (1 - band(s, 2.2 + d, 2.45 + d)) : 0; // prettier-ignore
        const burst = on ? (1 - (1 - band(s, 2.2 + d, 2.6 + d)) ** 3) * (1 - easeInOut(band(s, 3.1 + d, 4.7 + d))) : 0; // prettier-ignore
        const rho = 1 - 0.45 * ball + (0.18 + 0.24 * f.far) * burst;
        const face = -(Math.PI / 2) * (on ? band(s, 2.2 + d, 2.4 + d) * (1 - band(s, 2.9 + d, 3.7 + d)) : 0); // prettier-ignore
        const th = f.rate * t + spin;
        const q = quatAxisAngle([0, 1, 0], th + face);
        const P = quatRotate(quatAxisAngle([0, 1, 0], th), vec.mul(f.pos, rho));
        return { base: [0, 0, 0], quat: q, offset: vec.sub(P, quatRotate(q, f.pos)) };
      });
    }

build:
build(k, o) {
      const kind = o.wings;
      // Wing outlines in polar form round the root (angles in degrees, 0 = +x).
      const fore = {
        root: [0.02, 0.1],
        a0: -6,
        a1: 84,
        r: (a) =>
          0.55 +
          0.4 * Math.pow(Math.max(0, Math.sin((Math.PI * (a + 6)) / 90)), 0.7) -
          0.1 * band(a, 60, 84),
      };
      const hind = {
        root: [0.02, 0.02],
        a0: -96,
        a1: 10,
        r: (a) => {
          let r = 0.36 + 0.24 * Math.pow(Math.max(0, Math.sin((Math.PI * (a + 96)) / 106)), 0.6);
          if (kind === "swallowtail") r += 0.28 * Math.exp(-(((a + 62) / 5) ** 2));
          return r;
        },
      };
      const patterns = {
        monarch(w, a, v, s) {
          const vein =
            Math.abs(fract(((a - w.a0) / (w.a1 - w.a0)) * (w === fore ? 7 : 6)) - 0.5) > 0.45;
          if (v > 0.84) {
            const dot1 = Math.abs(v - 0.9) < 0.028 && Math.abs(fract(a / 7) - 0.5) < 0.2;
            const dot2 = Math.abs(v - 0.955) < 0.02 && Math.abs(fract(a / 5 + 0.5) - 0.5) < 0.18;
            return dot1 || dot2 ? "#fbf7ea" : "#16110e";
          }
          if (vein || Math.abs(v - 0.5) < 0.018) return "#1b1410";
          if (w === fore && a > 40 && v > 0.66)
            return Math.abs(fract(a / 9) - 0.5) < 0.18 && v < 0.8 ? "#fbf1d8" : "#16110e";
          return mix("#f7a21e", "#e0620f", 0.5 * v + 0.2 * s);
        },
        morpho(w, a, v, s) {
          if (v > 0.8) {
            const d = Math.abs(v - 0.9) < 0.03 && Math.abs(fract(a / 8) - 0.5) < 0.2;
            return d ? "#f5f5f0" : "#101622";
          }
          const sheen = 0.5 + 0.5 * Math.sin(a * 0.05 + v * 3);
          const vein = Math.abs(fract(((a - w.a0) / (w.a1 - w.a0)) * 8) - 0.5) > 0.47;
          const col = mix("#1f7fe8", "#5ee8ff", sheen * (1 - v) + 0.2 * s);
          return vein ? shade(col, 0.7) : col;
        },
        swallowtail(w, a, v) {
          if (v > 0.84) {
            const c = Math.abs(v - 0.91) < 0.03 && Math.abs(fract(a / 9) - 0.5) < 0.25;
            return c ? "#f6de5a" : "#15130f";
          }
          if (w === hind) {
            const eyeA = Math.hypot((a + 20) / 30, (v - 0.72) / 0.1);
            if (eyeA < 1) return eyeA < 0.5 ? "#ff7a1a" : "#2d5fd8";
            if (v > 0.7) return "#15130f";
          }
          const stripe = w === fore && Math.abs(fract(a / 16 + 0.3) - 0.5) < 0.12;
          return stripe || Math.abs(v - 0.55) < 0.02 ? "#15130f" : "#f7e27a";
        },
        rose(w, a, v, s) {
          if (v > 0.85)
            return Math.abs(fract(a / 7) - 0.5) < 0.2 && Math.abs(v - 0.92) < 0.03
              ? "#ffffff"
              : "#5a1f5c";
          const spot = w === fore && Math.hypot((a - 50) / 14, (v - 0.62) / 0.1) < 1;
          if (spot) return "#ffffff";
          return mix("#ff7ac0", "#9a5cff", v * 0.9 + 0.15 * s);
        },
      };
      const paint = patterns[kind];
      const parts = {
        right: k.part("right", { pivot: [0, 0.05, 0], axis: [0, 1, 0] }),
        left: k.part("left", { pivot: [0, 0.05, 0], axis: [0, 1, 0] }),
      };
      for (const side of [1, -1]) {
        const part = side > 0 ? parts.right : parts.left;
        for (const w of [fore, hind]) {
          const shape = k.param(
            (u, v) => {
              const a = (w.a0 + u * (w.a1 - w.a0)) * DEG;
              const r = v * w.r(w.a0 + u * (w.a1 - w.a0));
              return [
                side * (w.root[0] + Math.cos(a) * r),
                w.root[1] + Math.sin(a) * r,
                -0.01 * v - (w === hind ? 0.006 : 0),
              ];
            },
            { grid: 48, normal: () => [0, 0, 1] },
          );
          k.add(shape, {
            even: true,
            opacity: 1,
            jitter: 0.015,
            part,
            flat: 0.12,
            weight: 1,
            color: (c) => {
              const a = w.a0 + c.u * (w.a1 - w.a0);
              const col = paint(w, a, c.v, c.noise(c.u * 8, c.v * 8, side));
              return shade(col, 1 + 0.08 * (0.5 - c.v));
            },
          });
        }
      }
      // Body: head, fuzzy thorax and a long abdomen.
      const fuzz = (c) =>
        lit(
          c,
          mix("#2a211c", "#4a3a2e", 0.5 + 0.5 * c.noise(c.p[0] * 80, c.p[1] * 80, c.p[2] * 80)),
          0.35,
        );
      k.add(k.ellipsoid(0.055, 0.13, 0.06), {
        pos: [0, 0.08, 0.02],
        weight: 2,
        pattern: false,
        color: fuzz,
      });
      k.add(k.ellipsoid(0.04, 0.24, 0.045), {
        pos: [0, -0.2, 0.02],
        weight: 2,
        pattern: false,
        color: (c) => {
          const ring = fract(c.p[1] * 22) < 0.2;
          return lit(c, ring ? "#6a5746" : "#2e241e", 0.35);
        },
      });
      k.add(k.sphere(0.05), { pos: [0, 0.24, 0.03], weight: 2, pattern: false, color: fuzz });
      for (const s of [-1, 1]) {
        eye(k, [s * 0.03, 0.255, 0.06], 0.022, [s * 0.5, 0.2, 1], { pupil: -1, weight: 3 });
        const ant = spline([
          [s * 0.02, 0.28, 0.04],
          [s * 0.07, 0.42, 0.07],
          [s * 0.14, 0.55, 0.08],
          [s * 0.2, 0.62, 0.07],
        ]);
        k.add(k.tube(ant, 0.006, { grid: 12, samples: 32 }), {
          weight: 3,
          pattern: false,
          kind: "sway",
          params: [0.2, 0.28],
          color: "#1d1712",
        });
        k.add(k.sphere(0.016), {
          pos: [s * 0.2, 0.62, 0.07],
          weight: 3,
          pattern: false,
          kind: "sway",
          params: [0.2, 0.28],
          color: "#1d1712",
        });
      }
    }

drive:
drive(t, c, out) {
      const amp = 0.35 + 0.55 * c.flap;
      const a = 0.12 + amp * (0.5 - 0.5 * Math.cos(t * (5 + 5 * c.flap)));
      out.parts.right = { angle: a };
      out.parts.left = { angle: -a };
      out.amount = 0.6;
    }

build:
build(k) {
      const { dirs, R } = PUFF;
      const parts = dirs.map((d, i) => k.part(`p${i}`, { pivot: vec.mul(d, R) }));
      const cap = 41 * DEG;
      const spots = (p) => k.noise(p[0] * 7 + 3, p[1] * 7, p[2] * 7) > 0.3;
      const skin = (c) => {
        const p = c.p;
        const m = Math.acos(clamp(dot(vec.unit(p), PUFF.mouth), -1, 1));
        if (m < 0.1) return keep(m < 0.05 ? "#3a1c18" : lit(c, "#c56a4a", 0.3));
        const belly = smoothstep(-0.05, -0.35, p[1]);
        let col = mix("#d9b24e", "#f6efd8", belly);
        if (belly < 0.5 && spots(p)) col = mix("#6b4526", col, belly * 1.5);
        col = mix(col, "#f5d66a", 0.25 * smoothstep(0.2, 0.7, p[0] / R) * (1 - belly));
        return lit(c, col, 0.35, 0.35);
      };
      dirs.forEach((d, i) => {
        const e1 = vec.unit(vec.cross(d, Math.abs(d[1]) < 0.9 ? [0, 1, 0] : [1, 0, 0]));
        const e2 = vec.cross(d, e1);
        const dirAt = (u, v) => {
          const a = v * cap;
          const b = u * TAU;
          return vec.add(
            vec.mul(d, Math.cos(a)),
            vec.add(vec.mul(e1, Math.sin(a) * Math.cos(b)), vec.mul(e2, Math.sin(a) * Math.sin(b))),
          );
        };
        k.add(
          k.param((u, v) => vec.mul(dirAt(u, v), R), {
            grid: 28,
            normal: (u, v) => dirAt(u, v),
            thick: 0.5,
          }),
          { part: parts[i], flat: 0.2, color: skin },
        );
      });
      // Big eyes, each riding on its own patch.
      for (const e of PUFF.eyes)
        eye(k, vec.mul(e, R - 0.02), 0.14, vec.add(e, [0.4, 0, 0]), {
          part: parts[PUFF.nearest(e)],
          iris: "#f0c030",
          white: "#f7f4ea",
          pupil: 0.72,
          irisEdge: 0.4,
        });
      // Spines stand up as it puffs.
      const n = 130;
      const g = Math.PI * (3 - Math.sqrt(5));
      for (let i = 0; i < n; i++) {
        const y = 1 - ((i + 0.5) / n) * 2;
        const rr = Math.sqrt(1 - y * y);
        const d = [Math.cos(g * i) * rr, y, Math.sin(g * i) * rr];
        if (dot(d, PUFF.mouth) > 0.9) continue;
        if (PUFF.eyes.some((e) => dot(d, e) > 0.94)) continue;
        if (d[0] < -0.9) continue;
        k.add(k.cone(0.024, 0.003, 0.14), {
          pos: vec.mul(d, R + 0.05),
          quat: quatFromTo([0, 1, 0], d),
          part: parts[PUFF.nearest(d)],
          weight: 2,
          flat: 0.3,
          kind: "grow",
          params: [0.35 + 0.4 * k.rand(), 0],
          color: (c) => lit(c, mix("#efe2b8", "#8a5a30", band(c.lp[1], 0.0, 0.07)), 0.25),
        });
      }
      // Fins: two pectoral fans and a tail.
      const fan = (root, dir, up, size, part, col) => {
        const side = vec.unit(vec.cross(dir, up));
        const shape = k.param(
          (u, v) => {
            const a = (u - 0.5) * 1.8;
            const r = v * size * (0.8 + 0.2 * Math.cos(u * TAU * 3));
            return vec.add(
              root,
              vec.add(vec.mul(dir, Math.cos(a) * r), vec.mul(side, Math.sin(a) * r)),
            );
          },
          { grid: 20, normal: () => up },
        );
        k.add(shape, {
          part,
          flat: 0.2,
          weight: 1.5,
          opacity: 0.85,
          pattern: false,
          color: (c) =>
            shade(mix(col, "#fff6d8", 0.4 * c.v), 0.9 + 0.2 * Math.abs(Math.sin(c.u * 40))),
        });
      };
      PUFF.fins.forEach((f, i) => {
        const root = vec.mul(f, R - 0.03);
        const part = k.part(i ? "finR" : "finL", { pivot: root, axis: [0, 1, 0] });
        fan(root, vec.unit([-0.5, 0, f[2] * 0.8]), [0, 1, 0], 0.22, part, "#e8c25a");
      });
      const tail = k.part("tail", { pivot: [-R + 0.05, 0, 0], axis: [0, 1, 0] });
      fan([-R + 0.05, 0, 0], [-1, 0, 0], [0, 0, 1], 0.32, tail, "#d9a940");
      const top = PUFF.nearest([-0.35, 1, 0]);
      fan(
        vec.mul(vec.unit([-0.45, 0.9, 0]), R - 0.02),
        vec.unit([-0.8, 0.5, 0]),
        [0, 0, 1],
        0.2,
        parts[top],
        "#d9a940",
      );
    }

drive:
drive(t, c, out) {
      // Poked, it gulps water and swells into a round, spiky ball with a
      // wobble, holds it, then lets it out with a sputter and slims down.
      const p = c.poke;
      const s = (1 - p) * 4.5;
      const up = band(s, 0, 0.45);
      const down = easeInOut(band(s, 2.8, 4.3));
      const scare = p > 0 ? (1 - (1 - up) ** 3) * (1 - down) : 0;
      const e = Math.max(c.puff, scare);
      const offs = PUFF.dirs.map((d, i) => vec.mul(d, -PUFF.shift[i] * (1 - e)));
      offs.forEach((o, i) => (out.parts[`p${i}`] = { offset: o }));
      const flap = (0.45 + 0.4 * (p > 0 ? 1 : 0)) * Math.sin(t * 7);
      out.parts.finL = { offset: offs[PUFF.finPatch[0]], angle: flap };
      out.parts.finR = { offset: offs[PUFF.finPatch[1]], angle: -flap };
      out.parts.tail = { angle: 0.35 * Math.sin(t * 4) };
      out.grow = e;
      if (p > 0) {
        const wobble =
          0.12 * Math.sin((s - 0.3) * 22) * Math.exp(-3 * Math.max(0, s - 0.3)) * band(s, 0.3, 0.4);
        const sputter = Math.sin(Math.PI * band(s, 2.8, 4.3));
        out.body = {
          squash: wobble,
          quat: quatMul(
            quatAxisAngle([0, 1, 0], 0.18 * sputter * Math.sin(s * 31)),
            quatAxisAngle([0, 0, 1], 0.1 * sputter * Math.sin(s * 23 + 1)),
          ),
          offset: [0.05 * sputter * Math.sin(s * 17), 0, 0],
        };
      }
    }

build:
build(k) {
      const N = NAUT;
      const t0 = N.tMax - 3.3 * Math.PI;
      const span = N.tMax - t0;
      const outward = (tt, phi) => [
        Math.cos(phi) * Math.cos(tt),
        Math.cos(phi) * Math.sin(tt),
        Math.sin(phi),
      ];
      // The shell.
      k.add(
        k.param((u, v) => N.at(t0 + u * span, 1, v * TAU), {
          grid: 120,
          normal: (u, v) => outward(t0 + u * span, v * TAU),
        }),
        {
          even: true,
          opacity: 1,
          jitter: 0.015,
          flat: 0.18,
          color: (c) => {
            const tt = t0 + c.u * span;
            const phi = c.v * TAU;
            const turns = tt / TAU;
            const fade = 1 - band(tt, N.tMax - 2.1, N.tMax - 0.9);
            const wav =
              0.22 * Math.sin(phi * 1.5 + turns * 3) + 0.06 * c.noise(c.p[0] * 9, c.p[1] * 9, 0);
            const s = fract(turns * 15 + wav);
            let col = "#f5ecdc";
            const lateral = Math.abs(Math.sin(phi));
            if (s < 0.45 * fade * (0.5 + 0.6 * lateral))
              col = mix("#b85a26", "#7a3416", band(Math.abs(s - 0.2), 0, 0.2));
            if (tt > N.tMax - 0.08)
              col = mix("#f2e4e8", "#e3c9d4", c.noise(c.p[0] * 30, c.p[1] * 30, 0));
            const rad = Math.hypot(c.p[0], c.p[1]);
            if (rad < 0.13 && Math.abs(c.p[2]) > 0.05) col = mix("#4a3326", col, rad / 0.13);
            return lit(c, col, 0.35, 0.45);
          },
        },
      );
      // The dark mouth of the shell.
      k.add(
        k.param((u, v) => N.at(N.tMax - 0.04, u * 0.97, v * TAU), {
          grid: 24,
          normal: () => [-Math.sin(N.tMax), Math.cos(N.tMax), 0],
        }),
        {
          even: true,
          opacity: 1,
          jitter: 0.015,
          flat: 0.3,
          color: (c) => mix("#2a1a12", "#5a3a28", c.u * 0.6),
        },
      );
      // Chambers inside: pearly walls every step, and the siphuncle
      // threading through them (Slice to see them).
      for (let i = 0; i < 16; i++) {
        const tt = N.tMax - 1.35 - i * 0.37;
        if (tt < t0 + 0.3) break;
        const s = N.sec(tt);
        const back = [Math.sin(tt), -Math.cos(tt), 0];
        k.add(
          k.param(
            (u, v) => vec.add(N.at(tt, u * 0.98, v * TAU), vec.mul(back, 0.3 * s.hw * (1 - u * u))),
            { grid: 20, normal: () => back },
          ),
          {
            even: true,
            opacity: 1,
            jitter: 0.015,
            flat: 0.3,
            weight: 0.8,
            color: (c) =>
              mix("#f3ebe2", "#e6d2e6", 0.5 + 0.5 * c.noise(c.p[0] * 25, c.p[1] * 25, i)),
          },
        );
      }
      k.add(
        k.tube(
          (t) => {
            const tt = t0 + 0.4 + t * (N.tMax - 1.3 - t0 - 0.4);
            const s = N.sec(tt);
            const rad = s.rc - 0.45 * s.hw;
            return [rad * Math.cos(tt), rad * Math.sin(tt), 0];
          },
          (t) => 0.004 + 0.012 * t,
          { grid: 16, samples: 128 },
        ),
        {
          even: true,
          opacity: 1,
          jitter: 0.015,
          flat: 0.3,
          weight: 2,
          color: "#b98a78",
        },
      );
      // The animal: a mottled hood, an eye and a bunch of short tentacles.
      const tm = N.tMax;
      const s = N.sec(tm);
      const dir = [Math.cos(tm), Math.sin(tm), 0];
      const tan = [-Math.sin(tm), Math.cos(tm), 0];
      const at = (rad, fwd, z) => vec.add(vec.add(vec.mul(dir, rad), vec.mul(tan, fwd)), [0, 0, z]);
      k.add(evenEllipsoid(k, 0.22, 0.13, 0.25), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: at(s.rc - 0.3 * s.hw, 0.02, 0),
        quat: quatFromTo([1, 0, 0], dir),
        flat: 0.25,
        color: (c) => {
          const n = c.noise(c.p[0] * 14, c.p[1] * 14, c.p[2] * 14);
          return lit(c, n > 0.2 ? "#f1e2c8" : mix("#8a4a28", "#a8603a", 0.5 + n), 0.35, 0.2);
        },
      });
      for (const z of [-1, 1])
        eye(k, at(s.rc + 0.05 * s.hw, 0.02, z * s.ht * 0.72), 0.05, [tan[0], tan[1], z * 0.8], {
          weight: 3,
        });
      const arms = k.part("arms", { pivot: at(s.rc, 0, 0), axis: [0, 0, 1] });
      for (let i = 0; i < 26; i++) {
        const f = (i + 0.5) / 26;
        const phi = f * TAU;
        const base = vec.add(
          at(s.rc + 0.55 * s.hw * Math.cos(phi) + 0.1 * s.hw, -0.02, 0.7 * s.ht * Math.sin(phi)),
          [0, 0, 0],
        );
        const len = 0.32 + 0.18 * k.rand();
        const curl = (k.rand() - 0.5) * 0.3;
        const pts = [];
        for (let j = 0; j <= 4; j++) {
          const g = j / 4;
          pts.push(
            vec.add(
              base,
              vec.add(
                vec.mul(tan, g * len),
                vec.add(vec.mul(dir, -g * g * 0.18 + curl * g), [0, 0, Math.sin(phi) * g * 0.08]),
              ),
            ),
          );
        }
        // Each tentacle shortens towards its base on channel 0 (its rings
        // bunch up), keeping its thickness.
        const curve = spline(pts);
        const rad = (t) => 0.02 * (1 - 0.55 * t);
        k.add(evenTube(k, curve, rad, { grid: 16, samples: 32, caps: true }), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          part: arms,
          flat: 0.35,
          weight: 1.4,
          kind: "morph",
          channel: 0,
          to: (c) => {
            const tt = clamp(c.t ?? 0, 0, 1);
            const off = vec.sub(c.p, curve(tt));
            return vec.add(curve(tt * 0.12), vec.mul(off, rad(tt * 0.12) / rad(tt)));
          },
          color: (c) => lit(c, fract(c.t * 7) < 0.3 ? "#e8b894" : "#f6dcc2", 0.3),
        });
      }
    }

drive:
drive(t, c, out) {
      // Startled, the nautilus jets back a little and pulls its tentacles
      // in behind its hood (each shortens towards its base). It waits, peeks
      // out halfway, then slowly reaches out again.
      const on = c.hide > 0;
      const s = progress(c.hide) * 4.4;
      const pull = on
        ? easeOut(band(s, 0, 0.55)) *
          (1 - 0.45 * easeInOut(band(s, 2.0, 2.5)) - 0.55 * easeInOut(band(s, 3.0, 4.1)))
        : 0;
      const tan = NAUT.tan;
      out.parts.arms = {
        angle: 0.08 * Math.sin(t * 1.2) * (1 - pull),
        offset: vec.mul(tan, -0.09 * pull),
      };
      out.morph = [pull];
      const jet = on ? Math.sin(Math.PI * band(s, 0, 1.1)) * (1 - band(s, 0, 1.1)) : 0;
      out.body = { offset: vec.mul(tan, -0.12 * jet) };
      out.amount = 0.8;
    }

build:
build(k) {
      const A = 0.5;
      const B = 0.42;
      const C = 0.6;
      const cz = -0.08;
      const spots = [
        [0.2, 0.12, 0.1],
        [0.3, -0.22, 0.1],
        [0.14, -0.46, 0.085],
        [0, 0.34, 0.1],
      ];
      const shell = (sgn) =>
        k.param(
          (u, v) => {
            const th = v * 98 * DEG;
            const ps = (sgn > 0 ? u : 1 + u) * Math.PI;
            return [
              A * Math.sin(th) * Math.sin(ps),
              B * Math.cos(th),
              cz + C * Math.sin(th) * Math.cos(ps),
            ];
          },
          { grid: 48 },
        );
      for (const sgn of [1, -1]) {
        const part = k.part(sgn > 0 ? "shellR" : "shellL", {
          pivot: [0, B - 0.02, cz],
          axis: [0, 0, 1],
        });
        k.add(shell(sgn), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          part,
          flat: 0.18,
          color: (c) => {
            const x = Math.abs(c.p[0]);
            const z = c.p[2];
            if (x < 0.014 && c.p[1] > 0) return keep("#141414");
            for (const [sx, sz, sr] of spots)
              if (Math.hypot(x - sx, z - sz) < sr) return keep(lit(c, "#151515", 0.3, 0.6));
            return lit(c, "#e0261e", 0.35, 0.7);
          },
        });
        // Hind wings, folded away until it flies.
        const wing = k.part(sgn > 0 ? "wingR" : "wingL", {
          pivot: [sgn * 0.1, 0.3, 0.1],
          axis: [0, 0, 1],
        });
        const d = vec.unit([sgn * 0.75, 0.35, -0.55]);
        const side = vec.unit(vec.cross(d, [0, 1, 0]));
        k.add(
          k.param(
            (u, v) => {
              const w = 0.17 * Math.sin(Math.PI * Math.pow(u, 0.8)) * (v - 0.5) * 2;
              return vec.add(
                [sgn * 0.1, 0.3, 0.1],
                vec.add(vec.mul(d, u * 0.85), vec.mul(side, w)),
              );
            },
            { grid: 24 },
          ),
          {
            even: true,
            jitter: 0.015,
            part: wing,
            flat: 0.15,
            opacity: 0.55,
            pattern: false,
            color: (c) => (Math.abs(fract(c.v * 4) - 0.5) > 0.44 ? "#6b4a2e" : "#d8c9b0"),
          },
        );
      }
      // Underside, pronotum and head.
      k.add(evenEllipsoid(k, 0.45, 0.16, 0.56), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [0, -0.08, cz],
        flat: 0.2,
        color: (c) => lit(c, "#1a1a1a", 0.3),
      });
      k.add(evenEllipsoid(k, 0.33, 0.2, 0.2), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [0, 0.05, 0.44],
        flat: 0.2,
        color: (c) =>
          Math.abs(c.lp[0]) > 0.17 && c.lp[1] > -0.05
            ? lit(c, "#f4f1e8", 0.3)
            : lit(c, "#161616", 0.3, 0.5),
      });
      k.add(k.sphere(0.17), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [0, -0.02, 0.62],
        flat: 0.2,
        color: (c) => {
          const l = c.lp;
          if (l[2] > 0.06 && l[1] > 0.02 && Math.abs(Math.abs(l[0]) - 0.075) < 0.04)
            return keep(lit(c, "#f4f1e8", 0.3));
          return lit(c, "#141414", 0.3, 0.5);
        },
      });
      for (const s of [-1, 1]) {
        eye(k, [s * 0.1, 0.0, 0.75], 0.035, [s * 0.5, 0.2, 1], { pupil: -1, weight: 3 });
        k.add(
          k.tube(
            spline([
              [s * 0.06, 0.08, 0.74],
              [s * 0.12, 0.2, 0.84],
              [s * 0.18, 0.26, 0.88],
            ]),
            0.008,
            { grid: 10, samples: 24 },
          ),
          {
            even: true,
            opacity: 1,
            jitter: 0.015,
            weight: 3,
            pattern: false,
            kind: "sway",
            params: [0.25, 0.05],
            color: "#141414",
          },
        );
        k.add(k.sphere(0.02), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [s * 0.18, 0.26, 0.88],
          weight: 3,
          pattern: false,
          color: "#141414",
        });
        for (const z of [0.25, -0.05, -0.35]) {
          k.add(
            evenTube(
              k,
              spline([
                [s * 0.2, -0.12, z],
                [s * 0.42, -0.2, z + 0.06],
                [s * 0.5, -0.38, z + 0.1],
              ]),
              0.02,
              { grid: 10, samples: 24, caps: true },
            ),
            {
              even: true,
              opacity: 1,
              jitter: 0.015,
              weight: 2,
              pattern: false,
              color: (c) => lit(c, "#1a1a1a", 0.3),
            },
          );
        }
      }
      k.reach([0, 1.1, cz]);
    }

drive:
drive(t, c, out) {
      const o = easeInOut(c.fly);
      out.parts.shellR = { angle: 1.15 * o };
      out.parts.shellL = { angle: -1.15 * o };
      const buzz = band(c.fly, 0.5, 1) * 0.3 * Math.sin(t * 24);
      const vis = band(c.fly, 0.35, 0.8);
      out.parts.wingR = { angle: buzz, visible: vis };
      out.parts.wingL = { angle: -buzz, visible: vis };
    }

build:
build(k) {
      const ground = -0.62;
      const shellPart = k.part("shell", { pivot: [-0.12, ground, 0], axis: [0, 0, 1] });
      const skinCol = (c) => {
        const n = c.noise(c.p[0] * 30, c.p[1] * 30, c.p[2] * 30);
        const edge = c.p[1] < ground + 0.06 ? 0.3 : 0;
        return lit(c, mix(mix("#b0a07a", "#8a7a58", 0.5 + 0.5 * n), "#d8ccaa", edge), 0.35, 0.6);
      };
      const tok = (i) => ({ kind: "token", params: [i, 0] });
      // The foot: one long ellipsoid cut into eight slices across its
      // length (tokens 0 to 7). The front five slide back into the shell's
      // opening, the tail three forward under the shell.
      const cuts = [-0.9, -0.7, -0.5, -0.3, -0.08, 0.14, 0.36, 0.58, 0.9];
      const slices = cuts.slice(0, -1).map((x0, i) => ({ i, x: (x0 + cuts[i + 1]) / 2, front: x0 >= -0.3 })); // prettier-ignore
      const sliceOf = (x) => {
        let i = 0;
        while (i < slices.length - 1 && x > cuts[i + 1]) i++;
        return i;
      };
      const footC = [-0.05, ground + 0.1, 0];
      k.add(
        k.param(
          (u, v) => {
            const f = v * Math.PI;
            const w = u * TAU;
            return [0.85 * Math.cos(f), 0.12 * Math.sin(f) * Math.cos(w), 0.2 * Math.sin(f) * Math.sin(w)]; // prettier-ignore
          },
          {
            grid: 64,
            normal: (u, v) => {
              const f = v * Math.PI;
              const w = u * TAU;
              return vec.unit([Math.cos(f) / 0.85, (Math.sin(f) * Math.cos(w)) / 0.12, (Math.sin(f) * Math.sin(w)) / 0.2]); // prettier-ignore
            },
          },
        ),
        {
          pos: footC,
          flat: 0.2,
          kind: "token",
          params: (c) => [sliceOf(c.p[0]), 0],
          color: skinCol,
        },
      );
      // The head's way in: down the neck to the foot, then back along the
      // foot into the shell.
      const neckPts = [
        [0.3, ground + 0.12, 0],
        [0.62, ground + 0.18, 0],
        [0.82, ground + 0.36, 0],
        [0.9, ground + 0.5, 0],
      ];
      const neckCurve = spline(neckPts);
      const headC = [0.92, ground + 0.52, 0];
      const way = [headC];
      for (let j = 20; j >= 0; j--) way.push(neckCurve(j / 20));
      way.push([-0.1, ground + 0.1, 0], [-0.6, ground + 0.1, 0]);
      const path = polyPath(way);
      // Head (token 8) and four pieces of neck (tokens 9 to 12).
      const pieces = [{ i: 8, s: 0, x: headC[0], head: true }];
      for (let j = 0; j < 4; j++) {
        const p = neckCurve((3.5 - j) / 4);
        pieces.push({ i: 9 + j, s: path.near(p), x: p[0] });
      }
      k.add(
        k.tube(neckCurve, (t) => 0.14 - 0.03 * t, { grid: 32, samples: 64 }),
        {
          flat: 0.2,
          kind: "token",
          params: (c) => [9 + Math.min(3, Math.floor((1 - c.t) * 4)), 0],
          color: skinCol,
        },
      );
      k.add(k.sphere(0.12), { pos: headC, flat: 0.2, ...tok(8), color: skinCol });
      // The eye stalks, each in four pieces with its eye (tokens 13 to 22).
      const stalks = [];
      let next = 13;
      for (const sd of [-1, 1]) {
        k.add(
          k.tube(
            spline([
              [0.98, ground + 0.48, sd * 0.06],
              [1.08, ground + 0.44, sd * 0.12],
              [1.14, ground + 0.42, sd * 0.14],
            ]),
            (t) => 0.025 - 0.01 * t,
            { grid: 12, samples: 24, caps: true },
          ),
          { flat: 0.2, ...tok(8), color: skinCol },
        );
        const top = [1.08, ground + 0.98, sd * 0.16];
        const curve = spline([
          [0.94, ground + 0.6, sd * 0.05],
          [1.0, ground + 0.78, sd * 0.1],
          top,
        ]);
        const st = polyPath(Array.from({ length: 21 }, (_, j) => curve(j / 20)));
        const first = next;
        const stPieces = [0, 1, 2, 3].map((j) => ({
          i: first + j,
          a: (st.length * (j + 0.5)) / 4,
        }));
        stPieces.push({ i: first + 4, a: st.length });
        next += 5;
        k.add(
          k.tube(curve, (t) => 0.026 - 0.008 * t, { grid: 12, samples: 32 }),
          {
            flat: 0.2,
            kind: "token",
            params: (c) => [first + Math.min(3, Math.floor(c.t * 4)), 0],
            color: skinCol,
          },
        );
        // The eye (a shiny dark bead with a highlight).
        const L = vec.unit([1, 0.2, sd * 0.4]);
        const H = vec.unit(vec.add(L, [0.35, 0.55, 0.2]));
        k.add(k.sphere(0.036), {
          pos: top,
          weight: 3,
          flat: 0.3,
          pattern: false,
          ...tok(first + 4),
          color: (c) => (dot(c.ln, H) > 0.94 ? "#ffffff" : lit(c, "#0f0f12", 0.2)),
        });
        stalks.push({ at: st.at, pieces: stPieces, len: st.length });
      }
      const stalkLen = stalks[0].len;
      // How far each part travels to be inside.
      const headRun = path.length - 0.05;
      k.data = {
        snail: {
          slices,
          path: { at: path.at, pieces },
          stalks,
          stalkLen,
          headRun,
          frontRun: 1.15,
          tailRun: 0.62,
          mem: new WeakMap(),
        },
      };
      // A glistening trail.
      k.add(k.roundedBox(0.45, 0.01, 0.18, 4), {
        pos: [-0.95, ground + 0.005, 0],
        flat: 0.2,
        opacity: 0.35,
        pattern: false,
        color: (c) => mix("#dfe9f2", "#ffffff", Math.max(0, c.noise(c.p[0] * 20, 0, c.p[2] * 20))),
      });
      // The shell: a coiled tube, growing 2.4 times each turn.
      const b = Math.log(2.4) / TAU;
      const t1 = -Math.PI / 2 + 3 * TAU;
      const SR = 0.44;
      const cen = [-0.12, 0.02, 0];
      const rr = (t) => SR * Math.exp(b * (t - t1));
      const shellAt = (t, phi) => {
        const r = rr(t);
        const rho = 0.52 * r;
        const hh = 0.32 * (SR - r);
        const dir = [Math.cos(t), Math.sin(t), 0];
        return vec.add(
          cen,
          vec.add(vec.mul(dir, r + rho * Math.cos(phi)), [0, 0, hh + rho * Math.sin(phi)]),
        );
      };
      const tA = t1 - 3.2 * TAU;
      // The drawn-in body, seen deep in the opening once it hides.
      k.add(k.disc(0.2), {
        pos: [-0.24, cen[1] - SR, 0],
        rot: [0, 0, 90],
        part: shellPart,
        weight: 1.5,
        flat: 0.2,
        pattern: false,
        color: (c) => mix("#4a4032", "#6b5d45", 0.5 + 0.5 * c.noise(c.p[1] * 20, c.p[2] * 20, 0)),
      });
      k.add(
        k.param((u, v) => shellAt(tA + u * (t1 - tA), v * TAU), {
          grid: 110,
          normal: (u, v) => {
            const t = tA + u * (t1 - tA);
            const phi = v * TAU;
            return [Math.cos(phi) * Math.cos(t), Math.cos(phi) * Math.sin(t), Math.sin(phi)];
          },
        }),
        {
          part: shellPart,
          flat: 0.18,
          interior: 0.06,
          core: "#6a4a2a",
          color: (c) => {
            const t = tA + c.u * (t1 - tA);
            const phi = c.v * TAU;
            const bandz = fract((phi / TAU) * 3 + 0.1);
            let col = bandz < 0.35 ? "#8a5528" : bandz < 0.45 ? "#5a3418" : "#d9b77e";
            const growth = Math.abs(fract(t * 6) - 0.5) < 0.05;
            if (growth) col = shade(col, 0.85);
            if (t > t1 - 0.12) col = "#efe1c4";
            return lit(c, col, 0.35, 0.55);
          },
        },
      );
    }

drive:
drive(t, c, out, info) {
      const S = info?.data?.snail;
      if (!S) return;
      const h = clamp(c.hide, 0, 1);
      const R = S.stalkLen * easeInOut(band(h, 0, 0.3));
      const Dh = S.headRun * easeInOut(band(h, 0.14, 0.78));
      const Df = S.frontRun * easeInOut(band(h, 0.3, 0.9));
      const Dt = S.tailRun * easeInOut(band(h, 0.36, 0.9));
      const tokens = [];
      const hideFront = (x) => 1 - band(-x, 0.26, 0.36);
      for (const sl of S.slices) {
        const d = sl.front ? -Df : Dt;
        const x = sl.x + d;
        tokens[sl.i] = { offset: [d, 0, 0], visible: sl.front ? hideFront(x) : 1 - band(x, -0.36, -0.26) }; // prettier-ignore
      }
      let headOff = [0, 0, 0];
      for (const pc of S.path.pieces) {
        const off = vec.sub(S.path.at(pc.s + Dh), S.path.at(pc.s));
        if (pc.head) headOff = off;
        tokens[pc.i] = { offset: off, visible: hideFront(pc.x + off[0]) };
      }
      const stalkVis = band(S.stalkLen - R, 0, 0.05);
      for (const st of S.stalks)
        for (const pc of st.pieces) {
          const slide = vec.sub(st.at(Math.min(pc.a, S.stalkLen - R)), st.at(pc.a));
          tokens[pc.i] = { offset: vec.add(headOff, slide), visible: stalkVis * hideFront(0.9 + headOff[0]) }; // prettier-ignore
        }
      out.tokens = tokens;
      // The shell settles once the body is in, with a little rock.
      const sett = easeInOut(band(h, 0.78, 1));
      out.parts.shell = {
        offset: [0, -0.05 * sett, 0],
        angle: 0.05 * Math.sin(Math.PI * band(h, 0.7, 1)),
      };
      // Sorted again every sixteenth of the way, in or out.
      const m = S.mem.get(c) || { step: -1 };
      S.mem.set(c, m);
      const step = Math.round(h * 16);
      if (step !== m.step) {
        if (m.step >= 0) out.resort = true;
        m.step = step;
      }
      out.amount = 1;
    }

build:
build(k, o) {
      const skin = { coral: "#ec5b4d", purple: "#9a5ad8", orange: "#f28a2e", teal: "#2fb3a6" }[
        o.color
      ];
      const pale = mix(skin, "#fff4e8", 0.55);
      const ground = -0.45;
      const skinCol = (c) => {
        const n = c.noise(c.p[0] * 16, c.p[1] * 16, c.p[2] * 16);
        let col = shade(skin, 0.92 + 0.12 * n);
        if (n > 0.45) col = mix(col, pale, 0.5);
        return lit(c, col, 0.35, 0.4);
      };
      // Mantle and head.
      const octo = k.part("octo", { pivot: [0, 0.2, 0] });
      k.add(evenEllipsoid(k, 0.44, 0.5, 0.44), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        part: octo,
        pos: [0, 0.4, -0.1],
        rot: [-18, 0, 0],
        flat: 0.2,
        interior: 0.08,
        core: shade(skin, 0.7),
        kind: "breathe",
        params: [0.03, 0],
        color: skinCol,
      });
      k.add(evenEllipsoid(k, 0.36, 0.28, 0.32), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        part: octo,
        pos: [0, 0.08, 0.08],
        flat: 0.2,
        kind: "breathe",
        params: [0.03, 0],
        color: (c) => {
          const cheek =
            c.lp[2] > 0.15 &&
            Math.abs(Math.abs(c.lp[0]) - 0.22) < 0.07 &&
            Math.abs(c.lp[1] + 0.06) < 0.05;
          return cheek ? keep(mix(skin, "#ff9aa8", 0.6)) : skinCol(c);
        },
      });
      for (const s of [-1, 1]) {
        eye(k, [s * 0.14, 0.14, 0.33], 0.1, [s * 0.15, 0.05, 1], {
          part: octo,
          white: "#fbfbf8",
          pupil: 0.75,
          irisEdge: 0.6,
          iris: "#141418",
        });
      }
      // Eight arms that curl up at the tips and sway.
      for (let i = 0; i < 8; i++) {
        const a = (i / 8) * TAU + TAU / 16;
        const d = [Math.sin(a), 0, Math.cos(a)];
        const P = (r, y) => [d[0] * r, y, d[2] * r];
        const curl = spline([
          P(0.1, 0.0),
          P(0.34, ground + 0.12),
          P(0.62, ground + 0.04),
          P(0.86, ground + 0.08),
          P(1.0, ground + 0.26),
          P(0.94, ground + 0.4),
          P(0.84, ground + 0.34),
        ]);
        const arm = k.part(`a${i}`, { pivot: P(0.1, 0), axis: [d[2], 0, -d[0]] });
        k.add(
          evenTube(k, curl, (t) => 0.1 * (1 - t) + 0.018, { grid: 32, samples: 96, caps: true }),
          {
            even: true,
            opacity: 1,
            jitter: 0.015,
            part: arm,
            flat: 0.2,
            kind: "sway",
            params: [0.25, ground + 0.1],
            color: (c) => {
              const under = dot(c.n, [0, -1, 0]) + 0.3 * dot(c.n, [-d[0], 0, -d[2]]);
              if (under > 0.35 && fract(c.t * 20) < 0.55) return keep(lit(c, "#fde7df", 0.25));
              return skinCol(c);
            },
          },
        );
      }
      // A cloud of ink behind, hidden until squirted: lumpy billows that
      // spread out from the siphon as it grows.
      const ink = k.part("ink", { pivot: [0, 0.1, -0.45] });
      const siphon = [0, 0.05, -0.4];
      const lumps = [];
      for (let i = 0; i < 12; i++) {
        const a = -1.7 + (i / 11) * 3.4 + (k.rand() - 0.5) * 0.3;
        const r = 0.3 + 0.35 * k.rand();
        lumps.push({
          c: [Math.sin(a) * r * 1.6, 0.1 + (k.rand() - 0.3) * 0.7, -0.35 - Math.cos(a) * r * 0.8],
          r: 0.22 + 0.16 * k.rand(),
        });
      }
      k.cloud({ share: 0.1, size: 3, pattern: false }, (rand, i) => {
        const L = lumps[i % lumps.length];
        const d = vec.unit([rand() - 0.5, rand() - 0.5, rand() - 0.5]);
        const p = vec.add(L.c, vec.mul(d, L.r * Math.cbrt(rand())));
        p[2] = Math.max(p[2], -1);
        const far = Math.min(1, vec.len(vec.sub(p, siphon)) / 0.95);
        return {
          p,
          color: mix("#1a1428", "#5a4a70", rand() * (0.3 + 0.7 * far)),
          opacity: 0.7,
          part: ink,
          kind: "grow",
          params: [far * 0.9, 0],
        };
      });
      k.reach([0, 1.2, -0.6]);
    }

drive:
drive(t, c, out) {
      // A big cloud of ink billows out behind while the octopus jets up and
      // away with its arms streaming, then it drifts back as the ink thins.
      const e = (1 - c.ink) * 4.5;
      const on = c.ink > 0;
      const jet = on
        ? (1 - (1 - band(e, 0.05, 0.55)) ** 3) * (1 - easeInOut(band(e, 1.3, 3.6)))
        : 0;
      const trail = on ? easeInOut(band(e, 0.05, 0.35)) * (1 - easeInOut(band(e, 0.9, 2.6))) : 0;
      const off = [0.12 * jet, 0.3 * jet, 0.06 * jet];
      out.parts.octo = { offset: off };
      for (let i = 0; i < 8; i++)
        out.parts[`a${i}`] = { offset: off, angle: 0.55 * trail * (1 + 0.15 * Math.sin(i * 2.1)) };
      out.grow = on ? 1 - (1 - band(e, 0.05, 1.3)) ** 2 : 0;
      out.parts.ink = {
        offset: [0, 0.18 * easeInOut(band(e, 0.4, 4.5)), 0],
        visible: on ? (1 + 0.35 * band(e, 0.2, 2)) * (1 - easeInOut(band(e, 2.8, 4.5))) : 0,
      };
      out.amount = 1;
    }

build:
build(k, o) {
      const base = { orange: "#f07a2a", red: "#d8392f", purple: "#8c4fcb", blue: "#2f7fd8" }[
        o.color
      ];
      const R0 = 0.24;
      const Rt = 1;
      const outline = (a) => R0 + (Rt - R0) * Math.pow(Math.abs(Math.cos(2.5 * a)), 1.35);
      const height = (rho) => 0.2 * Math.pow(Math.max(0, 1 - Math.pow(rho, 1.7)), 0.55);
      const top = (a, r) => {
        const R = outline(a);
        return height(r / R) * (1 - 0.35 * (r / Rt));
      };
      const surf = (a0, a1, r0, top1) =>
        k.param(
          (u, v) => {
            const a = a0 + u * (a1 - a0);
            const R = outline(a);
            const r = r0 + v * Math.max(0, R - r0);
            const h = top(a, r);
            return [Math.sin(a) * r, top1 ? h : -0.3 * h, Math.cos(a) * r];
          },
          { grid: 40, flip: top1 },
        );
      const tub = (c) => {
        const n = c.noise(c.p[0] * 34, c.p[1] * 34, c.p[2] * 34);
        return n > 0.5;
      };
      const color = (c) => {
        if (c.n[1] < 0) return lit(c, mix(base, "#fff0dc", 0.55), 0.2);
        const r = Math.hypot(c.p[0], c.p[2]);
        let col = mix(shade(base, 0.8), mix(base, "#ffd9a8", 0.15), band(r, 0, 1));
        const mottle = c.noise(c.p[0] * 9 + 2, c.p[1] * 9, c.p[2] * 9);
        col = shade(col, 0.92 + 0.12 * mottle);
        if (tub(c)) col = mix(col, "#ffe8c8", 0.4);
        return lit(c, col, 0.45, 0.25);
      };
      k.add(surf(0, TAU, 0, true), { flat: 0.2, color, scale: [1, 1, 1] });
      k.add(surf(0, TAU, 0, false), { flat: 0.2, color });
      for (let i = 0; i < 5; i++) {
        const a = (i / 5) * TAU;
        const part = k.part(`arm${i}`, {
          pivot: [Math.sin(a) * 0.3, 0, Math.cos(a) * 0.3],
          axis: [Math.cos(a), 0, -Math.sin(a)],
        });
        const s = TAU / 10;
        k.add(surf(a - s, a + s, 0.3, true), { part, flat: 0.2, color });
        k.add(surf(a - s, a + s, 0.3, false), { part, flat: 0.2, color });
        // Bumps along the arm.
        for (let j = 0; j < 7; j++) {
          const r = 0.34 + j * 0.09;
          for (const off of [-0.05, 0, 0.05]) {
            const aa = a + off / r;
            const h = top(aa, r);
            if (h < 0.02) continue;
            k.add(k.sphere(0.022 - j * 0.0015), {
              pos: [Math.sin(aa) * r, h + 0.005, Math.cos(aa) * r],
              part,
              weight: 3,
              color: (c) => lit(c, mix(base, "#fff0d0", 0.6), 0.3),
            });
          }
        }
      }
      k.add(k.sphere(0.03), {
        pos: [0.06, top(0.3, 0.07) + 0.01, 0.04],
        weight: 3,
        color: (c) => lit(c, mix(base, "#ffe38a", 0.6), 0.3),
      });
    }

drive:
drive(t, c, out) {
      const u = 1 - c.wave;
      for (let i = 0; i < 5; i++) {
        const w = c.wave > 0 ? Math.sin(Math.PI * band(u * 1.6 - i * 0.12, 0, 0.6)) : 0;
        out.parts[`arm${i}`] = { angle: -0.05 * (1 + Math.sin(t * 0.9 + i * 1.3)) - 0.55 * w };
      }
    }

build:
build(k, o) {
      const pal = {
        purple: ["#4a1f6a", "#b46ad8"],
        black: ["#141218", "#5a4a6a"],
        red: ["#8a1c22", "#ff7a5a"],
        green: ["#2f5a2a", "#b8d86a"],
      }[o.color];
      const E = [0.5, 0.36, 0.5];
      const cy = -0.25;
      const onTest = (d) => {
        const r = 1 / Math.hypot(d[0] / E[0], d[1] / E[1], d[2] / E[2]);
        return [d[0] * r, cy + d[1] * r, d[2] * r];
      };
      k.add(k.ellipsoid(...E), {
        pos: [0, cy, 0],
        flat: 0.2,
        interior: 0.14,
        core: (c) => mix("#f0a030", "#d0701a", c.rand()),
        color: (c) => {
          const a = Math.atan2(c.lp[0], c.lp[2]) / TAU;
          const row = Math.abs(fract(a * 5) - 0.5) < 0.07;
          const dotRow = row && fract(c.lp[1] * 30) < 0.5;
          return lit(c, dotRow ? pal[1] : mix(pal[0], pal[1], 0.2), 0.35);
        },
      });
      // Spines: streaks radiating from the shell.
      const spines = [];
      const n = 460;
      const g = Math.PI * (3 - Math.sqrt(5));
      for (let i = 0; i < n; i++) {
        const y = 1 - ((i + 0.5) / n) * 2;
        if (y < -0.45) continue;
        const rr = Math.sqrt(1 - y * y);
        const d = [Math.cos(g * i) * rr, y, Math.sin(g * i) * rr];
        const dir = vec.unit(vec.add(d, [(k.rand() - 0.5) * 0.15, 0.1, (k.rand() - 0.5) * 0.15]));
        spines.push({
          base: onTest(d),
          dir,
          len: 0.42 + 0.22 * k.rand() * (1 - 0.4 * Math.abs(y)),
        });
      }
      // Each spine tilts sideways (round the urchin) on its base by one of
      // channels 0 to 2, picked by its sector, so the spine stays straight.
      // (The tilted tips stay within the urchin's reach, so they are left
      // out of the fit.)
      k.fitMorphs = false;
      for (const sp of spines) {
        const a = Math.atan2(sp.base[0], sp.base[2]);
        sp.side = [Math.cos(a), 0, -Math.sin(a)];
        sp.tilt = vec.unit(vec.add(vec.mul(sp.dir, Math.cos(0.6)), vec.mul(sp.side, Math.sin(0.6)))); // prettier-ignore
        sp.ch = Math.floor((a / TAU + 0.5) * 12) % 3;
      }
      k.cloud({ share: 0.55, size: 0.55 }, (rand, i) => {
        const s = spines[i % spines.length];
        const t = rand();
        return {
          p: vec.add(s.base, vec.mul(s.dir, t * s.len)),
          dir: s.dir,
          stretch: 3,
          size: 1.2 - 0.8 * t,
          color: mix(pal[0], pal[1], t * t),
          kind: "morph",
          channel: s.ch,
          to: vec.add(s.base, vec.mul(s.tilt, t * s.len)),
        };
      });
      // Little pink tube feet between the spines: they reach out on
      // channel 3.
      k.cloud({ share: 0.02, size: 0.5 }, (rand) => {
        const d = vec.unit([rand() - 0.5, rand() * 0.9 - 0.3, rand() - 0.5]);
        const p = vec.add(onTest(d), vec.mul(d, 0.02));
        return {
          p,
          color: "#f7a8c8",
          pattern: false,
          kind: "morph",
          channel: 3,
          to: vec.add(p, vec.mul(d, 0.05 + 0.05 * rand())),
        };
      });
    }

drive:
drive(t, c, out, info) {
      // The spines sweep round in waves (each tilts on its base, by one of
      // three channels a third of a cycle apart, so the wave runs round the
      // urchin), the pink tube feet reach out, and it creeps a little way
      // to the side and back.
      const on = c.walk > 0;
      const s = progress(c.walk) * 4.6;
      const amp = on ? easeInOut(band(s, 0, 0.5)) * (1 - easeInOut(band(s, 3.6, 4.5))) : 0;
      const ph = s * TAU * 1.1;
      out.morph = [0, 1, 2].map((j) => amp * Math.sin(ph - (j * TAU) / 3));
      out.morph.push(amp);
      out.body = { offset: vec.mul([0.85, 0, -0.52], 0.15 * Math.sin(Math.PI * (on ? band(s, 0.2, 4.4) : 0))) }; // prettier-ignore
    }

build:
build(k, o) {
      const skin = { green: "#58b83a", red: "#e8452a", blue: "#2f7fe0", yellow: "#f2c52a" }[
        o.color
      ];
      const spot = { green: "#2f7a22", red: "#1a1a1a", blue: "#101830", yellow: "#1a1a1a" }[
        o.color
      ];
      const belly = "#f4ecbc";
      const breathe = { kind: "breathe", params: [0.012, 0] };
      const skinCol = (c, bellyTest) => {
        if (bellyTest && bellyTest(c)) return lit(c, belly, 0.3, 0.3);
        const n = c.noise(c.p[0] * 7 + 5, c.p[1] * 7, c.p[2] * 7);
        return lit(c, n > 0.38 && c.p[1] > -0.3 ? spot : skin, 0.35, 0.45);
      };
      k.add(k.ellipsoid(0.5, 0.42, 0.56), {
        pos: [0, -0.2, -0.1],
        rot: [-22, 0, 0],
        flat: 0.2,
        interior: 0.1,
        core: "#c9e0a0",
        ...breathe,
        color: (c) => skinCol(c, (cc) => cc.lp[2] > 0.25 && cc.lp[1] < 0.05),
      });
      // The head; below its smile the front is the lower jaw (a part hinged
      // at the back of the mouth).
      const jaw = k.part("jaw", { pivot: FROG.hinge, axis: [1, 0, 0] });
      const smileAt = (x) => -0.06 + 0.1 * (x / 0.46) ** 2;
      k.add(k.ellipsoid(0.46, 0.28, 0.4), {
        pos: [0, 0.14, 0.22],
        flat: 0.2,
        ...breathe,
        part: (c) => (c.lp[1] < smileAt(c.lp[0]) - 0.012 && c.lp[2] > -0.12 ? jaw : 0),
        color: (c) => {
          const l = c.lp;
          const smile = smileAt(l[0]);
          if (l[2] > 0.1 && Math.abs(l[1] - smile) < 0.012 && Math.abs(l[0]) < 0.36)
            return keep("#2a1a14");
          if (l[2] > 0.3 && l[1] > 0.02 && l[1] < 0.07 && Math.abs(Math.abs(l[0]) - 0.07) < 0.015)
            return keep("#1d2a14");
          if (l[2] > 0.05 && Math.abs(Math.abs(l[0]) - 0.3) < 0.07 && Math.abs(l[1] + 0.02) < 0.05)
            return keep(mix(skin, "#ff8fa0", 0.55));
          return skinCol(c, (cc) => cc.lp[1] < smile - 0.01 && cc.lp[2] > 0.0);
        },
      });
      // Inside the mouth (hidden while it is shut): the palate, the floor
      // and the tongue, which shoots out to the fly on channel 0 (built at
      // its full reach, with the jaw open).
      k.add(k.disc(1), {
        pos: [0, 0.114, 0.25],
        scale: [0.42, 1, 0.34],
        flat: 0.3,
        pattern: false,
        color: (c) => mix("#6e1c28", "#8e2a36", c.rand()),
      });
      k.add(k.disc(1), {
        part: jaw,
        pos: [0, 0.1, 0.25],
        scale: [0.41, 1, 0.33],
        flat: 0.3,
        pattern: false,
        color: (c) => mix("#b8404f", "#c9566a", c.rand()),
      });
      k.fitMorphs = false;
      const tongueR = (t) => 0.032 + 0.028 * smoothstep(0.82, 1, t);
      const axis = vec.sub(FROG.tipFull, FROG.tipRest);
      const ax = vec.unit(axis);
      const e1 = vec.unit(vec.cross(ax, [0, 1, 0]));
      const e2 = vec.cross(e1, ax);
      k.cloud({ share: 0.012, size: 1.1, pattern: false, part: jaw }, (rand) => {
        const t = Math.sqrt(rand());
        const a = rand() * TAU;
        const rr = [Math.cos(a), Math.sin(a)];
        const n = vec.add(vec.mul(e1, rr[0]), vec.mul(e2, rr[1]));
        const full = vec.add(vec.add(FROG.tipRest, vec.mul(axis, t)), vec.mul(n, tongueR(t)));
        const rest = vec.add(vec.add(FROG.tipRest, vec.mul(ax, 0.07 * t)), vec.mul(n, 0.8 * tongueR(t))); // prettier-ignore
        const light = 0.8 + 0.3 * Math.max(0, dot(n, LIGHT));
        return {
          p: rest,
          n,
          color: shade(mix("#e2677e", "#f28aa0", rand() * 0.5), light),
          kind: "morph",
          channel: 0,
          to: full,
        };
      });
      // The fly, built where the tongue catches it.
      // The fly (hidden at rest), built within the frog's own bounds (so it
      // takes no room in the frame) and carried out to where it is caught.
      const fly = k.part("fly", { pivot: FROG.flyBuilt });
      const F = { part: fly, weight: 12, flat: 0.3, pattern: false };
      const at = (p) => vec.add(FROG.flyBuilt, p);
      k.add(k.ellipsoid(0.045, 0.034, 0.058), { ...F, pos: FROG.flyBuilt, color: (c) => lit(c, "#2c2c34", 0.4, 0.5) }); // prettier-ignore
      k.add(k.sphere(0.03), { ...F, pos: at([0, 0.006, 0.058]), color: "#9a2424" });
      for (const sx of [-1, 1])
        k.add(k.ellipsoid(0.07, 0.006, 0.034), {
          ...F,
          pos: at([sx * 0.06, 0.036, -0.015]),
          rot: [0, sx * 25, sx * 18],
          opacity: 0.65,
          color: "#e2ecf4",
        });
      // The throat sac that blows up for a croak (hidden at rest).
      const sac = k.part("sac", { pivot: [0, -0.02, 0.42] });
      k.add(k.sphere(0.15), {
        part: sac,
        pos: [0, -0.07, 0.44],
        flat: 0.3,
        pattern: false,
        color: (c) => lit(c, "#f6efc8", 0.3, 0.6),
      });
      const eyes = k.part("eyes", { pivot: [0, 0.35, 0.22] });
      for (const s of [-1, 1]) {
        k.add(k.sphere(0.15), {
          part: eyes,
          pos: [s * 0.24, 0.34, 0.2],
          flat: 0.2,
          ...breathe,
          color: (c) => skinCol(c),
        });
        eye(k, [s * 0.25, 0.37, 0.28], 0.12, [s * 0.35, 0.15, 1], {
          part: eyes,
          iris: "#e8b020",
          white: "#e8b020",
          pupil: 0.86,
          irisEdge: -1,
        });
        // Front legs with little toes.
        k.add(rod(k, [s * 0.26, -0.12, 0.26], [s * 0.32, -0.56, 0.4], 0.065, { caps: true }), {
          flat: 0.2,
          color: (c) => skinCol(c),
        });
        for (let j = -1; j <= 1; j++) {
          const a = s * 0.35 + j * 0.45;
          k.add(k.sphere(0.035), {
            pos: [s * 0.32 + Math.sin(a) * 0.1, -0.6, 0.44 + Math.cos(a) * 0.1],
            weight: 2,
            color: (c) => lit(c, skin, 0.3),
          });
        }
        // Folded back legs and webbed feet.
        k.add(k.ellipsoid(0.2, 0.17, 0.32), {
          pos: [s * 0.42, -0.42, -0.12],
          rot: [-10, s * 20, 0],
          flat: 0.2,
          color: (c) => skinCol(c),
        });
        k.add(k.ellipsoid(0.13, 0.03, 0.2), {
          pos: [s * 0.5, -0.6, 0.18],
          rot: [0, s * -25, 0],
          flat: 0.2,
          color: (c) => lit(c, shade(skin, 0.9), 0.3),
        });
        for (let j = -1; j <= 1; j++) {
          const a = s * -0.4 + j * 0.4;
          k.add(k.sphere(0.035), {
            pos: [s * 0.5 + Math.sin(a) * 0.2, -0.6, 0.18 + Math.cos(a) * 0.2],
            weight: 2,
            color: (c) => lit(c, skin, 0.3),
          });
        }
      }
    }

drive:
drive(t, c, out) {
      // A fly buzzes in and hovers. The frog's jaw drops, its tongue shoots
      // out (channel 0), catches the fly and snaps back into the mouth; the
      // jaw shuts, the eyes sink to push the fly down (frogs swallow with
      // their eyes), and it croaks twice with its throat sac.
      const on = c.snap > 0;
      const s = progress(c.snap) * FROG.secs;
      const jaw = on ? FROG.open * easeOut(band(s, 0.92, 1.02)) * (1 - easeInOut(band(s, 1.62, 1.78))) : 0; // prettier-ignore
      const tongue = on ? easeOut(band(s, 1.0, 1.1)) * (1 - easeInOut(band(s, 1.34, 1.6))) : 0;
      out.parts.jaw = { angle: jaw };
      out.morph = [tongue];
      // The fly: in from the right on a wobbly path, a hover, then carried
      // on the tongue's tip into the mouth.
      let fp;
      if (s < 1.1) {
        const u = easeOut(band(s, 0, 0.95));
        const w = 1 - u;
        fp = vec.add(vec.add(FROG.catch, vec.mul(FROG.from, w)), [
          0.06 * Math.sin(s * 17) * (0.3 + w),
          0.05 * Math.sin(s * 23 + 1) * (0.3 + w),
          0.03 * Math.sin(s * 13),
        ]);
      } else {
        const tip = vec.add(FROG.tipRest, vec.mul(vec.sub(FROG.tipFull, FROG.tipRest), tongue));
        fp = vec.add(FROG.hinge, quatRotate(quatAxisAngle([1, 0, 0], jaw), vec.sub(tip, FROG.hinge))); // prettier-ignore
      }
      out.parts.fly = {
        offset: vec.sub(fp, FROG.flyBuilt),
        quat: quatAxisAngle([0, 1, 0], 0.4 * Math.sin(s * 9)),
        visible: on && s < 1.58 ? 1 : 0,
      };
      out.parts.eyes = { offset: [0, -0.065 * (on ? band(s, 1.8, 2.0) * (1 - band(s, 2.2, 2.45)) : 0), 0] }; // prettier-ignore
      const croak = (a) => Math.sin(Math.PI * band(s, a, a + 0.36));
      const sac = on ? Math.max(croak(2.55), croak(3.05)) : 0;
      out.parts.sac = { scale: 0.2 + 0.8 * sac, visible: sac > 0.01 ? 1 : 0 };
    }

build:
build(k) {
      const black = "#1e2230";
      const prof = [
        [0, -0.88],
        [0.36, -0.85],
        [0.5, -0.62],
        [0.53, -0.3],
        [0.48, 0.05],
        [0.4, 0.34],
        [0.35, 0.52],
        [0.32, 0.7],
        [0.2, 0.87],
        [0, 0.92],
      ];
      k.add(k.lathe(prof, { grid: 80 }), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        flat: 0.2,
        interior: 0.08,
        core: "#c8c8c8",
        kind: "breathe",
        params: [0.01, 0],
        color: (c) => {
          const [x, y, z] = c.p;
          const a = Math.atan2(x, z);
          const belly =
            y < 0.5 &&
            Math.abs(a) < (1.05 - 0.4 * band(y, 0.2, 0.5)) * (0.95 + 0.05 * Math.cos(y * 6));
          const face =
            y > 0.5 &&
            z > 0 &&
            (Math.hypot(x - 0.1, y - 0.64) < 0.1 || Math.hypot(x + 0.1, y - 0.64) < 0.1);
          if (belly || face) return lit(c, "#f7f7f4", 0.3, 0.2);
          if (
            Math.hypot(
              (Math.abs(a) - 1.3) / 0.3,
              (y - 0.5) / (0.07 + 0.1 * band(Math.abs(a), 1.0, 1.6)),
            ) < 1
          )
            return lit(c, mix("#ffd23a", "#ff9a2a", band(y, 0.36, 0.56)), 0.3);
          return lit(c, black, 0.3, 0.35);
        },
      });
      for (const s of [-1, 1]) {
        eye(k, [s * 0.1, 0.65, 0.29], 0.04, [s * 0.3, 0.1, 1], { pupil: -1, weight: 3 });
        k.add(k.sphere(0.045), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [s * 0.2, 0.55, 0.28],
          scale: [1, 0.6, 0.4],
          weight: 2,
          pattern: false,
          color: "#ffadb8",
        });
        const flip = k.part(s > 0 ? "flipR" : "flipL", {
          pivot: [s * 0.42, 0.28, 0],
          axis: [0, 0, 1],
        });
        k.add(k.ellipsoid(0.06, 0.34, 0.16), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [s * 0.5, -0.02, 0],
          rot: [0, 0, s * 12],
          part: flip,
          flat: 0.2,
          color: (c) => lit(c, c.n[0] * s < -0.2 ? "#f4f4f0" : black, 0.3, 0.3),
        });
        k.add(k.ellipsoid(0.14, 0.05, 0.22), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [s * 0.18, -0.88, 0.14],
          rot: [0, s * -12, 0],
          flat: 0.2,
          pattern: false,
          color: (c) => lit(c, "#f28c28", 0.3),
        });
      }
      k.add(k.cone(0.075, 0.0, 0.2), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [0, 0.56, 0.38],
        rot: [80, 0, 0],
        weight: 2,
        pattern: false,
        color: (c) => lit(c, c.lp[1] < -0.02 ? "#e0701a" : "#f7a030", 0.3, 0.3),
      });
    }

drive:
drive(t, c, out) {
      const u = 1 - c.flap;
      const f = c.flap > 0 ? Math.abs(Math.sin(u * Math.PI * 6)) * (1 - u) : 0;
      const idle = 0.04 * Math.sin(t * 1.4);
      out.parts.flipR = { angle: 0.12 + idle + 0.9 * f };
      out.parts.flipL = { angle: -0.12 - idle - 0.9 * f };
    }

build:
build(k) {
      const brown = "#8a5a34";
      const cream = "#efdcb4";
      const feathers = (c, base) => {
        const a = Math.atan2(c.p[0], c.p[2]);
        const row = Math.floor(c.p[1] * 14);
        const cu = fract((a / TAU) * 26 + (row % 2 ? 0.5 : 0));
        const cy = fract(c.p[1] * 14);
        const e = Math.hypot((cu - 0.5) * 2, cy);
        return shade(base, e > 0.9 ? 0.72 : 0.95 + 0.1 * (1 - e));
      };
      k.add(
        k.lathe(
          [
            [0, -0.72],
            [0.34, -0.68],
            [0.48, -0.45],
            [0.5, -0.1],
            [0.45, 0.14],
            [0.36, 0.3],
            [0, 0.34],
          ],
          { grid: 72 },
        ),
        {
          even: true,
          opacity: 1,
          jitter: 0.015,
          flat: 0.2,
          interior: 0.08,
          core: "#b88a5a",
          color: (c) => {
            const a = Math.atan2(c.p[0], c.p[2]);
            if (Math.abs(a) < 0.75) {
              const chev = Math.abs(fract(c.p[1] * 7 + Math.abs(c.p[0]) * 2) - 0.5) < 0.07;
              return lit(c, chev ? "#9a6a40" : cream, 0.3);
            }
            return lit(c, feathers(c, brown), 0.35);
          },
        },
      );
      for (const s of [-1, 1]) {
        k.add(k.ellipsoid(0.14, 0.4, 0.3), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [s * 0.42, -0.14, -0.06],
          rot: [8, 0, s * -8],
          flat: 0.2,
          color: (c) => lit(c, fract(c.p[1] * 9 + c.p[2] * 3) < 0.25 ? "#5a3a20" : "#7a4e2c", 0.35),
        });
        for (let j = -1; j <= 1; j++)
          k.add(k.cylinder(0.025, 0.12), {
            even: true,
            opacity: 1,
            jitter: 0.015,
            pos: [s * 0.16 + j * 0.05, -0.74, 0.14],
            rot: [70, 0, 0],
            weight: 2,
            pattern: false,
            color: (c) => lit(c, "#e8a830", 0.3),
          });
      }
      // The branch.
      k.add(rod(k, [-0.95, -0.8, 0.12], [0.95, -0.84, 0.04], 0.075, { caps: true }), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        flat: 0.2,
        color: (c) =>
          lit(
            c,
            mix("#5a3a22", "#7a5434", 0.5 + 0.5 * c.noise(c.p[0] * 12, c.t * 40, c.p[2] * 12)),
            0.35,
          ),
      });
      for (const [x, z, r] of [
        [-0.82, 0.22, 30],
        [0.86, 0.14, -30],
        [0.7, -0.05, -60],
      ])
        k.add(k.ellipsoid(0.12, 0.012, 0.06), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [x, -0.74, z],
          rot: [0, r, 15],
          weight: 2,
          color: (c) => lit(c, "#5aa03a", 0.35),
        });
      // The head: it turns.
      const head = k.part("head", { pivot: [0, 0.3, 0], axis: [0, 1, 0] });
      const lids = k.part("lids", { pivot: [0, 0.3, 0], axis: [0, 1, 0] });
      const eyes = [
        [-0.15, 0.52, 0.34],
        [0.15, 0.52, 0.34],
      ];
      k.add(k.ellipsoid(0.44, 0.38, 0.4), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [0, 0.52, 0.02],
        part: head,
        flat: 0.2,
        color: (c) => {
          const [x, y, z] = c.p;
          if (z > 0.1) {
            const d = Math.min(Math.hypot(x - 0.15, y - 0.52), Math.hypot(x + 0.15, y - 0.52));
            if (d < 0.19)
              return lit(c, d > 0.16 ? "#6a4424" : mix("#f6e6c8", cream, d / 0.19), 0.25);
          }
          return lit(c, feathers(c, brown), 0.35);
        },
      });
      for (const e of eyes) {
        eye(k, e, 0.1, [e[0] * 0.8, 0, 1], {
          part: head,
          iris: "#f5a623",
          white: "#f5a623",
          pupil: 0.8,
          irisEdge: -1,
        });
        k.add(k.sphere(0.106), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: e,
          part: lids,
          weight: 2,
          pattern: false,
          color: (c) => lit(c, "#c8a070", 0.3),
        });
      }
      k.add(k.cone(0.05, 0, 0.12), {
        opacity: 1,
        jitter: 0.015,
        pos: [0, 0.42, 0.42],
        rot: [150, 0, 0],
        part: head,
        weight: 3,
        pattern: false,
        color: (c) => lit(c, "#4a4038", 0.3, 0.4),
      });
      for (const s of [-1, 1])
        k.add(k.cone(0.09, 0.0, 0.24), {
          opacity: 1,
          jitter: 0.015,
          pos: [s * 0.24, 0.86, 0],
          rot: [0, 0, s * -25],
          part: head,
          flat: 0.2,
          color: (c) => lit(c, feathers(c, "#7a4e2c"), 0.35),
        });
    }

drive:
drive(t, c, out) {
      const u = 1 - c.turn;
      const turn =
        c.turn > 0 ? 1.7 * easeInOut(band(u, 0, 0.22)) * (1 - easeInOut(band(u, 0.62, 0.95))) : 0;
      const q = quatMul(
        quatAxisAngle([0, 1, 0], turn),
        quatAxisAngle([0, 0, 1], 0.06 * Math.sin(t * 0.7)),
      );
      out.parts.head = { quat: q };
      const ph = fract(t / 4.2);
      out.parts.lids = { quat: q, visible: Math.exp(-(((ph - 0.5) / 0.018) ** 2)) };
    }

build:
build(k) {
      const face = 0.3; // the face looks a little towards the viewer
      const S = [1, 0.78, 1];
      const rib = (phi) => 1 - 0.08 * Math.pow(1 - Math.abs(Math.cos(phi * 5)), 1.4);
      const R = (phi, e) => rib(phi) * (1 - 0.3 * Math.max(0, Math.abs(Math.sin(e)) - 0.82));
      const P = (phi, e, s = 1) => {
        const r = R(phi, e) * s;
        return [
          Math.cos(e) * Math.sin(phi) * r * S[0],
          Math.sin(e) * r * S[1],
          Math.cos(e) * Math.cos(phi) * r * S[2],
        ];
      };
      const zig = (x) => Math.abs(fract(x) - 0.5) * 4 - 1;
      const cutE = (phi) => 0.95 + 0.06 * zig((phi / TAU) * 12);
      // The carved face, in (angle, elevation) around the face centre.
      const tri = (X, Y, cx, cy, w, h, g) => {
        const y0 = cy - h / 2 - g;
        const yy = Y - y0;
        return yy > 0 && yy < h + 2 * g && Math.abs(X - cx) < (w / 2 + g) * (1 - yy / (h + 2 * g));
      };
      const carved = (X, Y, g) => {
        if (tri(X, Y, -0.36, 0.26, 0.34, 0.28, g) || tri(X, Y, 0.36, 0.26, 0.34, 0.28, g))
          return true;
        if (tri(X, Y, 0, 0.0, 0.16, 0.14, g)) return true;
        if (Math.abs(X) > 0.66 + g) return false;
        const lo = -0.46 + 0.36 * X * X - g;
        const hi = -0.26 + 0.5 * X * X + g;
        if (Y < lo || Y > hi) return false;
        if (g === 0) {
          if (X > -0.22 && X < -0.08 && Y > hi - 0.09) return false;
          if (X > 0.1 && X < 0.24 && Y < lo + 0.09) return false;
        }
        return true;
      };
      const faceXY = (p) => {
        const phi = Math.atan2(p[0], p[2]) - face;
        const e = Math.asin(clamp(p[1] / (S[1] * Math.hypot(p[0], p[1] / S[1], p[2]) || 1), -1, 1));
        return [Math.atan2(Math.sin(phi), Math.cos(phi)), e];
      };
      const skin = (c) => {
        const phi = Math.atan2(c.p[0], c.p[2]);
        const groove = Math.pow(1 - Math.abs(Math.cos(phi * 5)), 3);
        const n = c.fbm(c.p[0] * 5, c.p[1] * 5, c.p[2] * 5, 2);
        let col = mix("#ee7a12", "#b84a08", 0.7 * groove + 0.2 * n);
        col = mix(col, "#ffb04a", 0.25 * Math.max(0, 1 - groove * 3) * (0.5 + 0.5 * c.n[1]));
        return lit(c, col, 0.35, 0.3);
      };
      // Body, with the face cut out and a band of flesh round each hole.
      k.add(
        k.param(
          (u, v) => {
            const phi = u * TAU;
            return P(phi, -Math.PI / 2 + v * (cutE(phi) + Math.PI / 2));
          },
          { grid: 96 },
        ),
        {
          flat: 0.2,
          color: (c) => {
            const [X, Y] = faceXY(c.p);
            if (Math.abs(X) < 1.2) {
              if (carved(X, Y, 0)) return null;
              if (carved(X, Y, 0.035)) return keep(lit(c, "#c8701e", 0.2));
            }
            return skin(c);
          },
        },
      );
      // The inside glows: warmest near the candle, flickering.
      k.add(
        k.param((u, v) => P(u * TAU, -Math.PI / 2 + v * (Math.PI / 2 + 0.95), 0.9), {
          grid: 64,
          flip: true,
        }),
        {
          flat: 0.3,
          pattern: false,
          kind: "twinkle",
          params: [0.18, 0],
          color: (c) =>
            mix("#fffbe0", "#ffb838", clamp(Math.hypot(c.p[0], c.p[1] + 0.35, c.p[2]) / 1.2, 0, 1)),
        },
      );
      k.add(k.cylinder(0.1, 0.2), {
        pos: [0, -0.6, 0],
        pattern: false,
        weight: 2,
        color: (c) => lit(c, "#f6ecd2", 0.2),
      });
      flame(k, [0, -0.49, 0], { share: 0.05, height: 0.32, width: 0.06 });
      // The lid with its stem and a curly vine.
      const lid = k.part("lid", {
        pivot: [0, Math.sin(0.95) * S[1] * 0.95, -Math.cos(0.95) * 0.95],
        axis: [1, 0, 0],
      });
      k.add(
        k.param(
          (u, v) => {
            const phi = u * TAU;
            const e0 = cutE(phi);
            return P(phi, e0 + v * (Math.PI / 2 - e0));
          },
          { grid: 40 },
        ),
        { part: lid, flat: 0.2, color: skin },
      );
      k.add(k.disc(0.5), {
        pos: [0, Math.sin(0.93) * S[1], 0],
        part: lid,
        flat: 0.3,
        color: "#e8a040",
      });
      const top = [0, S[1] * 0.8, 0];
      k.add(
        k.tube(
          spline([
            vec.add(top, [0, -0.05, 0]),
            vec.add(top, [0.02, 0.12, 0]),
            vec.add(top, [0.08, 0.24, 0.02]),
            vec.add(top, [0.16, 0.28, 0.04]),
          ]),
          (t) => 0.075 - 0.035 * t,
          {
            caps: true,
            grid: 32,
          },
        ),
        {
          part: lid,
          flat: 0.2,
          color: (c) =>
            lit(c, mix("#6b7a2a", "#4a5220", 0.5 + 0.5 * Math.sin(c.u * TAU * 6)), 0.35),
        },
      );
      k.add(
        k.tube(
          (t) => {
            const a = t * TAU * 2.2;
            const r = 0.12 * (1 - 0.6 * t);
            return vec.add(top, [
              -0.08 - t * 0.25 + Math.cos(a) * r * 0.4,
              0.02 + Math.sin(a) * r,
              Math.sin(a) * r * 0.8 + 0.1,
            ]);
          },
          0.014,
          { grid: 12, samples: 96 },
        ),
        { part: lid, weight: 2, color: (c) => lit(c, "#6b8a2a", 0.3) },
      );
      k.reach([0, S[1] + 0.55, -0.6]);
    }

drive:
drive(t, c, out) {
      out.parts.lid = { angle: -1.1 * easeInOut(c.lid), offset: [0, 0.12 * easeInOut(c.lid), 0] };
      out.amount = 0.9;
    }

build:
build(k) {
      const snow = (c) => {
        const d = dot(c.n, LIGHT);
        const n = c.noise(c.p[0] * 40, c.p[1] * 40, c.p[2] * 40);
        let col = mix("#c9d6ea", "#ffffff", clamp(0.55 + 0.5 * d + 0.08 * n, 0, 1));
        if (n > 0.62) col = "#ffffff";
        return col;
      };
      // The three balls, each a part; `from` and `to` are the melt levels
      // over which it shrinks (the head first).
      const balls = [
        { r: 0.55, y: -0.42, from: 0.35, to: 1 },
        { r: 0.4, y: 0.3, from: 0.2, to: 0.92 },
        { r: 0.29, y: 0.85, from: 0.05, to: 0.8 },
      ];
      balls.forEach((b, i) =>
        k.add(k.sphere(b.r), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          part: k.part(`ball${i}`, { pivot: [0, b.y, 0] }),
          pos: [0, b.y, 0],
          flat: 0.25,
          interior: 0.08,
          core: "#e8eef6",
          color: snow,
        }),
      );
      // The pieces, each a token: where it sits, which ball holds it, the
      // melt level at which it drops off, where it lands and how it turns.
      const pieces = [];
      const piece = (home, ball, drop, landR, spin, order, lift = 0.035) => {
        const out = vec.unit([home[0] || 0.001, 0, home[2] || 0.001]);
        const land = [out[0] * landR, SNOW.ground + lift, out[2] * landR];
        const axis = vec.unit(vec.cross([0, 1, 0], out));
        pieces.push({ home, ball, drop, land, spin, axis, order });
        return { kind: "token", params: [pieces.length - 1, 0] };
      };
      const coal = (c) => lit(c, "#1d1c1f", 0.3, 0.4);
      for (const s of [-1, 1])
        k.add(k.sphere(0.035), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [s * 0.1, 0.94, 0.26],
          weight: 3,
          pattern: false,
          ...piece([s * 0.1, 0.94, 0.26], 2, 0.45 + 0.03 * s, 0.62, 1.2, 10 + s),
          color: coal,
        });
      for (let i = 0; i < 5; i++) {
        const a = (i - 2) * 0.22;
        const home = [Math.sin(a) * 0.16, 0.76 - Math.cos(a) * 0.04 + 0.03, 0.26];
        k.add(k.sphere(0.022), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: home,
          weight: 3,
          pattern: false,
          ...piece(home, 2, 0.5 + 0.02 * i, 0.5 + 0.06 * Math.abs(i - 2), 1.5, 5 + i),
          color: coal,
        });
      }
      [0.45, 0.3, 0.15].forEach((y, i) => {
        const z = Math.sqrt(0.4 * 0.4 - (y - 0.3) ** 2);
        const home = [0, y, z - 0.01];
        k.add(k.sphere(0.04), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: home,
          weight: 3,
          pattern: false,
          ...piece(home, 1, 0.72 + 0.05 * i, 0.72 + 0.08 * i, 1.4, 2 + i),
          color: coal,
        });
      });
      k.add(k.cone(0.045, 0.0, 0.26), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [0, 0.86, 0.38],
        rot: [90, 0, 0],
        weight: 2.5,
        pattern: false,
        ...piece([0, 0.86, 0.38], 2, 0.38, 0.85, 0.25, 12),
        color: (c) => lit(c, fract(c.lp[1] * 22) < 0.2 ? "#d2601a" : "#f28a2a", 0.3),
      });
      // Stick arms.
      for (const s of [-1, 1]) {
        const a = [s * 0.36, 0.38, 0];
        const b = [s * 0.82, 0.68, 0.04];
        const home = vec.mul(vec.add(a, b), 0.5);
        // Both sticks of an arm share its token.
        const stick = {
          flat: 0.25,
          weight: 2,
          pattern: false,
          ...piece(home, 1, 0.55 + 0.04 * s, 1.1, 0.6, 8 + s, 0.05),
          color: (c) => lit(c, "#5a3a22", 0.3),
        };
        k.add(
          k.tube(
            (t) => vec.add(a, vec.mul(vec.sub(b, a), t)),
            (t) => 0.025 - 0.012 * t,
            { grid: 12, samples: 16, caps: true },
          ),
          stick,
        );
        const m = vec.add(a, vec.mul(vec.sub(b, a), 0.7));
        const f = [m[0] + s * 0.08, m[1] + 0.14, 0.02];
        k.add(
          k.tube((t) => vec.add(m, vec.mul(vec.sub(f, m), t)), 0.012, {
            grid: 10,
            samples: 8,
            caps: true,
          }),
          stick,
        );
      }
      // Scarf (ring and tail together) and the top hat.
      const scarf = piece([0, 0.6, 0.001], 1, 0.66, 0.02, 0.25, 1);
      k.add(k.torus(0.27, 0.06), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [0, 0.6, 0],
        scale: [1, 0.8, 1],
        flat: 0.3,
        pattern: false,
        ...scarf,
        color: (c) =>
          lit(c, fract(Math.atan2(c.p[0], c.p[2]) * 1.6) < 0.5 ? "#d8262e" : "#f4f0e6", 0.3),
      });
      k.add(k.roundedBox(0.12, 0.34, 0.04, 4), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [0.14, 0.42, 0.3],
        rot: [-15, 0, 10],
        flat: 0.3,
        pattern: false,
        ...scarf,
        color: (c) => lit(c, fract(c.lp[1] * 7) < 0.5 ? "#d8262e" : "#f4f0e6", 0.3),
      });
      const hat = piece([0.01, 1.16, 0], 2, 0.2, 0.95, 1.5, 13, 0.17);
      k.add(k.cylinder(0.26, 0.02), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [0, 1.08, 0],
        rot: [0, 0, -8],
        pattern: false,
        ...hat,
        color: (c) => lit(c, "#222026", 0.3, 0.3),
      });
      k.add(k.cylinder(0.17, 0.3), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [0.02, 1.24, 0],
        rot: [0, 0, -8],
        pattern: false,
        ...hat,
        color: (c) =>
          c.lp[1] < -0.08 && c.lp[1] > -0.13 ? lit(c, "#c8262e", 0.3) : lit(c, "#222026", 0.3, 0.3),
      });
      k.data = { balls, pieces };
      // A puddle spreads as it melts.
      k.add(k.disc(1), {
        even: true,
        jitter: 0.015,
        pos: [0, -0.965, 0],
        pattern: false,
        opacity: 0.6,
        kind: "grow",
        params: (c) => [0.15 + 0.6 * clamp(Math.hypot(c.p[0], c.p[2]), 0, 1), 0],
        color: (c) => mix("#bfe3ff", "#e8f6ff", c.rand()),
      });
      // Drips falling from the bottom ball as the melt starts (hidden at
      // rest, and before that ball shrinks).
      k.cloud({ share: 0.002, size: 0.9, pattern: false, part: k.part("drips") }, (rand) => {
        const b = balls[0];
        const a = rand() * TAU;
        const rr = b.r * (0.72 + 0.12 * rand());
        return {
          p: [Math.sin(a) * rr, b.y - b.r * 0.62, Math.cos(a) * rr],
          color: mix("#cfeaff", "#ffffff", rand()),
          opacity: 0.85,
          kind: "fall",
          params: [0.22, rand()],
        };
      });
      // Snow falling round it.
      k.cloud({ share: 0.004, size: 0.8, pattern: false }, (rand) => ({
        p: [(rand() - 0.5) * 1.7, 0.2 + rand() * 1.2, (rand() - 0.5) * 1.7],
        color: "#ffffff",
        opacity: 0.9,
        kind: "fall",
        params: [1.4, rand()],
      }));
    }

drive:
drive(t, c, out, info) {
      // It melts as solid pieces, not a squash: the three snowballs shrink
      // (the head fastest), drips fall, and the hat, nose, coals, arms and
      // scarf drop off one by one into a spreading puddle. Then it builds
      // itself again: the balls grow back from the bottom up, and each
      // piece hops back to its place. Warmth melts it the same way.
      const on = c.thaw > 0;
      const s = progress(c.thaw) * SNOW.secs;
      const tap = on ? (s < 3.1 ? band(s, 0.1, 2.7) ** 1.5 : 1) : 0;
      const m = Math.max(c.warmth, tap);
      const r = on ? band(s, 3.1, SNOW.secs - 0.2) : 0;
      const d = info.data;
      if (!d) return;
      // The balls: each shrinks about its centre and sits on the one below.
      const melted = d.balls.map((b, i) => 1 - 0.85 * band(m, b.from, b.to));
      const grown = d.balls.map((b, i) => {
        const g = band(r, 0.12 * i, 0.12 * i + 0.25);
        return g <= 0 ? 0 : g >= 1 ? 1 : easeInOut(g) + 0.12 * Math.sin(Math.PI * g);
      });
      const sc = melted.map((v, i) => (r > 0 ? v + (1 - v) * grown[i] : v));
      const centres = [];
      d.balls.forEach((b, i) => {
        const y =
          i === 0
            ? SNOW.ground + b.r * sc[0]
            : centres[i - 1] + (b.y - d.balls[i - 1].y) * (sc[i] + sc[i - 1]) * 0.5;
        centres.push(y);
        out.parts[`ball${i}`] = { scale: sc[i], offset: [0, y - b.y, 0] };
      });
      // The pieces ride on their ball, drop off when the melt reaches them,
      // and hop home in turn as it is rebuilt.
      out.tokens = d.pieces.map((pc, i) => {
        const b = d.balls[pc.ball];
        const rideAt = (mm) => {
          const k = 1 - 0.85 * band(mm, b.from, b.to);
          const idx = pc.ball;
          let y =
            SNOW.ground + d.balls[0].r * (1 - 0.85 * band(mm, d.balls[0].from, d.balls[0].to));
          for (let j = 1; j <= idx; j++) {
            const kj = 1 - 0.85 * band(mm, d.balls[j].from, d.balls[j].to);
            const kp = 1 - 0.85 * band(mm, d.balls[j - 1].from, d.balls[j - 1].to);
            y += (d.balls[j].y - d.balls[j - 1].y) * (kj + kp) * 0.5;
          }
          return vec.add([0, y, 0], vec.mul(vec.sub(pc.home, [0, b.y, 0]), k));
        };
        const f = band(m, pc.drop, pc.drop + 0.2);
        let p = rideAt(Math.min(m, pc.drop));
        let angle = 0;
        if (f > 0) {
          const from = rideAt(pc.drop);
          p = vec.add(vec.add(from, vec.mul(vec.sub(pc.land, from), f)), [0, 0, 0]);
          p[1] = from[1] + (pc.land[1] - from[1]) * f * f;
          angle = pc.spin * f;
        }
        if (r > 0) {
          const e = easeInOut(band(r, 0.4 + 0.025 * pc.order, 0.6 + 0.025 * pc.order));
          const from = f > 0 ? p : rideAt(m);
          p = vec.add(vec.add(from, vec.mul(vec.sub(pc.home, from), e)), [0, (0.3 + 0.2 * Math.max(0, pc.home[1] - pc.land[1])) * Math.sin(Math.PI * e), 0]); // prettier-ignore
          angle *= 1 - e;
        }
        return { base: pc.home, offset: vec.sub(p, pc.home), quat: quatAxisAngle(pc.axis, angle) };
      });
      out.grow = r > 0 ? m * (1 - easeInOut(band(r, 0.2, 0.7))) : m;
      out.parts.drips = { visible: m > 0.08 && m < 0.45 && r <= 0 ? 1 : 0 };
    }

build:
build(k) {
      const ground = FW.ground;
      // A crate of launch tubes.
      k.add(k.roundedBox(0.5, 0.2, 0.34, 6), {
        pos: [0, ground + 0.1, 0],
        flat: 0.2,
        color: (c) =>
          lit(
            c,
            mix(
              "#9a6a3a",
              "#7a4e28",
              0.5 + 0.5 * Math.sin(c.p[1] * 60 + c.noise(c.p[0] * 8, 0, c.p[2] * 8) * 3),
            ),
            0.35,
          ),
      });
      for (const { x, z, col } of FW.tubes)
        k.add(k.cylinder(0.05, 0.22, { caps: false }), {
          pos: [x, ground + 0.3, z],
          flat: 0.2,
          weight: 1.5,
          color: (c) => lit(c, fract(c.p[1] * 14) < 0.5 ? col : "#f4efe4", 0.3),
        });
      // Bursts in the sky: rays of sparks, twinkling tips and drooping embers.
      const bursts = [
        { c: [-0.5, 0.28, 0.05], r: 0.52, a: "#ff3b4a", b: "#ffd23a" },
        { c: [0.52, 0.46, -0.12], r: 0.48, a: "#3b82ff", b: "#e8f4ff" },
        { c: [-0.02, 0.98, 0.1], r: 0.42, a: "#34e070", b: "#ff5ad8" },
      ];
      const rays = 64;
      const dirs = [];
      const g = Math.PI * (3 - Math.sqrt(5));
      for (let i = 0; i < rays; i++) {
        const y = 1 - ((i + 0.5) / rays) * 2;
        const rr = Math.sqrt(1 - y * y);
        dirs.push([Math.cos(g * i) * rr, y, Math.sin(g * i) * rr]);
      }
      const burst = (B, share) => {
        k.cloud({ share, size: 0.7, pattern: false }, (rand, i) => {
          const d = dirs[i % rays];
          const t = Math.pow(rand(), 0.6);
          const tip = t > 0.9;
          const p = vec.add(
            B.c,
            vec.add(vec.mul(d, B.r * (0.25 + 0.75 * t)), [0, -0.06 * t * t, 0]),
          );
          return {
            p,
            dir: d,
            stretch: tip ? 1.2 : 2.6,
            size: tip ? 1.5 : 0.9,
            color: mix(B.b, B.a, t),
            opacity: tip ? 1 : 0.4 + 0.5 * t,
            kind: tip ? "twinkle" : undefined,
            params: [0.6, rand() * TAU],
          };
        });
      };
      for (const B of bursts) {
        burst(B, 0.13);
        k.cloud({ share: 0.025, size: 0.8, pattern: false }, (rand) => {
          const a = rand() * TAU;
          const y = rand() * 2 - 1;
          const rr = Math.sqrt(1 - y * y) * B.r;
          return {
            p: vec.add(B.c, [Math.cos(a) * rr, y * B.r, Math.sin(a) * rr]),
            color: B.b,
            opacity: 0.9,
            kind: "fall",
            params: [0.35, rand()],
          };
        });
        // A faint trail from the crate.
        k.cloud({ share: 0.012, size: 0.6, pattern: false }, (rand) => {
          const t = rand();
          const from = [0, ground + 0.4, 0];
          const to = vec.add(B.c, [0, -B.r * 0.3, 0]);
          return {
            p: vec.add(vec.add(from, vec.mul(vec.sub(to, from), t)), [
              (rand() - 0.5) * 0.02,
              0,
              (rand() - 0.5) * 0.02,
            ]),
            color: mix("#f2d8a0", "#ffffff", t),
            opacity: 0.12 + 0.3 * t * t,
          };
        });
      }
      // The launched rocket (moved to whichever tube fires).
      const rocket = k.part("rocket", { pivot: [0, ground + 0.4, 0] });
      k.add(k.cylinder(0.03, 0.14), {
        pos: [0, ground + 0.45, 0],
        part: rocket,
        weight: 3,
        pattern: false,
        color: "#f4efe4",
      });
      k.cloud({ share: 0.01, size: 0.8, pattern: false }, (rand) => ({
        p: [(rand() - 0.5) * 0.03, ground + 0.38 - rand() * 0.02, (rand() - 0.5) * 0.03],
        color: "#ffd27a",
        opacity: 0.9,
        part: rocket,
        kind: "flame",
        params: [-0.25, rand()],
      }));
      // A bright spark trail behind it, so the launch reads at a glance.
      k.cloud({ share: 0.006, size: 1.1, pattern: false }, (rand) => {
        const f = rand();
        return {
          p: [(rand() - 0.5) * 0.02 * (1 + 2 * f), ground + 0.37 - 0.32 * f, (rand() - 0.5) * 0.02],
          dir: [0, 1, 0],
          stretch: 2.5,
          color: mix("#fff6d0", "#ff9a2a", f),
          opacity: 1 - 0.8 * f,
          part: rocket,
        };
      });
      // Its burst: one per tube colour and shell type, each revealed from the
      // centre outwards as it grows. Flat shapes face the home view.
      const e1 = vec.unit(vec.cross([0, 1, 0], VIEW));
      const e2 = vec.cross(VIEW, e1);
      const ringN = vec.unit([0.25, 0.55, 0.8]);
      const r1 = vec.unit(vec.cross([0, 1, 0], ringN));
      const r2 = vec.cross(ringN, r1);
      const shell = {
        peony: (rand, i) => {
          const d = dirs[i % rays];
          const t = Math.pow(rand(), 0.6);
          return { t, p: vec.add(vec.mul(d, 0.25 + 0.75 * t), [0, -0.06 * t * t, 0]), dir: d };
        },
        ring: (rand) => {
          const a = rand() * TAU;
          const d = vec.add(vec.mul(r1, Math.cos(a)), vec.mul(r2, Math.sin(a)));
          const t = rand() < 0.8 ? 0.88 + 0.12 * rand() : 0.2 + 0.6 * rand();
          return { t, p: vec.mul(d, t), dir: d };
        },
        willow: (rand, i) => {
          const d = dirs[((i * 7) % (rays / 2)) + 2];
          const s = Math.pow(rand(), 0.7);
          const p = vec.add(vec.mul(d, 0.8 * s), [0, -0.55 * s * s, 0]);
          return { t: s, p, dir: vec.unit(vec.add(d, [0, -1.1 * s, 0])), long: true };
        },
        star: (rand) => {
          const a = rand() * TAU;
          const out = rand() < 0.8;
          const rr = starRadius(a, 1) * (out ? 0.95 + 0.08 * rand() : rand());
          const d = vec.add(vec.mul(e1, Math.sin(a)), vec.mul(e2, Math.cos(a)));
          return { t: out ? 1 : rr, p: vec.mul(d, rr), dir: d };
        },
      };
      FW.tubes.forEach((T, ti) => {
        FW.types.forEach((type, j) => {
          const part = k.part(`b${ti}${j}`, { pivot: T.c });
          k.cloud({ share: 0.025, size: 0.75, pattern: false }, (rand, i) => {
            const S = shell[type](rand, i);
            const tip = S.t > 0.9 && !S.long;
            let col = mix(T.b, T.a, Math.min(1, S.t * 1.3));
            if (S.long) col = mix(col, "#ffd27a", 0.35 * S.t);
            return {
              p: vec.add(T.c, vec.mul(S.p, FW.r)),
              dir: S.dir,
              stretch: tip ? 1.2 : S.long ? 3.2 : 2.4,
              size: tip ? 1.5 : 0.95,
              color: col,
              opacity: tip ? 1 : 0.45 + 0.5 * S.t,
              part,
              kind: "grow",
              params: [S.t * 0.9, 0],
            };
          });
        });
      });
    }

drive:
drive(t, c, out) {
      // Each launch picks another tube and another shell type (never the
      // same as the last), so no two in a row look alike. The burst is the
      // colour of the tube that fired it.
      const m = mem(c);
      if (m.tube === undefined) Object.assign(m, { tube: 1, type: 0, n: 0 });
      if (fired(m, "launch", c.launch)) {
        m.n++;
        m.tube = (m.tube + 1 + (hashInt(m.n * 2 + 1) % 2)) % 3;
        m.type = (m.type + 1 + (hashInt(m.n * 2 + 7) % 3)) % 4;
      }
      const u = 1 - c.launch;
      const on = c.launch > 0;
      const T = FW.tubes[m.tube];
      const from = [T.x, FW.ground + 0.4, T.z];
      const rise = easeInOut(band(u, 0, 0.24));
      out.parts.rocket = {
        offset: vec.mul(vec.sub(T.c, from), rise).map((v, i) => v + [T.x, 0, T.z][i]),
        visible: on && u < 0.24 ? 1 : 0,
      };
      out.grow = on ? band(u, 0.24, 0.44) : 0;
      const droop = FW.types[m.type] === "willow" ? 0.3 : 0.16;
      for (let i = 0; i < 3; i++)
        for (let j = 0; j < 4; j++)
          out.parts[`b${i}${j}`] = {
            offset: [0, -droop * band(u, 0.24, 1) ** 2, 0],
            visible: on && i === m.tube && j === m.type ? 1 - band(u, 0.66, 1) : 0,
          };
      out.amount = 0.7 + 0.4 * c.launch;
    }

build:
build(k) {
      const tiers = 5;
      const tierAt = (i) => ({
        y0: -0.6 + i * 0.3,
        h: 0.5 - i * 0.02,
        r: 0.8 - i * 0.14,
      });
      // Radius of the tree's outer surface at a height (for decorations).
      const coneR = (y, phi) => {
        let best = 0;
        for (let i = 0; i < tiers; i++) {
          const T = tierAt(i);
          const f = (y - T.y0) / T.h;
          if (f < 0 || f > 1) continue;
          best = Math.max(best, T.r * (1 - f) * (1 + 0.07 * Math.cos(phi * 9)) + 0.04);
        }
        return best;
      };
      const needles = (c) => {
        const n = c.noise(c.p[0] * 22, c.p[1] * 22, c.p[2] * 22);
        const tip = band(Math.hypot(c.p[0], c.p[2]), 0.1, 0.8);
        return lit(c, mix(mix("#1f5a2c", "#2f7a38", 0.5 + 0.5 * n), "#4f9a48", 0.3 * tip), 0.4);
      };
      for (let i = 0; i < tiers; i++) {
        const T = tierAt(i);
        k.add(
          k.param(
            (u, v) => {
              const phi = u * TAU;
              const r = T.r * v * (1 + 0.08 * Math.cos(phi * 9) * v);
              const y = T.y0 + T.h * (1 - v) - 0.06 * v * v;
              return [Math.sin(phi) * r, y, Math.cos(phi) * r];
            },
            { grid: 64, flip: true },
          ),
          { flat: 0.3, interior: 0.06, core: "#1a4a24", color: needles },
        );
      }
      // Fluffy needle tufts.
      k.cloud({ share: 0.12, size: 0.8 }, (rand) => {
        const y = -0.62 + rand() * 1.6;
        const phi = rand() * TAU;
        const r = coneR(y, phi) * (0.8 + 0.25 * rand());
        if (r <= 0.02) return null;
        const d = [Math.sin(phi), -0.4, Math.cos(phi)];
        return {
          p: [Math.sin(phi) * r, y, Math.cos(phi) * r],
          dir: d,
          stretch: 2.4,
          color: mix("#1f5a2c", "#5aa84e", rand()),
        };
      });
      // Trunk, a tree skirt and presents.
      k.add(k.cylinder(0.09, 0.2), { pos: [0, -0.7, 0], color: (c) => lit(c, "#6a4226", 0.3) });
      k.add(k.disc(0.62), {
        pos: [0, -0.79, 0],
        flat: 0.3,
        color: (c) => (Math.hypot(c.p[0], c.p[2]) > 0.55 ? "#f4f0e6" : lit(c, "#b8202a", 0.2)),
      });
      const gifts = [
        [0.42, 0.34, 0.2, "#2f6fd8", "#f2c230", 20],
        [-0.46, 0.22, 0.16, "#e8e0d0", "#d8262e", -15],
        [0.05, 0.52, 0.14, "#d8262e", "#2fa05a", 40],
      ];
      for (const [x, z, s, col, rib, rot] of gifts) {
        k.add(k.box(s, s, s), {
          pos: [x, -0.79 + s / 2, z],
          rot: [0, rot, 0],
          flat: 0.2,
          weight: 1.4,
          color: (c) => {
            const l = c.lp;
            const onRib = Math.abs(l[0]) < s * 0.1 || Math.abs(l[2]) < s * 0.1;
            return lit(c, onRib ? rib : col, 0.3, 0.2);
          },
        });
        k.add(k.torus(s * 0.16, s * 0.05), {
          pos: [x, -0.79 + s + 0.02, z],
          rot: [90, rot + 45, 0],
          weight: 3,
          color: (c) => lit(c, rib, 0.3),
        });
      }
      // A golden garland spiralling up.
      k.add(
        k.tube(
          (t) => {
            const y = -0.55 + t * 1.3;
            const phi = t * TAU * 3.2;
            const r = coneR(y, phi) + 0.01;
            return [Math.sin(phi) * r, y, Math.cos(phi) * r];
          },
          0.018,
          { grid: 16, samples: 400 },
        ),
        { weight: 2.2, pattern: false, kind: "glint", params: [0.5, 0], color: (c) => gold(c) },
      );
      // Baubles.
      const bauble = ["#d8262e", "#f2c230", "#2f6fd8", "#c8ccd4", "#b83ad8"];
      for (let i = 0; i < 26; i++) {
        const y = -0.5 + (i / 26) * 1.15 + (k.rand() - 0.5) * 0.06;
        const phi = i * 2.39996 + k.rand() * 0.3;
        const r = coneR(y, phi) + 0.02;
        if (r < 0.1) continue;
        const col = bauble[i % bauble.length];
        const s = 0.045 + 0.02 * k.rand();
        k.add(k.sphere(s), {
          pos: [Math.sin(phi) * r, y - s * 0.6, Math.cos(phi) * r],
          weight: 3,
          pattern: false,
          color: (c) => lit(c, col, 0.45, 0.9),
        });
      }
      // Fairy lights: dim bulbs, and a glow that switches on in three
      // groups (every third bulb), bottom to top.
      const groups = [0, 1, 2].map((g) => k.part(`lights${g}`, { pivot: [0, 0, 0] }));
      const bulbCols = ["#ffe9a8", "#ff6a5a", "#6ac8ff", "#9aff7a", "#ffb0f0"];
      const bulbs = [];
      for (let i = 0; i < 70; i++) {
        const t = i / 70;
        const y = -0.52 + t * 1.2;
        const phi = t * TAU * 4.5 + 1.2;
        const r = coneR(y, phi) + 0.01;
        bulbs.push({
          p: [Math.sin(phi) * r, y, Math.cos(phi) * r],
          col: bulbCols[i % bulbCols.length],
          out: [Math.sin(phi) * (r + 0.03), y, Math.cos(phi) * (r + 0.03)],
          t,
          i,
        });
      }
      k.cloud({ share: 0.004, size: 0.9, pattern: false }, (rand, i) => ({
        p: bulbs[i % bulbs.length].p,
        color: "#5a5a50",
        opacity: 1,
      }));
      groups.forEach((part, g) => {
        const mine = bulbs.filter((b) => b.i % 3 === g);
        // A bright bulb, a little proud of the needles, and a soft halo.
        k.cloud({ share: 0.008, size: 2.6, pattern: false }, (rand, i) => {
          const b = mine[i % mine.length];
          const d = vec.unit([rand() - 0.5, rand() - 0.5, rand() - 0.5]);
          return {
            p: vec.add(b.out, vec.mul(d, 0.025 * rand())),
            color: mix(b.col, "#ffffff", 0.5),
            opacity: 1,
            part,
            kind: "grow",
            params: [b.t * 0.9, 0],
          };
        });
        k.cloud({ share: 0.003, size: 5, pattern: false }, (rand, i) => {
          const b = mine[i % mine.length];
          const d = vec.unit([rand() - 0.5, rand() - 0.5, rand() - 0.5]);
          return {
            p: vec.add(b.out, vec.mul(d, 0.04 * rand())),
            color: b.col,
            opacity: 0.24,
            part,
            kind: "grow",
            params: [b.t * 0.9, 0],
          };
        });
      });
      // The star on top: a faceted, bevelled gold star (each point has a lit
      // and a shaded face), turned to face the home view so its shape reads.
      // It sits above the tip, so its lower points clear the needles (the
      // tufts reach y = 0.98), on a short gold stem.
      const top = [0, 1.17, 0];
      const R = 0.2;
      const seg = TAU / 5;
      k.add(k.cylinder(0.018, 0.2), {
        pos: [0, 0.94, 0],
        weight: 3,
        pattern: false,
        color: (c) => shade("#d9a22a", 0.85 + 0.25 * Math.max(0, c.n[0])),
      });
      for (const side of [1, -1]) {
        k.add(
          k.param(
            (u, v) => {
              const a = u * TAU;
              const r = v * starRadius(a, R);
              return [Math.sin(a) * r, Math.cos(a) * r, side * 0.045 * (1 - v)];
            },
            { grid: 60, flip: side < 0 },
          ),
          {
            pos: top,
            rot: [0, 31.5, 0],
            weight: 4,
            even: true,
            jitter: 0.01,
            flat: 0.15,
            pattern: false,
            kind: "twinkle",
            params: [0.15, 0],
            color: (c) => {
              const a = Math.atan2(c.lp[0], c.lp[1]);
              // Which half of a point the splat is on: one catches the light.
              const d = fract(a / seg + 0.5) - 0.5;
              const facet = d > 0 ? 1.08 : 0.72;
              const ridge = Math.abs(d) < 0.02 ? 1.25 : 1;
              const tip = c.v > 0.93 ? 1.15 : 1;
              return shade(mix("#ffe79a", "#e5a51c", c.v * 0.8), facet * ridge * tip);
            },
          },
        );
      }
      // A faint warm glow behind it, and a bright halo while the lights are on.
      k.cloud({ share: 0.004, size: 2.4, pattern: false }, (rand) => {
        const d = vec.unit([rand() - 0.5, rand() - 0.5, rand() - 0.5]);
        return {
          p: vec.add(top, vec.mul(d, 0.08 + 0.12 * rand())),
          color: "#fff0a0",
          opacity: 0.035,
          kind: "twinkle",
          params: [0.3, rand() * TAU],
        };
      });
      const halo = k.part("halo", { pivot: top });
      const behind = vec.add(top, vec.mul(VIEW, -0.08));
      k.cloud({ share: 0.005, size: 2.6, pattern: false }, (rand) => {
        const d = vec.unit([rand() - 0.5, rand() - 0.5, rand() - 0.5]);
        const r = 0.12 + 0.16 * Math.pow(rand(), 1.5);
        return {
          p: vec.add(behind, vec.mul(d, r)),
          color: mix("#fff6c8", "#ffc840", r * 3),
          opacity: 0.09,
          part: halo,
        };
      });
    }

drive:
drive(t, c, out) {
      // The lights switch on in a sweep up the tree and stay on, playing
      // three patterns in turn: a chase, a slow ripple and all steady. The
      // star glows while they are on.
      const on = c.lights;
      out.grow = on;
      const phase = Math.floor(t / 4) % 3;
      for (let g = 0; g < 3; g++) {
        let v = 1.15;
        if (phase === 0) v = Math.floor(t * 6) % 3 === g ? 1.45 : 0.45;
        else if (phase === 1) v = 0.55 + 0.75 * (0.5 + 0.5 * Math.sin(t * 4 - g * 2.1));
        out.parts[`lights${g}`] = { visible: v * smoothstep(0, 0.3, on) };
      }
      out.parts.halo = { visible: on * (1 + 0.12 * Math.sin(t * 2.6)) };
      out.amount = 0.9 + 1.2 * on;
    }

build:
build(k, o) {
      const yc = 0.1;
      const H = 0.85;
      const W = 0.6;
      const prof = [];
      for (let i = 0; i <= 30; i++) {
        const t = -1 + (2 * i) / 30;
        prof.push([W * Math.sqrt(Math.max(0, 1 - t * t)) * (1 - 0.13 * t), yc + H * t]);
      }
      const egg = k.part("egg", { pivot: [0, 0, 0], axis: [0, 1, 0] });
      const c1 = o.c1;
      const c2 = o.c2;
      const white = "#faf6ec";
      const dark = "#241a1e";
      const design = (u, y) => {
        const Y = (y - yc) / H; // -1 .. 1
        switch (o.pattern) {
          case "stripes": {
            const b = Math.floor((Y + 1) * 6);
            const edge = Math.abs(fract((Y + 1) * 6) - 0.5) > 0.44;
            return edge ? white : [c1, c2, white, c2][b % 4];
          }
          case "dots": {
            const row = Math.floor((Y + 1) * 7);
            const cu = fract(u * 10 + (row % 2) * 0.5) - 0.5;
            const cy = fract((Y + 1) * 7) - 0.5;
            const d = Math.hypot(cu, cy * 0.9);
            return d < 0.22 ? (row % 2 ? c2 : white) : c1;
          }
          case "zigzag": {
            const z = Math.abs(fract(u * 8) - 0.5) * 0.25;
            const b = Math.floor((Y + 1 + z) * 5);
            return [c1, white, c2, white][b % 4];
          }
          case "flowers": {
            const row = Math.floor((Y + 1) * 3.5);
            const cu = fract(u * 6 + (row % 2) * 0.5) - 0.5;
            const cy = fract((Y + 1) * 3.5) - 0.5;
            const a = Math.atan2(cy, cu);
            const r = Math.hypot(cu, cy);
            if (r < 0.07) return c2;
            if (r < 0.2 + 0.12 * Math.cos(a * 5)) return white;
            return c1;
          }
          case "stars": {
            const row = Math.floor((Y + 1) * 4);
            const cu = fract(u * 7 + (row % 2) * 0.5) - 0.5;
            const cy = fract((Y + 1) * 4) - 0.5;
            const a = Math.atan2(cu, cy);
            return Math.hypot(cu, cy) < starRadius(a, 0.34) ? c2 : c1;
          }
          default: {
            // Folk: meridian bands, a rosette band round the middle, wavy lines.
            const ab = Math.abs(Y);
            if (Math.abs(ab - 0.36) < 0.03) return dark;
            if (ab < 0.33) {
              const cu = fract(u * 8) - 0.5;
              const a = Math.atan2(Y, cu * 1.6);
              const r = Math.hypot(cu * 1.6, Y);
              if (r < 0.08) return c2;
              if (r < 0.25 + 0.06 * Math.cos(a * 8)) return r > 0.2 ? dark : white;
              return c1;
            }
            const wave = Math.abs(Y - Math.sign(Y) * (0.6 + 0.08 * Math.sin(u * TAU * 8)));
            if (wave < 0.045) return white;
            if (Math.abs(fract(u * 16) - 0.5) < 0.06 && ab > 0.4 && ab < 0.9) return dark;
            return ab > 0.88 ? c2 : c1;
          }
        }
      };
      k.add(k.lathe(prof, { grid: 96 }), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        part: egg,
        flat: 0.18,
        interior: 0.1,
        core: (c) => (Math.hypot(c.p[0], c.p[1] - 0.0, c.p[2]) < 0.3 ? "#f6c230" : "#fbf4e2"),
        color: (c) => lit(c, design(c.u, c.p[1]), 0.35, 0.55),
      });
      // A little golden stand.
      k.add(
        k.lathe(
          [
            [0.0, -0.95],
            [0.34, -0.94],
            [0.36, -0.9],
            [0.2, -0.86],
            [0.14, -0.8],
            [0.22, -0.74],
            [0.3, -0.7],
          ],
          { grid: 64 },
        ),
        { even: true, opacity: 1, jitter: 0.015, flat: 0.2, pattern: false, color: (c) => gold(c) },
      );
    }

drive:
drive(t, c, out) {
      const u = 1 - c.spin;
      const turns = c.spin > 0 ? 2 * (1 - (1 - u) ** 3) : 0;
      out.parts.egg = { angle: turns * TAU };
    }

build:
build(k, o) {
      const paper = { red: "#f2302a", gold: "#f8b020", teal: "#22c0b4", purple: "#a044e8" }[
        o.color
      ];
      const hook = [0, 1.02, 0];
      const lantern = k.part("lantern", { pivot: hook, axis: [0, 0, 1] });
      const L = (shape, opts) =>
        k.add(shape, {
          opacity: 1,
          jitter: 0.015,
          part: lantern,
          ...opts,
        });
      // The glowing paper body with ribs.
      const prof = [];
      for (let i = 0; i <= 24; i++) {
        const t = -1 + (2 * i) / 24;
        prof.push([0.72 * Math.pow(Math.max(0, 1 - t * t), 0.55) + 0.18, 0.05 + 0.55 * t]);
      }
      L(k.lathe(prof, { grid: 96 }), {
        even: true,
        flat: 0.2,
        kind: "twinkle",
        params: [0.06, 0],
        color: (c) => {
          const a = Math.atan2(c.p[0], c.p[2]);
          const rib = Math.abs(fract((a / TAU) * 16) - 0.5) > 0.46;
          const face = Math.max(0, dot(c.n, VIEW));
          const mid = 1 - Math.abs(c.p[1] - 0.05) / 0.6;
          const glow = Math.pow(face, 0.8) * (0.4 + 0.6 * mid);
          let col =
            glow < 0.5
              ? mix(shade(paper, 0.55), paper, glow * 2)
              : mix(paper, mix(paper, "#ffd040", 0.65), (glow - 0.5) * 2);
          if (rib) col = shade(col, 0.72);
          // A simple golden circle motif on the front.
          const m = Math.hypot(Math.atan2(c.p[0], c.p[2]) - 0.35, (c.p[1] - 0.05) * 1.6);
          if (Math.abs(m - 0.28) < 0.025 || (m < 0.16 && Math.abs(fract(m * 12) - 0.5) < 0.2))
            col = mix(col, "#ffd24a", 0.85);
          return keep(col);
        },
      });
      // Golden caps, a cord and a tassel.
      for (const [y, s] of [
        [0.66, 1],
        [-0.56, -1],
      ]) {
        L(k.cylinder(0.26, 0.1), {
          pos: [0, y, 0],
          flat: 0.2,
          pattern: false,
          color: (c) => gold(c),
        });
        L(k.torus(0.26, 0.022), {
          pos: [0, y - s * 0.05, 0],
          weight: 2,
          pattern: false,
          color: (c) => gold(c),
        });
      }
      L(k.cylinder(0.012, 0.3, { caps: false }), {
        pos: [0, 0.86, 0],
        weight: 3,
        pattern: false,
        color: "#8a1c1c",
      });
      L(k.sphere(0.06), { pos: [0, -0.66, 0], weight: 2, pattern: false, color: (c) => gold(c) });
      L(k.cone(0.02, 0.07, 0.08), {
        pos: [0, -0.74, 0],
        weight: 2,
        pattern: false,
        color: (c) => gold(c),
      });
      k.cloud({ share: 0.05, size: 0.7, pattern: false }, (rand) => {
        const a = rand() * TAU;
        const r = 0.055 * Math.sqrt(rand());
        const len = 0.4 + 0.05 * rand();
        const t = rand();
        return {
          p: [Math.sin(a) * r * (1 + t * 0.6), -0.78 - t * len, Math.cos(a) * r * (1 + t * 0.6)],
          dir: [0, 1, 0],
          stretch: 3,
          color: mix(paper, "#8a1010", t * 0.5),
          part: lantern,
        };
      });
      // A little hook it hangs from.
      k.add(evenTorus(k, 0.04, 0.012), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: hook,
        rot: [90, 0, 0],
        weight: 3,
        pattern: false,
        color: (c) => gold(c),
      });
      k.reach([0.5, -1.3, 0]);
      k.reach([-0.5, -1.3, 0]);
    }

drive:
drive(t, c, out) {
      const a = 0.05 + 0.25 * c.swing;
      out.parts.lantern = {
        quat: quatMul(
          quatAxisAngle([0, 0, 1], a * Math.sin(t * 1.6)),
          quatAxisAngle([1, 0, 0], 0.6 * a * Math.sin(t * 1.1 + 1)),
        ),
      };
      out.amount = 0.8;
    }

build:
build(k) {
      const base = -0.55;
      // A rangoli of coloured powder under the lamp.
      const rc = ["#ff4f8a", "#ffb020", "#2fbf71", "#3b82ff", "#ff7a2a", "#f4f0e6"];
      k.add(k.disc(1), {
        pos: [0, base - 0.02, 0],
        flat: 0.3,
        color: (c) => {
          const x = c.p[0];
          const z = c.p[2];
          const r = Math.hypot(x, z);
          if (c.n[1] < 0) return "#b8a890";
          const a = Math.atan2(x, z);
          const petal = r - (0.62 + 0.14 * Math.abs(Math.cos(a * 4)));
          if (r > 0.97) return rc[5];
          if (petal > 0.06)
            return Math.abs(fract(((a * 8) / TAU) * 2) - 0.5) < 0.18 && r > 0.82 ? rc[1] : rc[3];
          if (petal > 0.03) return rc[5];
          if (petal > -0.1) return rc[0];
          if (r > 0.42) return Math.abs(fract((a / TAU) * 16) - 0.5) < 0.25 ? rc[2] : rc[1];
          if (r > 0.38) return rc[5];
          return rc[4];
        },
      });
      k.cloud({ share: 0.02, size: 1.2, pattern: false }, (rand) => {
        const a = rand() * TAU;
        const r = 0.75 + rand() * 0.2;
        return {
          p: [Math.sin(a) * r, base, Math.cos(a) * r],
          n: [0, 1, 0],
          color: rand() < 0.5 ? "#ff8a1a" : "#ffd21a",
        };
      });
      // The lamp: a round clay bowl pinched into a pointed spout.
      const spoutA = 1.35;
      const spout = (a) =>
        Math.pow(Math.max(0, Math.cos(Math.atan2(Math.sin(a - spoutA), Math.cos(a - spoutA)))), 8);
      const rimR = (a) => 0.5 * (1 + 0.65 * spout(a));
      const depth = 0.3;
      const bowlAt = (a, v, inner) => {
        const q = (v * Math.PI) / 2;
        const r = rimR(a) * Math.pow(Math.sin(q), 0.85) * (inner ? 0.86 : 1);
        const y =
          base +
          0.02 +
          (inner ? 0.04 : 0) +
          depth * (1 - Math.cos(q)) * (inner ? 0.88 : 1) +
          0.07 * spout(a) * v * v;
        return [Math.sin(a) * r, y, Math.cos(a) * r];
      };
      const bowl = (inner) =>
        k.param((u, v) => bowlAt(u * TAU, v, inner), { grid: 72, flip: inner });
      const zig = (x) => Math.abs(fract(x) - 0.5) * 4 - 1;
      // Burnished terracotta, painted: a row of white dots under the rim, a
      // red line, a band of lotus petals (white outline, saffron fill, a
      // green heart) and a green line at the foot.
      const clay = (c) => {
        const y = c.p[1] - base;
        const n = c.fbm(c.p[0] * 4, c.p[1] * 4, c.p[2] * 4, 3);
        let col = mix("#c9662a", "#a9501f", 0.5 + 0.8 * n);
        const a = Math.atan2(c.p[0], c.p[2]) / TAU;
        const r = Math.hypot(c.p[0], c.p[2]);
        // Dots: round, about the same size all the way round.
        const du = (fract(a * 24) - 0.5) * ((TAU * r) / 24);
        if (Math.hypot(du, y - 0.292) < 0.014) col = "#fbf4e0";
        if (Math.abs(y - 0.262) < 0.008) col = "#d8202f";
        // Petals.
        const h = (y - 0.12) / 0.13;
        if (h > 0 && h < 1) {
          const u = Math.abs(fract(a * 14) - 0.5);
          const w = 0.44 * Math.pow(Math.sin(Math.PI * Math.pow(h, 0.8)), 0.7);
          if (u < w) col = u > w - 0.09 ? "#fbf4e0" : u < 0.1 && h < 0.55 ? "#2f9a5a" : "#f7b21c";
        }
        if (Math.abs(y - 0.105) < 0.008) col = "#2f9a5a";
        return lit(c, col, 0.35, 0.18);
      };
      k.add(bowl(false), { flat: 0.2, weight: 2, even: true, jitter: 0.012, color: clay });
      k.add(bowl(true), {
        flat: 0.2,
        even: true,
        jitter: 0.012,
        color: (c) =>
          lit(c, shade("#8a3a14", 0.95 + 0.1 * c.fbm(c.p[0] * 5, 0, c.p[2] * 5)), 0.3, 0.2),
      });
      // The rounded lip joining outside and inside.
      k.add(
        k.param(
          (u, w) => {
            const a = u * TAU;
            const p = vec.add(vec.mul(bowlAt(a, 1, false), 1 - w), vec.mul(bowlAt(a, 1, true), w));
            return vec.add(p, [0, 0.02 * Math.sin(Math.PI * w), 0]);
          },
          { grid: 64 },
        ),
        {
          flat: 0.2,
          weight: 2,
          even: true,
          jitter: 0.012,
          color: (c) => lit(c, "#c8642a", 0.3, 0.25),
        },
      );
      // Oil, glinting.
      k.add(
        k.param(
          (u, w) => {
            const a = u * TAU;
            const r = rimR(a) * 0.78 * w;
            return [Math.sin(a) * r, base + 0.25, Math.cos(a) * r];
          },
          { grid: 40, normal: () => [0, 1, 0] },
        ),
        {
          flat: 0.3,
          weight: 1.5,
          even: true,
          jitter: 0.008,
          pattern: false,
          color: (c) => {
            // Dark amber oil: rings of a slow ripple, a glossy sheen, and the
            // flame's warm reflection near the wick.
            const r = Math.hypot(c.p[0], c.p[2]);
            const ripple = 0.985 + 0.025 * Math.sin(r * 45);
            const toWick = Math.hypot(
              c.p[0] - Math.sin(spoutA) * 0.36,
              c.p[2] - Math.cos(spoutA) * 0.36,
            );
            let col = shade("#9c5a12", ripple);
            col = mix(col, "#ffe6a0", 0.75 * Math.exp(-((toWick / 0.12) ** 2)));
            col = mix(
              col,
              "#fff4d6",
              0.35 * smoothstep(0.1, 0.5, c.p[0] * -0.5 + c.p[2] * 0.4 + 0.2),
            );
            return lit(c, col, 0.2, 0.9);
          },
        },
      );
      // The wick in the spout, and its flame.
      const tip = [Math.sin(spoutA) * 0.7, base + 0.43, Math.cos(spoutA) * 0.7];
      k.add(
        k.tube(
          spline([
            [Math.sin(spoutA) * 0.3, base + 0.25, Math.cos(spoutA) * 0.3],
            vec.add(tip, [-0.02, -0.08, 0]),
            tip,
          ]),
          0.022,
          { grid: 12, samples: 24, caps: true },
        ),
        {
          weight: 3,
          pattern: false,
          color: (c) => (c.t > 0.85 ? "#2a1a10" : "#f4ecd8"),
        },
      );
      const main = k.part("flame", { pivot: vec.add(tip, [0, 0.02, 0]) });
      flame(k, vec.add(tip, [0, 0.02, 0]), {
        share: 0.08,
        height: 0.55,
        width: 0.08,
        size: 1.2,
        part: main,
      });
      // A ring of small diyas on the rangoli, unlit until the big one
      // passes its light round.
      for (let i = 0; i < DIYAS; i++) {
        const a = spoutA + TAU / 16 + (i / DIYAS) * TAU;
        const at = [Math.sin(a) * 0.84, base, Math.cos(a) * 0.84];
        const small = (u, v, inner) => {
          const q = (v * Math.PI) / 2;
          const r = 0.085 * Math.pow(Math.sin(q), 0.8) * (inner ? 0.85 : 1);
          const y = 0.005 + 0.055 * (1 - Math.cos(q)) * (inner ? 0.85 : 1) + (inner ? 0.008 : 0);
          return [at[0] + Math.sin(u * TAU) * r, at[1] + y, at[2] + Math.cos(u * TAU) * r];
        };
        for (const inner of [false, true])
          k.add(
            k.param((u, v) => small(u, v, inner), { grid: 24, flip: inner }),
            {
              flat: 0.2,
              weight: 2,
              even: true,
              jitter: 0.012,
              color: (c) => {
                if (inner) return lit(c, "#7a3412", 0.3, 0.2);
                const y = c.p[1] - base;
                const dotRow = Math.abs(y - 0.042) < 0.006 && fract(c.u * 12) < 0.4;
                return lit(c, dotRow ? "#fbf4e0" : "#c9662a", 0.35, 0.18);
              },
            },
          );
        k.add(k.disc(0.062), {
          pos: [at[0], base + 0.05, at[2]],
          flat: 0.3,
          weight: 2,
          pattern: false,
          color: (c) => lit(c, "#9c5a12", 0.2, 0.9),
        });
        const wick = [at[0], base + 0.065, at[2]];
        k.add(k.cylinder(0.008, 0.03), {
          pos: wick,
          weight: 4,
          pattern: false,
          color: "#2a1a10",
        });
        const part = k.part(`d${i}`, { pivot: wick });
        flame(k, vec.add(wick, [0, 0.012, 0]), {
          share: 0.007,
          height: 0.22,
          width: 0.03,
          size: 0.8,
          part,
        });
      }
      k.reach(vec.add(tip, [0, 0.75, 0]));
    }

drive:
drive(t, c, out) {
      // The flame flares up and grows, then carries its light round a ring
      // of small diyas one by one. They stay lit until the next tap.
      const dip = Math.sin(Math.PI * clamp(c.blow, 0, 1));
      const flare = Math.sin(Math.PI * band(c.ring, 0, 0.3));
      out.amount = (0.45 + 0.9 * c.size) * (1 - 0.75 * dip) * (1 + 0.45 * c.ring + 0.9 * flare);
      out.parts.flame = { visible: 1 + 0.35 * c.ring + 0.5 * flare };
      for (let i = 0; i < DIYAS; i++) {
        const a = 0.12 + i * 0.1;
        out.parts[`d${i}`] = { visible: easeInOut(band(c.ring, a, a + 0.1)) };
      }
    }

build:
build(k) {
      const y0 = 0.35;
      const brass = (c) => gold(c);
      // Foot and stem.
      k.add(
        k.lathe(
          [
            [0, -0.95],
            [0.42, -0.94],
            [0.44, -0.9],
            [0.3, -0.84],
            [0.14, -0.78],
            [0.07, -0.66],
            [0.06, -0.5],
          ],
          { grid: 64 },
        ),
        { flat: 0.2, color: brass },
      );
      k.add(k.cylinder(0.045, y0 + 0.95 + 0.2), {
        pos: [0, (y0 + 0.2 - 0.95) / 2, 0],
        flat: 0.2,
        weight: 1.4,
        color: brass,
      });
      // Branches: four nested arcs.
      for (let i = 1; i <= 4; i++) {
        const R = 0.2 * i;
        k.add(
          k.tube(
            (t) => {
              const a = Math.PI * t;
              return [-Math.cos(a) * R, y0 - Math.sin(a) * R, 0];
            },
            0.028,
            { grid: 16, samples: 96 },
          ),
          { flat: 0.2, weight: 1.4, color: brass },
        );
      }
      // Cups, candles and flames.
      const spots = [];
      for (let i = 1; i <= 4; i++) spots.push([-0.2 * (5 - i), y0], [0.2 * i, y0]);
      spots.sort((a, b) => a[0] - b[0]);
      spots.push([0, y0 + 0.2]);
      const candles = [
        "#f4f0e6",
        "#6aa8ff",
        "#f4f0e6",
        "#6aa8ff",
        "#6aa8ff",
        "#f4f0e6",
        "#6aa8ff",
        "#f4f0e6",
        "#f4f0e6",
      ];
      spots.forEach(([x, y], i) => {
        k.add(k.cylinder(0.06, 0.06), { pos: [x, y + 0.03, 0], weight: 2, color: brass });
        k.add(k.cylinder(0.028, 0.26), {
          pos: [x, y + 0.19, 0],
          weight: 2,
          pattern: false,
          color: (c) =>
            lit(
              c,
              fract(c.lp[1] * 12 + Math.atan2(c.lp[0], c.lp[2]) / TAU) < 0.5
                ? candles[i]
                : mix(candles[i], "#ffffff", 0.5),
              0.25,
            ),
        });
        const part = k.part(`f${i}`, { pivot: [x, y + 0.34, 0] });
        flame(k, [x, y + 0.33, 0], { share: 0.018, height: 0.16, width: 0.025, part, size: 0.7 });
      });
      k.reach([0, y0 + 0.75, 0]);
    }

drive:
drive(t, c, out) {
      // The helper candle first, then the others one by one.
      out.parts.f8 = { visible: band(c.light, 0, 0.08) };
      for (let i = 0; i < 8; i++)
        out.parts[`f${i}`] = { visible: band(c.light, 0.1 + i * 0.11, 0.17 + i * 0.11) };
      out.amount = 0.8;
    }

build:
build(k, o) {
      const g = group(k, [0.1, -0.05, 0], [-12, 0, 38]);
      const T = 0.22;
      const yb = -0.9;
      const yt = 0.42;
      const smax = (a, b, s = 16) => Math.log(Math.exp(s * a) + Math.exp(s * b)) / s;
      const halfW = (y) => {
        const w1 = Math.sqrt(Math.max(0, 0.43 ** 2 - (y + 0.47) ** 2));
        const w2 = Math.sqrt(Math.max(0, 0.32 ** 2 - (y - 0.1) ** 2));
        const w =
          w1 > 0.001 || w2 > 0.001
            ? smax(w1, w2) - 0.04 * Math.exp(-(((y + 0.13) / 0.08) ** 2))
            : 0;
        return Math.max(0, Math.min(w, Math.max(w1, w2) + 0.02));
      };
      const top = {
        sunburst: ["#f2c278", "#6a2a10"],
        natural: ["#efcf96", "#c89a58"],
        cherry: ["#d8402e", "#5a0e10"],
      }[o.finish];
      const side = o.finish === "natural" ? "#8a4a22" : "#5a2412";
      // Soundboard with a sound hole and rosette. (Each face is a flat sheet
      // whose rows are spaced by the outline's width, so its splats are
      // spread alike everywhere: no rows, no lattice.)
      const ROWS = 256;
      const cum = [0];
      for (let i = 0; i < ROWS; i++)
        cum.push(cum[i] + 2 * halfW(yb + ((i + 0.5) / ROWS) * (yt - yb)));
      const yAt = (v) => {
        const want = v * cum[ROWS];
        let i = 0;
        while (i < ROWS - 1 && cum[i + 1] < want) i++;
        const f = (want - cum[i]) / Math.max(1e-9, cum[i + 1] - cum[i]);
        return yb + ((i + f) / ROWS) * (yt - yb);
      };
      const face = (z, flip) => {
        const n = [0, 0, flip ? -1 : 1];
        return {
          area: (cum[ROWS] / ROWS) * (yt - yb),
          thick: 0.01,
          dims: 2,
          sample(rand) {
            const u = rand();
            const v = rand();
            const y = yAt(v);
            return { p: [(u * 2 - 1) * halfW(y), y, z], n, u, v, face: flip ? 3 : 2 };
          },
        };
      };
      g.add(face(T / 2, false), {
        flat: 0.15,
        ...smooth,
        color: (c) => {
          const [x, y] = c.lp;
          const hole = Math.hypot(x, y + 0.02);
          if (hole < 0.11) return null;
          if (hole < 0.15) {
            const dark = hole < 0.117 || (hole > 0.127 && hole < 0.133) || hole > 0.143;
            return keep(dark ? "#2a1a10" : "#e8d8b8");
          }
          const w = halfW(y) || 1;
          if (Math.abs(x) > w - 0.02) return keep("#f4ead8");
          const edge = Math.max(Math.abs(x) / w, band(Math.abs(y + 0.25), 0.4, 0.66));
          return lacquer(c, mix(top[0], top[1], Math.pow(edge, 3)), 0.4);
        },
      });
      g.add(face(-T / 2, true), {
        flat: 0.15,
        ...smooth,
        color: (c) => lacquer(c, side, 0.3, 0.12),
      });
      // The dark inside, seen through the sound hole.
      g.add(k.disc(0.12), { pos: [0, -0.02, -T / 2 + 0.02], rot: [90, 0, 0], ...smooth, color: () => keep("#140c08") }); // prettier-ignore
      // Ribs round the outline.
      g.add(
        k.param(
          (u, v) => {
            const right = u < 0.5;
            const s = right ? u / 0.5 : (u - 0.5) / 0.5;
            const y = right ? yb + s * (yt - yb) : yt - s * (yt - yb);
            return [(right ? 1 : -1) * halfW(y), y, (v - 0.5) * T];
          },
          { grid: 96 },
        ),
        // The cream binding wraps over the top edge of the ribs.
        { flat: 0.15, ...smooth, color: (c) => (c.v > 0.86 ? keep("#f4ead8") : lacquer(c, side, 0.3, 0.1)) }, // prettier-ignore
      );
      // Bridge and saddle.
      g.add(k.roundedBox(0.3, 0.06, 0.025, 4), {
        pos: [0, -0.58, T / 2 + 0.012],
        flat: 0.2,
        weight: 2,
        ...smooth,
        color: (c) => lacquer(c, "#2a1810", 0.3),
      });
      g.add(k.box(0.2, 0.008, 0.012), {
        pos: [0, -0.575, T / 2 + 0.028],
        weight: 3,
        pattern: false,
        ...smooth,
        color: () => keep("#f4efe0"),
      });
      // Neck, fingerboard with frets and dots, and the headstock with pegs.
      const nutY = 1.36;
      const L = nutY + 0.575;
      const fret = (n) => nutY - L * (1 - Math.pow(2, -n / 12));
      g.add(k.box(0.1, nutY - 0.38, 0.05), {
        pos: [0, (nutY + 0.38) / 2, T / 2 - 0.035],
        flat: 0.2,
        ...smooth,
        color: (c) => lacquer(c, "#9a6a3a", 0.3, 0.1),
      });
      g.add(k.box(0.1, nutY - 0.12, 0.018), {
        pos: [0, (nutY + 0.12) / 2, T / 2 + 0.005],
        flat: 0.15,
        weight: 1.5,
        ...smooth,
        color: (c) => {
          const y = c.p === undefined ? 0 : c.lp[1] + (nutY + 0.12) / 2;
          for (let n = 1; n <= 19; n++)
            if (Math.abs(y - fret(n)) < 0.005) return keep(metal(c, "#e0e4e8"));
          for (const n of [3, 5, 7, 9, 15, 17])
            if (Math.hypot(c.lp[0], y - (fret(n) + fret(n - 1)) / 2) < 0.016)
              return keep("#f4f0e6");
          if (
            Math.abs(y - (fret(12) + fret(11)) / 2) < 0.016 &&
            Math.abs(Math.abs(c.lp[0]) - 0.025) < 0.012
          )
            return keep("#f4f0e6");
          return lacquer(c, "#2e1e14", 0.2);
        },
      });
      g.add(k.box(0.105, 0.012, 0.022), {
        pos: [0, nutY, T / 2 + 0.012],
        weight: 3,
        pattern: false,
        ...smooth,
        color: () => keep("#f4efe0"),
      });
      g.add(k.roundedBox(0.16, 0.34, 0.035, 5), {
        pos: [0, nutY + 0.18, T / 2 - 0.04],
        rot: [-10, 0, 0],
        flat: 0.2,
        ...smooth,
        color: (c) => lacquer(c, "#2a1810", 0.4),
      });
      for (let i = 0; i < 3; i++)
        for (const s of [-1, 1]) {
          const y = nutY + 0.08 + i * 0.09;
          g.add(k.cylinder(0.016, 0.07), {
            pos: [s * 0.1, y, T / 2 - 0.04],
            rot: [0, 0, 90],
            weight: 3,
            pattern: false,
            ...smooth,
            color: (c) => keep(chrome(c)),
          });
          g.add(k.roundedBox(0.03, 0.05, 0.015, 4), {
            pos: [s * 0.15, y, T / 2 - 0.04],
            weight: 3,
            pattern: false,
            ...smooth,
            color: (c) => lacquer(c, "#f0e8d8", 0.3),
          });
        }
      // Rings of sound that pulse out of the soundhole, hidden at rest: three
      // circles of glowing sparks, each wider than the last.
      for (let i = 0; i < 3; i++) {
        const ring = k.part(`ring${i}`, { pivot: g.pt([0, -0.02, T / 2]) });
        const rr = 0.2 + i * 0.15;
        k.cloud({ share: 0.008, size: 1.1 + 0.25 * i, pattern: false }, (rand) => {
          const a = rand() * TAU;
          const r = rr * (0.96 + 0.08 * rand());
          const d = [Math.cos(a), Math.sin(a), 0];
          return {
            p: g.pt([d[0] * r, -0.02 + d[1] * r, T / 2 + 0.07 + 0.03 * i]),
            n: g.dir([0, 0, 1]),
            color: mix("#fff4c8", "#ffc24a", i * 0.4 + 0.3 * rand()),
            opacity: 0.9,
            part: ring,
            kind: "twinkle",
            params: [0.4, rand() * TAU],
          };
        });
      }
      // Six strings that vibrate when strummed. Each is two halves, turned
      // about the bridge and the nut, so it bends at the middle while both
      // ends stay put.
      const zS = T / 2 + 0.03;
      const normal = g.dir([0, 0, 1]);
      for (let i = 0; i < 6; i++) {
        const f = (i - 2.5) / 2.5;
        const a = [f * 0.075, -0.575, zS];
        const b = [f * 0.042, nutY, zS];
        const mid = vec.mul(vec.add(a, b), 0.5);
        const r = 0.0026 - i * 0.00026;
        const wound = i < 4;
        for (const [p0, p1, key] of [
          [a, mid, "a"],
          [mid, b, "b"],
        ]) {
          const part = k.part(`s${i}${key}`, { pivot: g.pt(key === "a" ? a : b), axis: normal });
          g.add(k.tube(line(p0, p1), r, { grid: 8, samples: 16 }), {
            part,
            flat: 0.3,
            weight: 6,
            size: 0.6,
            // Splats drawn out along the string, so it reads as one line.
            stretch: 3,
            pattern: false,
            ...smooth,
            // Clean lines: one even color along each string, lit softly.
            color: (c) => keep(lit(c, wound ? "#dcbc84" : "#eef1f4", 0.12)),
          });
        }
      }
    }

drive:
drive(t, c, out) {
      // A down-strum: each string is plucked a moment after the one above
      // and vibrates, bending at its middle and blurring wider, dying away
      // over about three seconds. The guitar rocks, hops and settles, and
      // rings of sound pulse out of the soundhole one after another.
      const e = (1 - c.strum) * 3;
      const on = c.strum > 0;
      for (let i = 0; i < 6; i++) {
        const el = e - 0.035 * i;
        const env = on && el > 0 ? Math.exp(-el * 0.8) * band(el, 0, 0.03) : 0;
        const a = 0.15 * env * Math.cos(TAU * (4.5 + i * 0.6) * el);
        out.parts[`s${i}a`] = { angle: a, visible: 1 + 1.6 * env };
        out.parts[`s${i}b`] = { angle: -a, visible: 1 + 1.6 * env };
      }
      for (let i = 0; i < 3; i++) {
        const a = 0.08 + i * 0.35;
        out.parts[`ring${i}`] = {
          visible: on ? 1.3 * Math.sin(Math.PI * band(e, a, a + 0.9)) : 0,
        };
      }
      if (on) {
        const rock = Math.exp(-e * 1.5) * Math.sin(e * 6);
        const hop = Math.sin(Math.PI * band(e, 0, 0.45));
        out.body = {
          quat: quatAxisAngle([0, 0, 1], -0.34 * rock),
          offset: [0, 0.1 * hop, 0],
          squash: -0.04 * hop + 0.05 * Math.sin(Math.PI * band(e, 0.45, 0.7)),
        };
      }
    }

build:
build(k, o) {
      const R = 0.7;
      const H = 0.42;
      const shellCol = o.shell;
      k.add(evenCylinder(R, R, H, false), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        flat: 0.2,
        color: (c) => {
          const sparkle = c.noise(c.p[0] * 90, c.p[1] * 90, c.p[2] * 90) > 0.55;
          return lit(c, sparkle ? mix(shellCol, "#ffffff", 0.16) : shellCol, 0.35, 0.6);
        },
      });
      // Heads: the top one ripples when hit.
      k.add(k.disc(R - 0.01), {
        opacity: 1,
        jitter: 0.015,
        pos: [0, H / 2 + 0.005, 0],
        flat: 0.2,
        kind: "wave",
        params: (c) => {
          const r = Math.hypot(c.p[0], c.p[2]) / R;
          return [0.08 * (1 - r * r), -r * 16];
        },
        color: (c) => {
          const r = Math.hypot(c.p[0], c.p[2]);
          const n = c.noise(c.p[0] * 30, 0, c.p[2] * 30);
          if (c.n[1] < 0) return "#dcd8cc";
          // A reinforcing dot in the middle and a faint ring pattern, so
          // the ripples show.
          if (r < 0.14) return keep(shade("#3a3a40", 0.9 + 0.2 * n));
          const ring = 0.5 + 0.5 * Math.cos(r * 60);
          return shade("#f3f0e6", 0.93 + 0.05 * n + 0.04 * ring - 0.06 * band(r, 0.5, 0.7));
        },
      });
      k.add(k.disc(R - 0.01), {
        opacity: 1,
        jitter: 0.015,
        pos: [0, -H / 2 - 0.005, 0],
        flat: 0.2,
        color: "#e8e4da",
      });
      for (const y of [H / 2 + 0.01, -H / 2 - 0.01])
        k.add(evenTorus(k, R + 0.012, 0.028), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [0, y, 0],
          weight: 1.6,
          pattern: false,
          color: (c) => chrome(c),
        });
      // Lugs and tension rods.
      for (let i = 0; i < 8; i++) {
        const a = (i / 8) * TAU + TAU / 16;
        const d = [Math.sin(a), 0, Math.cos(a)];
        k.add(k.roundedBox(0.06, 0.13, 0.05, 4), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [d[0] * (R + 0.02), 0, d[2] * (R + 0.02)],
          rot: [0, (a * 180) / Math.PI, 0],
          weight: 2,
          pattern: false,
          color: (c) => chrome(c),
        });
        for (const s of [1, -1])
          k.add(evenCylinder(0.009, 0.009, 0.12), {
            even: true,
            opacity: 1,
            jitter: 0.015,
            pos: [d[0] * (R + 0.03), s * 0.14, d[2] * (R + 0.03)],
            weight: 3,
            pattern: false,
            color: (c) => chrome(c),
          });
      }
      // Two drumsticks, resting over the head.
      STICKS.forEach((s, i) => {
        const part = k.part(`stick${i}`, { pivot: s.butt, axis: stickAxis(s) });
        k.add(
          evenTube(k, line(s.butt, s.tip), (t) => 0.024 - 0.012 * t * t, {
            grid: 16,
            samples: 32,
            caps: true,
          }),
          {
            even: true,
            opacity: 1,
            jitter: 0.015,
            part,
            flat: 0.2,
            weight: 1.5,
            pattern: false,
            color: (c) => lit(c, wood(c, "#e0b27a", c.p, 0, 0.85), 0.3, 0.3),
          },
        );
        k.add(k.sphere(0.02), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: s.tip,
          scale: [1, 0.8, 1],
          part,
          weight: 3,
          pattern: false,
          color: (c) => lit(c, "#e8c08a", 0.3, 0.3),
        });
      });
      k.reach([0, 0.9, 0]);
    }

drive:
drive(t, c, out) {
      // A roll: the sticks strike in turn. A tap during a roll speeds it up
      // (four speeds) and makes it last longer; a pause starts over slowly.
      const m = mem(c);
      const e = (1 - c.hit) * 3.2;
      if (fired(m, "hit", c.hit)) {
        m.level = m.rolling && m.gap < 0.9 ? Math.min(3, (m.level ?? 0) + 1) : 0;
        m.fresh = !m.rolling;
        if (m.fresh) m.beats = 0;
        m.last = 0;
      }
      const R = ROLL[m.level ?? 0];
      m.gap = e;
      m.beats = (m.beats ?? 0) + Math.max(0, e - (m.last ?? e)) / R.beat;
      m.last = e;
      const env =
        c.hit > 0 ? (m.fresh ? band(e, 0, 0.08) : 1) * (1 - band(e, R.len - 0.3, R.len)) : 0;
      m.rolling = env > 0;
      const P = m.beats;
      STICKS.forEach((s, i) => {
        const up = Math.sin((Math.PI * (P + i)) / 2) ** 2;
        out.parts[`stick${i}`] = { angle: env * (-0.1 + (R.lift + 0.1) * up) };
      });
      const hitNow = Math.exp(-fract(P) * 5);
      out.amount = 1.2 * env;
      out.body = { squash: 0.03 * env * hitNow };
    }

build:
build(k) {
      const X = XYLO;
      const colors = [
        "#e8352e",
        "#f2862a",
        "#f6d02a",
        "#4cc84a",
        "#2ab8b0",
        "#2f7fe0",
        "#5a4fd8",
        "#b04ad8",
      ];
      // Two wooden rails under the bar ends, closer together to the right.
      const railZ = (x, s) => s * (0.42 - 0.12 * ((x + 0.77) / 1.54));
      for (const s of [-1, 1]) {
        const a = [-0.95, 0, railZ(-0.95, s)];
        const b = [0.95, 0, railZ(0.95, s)];
        k.add(evenTube(k, line(a, b), 0.05, { grid: 16, samples: 8, caps: true }), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          flat: 0.2,
          color: (c) => lit(c, wood(c, "#d8a86a", c.p, 0), 0.3, 0.2),
        });
        // Little wheels, for pulling it along.
        for (const x of [-0.8, 0.8])
          k.add(evenCylinder(0.11, 0.11, 0.05), {
            even: true,
            opacity: 1,
            jitter: 0.015,
            pos: [x, -0.08, railZ(x, s) + s * 0.07],
            rot: [90, 0, 0],
            flat: 0.2,
            weight: 1.4,
            pattern: false,
            color: (c) =>
              c.s.cap && c.s.radial < 0.4 ? lit(c, "#f4f0e6", 0.3) : lit(c, "#d8262e", 0.3, 0.4),
          });
      }
      // The bars, with a nail at each end.
      X.bars.forEach((b, i) => {
        const half = (b.len / 2) * 0.86;
        const bar = k.part(`bar${i}`, { pivot: [b.x, X.top, 0] });
        k.add(k.roundedBox(0.17, 0.05, b.len * 0.86, 5), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [b.x, X.top, 0],
          part: bar,
          flat: 0.18,
          kind: "wave",
          params: [0.012, i * 1.3],
          color: (c) => lit(c, colors[i], 0.35, 0.7),
        });
        for (const s of [-1, 1])
          k.add(k.sphere(0.022), {
            even: true,
            opacity: 1,
            jitter: 0.015,
            pos: [b.x, X.top + 0.025, s * Math.min(half - 0.06, Math.abs(railZ(b.x, s)))],
            part: bar,
            weight: 3,
            pattern: false,
            color: (c) => chrome(c),
          });
      });
      // The mallet: a stick with a round head.
      const head = X.rest;
      const end = [1.05, 0.62, 0.95];
      const mallet = k.part("mallet", { pivot: head });
      k.add(evenTube(k, line(head, end), 0.022, { grid: 16, samples: 16, caps: true }), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        part: mallet,
        flat: 0.2,
        weight: 1.5,
        pattern: false,
        color: (c) => lit(c, wood(c, "#e8c08a", c.p, 0, 0.85), 0.3),
      });
      k.add(k.sphere(0.075), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: head,
        part: mallet,
        weight: 2,
        pattern: false,
        color: (c) => lit(c, "#d8262e", 0.35, 0.8),
      });
      k.reach([-0.8, 0.45, 0]);
    }

drive:
drive(t, c, out, info) {
      const X = XYLO;
      const u = 1 - c.play;
      const first = X.bars[0];
      const last = X.bars[7];
      const at = (s) => {
        const x = first.x + (last.x - first.x) * s;
        const hop = Math.abs(Math.sin(Math.PI * s * 7));
        return [x, X.top + 0.06 + 0.14 * hop, 0.08];
      };
      // A struck bar dips and rings for a moment.
      const dip = X.bars.map(() => 0);
      const ring = (e, a = 0.018) => (e < 0 ? 0 : -a * Math.exp(-e * 6) * Math.cos(e * 45));
      let head = X.rest;
      if (c.play > 0) {
        if (u < 0.1) head = vec.add(X.rest, vec.mul(vec.sub(at(0), X.rest), easeInOut(u / 0.1)));
        else if (u < 0.85) head = at((u - 0.1) / 0.75);
        else head = vec.add(at(1), vec.mul(vec.sub(X.rest, at(1)), easeInOut((u - 0.85) / 0.15)));
        X.bars.forEach((b, k) => (dip[k] = ring((u - 0.1 - (0.75 * k) / 7) * 3)));
      }
      // Every bar struck since the last frame rings (a glissando strikes
      // several in a row; lane UI r4).
      const now = info?.time ?? 0;
      for (const tp of newTaps(info, xylo)) if (tp.key === "strike" && tp.pick !== null) xylo.hits.set(tp.pick, now); // prettier-ignore
      for (const [k, at] of xylo.hits) {
        if (now - at > 1.2 || now < at) xylo.hits.delete(k);
        else dip[k] = Math.min(dip[k], ring(now - at - 0.12, 0.045));
      }
      // One bar: the mallet swings over it from wherever it is, strikes at
      // 0.12 s (with the note), bounces up and goes home; the bar jumps.
      const i = info?.tap?.key === "strike" ? info.tap.pick : null;
      if (c.strike > 0 && i !== null && !(c.play > 0)) {
        const e = 1 - c.strike;
        if (xylo.tap !== info.tap.n) {
          xylo.tap = info.tap.n;
          xylo.from = xylo.head;
        }
        const from = xylo.from || X.rest;
        const hit = [X.bars[i].x, X.top + 0.06, 0.08];
        const above = vec.add(hit, [0, 0.24, 0]);
        if (e < 0.07) head = vec.add(from, vec.mul(vec.sub(above, from), easeInOut(e / 0.07)));
        else if (e < 0.12) head = vec.add(above, vec.mul(vec.sub(hit, above), ((e - 0.07) / 0.05) ** 2)); // prettier-ignore
        else if (e < 0.3) head = vec.add(hit, [0, 0.16 * Math.sin(Math.PI * ((e - 0.12) / 0.36)), 0]);
        else head = vec.add(vec.add(hit, [0, 0.16, 0]), vec.mul(vec.sub(X.rest, vec.add(hit, [0, 0.16, 0])), easeInOut((e - 0.3) / 0.7))); // prettier-ignore
        dip[i] = ring(e - 0.12, 0.045);
      }
      xylo.head = head;
      out.parts.mallet = { offset: vec.sub(head, X.rest) };
      X.bars.forEach((b, k) => (out.parts[`bar${k}`] = { offset: [0, dip[k], 0] }));
      out.amount = Math.max(c.play, c.strike * 0.6);
    }

build:
build(k, o) {
      const body = o.case;
      const lacquer = (c) => lit(c, body, 0.32, 0.55);
      const inside = (c) => lit(c, wood(c, "#e2c192", c.p, 0, 0.88), 0.25, 0.1);
      const gold = "#e9c35a";
      // Ivory keys, their top edges a touch darker so neighbours stay apart.
      const ivory = (c) => {
        const edge = c.n[1] > 0.9 ? Math.min(c.u, 1 - c.u) * 0.096 : 1;
        return lit(c, edge < 0.005 ? "#d9d2c2" : "#f8f4ea", 0.16, 0.35);
      };
      const ebony = (c) => lit(c, "#1c1b20", 0.5, 0.6);
      // A lacquered panel with a gold pinstripe inset from its edge (only on
      // the face that looks out along `face`).
      const striped =
        (face, w, h, inset = 0.035) =>
        (c) => {
          if (dot(c.n, face) < 0.9) return lacquer(c);
          const du = Math.min(c.u, 1 - c.u) * w;
          const dv = Math.min(c.v, 1 - c.v) * h;
          const d = Math.min(du, dv);
          if (Math.abs(d - inset) < 0.008) return keep(lit(c, gold, 0.2, 0.6));
          return lacquer(c);
        };

      // Plinth, cheeks, the lower front board and the keybed.
      box6(k, [0, 0.025, -0.08], [1.44, 0.05, 0.54], { color: lacquer, flat: 0.15 }, "Y");
      for (const s of [-1, 1]) {
        box6(
          k,
          [s * 0.655, 0.525, -0.09],
          [0.05, 0.95, 0.42],
          {
            flat: 0.15,
            color: (c) => (dot(c.n, [-s, 0, 0]) > 0.9 ? inside(c) : lacquer(c)),
          },
          "Y",
        );
        // The arms beside the keys.
        box6(k, [s * 0.655, 0.265, 0.28], [0.05, 0.43, 0.32], { flat: 0.15, color: lacquer }, "ZY");
      }
      box6(k, [0, 0.19, 0.06], [1.26, 0.3, 0.03], { flat: 0.15, color: striped([0, 0, 1], 1.26, 0.3) }, "xXYZ"); // prettier-ignore
      box6(
        k,
        [0, 0.37, 0.12],
        [1.26, 0.06, 0.64],
        {
          flat: 0.15,
          color: (c) => (c.n[1] > 0.9 ? lit(c, "#4a1418", 0.2) : lacquer(c)),
        },
        "xXYZ",
      );
      // The fallboard over the keys: a gold stripe and a painted star.
      box6(
        k,
        [0, 0.545, 0.09],
        [1.26, 0.09, 0.035],
        {
          flat: 0.15,
          weight: 3,
          color: (c) => {
            if (c.n[2] > 0.9) {
              const x = (c.u - 0.5) * 1.26;
              const y = (c.v - 0.5) * 0.09;
              const a = Math.atan2(y, x);
              const r = Math.hypot(x, y);
              const star = 0.03 * (0.55 + 0.45 * Math.cos(5 * (a - Math.PI / 2)));
              if (r < star + 0.004) return keep(lit(c, gold, 0.2, 0.6));
            }
            if (c.n[2] < -0.9) return inside(c);
            return striped([0, 0, 1], 1.26, 0.09, 0.02)(c);
          },
        },
        "xXY",
      );
      // The lid, raised: hinged at the back of the top, standing up behind.
      const hinge = [0, 1.0, -0.3];
      const lidQ = quatEuler(-145, 0, 0);
      box6(k, vec.add(hinge, quatRotate(lidQ, [0, 0.015, 0.23])), [1.36, 0.03, 0.46], {
        quat: lidQ,
        flat: 0.15,
        color: striped(quatRotate(lidQ, [0, -1, 0]), 1.36, 0.46, 0.04),
      });
      // Where the rods stand, and the rail the hammers turn on.
      box6(
        k,
        [0, 0.47, TP.rodZ],
        [1.26, 0.06, 0.08],
        {
          flat: 0.15,
          color: (c) => lit(c, "#474b52", 0.35, 0.4),
        },
        "xXY",
      );
      box6(k, [0, TP.hamPivot[0] - 0.012, TP.hamPivot[1]], [1.26, 0.024, 0.045], { flat: 0.15, color: inside }, "xXY"); // prettier-ignore

      // The keys: tokens 0-17, each turning about the balance rail.
      TP.keys.forEach((key) => {
        const tok = { kind: "token", params: [key.i, 0], pattern: false, flat: 0.15 };
        if (key.black) {
          box6(k, [key.x, TP.keyTop + 0.022, 0.21], [0.058, 0.05, 0.2], { ...tok, weight: 4, color: ebony }, "Y"); // prettier-ignore
          box6(k, [key.x, TP.keyTop - 0.02, -0.02], [0.028, 0.024, 0.34], { ...tok, color: inside }, "Y"); // prettier-ignore
        } else {
          box6(k, [key.x, TP.keyTop - 0.022, 0.275], [0.096, 0.044, 0.33], { ...tok, weight: 4, color: ivory }, "Y"); // prettier-ignore
          box6(k, [key.x, TP.keyTop - 0.03, -0.02], [0.03, 0.024, 0.26], { ...tok, color: inside }, "Y"); // prettier-ignore
        }
      });
      // The hammers (tokens 18-35) and the rods (tokens 36-47, then parts).
      TP.rods.forEach((rod, i) => {
        const tok = { kind: "token", params: [18 + i, 0], pattern: false };
        const a = [rod.x, TP.hamPivot[0], TP.hamPivot[1]];
        const b = [rod.x, TP.hamHead[0], TP.hamHead[1]];
        k.add(k.tube(line(a, b), 0.009, { grid: 8, samples: 16 }), {
          ...tok,
          flat: 0.3,
          weight: 3,
          size: 1.3,
          opacity: 1,
          color: (c) => lit(c, "#6b3f22", 0.3, 0.2),
        });
        k.add(
          k.param(
            (u, v) => {
              const r = TP.headR;
              const w = 0.044;
              // A felt head: a short cylinder along X with flat ends.
              const ang = TAU * u;
              const q = v * 4;
              const rr = q < 1 ? r * q : q > 3 ? r * (4 - q) : r;
              const xx = q < 1 ? -w / 2 : q > 3 ? w / 2 : -w / 2 + (w * (q - 1)) / 2;
              return [b[0] + xx, b[1] + rr * Math.cos(ang), b[2] + rr * Math.sin(ang)];
            },
            { grid: 32, thick: TP.headR },
          ),
          { ...tok, even: true, opacity: 1, jitter: 0.01, flat: 0.25, weight: 3, color: (c) => lit(c, "#e3a93a", 0.3, 0.15) }, // prettier-ignore
        );
        const base = [rod.x, TP.rodBase, TP.rodZ];
        const rodOpt =
          i < 12
            ? { kind: "token", params: [36 + i, 0] }
            : { part: k.part(`rod${i}`, { pivot: base, axis: TP_ROD_AXIS }) };
        rodShape(k, base, TP.rodR, rod.len, {
          ...rodOpt,
          pattern: false,
          flat: 0.3,
          weight: 3,
          color: steel,
        });
        // The screw that holds it.
        k.add(k.sphere(0.012), {
          pos: [rod.x, TP.rodBase, TP.rodZ + 0.042],
          even: true,
          weight: 3,
          pattern: false,
          color: steel,
        });
      });
      k.reach([0, 1.46, -0.4]);
    }

drive:
drive(t, c, out, info) {
      const m = mem(c);
      if (!m.hits) m.hits = new Map();
      const now = info?.time ?? 0;
      // Every tap since the last frame (a glissando presses several keys).
      for (const tap of newTaps(info, m))
        if (tap.key === "strike" && tap.pick !== null && c.strike > 0)
          m.hits.set(tap.pick, { at: now, sounded: false });
      // How long ago each key started down (the latest press wins).
      const since = TP.keys.map(() => Infinity);
      if (c.play > 0) {
        const e = (1 - c.play) * TP.songLen;
        TP_SONG.forEach((k, j) => {
          const s = e - (TP.songAt + j * TP.step);
          if (k >= 0 && s >= 0 && s < since[k]) since[k] = s;
        });
      }
      for (const [k, h] of m.hits) {
        const s = now - h.at;
        if (s > 1.6 || s < 0) {
          m.hits.delete(k);
          continue;
        }
        if (s < since[k]) since[k] = s;
        if (!h.sounded && s >= TP.hit) {
          h.sounded = true;
          out.cues.push(tpNote(TP.keys[k].note));
        }
      }
      const tokens = [];
      TP.keys.forEach((k, i) => {
        const p = tpPress(since[i]);
        const rod = TP.rods[i];
        tokens[i] = { base: [k.x, TP.fulcrum[0], TP.fulcrum[1]], quat: quatAxisAngle([1, 0, 0], p.key) }; // prettier-ignore
        tokens[18 + i] = { base: [rod.x, TP.hamPivot[0], TP.hamPivot[1]], quat: quatAxisAngle([1, 0, 0], p.ham) }; // prettier-ignore
        if (i < 12)
          tokens[36 + i] = { base: [rod.x, TP.rodBase, TP.rodZ], quat: quatAxisAngle(TP_ROD_AXIS, p.rod) }; // prettier-ignore
        else out.parts[`rod${i}`] = { angle: p.rod };
      });
      out.tokens = tokens;
    }

build:
function buildGrand(k) {
  sharpen(k);
  grand.player.pause();
  const { layout, outline, rightX, backZ } = G;
  const [y0, y1] = G.rim;
  // Levers: the keys tip about their balance rail, the hammers swing up
  // about their flange rail, the dampers lift off the strings.
  const keys = k.lever({ pivot: [0, 0.69, -0.42], axis: [1, 0, 0], angle: 0.055, ...tunerGlow() }); // lane Live input
  const hammers = k.lever({ pivot: [0, 0.8, -0.195], axis: [1, 0, 0], angle: 0.215, channel: 1 }); // prettier-ignore
  const dampers = k.lever({ dir: [0, 1, 0], move: 0.017, channel: 2 });
  const pedal = k.part("pedal", { pivot: [0.045, 0.1, -0.3], axis: [1, 0, 0] });

  // The keys: ivory and ebony.
  buildKeys(k, layout, keys, { top: G.top, len: 0.15, blackLen: 0.095, height: 0.022, white: IVORY, black: EBONY }); // prettier-ignore

  // The case: a black lacquered rim along the curved outline.
  const tangent = (u) => {
    const a = outline(Math.max(0, u - 0.002));
    const b = outline(Math.min(1, u + 0.002));
    return vec.unit([b[0] - a[0], 0, b[2] - a[2]]);
  };
  k.add(
    edged(
      k.param(
        (u, v) => {
          const p = outline(u);
          return [p[0], y0 + v * (y1 - y0), p[2]];
        },
        { normal: (u) => outward(tangent(u)) },
      ),
      (u, v) => Math.min(v, 1 - v) * (y1 - y0),
      y1 - y0,
    ),
    { color: (c) => lacquer(c), even: true, weight: 1.4, flat: 0.06, jitter: 0.006, interior: 0 },
  );
  // Its top edge, with the inside of the rim below it.
  k.add(
    edged(
      k.param(
        (u, v) => {
          const p = outline(u);
          const t = tangent(u);
          return [p[0] - t[2] * 0.04 * v, y1, p[2] + t[0] * 0.04 * v];
        },
        { grid: 96, normal: UP },
      ),
      (u, v) => Math.min(v, 1 - v) * 0.04,
      0.04,
    ),
    { color: (c) => lacquer(c, 0.3), even: true, weight: 1.4, flat: 0.1, jitter: 0.006 },
  );
  // The soundboard and the golden iron plate over it (its round holes show
  // the spruce), behind the hammers.
  const zFront = -0.36;
  const zBack = -2.06;
  k.add(
    k.param(
      (u, v) => {
        const z = zFront + (zBack - zFront) * u;
        const xr = rightX(z) - 0.03;
        const xl = -0.735;
        return [xl + (xr - xl) * v, G.board, z];
      },
      { grid: 80, normal: UP },
    ),
    {
      color: (c) => {
        const [x, , z] = c.p;
        const edge = Math.min(x + 0.735, rightX(z) - 0.03 - x, z - zBack);
        const holes = [
          [-0.35, -0.8],
          [0.02, -0.72],
          [-0.45, -1.35],
          [-0.12, -1.25],
          [-0.5, -1.75],
        ];
        const hole = holes.some(([hx, hz]) => (x - hx) ** 2 + (z - hz) ** 2 < 0.075 ** 2);
        if (edge < 0.05 || hole) return wood(c, "#d9b77c", c.p, 2, 0.82);
        return metal(c, BRASS, "#6f5424");
      },
      even: true,
      weight: 0.9,
      flat: 0.1,
      jitter: 0.01,
    },
  );
  // Under the hammers: the dark action bed, and the flange rail.
  k.add(stripBox(1.3, 0.01, 0.2), { pos: [0, 0.74, -0.26], color: (c) => lit(c, "#2c241c", 0.2), even: true, weight: 0.7 }); // prettier-ignore
  k.add(stripBox(1.26, 0.018, 0.022), { pos: [0, 0.79, -0.195], color: (c) => wood(c, "#6b4a2c", c.p, 0), even: true, weight: 1.4 }); // prettier-ignore

  // The strings: thin steel wires, copper-wound in the bass, from the front
  // of the plate back to the rim. A fixed share of the splats, long and
  // thin, so they read as wires over the plate.
  const runs = layout.keys.map((key) => {
    const x = key.x * 0.98;
    return { x, z1: backZ(x) + 0.08, copper: key.n < 45 };
  });
  const total = runs.reduce((sum, r) => sum + (-0.29 - r.z1), 0);
  for (const r of runs)
    k.add(
      k.tube((t) => [r.x, G.strings, -0.29 + (r.z1 + 0.29) * t], 0.0012, STRAIGHT),
      {
        color: (c) => metal(c, r.copper ? "#d08a4e" : "#eef1f5", r.copper ? "#6a3c18" : "#707782"),
        share: (0.1 * (-0.29 - r.z1)) / total,
        size: 0.3,
        stretch: 7,
        flat: 0.4,
        jitter: 0,
        pattern: false,
      },
    );

  // The hammers: felt heads on thin shanks, one per key.
  layout.keys.forEach((key, i) => {
    const x = key.x * 0.98;
    const params = [k.leverParam(hammers, i), 0];
    // The felt head on its wooden molding, two pieces so the line between
    // them is a clean edge.
    k.add(stripBox(0.0115, 0.017, 0.03), {
      pos: [x, 0.829 + 0.0045, G.strike],
      color: (c) => lit(c, FELT, 0.25),
      kind: "lever",
      params,
      weight: 5,
      stretch: 0,
      flat: 0.15,
      pattern: false,
    });
    k.add(stripBox(0.0115, 0.009, 0.028), {
      pos: [x, 0.829 - 0.0085, G.strike],
      color: (c) => lit(c, "#7a5534", 0.3),
      kind: "lever",
      params,
      weight: 5,
      flat: 0.15,
      pattern: false,
    });
    k.add(
      k.tube((t) => [x, 0.8 + 0.018 * t, -0.195 - 0.105 * t], 0.0022, STRAIGHT),
      {
        color: (c) => wood(c, "#c9a57a", c.p, 2),
        kind: "lever",
        params,
        weight: 3,
        size: 0.45,
        stretch: 3,
        jitter: 0.004,
        pattern: false,
      },
    );
  });

  // The dampers: felt pads on wooden heads, resting on the strings.
  layout.keys.forEach((key, i) => {
    if (i >= G.dampers) return;
    k.add(stripBox(0.0125, 0.022, 0.026), {
      pos: [key.x * 0.98, G.strings + 0.0012 + 0.011, -0.385],
      color: (c) => (c.lp[1] < -0.005 ? lit(c, FELT, 0.2) : lit(c, "#1b1612", 0.35, 0.2)),
      kind: "lever",
      params: [k.leverParam(dampers, i), 0],
      even: true,
      weight: 5,
      stretch: 0,
      flat: 0.15,
      jitter: 0.006,
      pattern: false,
    });
  });

  // The front: the key bed and slip, the cheek blocks at each end and the
  // nameboard behind the keys.
  const half = layout.width / 2;
  k.add(stripBox(layout.width + 0.02, 0.05, 0.02), { pos: [0, 0.68, 0.011], color: (c) => lacquer(c), even: true, weight: 1.2 }); // prettier-ignore
  k.add(stripBox(layout.width + 0.02, 0.012, 0.2), { pos: [0, 0.692, -0.09], color: (c) => lit(c, "#1c1a18", 0.2), even: true, weight: 0.5 }); // prettier-ignore
  for (const s of [-1, 1])
    k.add(evenRoundBox(0.075, 0.11, 0.2, 0.0225), {
      pos: [s * (half + 0.04), 0.715, -0.085],
      color: (c) => lacquer(c),
      even: true,
      weight: 1.2,
      flat: 0.1,
    });
  k.add(stripBox(layout.width + 0.02, 0.085, 0.018), {
    pos: [0, 0.742, -0.167],
    color: (c) => lacquer(c, 0.4),
    even: true,
    weight: 1.2,
  });
  // The case's bottom, under the keyboard and the rim.
  k.add(
    k.param(
      (u, v) => {
        const z = -0.17 + (zBack - 0.02 + 0.17) * u;
        const xr = rightX(z);
        return [-0.765 + (xr + 0.765) * v, y0, z];
      },
      { grid: 64, normal: UP },
    ),
    { color: (c) => lit(c, "#0a0a0c", 0.3), even: true, weight: 0.35, flat: 0.1 },
  );
  k.add(stripBox(layout.width + 0.18, 0.1, 0.19), { pos: [0, 0.6, -0.08], color: (c) => lacquer(c), even: true, weight: 0.7 }); // prettier-ignore

  // The lid, raised on its hinges along the straight side and held by its
  // prop stick.
  const a = G.lid;
  const hinge = [-0.765, y1 + 0.005];
  const lidPt = (x, z, lift = 0) => {
    const r = x - hinge[0];
    return [hinge[0] + r * Math.cos(a) - lift * Math.sin(a), hinge[1] + r * Math.sin(a) + lift * Math.cos(a), z]; // prettier-ignore
  };
  const lidZ = [-0.2, zBack - 0.01];
  const lidEdge = (u, v) => {
    const z = lidZ[0] + (lidZ[1] - lidZ[0]) * u;
    const wide = rightX(z) + 0.765;
    return Math.min(Math.min(u, 1 - u) * (lidZ[0] - lidZ[1]), Math.min(v, 1 - v) * wide);
  };
  for (const side of [0, 1])
    k.add(
      edged(
        k.param(
          (u, v) => {
            const z = lidZ[0] + (lidZ[1] - lidZ[0]) * u;
            const xr = rightX(z);
            return lidPt(-0.765 + (xr + 0.765) * v, z, side * 0.022);
          },
          {
            grid: 72,
            normal: () => (side ? [-Math.sin(a), Math.cos(a), 0] : [Math.sin(a), -Math.cos(a), 0]),
          },
        ),
        lidEdge,
        0.3,
      ),
      { color: (c) => lacquer(c, side ? 0.6 : 0.3), even: true, weight: 0.9, flat: 0.1, jitter: 0.006 }, // prettier-ignore
    );
  lidRim(k, { x0: -0.765, zF: lidZ[0], zB: lidZ[1], rightX, lidPt, a, lift: 0.022, color: (c) => lacquer(c, 0.5) }); // prettier-ignore
  const pz = -1.0;
  const px = rightX(pz) - 0.05;
  const top = lidPt(-0.765 + (rightX(pz) + 0.765) * 0.88, pz);
  k.add(
    k.tube((t) => [px + (top[0] - px) * t, y1 + (top[1] - y1) * t, pz], 0.011, STRAIGHT),
    {
      color: (c) => lacquer(c, 0.4),
      weight: 1.4,
    },
  );

  // The legs, on brass casters, and the lyre with its three brass pedals.
  for (const [x, z] of [
    [-0.68, -0.3],
    [0.68, -0.3],
    [-0.42, -1.72],
  ]) {
    k.add(evenCylinder(0.045, 0.062, y0 - 0.05), { pos: [x, (y0 + 0.05) / 2, z], color: (c) => lacquer(c, 0.2, 80), even: true, weight: 1.2 }); // prettier-ignore
    k.add(evenCylinder(0.03, 0.03, 0.05), { pos: [x, 0.025, z], color: (c) => metal(c, BRASS, "#5e4418"), even: true, weight: 1.5 }); // prettier-ignore
  }
  for (const s of [-1, 1])
    k.add(stripBox(0.022, y0 - 0.12, 0.05), { pos: [s * 0.07, (y0 + 0.12) / 2, -0.31], color: (c) => lacquer(c), even: true, weight: 1.2 }); // prettier-ignore
  k.add(stripBox(0.3, 0.06, 0.07), { pos: [0, 0.1, -0.31], color: (c) => lacquer(c), even: true, weight: 1.2 }); // prettier-ignore
  [-0.075, 0, 0.075].forEach((x, i) =>
    k.add(stripBox(0.032, 0.012, 0.11), {
      pos: [x, 0.1, -0.225],
