drive(t, c, out) {
      const a = -(t * 2.5 + burst(c.vroom, 3));
      out.parts.front = { angle: a };
      out.parts.rear = { angle: a };
      const v = c.vroom > 0.001 ? Math.sin(Math.PI * (1 - c.vroom)) : 0;
      out.parts.puff = { visible: smoothstep(0, 0.2, c.vroom) };
      out.body = { quat: quatAxisAngle([0, 0, 1], 0.035 * v) };
      out.amount = 1 + c.vroom;
    }

build:
function busBuild(k, o) {
  const P = { flat: 0.2 };
  const dark = "#111214";
  const isSchool = o.style !== "double";
  const W = BUS[isSchool ? "school" : "double"];
  if (isSchool) {
    const yellow = "#f5b400";
    const x0 = -1.72;
    const x1 = 1.0;
    k.add(evenRoundBox(x1 - x0, 1.22, 1.04, 0.16), {
      even: true,
      opacity: 1,
      jitter: 0.015,
      ...P,
      pos: [(x0 + x1) / 2, 0.92, 0],
      interior: 0.05,
      core: "#444",
      color: (c) => {
        const [x, y, z] = c.p;
        const n = c.n;
        if (Math.abs(n[2]) > 0.7) {
          if (z > 0 && x > 0.52 && x < 0.94 && y > 0.4 && y < 1.36) {
            if (y < 0.44 || y > 1.33 || x < 0.55 || x > 0.91) return keep(dark);
            return keep(doorway(y - 0.44));
          }
          if (y > 1.0 && y < 1.33 && x > -1.6 && x < 0.46) {
            const f = (x + 1.6) / 0.31;
            if (f % 1 > 0.12) return glass(c, "#223344");
            return lit(yellow, c);
          }
          if (
            Math.abs(y - 0.62) < 0.022 ||
            Math.abs(y - 0.84) < 0.022 ||
            Math.abs(y - 0.975) < 0.012
          )
            return keep(lit(dark, c));
        }
        if (n[0] > 0.7 && y > 0.98 && y < 1.4 && Math.abs(z) < 0.46)
          return Math.abs(z) < 0.02 ? keep(dark) : glass(c, "#223344");
        if (n[0] < -0.7 && y > 0.95 && y < 1.32 && Math.abs(z) < 0.22) return glass(c, "#223344");
        if (y < 0.36) return lit(dark, c);
        return lit(yellow, c);
      },
    });
    // The bonnet, grille, lights and bumpers.
    k.add(evenRoundBox(0.72, 0.6, 0.92, 0.096), {
      even: true,
      opacity: 1,
      jitter: 0.015,
      ...P,
      pos: [1.33, 0.64, 0],
      color: (c) => {
        const [x, y, z] = c.p;
        if (c.n[0] > 0.7 && Math.abs(z) < 0.28 && y > 0.42 && y < 0.86)
          return keep(Math.sin(y * 120) > 0 ? "#d8dade" : "#3a3b3f");
        return lit(yellow, c);
      },
    });
    for (const z of [-0.36, 0.36])
      k.add(k.sphere(0.07), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [1.68, 0.74, z],
        weight: 3,
        pattern: false,
        color: "#fff8d8",
      });
    for (const x of [1.74, -1.76])
      k.add(evenBox(0.08, 0.13, 1.04), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        ...P,
        pos: [x, 0.38, 0],
        color: (c) => lit(dark, c),
      });
    // Warning lights on the roof corners.
    for (const x of [0.96, -1.66])
      for (const z of [-0.34, 0.34])
        k.add(k.sphere(0.05), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [x, 1.5, z],
          weight: 4,
          pattern: false,
          kind: "twinkle",
          params: [0.5, x > 0 ? 0 : 3],
          color: Math.abs(z) > 0.3 && x > 0 ? "#ff3b2f" : "#ffb300",
        });
    for (const z of [-0.6, 0.6])
      rod(k, [0.98, 1.2, z * 0.85], [1.08, 1.2, z], 0.012, { weight: 3, color: dark });
    for (const z of [-0.6, 0.6])
      k.add(evenBox(0.04, 0.16, 0.08), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [1.08, 1.2, z],
        color: dark,
      });
    busDoors(k, 0.55, 0.91, 0.44, 1.33, 0.52);
    // The stop arm lies folded against the side, behind the door; it swings
    // out to face the traffic.
    const stop = k.part("stop", { pivot: [0.44, 0.73, 0.535], axis: [0, 1, 0] });
    rod(k, [0.44, 0.73, 0.54], [0.4, 0.73, 0.54], 0.012, { part: stop, weight: 3, color: dark });
    k.add(k.disc(0.2), {
      opacity: 1,
      jitter: 0.015,
      part: stop,
      pos: [0.22, 0.73, 0.545],
      rot: [90, 0, 0],
      weight: 4,
      pattern: false,
      color: (c) => {
        const x = Math.abs(c.lp[0]);
        const z = Math.abs(c.lp[2]);
        const d = Math.max(x, z, (x + z) / Math.SQRT2);
        if (d > 0.175) return null;
        if (d > 0.152) return "#f4f4f0";
        return Math.abs(c.lp[2]) < 0.024 && x < 0.1 ? "#f4f4f0" : "#d8231f";
      },
    });
    // Flashing warning lights: a bright halo over each roof light.
    const halo = (part, pos, col) =>
      k.add(k.sphere(0.1), {
        even: true,
        jitter: 0.015,
        part,
        pos,
        weight: 2,
        opacity: 0.75,
        pattern: false,
        color: col,
      });
    const fa = k.part("flashA", { pivot: [0, 1.5, 0] });
    const fb = k.part("flashB", { pivot: [0, 1.5, 0] });
    for (const z of [-0.34, 0.34]) {
      halo(fa, [0.96, 1.5, z], "#ff5a4a");
      halo(fb, [-1.66, 1.5, z], "#ff5a4a");
    }
  } else {
    const red = "#cc2229";
    const x0 = -1.55;
    const x1 = 1.55;
    k.add(evenRoundBox(x1 - x0, 1.85, 0.98, 0.16), {
      even: true,
      opacity: 1,
      jitter: 0.015,
      ...P,
      pos: [0, 1.23, 0],
      interior: 0.05,
      core: "#444",
      color: (c) => {
        const [x, y, z] = c.p;
        const n = c.n;
        const row = (y > 0.8 && y < 1.18) || (y > 1.5 && y < 1.92);
        if (Math.abs(n[2]) > 0.7) {
          if (z > 0 && x > 0.12 && x < 0.58 && y > 0.36 && y < 1.22) {
            if (y > 1.18 || x < 0.15 || x > 0.55) return keep(dark);
            return keep(doorway(y - 0.4));
          }
          if (row && x > -1.42 && x < 1.3) {
            const f = (x + 1.42) / 0.34;
            if (f % 1 > 0.1) return glass(c, "#223344");
          }
          if (y > 1.24 && y < 1.34) return lit("#f1e6c8", c);
        }
        if (n[0] > 0.7) {
          if (y > 1.5 && y < 1.92 && Math.abs(z) > 0.03 && Math.abs(z) < 0.44)
            return glass(c, "#223344");
          if (y > 0.8 && y < 1.2 && Math.abs(z) < 0.44) return glass(c, "#223344");
          if (y > 1.25 && y < 1.4 && Math.abs(z) < 0.3)
            return keep(Math.abs(y - 1.325) < 0.02 && Math.abs(z) < 0.22 ? "#ffd84a" : "#141414");
          if (y > 0.4 && y < 0.7 && Math.abs(z) < 0.26)
            return keep(Math.sin(y * 120) > 0 ? "#d8dade" : "#3a3b3f");
        }
        if (y < 0.4) return lit(shade(red, 0.5), c);
        return lit(red, c);
      },
    });
    for (const z of [-0.36, 0.36])
      k.add(k.sphere(0.065), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        pos: [1.55, 0.55, z],
        weight: 3,
        pattern: false,
        color: "#fff8d8",
      });
    for (const x of [1.58, -1.58])
      k.add(evenBox(0.06, 0.12, 0.98), {
        even: true,
        opacity: 1,
        jitter: 0.015,
        ...P,
        pos: [x, 0.36, 0],
        color: (c) => lit(dark, c),
      });
    busDoors(k, 0.15, 0.55, 0.4, 1.18, 0.49);
    // Hazard lights at the corners, and their flashing halos.
    const fa = k.part("flashA", { pivot: [0, 0.6, 0] });
    const fb = k.part("flashB", { pivot: [0, 0.6, 0] });
    for (const x of [1.555, -1.555])
      for (const z of [-0.42, 0.42]) {
        k.add(k.sphere(0.045), {
          even: true,
          opacity: 1,
          jitter: 0.015,
          pos: [x, 0.62, z],
          weight: 4,
          pattern: false,
          color: "#ffa21a",
        });
        k.add(k.sphere(0.1), {
          even: true,
          jitter: 0.015,
          part: x * z > 0 ? fa : fb,
          pos: [x, 0.62, z],
          weight: 2,
          opacity: 0.75,
          pattern: false,
          color: "#ffc04a",
        });
      }
  }
  for (const [name, w] of [
    ["front", W.front],
    ["rear", W.rear],
  ]) {
    const part = k.part(name, { pivot: w, axis: [0, 0, 1] });
    for (const z of [-0.47, 0.47])
      wheel(k, [w[0], w[1], z], 0.3, 0.22, {
        part,
        rim: "#3b3c40",
        hub: "#d3d5d9",
        spokes: 0,
        even: true,
      });
  }
  shadow(k, 0.004, isSchool ? 1.95 : 1.75, 0.72);
}

drive:
drive(t, c, out) {
      // A bus stop: the lights flash, the stop arm swings out and the doors
      // open; then everything folds away again.
      const p = c.beep > 0.001 ? 1 - c.beep : 1;
      const open = easeInOut(smoothstep(0, 0.14, p) * (1 - smoothstep(0.78, 0.95, p)));
      const a = -t * 2;
      out.parts.front = { angle: a };
      out.parts.rear = { angle: a };
      out.parts.stop = { angle: (Math.PI / 2) * open };
      out.parts.doorA = { angle: -1.45 * open };
      out.parts.doorB = { angle: 1.45 * open };
      const on = p < 0.97;
      const blink = Math.floor(p * 18) % 2;
      out.parts.flashA = { visible: on && blink ? 1 : 0 };
      out.parts.flashB = { visible: on && !blink ? 1 : 0 };
      out.body = { squash: 0.03 * Math.sin(Math.PI * smoothstep(0, 0.12, p)) };
    }

build:
function planeBuild(k, o) {
  const col = o.color;
  const wing = o.wings;
  const wood = "#6b4a2b";
  // The fuselage: a lathe turned to lie along X.
  const fus = k.lathe(
    [
      [0.03, -1.8],
      [0.1, -1.6],
      [0.17, -1.0],
      [0.26, -0.3],
      [0.31, 0.3],
      [0.32, 0.75],
      [0.3, 1.0],
      [0.27, 1.12],
    ],
    { grid: 72 },
  );
  k.add(fus, {
    opacity: 1,
    jitter: 0.015,
    rot: [0, 0, -90],
    flat: 0.2,
    interior: 0.05,
    core: "#555",
    color: (c) => {
      const [x, y, z] = c.p;
      if (x > 0.84) return lit(Math.abs(x - 0.86) < 0.02 ? "#7b7d82" : "#c9ccd1", c);
      if (y > 0.18 && Math.hypot((x + 0.2) / 0.19, z / 0.17) < 1) return keep("#1a1411");
      if (Math.abs(x + 0.9) < 0.05) return lit("#f5f1e6", c);
      return lit(col, c);
    },
  });
  k.add(evenCylinder(0.25, 0.25, 0.04), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    pos: [1.13, 0, 0],
    rot: [0, 0, 90],
    color: (c) => (c.s.radial > 0.8 ? "#9a9da3" : "#2a2a2c"),
  });
  // The pilot, with goggles and a scarf that flutters.
  k.add(k.sphere(0.1), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    pos: [-0.2, 0.36, 0],
    weight: 2,
    color: (c) => lit("#6d4c33", c),
  });
  for (const z of [-0.045, 0.045])
    k.add(k.sphere(0.035), {
      even: true,
      opacity: 1,
      jitter: 0.015,
      pos: [-0.12, 0.38, z],
      weight: 4,
      pattern: false,
      color: "#9fd8ff",
    });
  k.add(
    k.tube(
      (t) => [-0.28 - 0.5 * t, 0.29 + 0.05 * Math.sin(t * 4), 0.03 * Math.sin(t * 7)],
      (t) => 0.035 * (1 - 0.5 * t),
    ),
    {
      even: true,
      opacity: 1,
      jitter: 0.015,
      weight: 2,
      kind: "sway",
      params: [0.4, 0.28],
      color: (c) => lit("#f4f1ea", c),
    },
  );
  slab(
    k,
    [
      [0.02, 0.26, -0.13],
      [0.02, 0.26, 0.13],
      [-0.04, 0.42, 0.11],
      [-0.04, 0.42, -0.11],
    ],
    0.01,
    { color: (c) => glass(c, "#5d7d99"), opacity: 0.7 },
  );
  // Two wings on struts.
  const wingColor = (c) => {
    const z = Math.abs(c.p[2]);
    if (z > 1.38) return lit(col, c);
    if (Math.abs(((z * 4) % 1) - 0.5) > 0.47) return keep(lit(shade(wing, 0.85), c));
    return lit(wing, c);
  };
  k.add(evenRoundBox(0.62, 0.07, 3.1, 0.021), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    pos: [0.3, -0.2, 0],
    flat: 0.2,
    color: wingColor,
  });
  k.add(evenRoundBox(0.62, 0.07, 3.3, 0.021), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    pos: [0.45, 0.62, 0],
    flat: 0.2,
    color: wingColor,
  });
  const strut = { weight: 2.5, color: (c) => lit(wood, c) };
  for (const s of [-1, 1]) {
    const z = 1.15 * s;
    rod(k, [0.16, -0.17, z], [0.3, 0.59, z], 0.022, strut);
    rod(k, [0.52, -0.17, z], [0.66, 0.59, z], 0.022, strut);
    rod(k, [0.26, 0.28, 0.12 * s], [0.34, 0.59, 0.3 * s], 0.018, strut);
    rod(k, [0.56, 0.28, 0.12 * s], [0.64, 0.59, 0.3 * s], 0.018, strut);
    // Rigging wires.
    rod(k, [0.25, -0.17, 0.3 * s], [0.3, 0.59, z], 0.005, { weight: 4, color: "#3a3a3a" });
    rod(k, [0.25, 0.59, 0.3 * s], [0.2, -0.17, z], 0.005, { weight: 4, color: "#3a3a3a" });
  }
  // Tail.
  k.add(evenRoundBox(0.45, 0.04, 1.15, 0.012), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    pos: [-1.55, 0.06, 0],
    flat: 0.2,
    color: wingColor,
  });
  slab(
    k,
    [
      [-1.3, 0.1, 0],
      [-1.84, 0.06, 0],
      [-1.87, 0.62, 0],
      [-1.62, 0.6, 0],
    ],
    0.04,
    { flat: 0.2, color: (c) => lit(c.p[0] < -1.74 ? "#f5f1e6" : col, c) },
  );
  // Landing gear.
  for (const s of [-1, 1]) {
    const ax = [0.55, -0.72, 0.33 * s];
    rod(k, [0.38, -0.26, 0.1 * s], ax, 0.02, { weight: 2.5, color: "#2f2f31" });
    rod(k, [0.74, -0.26, 0.1 * s], ax, 0.02, { weight: 2.5, color: "#2f2f31" });
    wheel(k, [0.55, -0.72, 0.39 * s], 0.17, 0.08, { rim: "#e6e1d6", hub: "#9a9a96", spokes: 0 });
  }
  rod(k, [0.55, -0.72, -0.35], [0.55, -0.72, 0.35], 0.015, { weight: 3, color: "#2f2f31" });
  rod(k, [-1.6, -0.08, 0], [-1.72, -0.22, 0], 0.015, { weight: 3, color: "#2f2f31" });
  // The propeller and spinner.
  const prop = k.part("prop", { pivot: PLANE.prop, axis: [1, 0, 0] });
  k.add(evenCylinder(0.11, 0.0, 0.22), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    part: prop,
    pos: [1.28, 0, 0],
    rot: [0, 0, -90],
    color: (c) => lit(col, c),
  });
  for (const s of [-1, 1])
    k.add(evenRoundBox(0.04, 0.62, 0.1, 0.018), {
      even: true,
      opacity: 1,
      jitter: 0.015,
      part: prop,
      pos: add(PLANE.prop, [0, s * 0.33, 0]),
      rot: [s * 12, 0, 0],
      weight: 2,
      color: (c) => (Math.abs(c.p[1]) > 0.56 ? keep("#e8c93a") : lit(wood, c)),
    });
}

drive:
drive(t, c, out) {
      out.parts.prop = { angle: t * 20 + burst(c.loop, 4) };
      const th = c.loop > 0.001 ? TAU * smoothstep(0, 1, 1 - c.loop) : 0;
      const R = 0.45;
      out.body = {
        quat: quatMulLocal(
          quatAxisAngle([0, 0, 1], th),
          quatAxisAngle([1, 0, 0], 0.05 * Math.sin(t * 0.8)),
        ),
        offset: [R * Math.sin(th), R * (1 - Math.cos(th)) + 0.03 * Math.sin(t * 1.2), 0],
      };
    }

drive(t, c, out) {
      // Climbs with the nose up while banking hard left, then hard right.
      const p = c.climb > 0.001 ? 1 - c.climb : 0;
      const v = Math.sin(Math.PI * p);
      const bank = -0.85 * Math.sin(TAU * p) * smoothstep(0, 0.08, p);
      out.body = {
        quat: quatMulLocal(
          quatAxisAngle([0, 0, 1], 0.2 * v),
          quatAxisAngle([1, 0, 0], bank + 0.06 * Math.sin(t * 0.5)),
        ),
        offset: [0, 0.03 * Math.sin(t * 0.9) + 0.3 * v, 0],
      };
    }

build:
function sailboatBuild(k, o) {
  const boat = k.part("boat", { pivot: BOAT.centre });
  const S = { part: boat, flat: 0.2 };
  const wl = -0.3;
  const H = { L: 2.6, B: 0.95, D: 0.5, bow: 0.42, stern: 0.14, boxy: 0.75, sheer: 0.08, rise: 0.3 };
  const { top } = hull(k, H, {
    side: {
      ...S,
      interior: 0.05,
      core: "#555",
      color: (c) => {
        const y = c.p[1];
        if (y < wl + 0.04) return lit("#b33a2e", c);
        if (Math.abs(y + 0.1) < 0.035) return lit(o.stripe, c);
        return lit("#f7f6f1", c);
      },
    },
    deck: { ...S, color: (c) => lit(shade("#c09160", 0.9 + 0.12 * Math.sin(c.p[2] * 70)), c) },
  });
  // A little cabin with portholes, and a lifebuoy.
  k.add(roundBox(0.85, 0.24, 0.56, 0.072), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    ...S,
    pos: [-0.1, top(0.45) + 0.1, 0],
    color: (c) => {
      if (Math.abs(c.n[2]) > 0.6 && Math.abs(c.p[1] - (top(0.45) + 0.12)) < 0.045) {
        const f = (c.p[0] + 0.5) / 0.25;
        if (Math.abs((f % 1) - 0.5) < 0.2) return keep("#23303d");
      }
      return lit("#f7f6f1", c);
    },
  });
  k.add(k.torus(0.1, 0.03), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    ...S,
    pos: [-0.72, top(0.2) + 0.2, 0.43],
    rot: [90, 0, 0],
    weight: 2,
    color: (c) => ((c.u * 4) % 1 < 0.5 ? "#e33b2f" : "#f7f6f1"),
  });
  // Mast, boom and stays.
  const mx = 0.3;
  const mTop = 3.3;
  rod(k, [mx, 0, 0], [mx, mTop, 0], 0.035, { ...S, weight: 1.6, color: "#d9d6cf" }, 0.022);
  rod(k, [mx, 0.62, 0], [-1.08, 0.66, 0], 0.024, { ...S, weight: 1.6, color: "#c09160" });
  rod(k, [1.28, top(1), 0], [mx, 2.85, 0], 0.006, { ...S, weight: 4, color: "#555" });
  rod(k, [-1.25, top(0), 0], [mx, mTop - 0.05, 0], 0.006, { ...S, weight: 4, color: "#555" });
  // Sails, filled with wind towards the viewer.
  const sailColor = (c) => {
    const y = c.p[1];
    const seam = Math.abs(((y - 0.6) / 0.34) % 1) < 0.03;
    const f = 0.8 + 0.22 * Math.abs(c.n[2]) + 0.05 * c.n[1];
    const base = shade(o.sails, f);
    return seam ? keep(shade(base, 0.9)) : base;
  };
  const main = k.param(
    (u, v) => {
      const luff = [mx - 0.03, 0.7 + 2.5 * v, 0];
      const leech = [-1.02 + 1.3 * v, 0.72 + 2.48 * v, 0];
      const p = lerp3(luff, leech, u);
      p[2] += 0.26 * Math.sin(Math.PI * u) * (1 - 0.75 * v);
      return p;
    },
    { grid: 48, thick: 0.01 },
  );
  k.add(main, { even: true, opacity: 1, jitter: 0.015, ...S, color: sailColor });
  const tack = [1.22, top(1) + 0.05, 0];
  const head = [mx + 0.05, 2.8, 0];
  const clew = [-0.1, 0.62, 0.3];
  const jib = k.param(
    (u, v) => {
      const a = lerp3(tack, head, v);
      const p = lerp3(a, clew, u * (1 - v));
      p[2] += 0.12 * Math.sin(Math.PI * u) * (1 - v);
      return p;
    },
    { grid: 40, thick: 0.01 },
  );
  k.add(jib, { even: true, opacity: 1, jitter: 0.015, ...S, color: sailColor });
  // A pennant at the masthead.
  k.add(
    quad(
      k,
      [mx, mTop - 0.02, 0],
      [mx, mTop - 0.14, 0],
      [mx - 0.4, mTop - 0.08, 0],
      [mx - 0.4, mTop - 0.08, 0],
    ),
    {
      even: true,
      opacity: 1,
      jitter: 0.015,
      ...S,
      weight: 2,
      kind: "sway",
      params: [0.6, mTop - 0.3],
      color: o.stripe,
    },
  );
  // Spray thrown up at the bow and along the lee side when a gust hits.
  const spray = k.part("spray", { pivot: [1.2, wl, 0.4] });
  k.cloud({ share: 0.018, size: 1.2, pattern: false, part: spray }, (rand) => {
    const bow = rand() < 0.8;
    const x = bow ? 1.15 + rand() * 0.35 : -1.2 + rand() * 0.3;
    const zz = bow ? (rand() - 0.2) * 0.5 : 0.35 + rand() * 0.3;
    return {
      p: [x, wl + rand() * 0.08, zz],
      color: mix("#dff4ff", "#ffffff", rand()),
      size: 0.6 + rand() * 1.1,
      opacity: 0.85,
      kind: "rise",
      params: [(bow ? 0.28 : 0.14) + rand() * 0.14, rand()],
    };
  });
  water(k, wl, 2.0, 1.45, {
    share: 0.22,
    deep: "#1c6a8f",
    light: "#63b7d9",
    foam: (x, z) => {
      const u = x / H.L + 0.5;
      if (u < -0.1 || u > 1.06) return 0;
      const b = hullBeam(clamp(u, 0, 1), H.B, H.bow, H.stern);
      const d = Math.abs(z) - b;
      return smoothstep(0.08, 0, d) * (0.5 + 0.6 * smoothstep(0.75, 1, u));
    },
  });
}

drive:
drive(t, c, out) {
      // The gust heels her right over at once, throws up spray, and she
      // rocks back upright as it passes.
      const p = c.gust > 0.001 ? 1 - c.gust : 1;
      const g = smoothstep(0, 0.14, p) * (1 - smoothstep(0.4, 1, p));
      const rock = 0.06 * Math.sin(TAU * 1.5 * p) * smoothstep(0.4, 0.7, p) * (1 - p);
      const tq = tilt(0.05 * Math.sin(t * 0.9) + 0.42 * g + rock, 0.03 * Math.sin(t * 0.7 + 1));
      out.parts.boat = carried(BOAT.centre, tq, BOAT.centre, [0, 0.02 * Math.sin(t * 1.1), 0]);
      out.parts.spray = { visible: smoothstep(0, 0.06, p) * (1 - smoothstep(0.45, 0.8, p)) };
      out.amount = 1 + 1.5 * g;
    }

build:
function submarineBuild(k, o) {
  const col = o.color;
  const brass = "#caa04a";
  const prof = [
    [0.0, -1.55],
    [0.2, -1.42],
    [0.38, -1.05],
    [0.5, -0.45],
    [0.52, 0.25],
    [0.49, 0.85],
    [0.38, 1.25],
    [0.2, 1.48],
    [0.0, 1.55],
  ];
  k.add(k.lathe(prof, { grid: 80 }), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    rot: [0, 0, -90],
    flat: 0.2,
    interior: 0.06,
    core: "#6d5a1a",
    color: (c) => {
      const x = c.p[0];
      if (Math.abs(x + 0.95) < 0.012 || Math.abs(x - 0.95) < 0.012)
        return keep(lit(shade(col, 0.65), c));
      for (const sx of [-0.95, 0.95])
        if (Math.abs(x - sx) < 0.05 && Math.abs(x - sx) > 0.03 && (c.u * 40) % 1 < 0.3)
          return keep(lit(shade(col, 0.72), c));
      return lit(col, c);
    },
  });
  // Portholes with brass rims.
  const rAt = curve(prof.map(([r, y]) => [y, r]));
  for (const px of [-0.55, 0, 0.55]) {
    const z = rAt(px) - 0.01;
    k.add(evenTorus(k, 0.13, 0.03), {
      even: true,
      opacity: 1,
      jitter: 0.015,
      pos: [px, 0.02, z],
      rot: [90, 0, 0],
      weight: 2,
      pattern: false,
      color: (c) => lit(brass, c),
    });
    k.add(k.disc(0.12), {
      opacity: 1,
      jitter: 0.015,
      pos: [px, 0.02, z - 0.005],
      rot: [90, 0, 0],
      weight: 2,
      pattern: false,
      color: (c) => {
        const d = Math.hypot(c.p[0] - px + 0.04, c.p[1] - 0.06);
        return mix("#0f3d5c", "#bde9ff", smoothstep(0.08, 0.0, d) * 0.9);
      },
    });
  }
  // The conning tower with its planes.
  k.add(evenRoundBox(0.72, 0.46, 0.34, 0.102), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    pos: [0.12, 0.62, 0],
    flat: 0.2,
    color: (c) => {
      if (Math.abs(c.n[2]) > 0.6 && Math.hypot(c.p[0] - 0.12, c.p[1] - 0.66) < 0.06)
        return keep("#16324a");
      return lit(col, c);
    },
  });
  for (const s of [-1, 1])
    slab(
      k,
      [
        [0.3, 0.66, 0.15 * s],
        [0.12, 0.66, 0.15 * s],
        [0.16, 0.66, 0.42 * s],
        [0.28, 0.66, 0.42 * s],
      ],
      0.03,
      { flat: 0.2, color: (c) => lit(shade(col, 0.9), c) },
    );
  // The periscope, which slides down into the tower.
  const scope = k.part("scope", { pivot: [0.3, 0.85, 0] });
  rod(k, [0.3, 0.7, 0], [0.3, 1.2, 0], 0.035, {
    part: scope,
    weight: 2,
    color: (c) => lit("#8d9096", c),
  });
  k.add(evenRoundBox(0.16, 0.08, 0.08, 0.024), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    part: scope,
    pos: [0.35, 1.22, 0],
    color: (c) => lit("#8d9096", c),
  });
  k.add(k.disc(0.03), {
    opacity: 1,
    jitter: 0.015,
    part: scope,
    pos: [0.435, 1.22, 0],
    rot: [0, 0, 90],
    weight: 4,
    pattern: false,
    color: "#9fe0ff",
  });
  // A lamp on the bow.
  k.add(k.sphere(0.07), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    pos: [1.28, 0.32, 0],
    weight: 3,
    pattern: false,
    color: "#fff6c9",
  });
  k.add(evenCylinder(0.08, 0.08, 0.08), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    pos: [1.22, 0.3, 0],
    rot: [0, 0, 70],
    color: (c) => lit("#8d9096", c),
  });
  // Tail fins.
  for (const [a, b] of [
    [0, 1],
    [0, -1],
    [1, 0],
    [-1, 0],
  ])
    slab(
      k,
      [
        [-1.05, 0.1 * a, 0.1 * b],
        [-1.42, 0.08 * a, 0.08 * b],
        [-1.5, 0.48 * a, 0.48 * b],
        [-1.32, 0.48 * a, 0.48 * b],
      ],
      0.035,
      { flat: 0.2, color: (c) => lit(shade(col, 0.88), c) },
    );
  // The propeller.
  const prop = k.part("prop", { pivot: SUB.prop, axis: [1, 0, 0] });
  k.add(evenCylinder(0.08, 0.02, 0.14), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    part: prop,
    pos: add(SUB.prop, [-0.02, 0, 0]),
    rot: [0, 0, 90],
    color: (c) => lit(brass, c),
  });
  for (let i = 0; i < 4; i++) {
    const a = (i * 90 * Math.PI) / 180;
    k.add(evenRoundBox(0.04, 0.26, 0.1, 0.018), {
      even: true,
      opacity: 1,
      jitter: 0.015,
      part: prop,
      pos: add(SUB.prop, [0, Math.cos(a) * 0.16, Math.sin(a) * 0.16]),
      rot: [i * 90 + 20, 0, 0],
      weight: 2,
      color: (c) => lit(brass, c),
    });
  }
  // A rush of bubbles from the vents when she dives.
  const vent = k.part("vent", { pivot: [0, 0, 0] });
  k.cloud({ share: 0.02, size: 1.0, pattern: false, part: vent }, (rand) => {
    const x = (rand() - 0.5) * 2.6;
    const a = rand() * TAU;
    const r = 0.5 + rand() * 0.25;
    return {
      p: [x, Math.abs(Math.sin(a)) * r * 0.9 + 0.1, Math.cos(a) * r],
      color: mix("#cdf3ff", "#ffffff", rand()),
      size: 0.5 + rand() * 1.4,
      opacity: 0.7,
      kind: "rise",
      params: [0.3 + rand() * 0.3, rand()],
    };
  });
  // Bubbles.
  k.cloud({ share: 0.018, size: 0.9, pattern: false }, (rand) => {
    const fromProp = rand() < 0.6;
    const s = rand();
    const p = fromProp
      ? [-1.72 - s * 0.3, (rand() - 0.5) * 0.25 + s * 0.6, (rand() - 0.5) * 0.3]
      : [(rand() - 0.5) * 2.2, 0.5 + rand() * 0.55, (rand() - 0.5) * 0.6];
    return {
      p,
      color: mix("#cdf3ff", "#ffffff", rand()),
      size: 0.5 + rand() * 1.1,
      opacity: 0.55,
      kind: "rise",
      params: [0.7 + rand() * 0.6, rand()],
    };
  });
}

drive:
drive(t, c, out) {
      // Periscope down, nose down and a rush of bubbles; she dives, then
      // noses back up to the surface and raises the periscope again.
      const p = c.dive > 0.001 ? 1 - c.dive : 1;
      const deep = smoothstep(0, 0.35, p) * (1 - smoothstep(0.5, 0.88, p));
      const pitch =
        -0.3 * Math.sin(Math.PI * smoothstep(0, 0.42, p)) +
        0.22 * Math.sin(Math.PI * smoothstep(0.46, 0.92, p));
      const down = smoothstep(0, 0.07, p) * (1 - smoothstep(0.82, 0.96, p));
      out.parts.prop = { angle: t * 9 + burst(c.dive, 6) };
      out.parts.scope = { offset: [0, -0.34 * down, 0] };
      out.parts.vent = { visible: smoothstep(0, 0.04, p) * (1 - smoothstep(0.4, 0.6, p)) };
      out.body = {
        offset: [0, 0.03 * Math.sin(t * 0.9) - 0.42 * deep, 0],
        quat: quatAxisAngle([0, 0, 1], 0.03 * Math.sin(t * 0.7) + pitch),
      };
      out.amount = 1 + 0.4 * deep;
    }

build:
function bicycleBuild(k, o) {
  const col = o.color;
  const tube = { weight: 2.2, flat: 0.25, color: (c) => lit(col, c, 0.62) };
  const metal = { weight: 3, color: (c) => lit("#c5c8cd", c, 0.6) };
  const black = { weight: 2.5, color: (c) => lit("#1f1f21", c, 0.6) };
  const wheelAt = (w, name) => {
    const part = k.part(name, { pivot: w, axis: [0, 0, 1] });
    k.add(k.torus(0.625, 0.038), {
      part,
      pos: w,
      rot: [90, 0, 0],
      weight: 1.6,
      pattern: false,
      color: (c) => shade("#222", 0.8 + 0.25 * Math.abs(c.ln[1])),
    });
    // Rims, hub and spokes stay metal under a flag or pattern.
    const bare = { part, pos: w, rot: [90, 0, 0], pattern: false };
    k.add(k.torus(0.59, 0.016), { ...bare, weight: 2.5, color: "#c9ccd1" });
    k.add(k.cylinder(0.035, 0.13), { ...bare, weight: 3, color: "#aeb1b6" });
    for (let i = 0; i < 24; i++) {
      const a = (i / 24) * TAU;
      const side = i % 2 ? 0.05 : -0.05;
      rod(
        k,
        add(w, [Math.cos(a) * 0.03, Math.sin(a) * 0.03, side]),
        add(w, [Math.cos(a + 0.2) * 0.585, Math.sin(a + 0.2) * 0.585, 0]),
        0.0055,
        {
          part,
          weight: 5,
          pattern: false,
          color: "#d4d6da",
        },
      );
    }
    return part;
  };
  wheelAt(BIKE.front, "front");
  const rearPart = wheelAt(BIKE.rear, "rear");
  k.add(k.cylinder(0.085, 0.02), {
    part: rearPart,
    pos: add(BIKE.rear, [0, 0, 0.1]),
    rot: [90, 0, 0],
    weight: 3,
    color: "#9ea1a6",
  });
  // The frame.
  const BB = BIKE.bb;
  const SC = [-0.36, 1.46, 0];
  const HT = [0.72, 1.5, 0];
  const HB = [0.8, 1.26, 0];
  rod(k, BB, [-0.37, 1.5, 0], 0.035, tube);
  rod(k, [-0.36, 1.4, 0], [0.73, 1.45, 0], 0.03, tube);
  rod(k, BB, HB, 0.04, tube);
  rod(k, HB, [0.715, 1.56, 0], 0.042, tube);
  for (const z of [-0.07, 0.07]) {
    rod(k, [-0.34, 1.38, 0], add(BIKE.rear, [0, 0, z]), 0.018, tube);
    rod(k, BB, add(BIKE.rear, [0, 0, z]), 0.02, tube);
    rod(k, HB, add(BIKE.front, [0, 0, z]), 0.022, tube);
  }
  // Seat, stem and handlebars.
  rod(k, SC, [-0.42, 1.68, 0], 0.02, metal);
  k.add(k.ellipsoid(0.2, 0.05, 0.1), {
    pos: [-0.45, 1.72, 0],
    weight: 2,
    color: (c) => lit("#5a3a24", c),
  });
  k.add(k.ellipsoid(0.12, 0.04, 0.05), {
    pos: [-0.3, 1.71, 0],
    weight: 2,
    color: (c) => lit("#5a3a24", c),
  });
  rod(k, [0.715, 1.56, 0], [0.71, 1.72, 0], 0.022, metal);
  rod(k, [0.71, 1.72, 0], [0.8, 1.74, 0], 0.02, metal);
  const bar = spline([
    [0.7, 1.84, -0.34],
    [0.8, 1.76, -0.27],
    [0.82, 1.74, 0],
    [0.8, 1.76, 0.27],
    [0.7, 1.84, 0.34],
  ]);
  k.add(k.tube(bar, 0.018), metal);
  for (const s of [-1, 1]) rod(k, [0.74, 1.81, 0.31 * s], [0.66, 1.86, 0.36 * s], 0.026, black);
  // The bell.
  const bell = k.part("bell", { pivot: BIKE.bell, axis: [1, 0, 0] });
  k.add(k.sphere(0.045), {
    part: bell,
    pos: BIKE.bell,
    scale: [1, 0.8, 1],
    weight: 4,
    color: (c) => lit("#e3e5e8", c, 0.5),
  });
  // Ring lines round the bell, shown while it rings (inner, then outer).
  for (const [name, radii] of [
    ["ringA", [0.1, 0.2]],
    ["ringB", [0.15, 0.26]],
  ]) {
    const part = k.part(name, { pivot: BIKE.bell });
    for (const r of radii)
      for (const s of [-1, 1])
        k.add(
          k.tube((t) => {
            const a = (t - 0.5) * 1.3 + (s > 0 ? 0.35 : Math.PI - 0.35);
            return add(BIKE.bell, [Math.cos(a) * r, Math.sin(a) * r + 0.02, 0.04]);
          }, 0.012),
          { part, weight: 4, pattern: false, color: "#ffe066" },
        );
  }
  // The chain, rear cog and kickstand.
  const chain = spline(
    [
      [-0.1, 0.8, 0.1],
      [-0.55, 0.77, 0.1],
      [-1.0, 0.745, 0.1],
      [-1.085, 0.66, 0.1],
      [-1.0, 0.575, 0.1],
      [-0.55, 0.5, 0.1],
      [-0.1, 0.4, 0.1],
      [0.1, 0.6, 0.1],
    ],
    { closed: true },
  );
  k.add(k.tube(chain, 0.012, { closed: true }), { weight: 3, color: "#4a4b4f" });
  rod(k, [-0.25, 0.58, -0.08], [-0.45, 0.02, -0.22], 0.016, black);
  // The crank: chainring, arms and pedals turn together.
  const crank = k.part("crank", { pivot: BB, axis: [0, 0, 1] });
  k.add(k.torus(0.19, 0.016), {
    part: crank,
    pos: add(BB, [0, 0, 0.1]),
    rot: [90, 0, 0],
    weight: 3,
    color: "#b5b8bd",
  });
  k.add(k.cylinder(0.16, 0.012), {
    part: crank,
    pos: add(BB, [0, 0, 0.1]),
    rot: [90, 0, 0],
    weight: 2,
    color: (c) => (c.s.radial < 0.25 || (c.u * 5) % 1 < 0.22 ? "#b5b8bd" : null),
  });
  for (const s of [-1, 1]) {
    const end = add(BB, [0, -0.34 * s, 0.15 * s]);
    rod(k, add(BB, [0, 0, 0.15 * s]), end, 0.022, { ...metal, part: crank });
    k.add(k.box(0.15, 0.035, 0.1), {
      part: crank,
      pos: add(end, [0, 0, 0.07 * s]),
      weight: 3,
      color: "#28292c",
    });
  }
  shadow(k, 0.004, 1.5, 0.3, { share: 0.008 });
}

drive:
drive(t, c, out, info) {
      // Ring-ring: the bell shakes and rings out, and the rider pedals hard
      // (whole turns, so the wheels end where they would have been).
      const p = c.ring > 0.001 ? 1 - c.ring : 1;
      const a = -t * 2.4;
      out.parts.front = { angle: a - burst(c.ring, 5) };
      out.parts.rear = { angle: a - burst(c.ring, 5) };
      out.parts.crank = { angle: a * 0.42 - burst(c.ring, 2) };
      const ringing = p < 0.7 ? 1 - smoothstep(0.55, 0.7, p) : 0;
      out.parts.bell = { angle: 0.35 * Math.sin(info.time * 40) * ringing };
      const beat = Math.floor(p * 16) % 2;
      out.parts.ringA = { visible: ringing * beat };
      out.parts.ringB = { visible: ringing * (1 - beat) };
    }

build:
function tractorBuild(k, o) {
  const col = o.color;
  const P = { flat: 0.2 };
  const grey = "#3a3b3e";
  // Wheels with deep chevron treads.
  const chevronTyre = (w, r, wid, part) => {
    const tr = r * 0.3;
    k.add(evenTorus(k, r - tr, tr), {
      even: true,
      opacity: 1,
      jitter: 0.015,
      part,
      pos: w,
      rot: [90, 0, 0],
      scale: [1, wid / (2 * tr), 1],
      flat: 0.25,
      weight: 1.2,
      pattern: false,
      color: (c) => {
        const out = Math.hypot(c.lp[0], c.lp[2]) > r - tr * 0.6;
        const f = (c.u * 26 + (Math.abs(c.lp[1]) / tr) * 0.45) % 1;
        const lug = out && f < 0.42;
        return shade("#262628", lug ? 1.25 : 0.7 + 0.2 * Math.abs(c.ln[1]));
      },
    });
    k.add(evenCylinder(r * 0.62, r * 0.62, wid * 0.75), {
      even: true,
      opacity: 1,
      jitter: 0.015,
      part,
      pos: w,
      rot: [90, 0, 0],
      flat: 0.2,
      pattern: false,
      color: (c) => {
        if (c.s.side) return "#9a927f";
        const rr = c.s.radial;
        if (rr < 0.28) return shade("#e9dfc4", 0.8);
        const bolt = Math.abs(rr - 0.45) < 0.06 && (c.u * 8) % 1 < 0.2;
        return shade("#e9dfc4", bolt ? 0.6 : 0.95 - 0.1 * rr);
      },
    });
  };
  for (const [name, w, r, wid, zz] of [
    ["rear", TRACTOR.rear, TRACTOR.rr, 0.38, 0.58],
    ["front", TRACTOR.front, TRACTOR.fr, 0.2, 0.44],
  ]) {
    const part = k.part(name, { pivot: w, axis: [0, 0, 1] });
    for (const z of [-zz, zz]) chevronTyre([w[0], w[1], z], r, wid, part);
  }
  // Chassis, bonnet and grille.
  k.add(evenBox(1.9, 0.26, 0.44), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    ...P,
    pos: [0.25, 0.58, 0],
    color: (c) => lit(grey, c),
  });
  k.add(evenBox(0.14, 0.18, 0.8), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    ...P,
    pos: [1.3, 0.55, 0],
    color: (c) => lit(grey, c),
  });
  k.add(evenRoundBox(1.28, 0.56, 0.56, 0.09), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    ...P,
    pos: [0.62, 0.98, 0],
    interior: 0.05,
    core: "#555",
    color: (c) => {
      const [x, y, z] = c.p;
      if (c.n[0] > 0.7 && Math.abs(z) < 0.2 && y > 0.78 && y < 1.2)
        return keep(Math.sin(y * 110) > 0 ? "#cfd2d6" : "#1c1c1e");
      if (
        Math.abs(c.n[2]) > 0.7 &&
        x > 0.55 &&
        x < 1.1 &&
        y > 0.88 &&
        y < 1.1 &&
        Math.sin(x * 70) > 0.3
      )
        return keep(lit(shade(col, 0.45), c));
      return lit(col, c);
    },
  });
  for (const z of [-0.22, 0.22])
    k.add(k.sphere(0.06), {
      even: true,
      opacity: 1,
      jitter: 0.015,
      pos: [1.22, 1.15, z],
      weight: 3,
      pattern: false,
      color: "#fff7d6",
    });
  // Exhaust stack and air intake.
  rod(k, [0.88, 1.22, 0.12], [0.88, 1.95, 0.12], 0.045, {
    weight: 2,
    color: (c) => lit("#1f1f21", c),
  });
  rod(k, [0.5, 1.22, -0.12], [0.5, 1.55, -0.12], 0.04, {
    weight: 2,
    color: (c) => lit("#bfc2c7", c),
  });
  k.add(evenCylinder(0.06, 0.06, 0.06), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    pos: [0.5, 1.58, -0.12],
    color: (c) => lit("#bfc2c7", c),
  });
  // A light, thinning wisp of exhaust (it was a heavy cloud).
  plume(k, [0.88, 2.0, 0.12], [-0.55, 0.45, 0], {
    share: 0.007,
    spread: 0.04,
    grow: 2.2,
    color: "#e6e3de",
    dark: "#9a958f",
    opacity: 0.08,
    height: 0.45,
  });
  // The cab: posts, roof, windows, a seat and a steering wheel.
  const cx0 = -1.05;
  const cx1 = -0.08;
  k.add(evenBox(cx1 - cx0 + 0.1, 0.08, 0.9), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    ...P,
    pos: [(cx0 + cx1) / 2, 0.94, 0],
    color: (c) => lit(grey, c),
  });
  for (const x of [cx0 + 0.05, cx1 - 0.05])
    for (const z of [-0.42, 0.42])
      rod(k, [x, 0.95, z], [x, 2.0, z], 0.035, { weight: 2, color: (c) => lit(grey, c) });
  k.add(evenRoundBox(cx1 - cx0 + 0.25, 0.09, 1.02, 0.03), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    ...P,
    pos: [(cx0 + cx1) / 2, 2.04, 0],
    color: (c) => lit(col, c),
  });
  const pane = (a, b, cc, d) =>
    k.add(quad(k, a, b, cc, d), {
      even: true,
      opacity: 0.2,
      pattern: false,
      even: true,
      jitter: 0.01,
      // Clear glass with a soft diagonal reflection (it was random static).
      color: (c) => {
        const t = (c.p[0] * 0.6 + c.p[1] * 1.4 + c.p[2] * 0.5) * 1.3;
        const f = t - Math.floor(t);
        return mix("#bcd6ea", "#ffffff", 0.8 * smoothstep(0, 0.06, f) * smoothstep(0.32, 0.1, f));
      },
    });
  pane(
    [cx1 - 0.05, 1.05, -0.4],
    [cx1 - 0.05, 1.05, 0.4],
    [cx1 - 0.05, 1.96, 0.4],
    [cx1 - 0.05, 1.96, -0.4],
  );
  pane(
    [cx0 + 0.05, 1.05, 0.42],
    [cx1 - 0.05, 1.05, 0.42],
    [cx1 - 0.05, 1.96, 0.42],
    [cx0 + 0.05, 1.96, 0.42],
  );
  k.add(evenRoundBox(0.3, 0.35, 0.4, 0.09), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    pos: [-0.72, 1.2, 0],
    color: (c) => lit("#1e1e20", c),
  });
  k.add(evenTorus(k, 0.13, 0.018), {
    even: true,
    opacity: 1,
    jitter: 0.015,
    pos: [-0.3, 1.45, 0],
    rot: [0, 0, 60],
    weight: 3,
    color: "#1e1e20",
  });
  rod(k, [-0.3, 1.45, 0], [-0.08, 1.1, 0], 0.02, { weight: 3, color: "#1e1e20" });
  // Mudguards over the big wheels.
  for (const s of [-1, 1]) {
    const guard = k.param(
      (u, v) => {
        const a = Math.PI * (0.05 + 0.9 * u);
        const R = TRACTOR.rr + 0.08;
        return [
          TRACTOR.rear[0] + Math.cos(a) * R,
          TRACTOR.rear[1] + Math.sin(a) * R,
          s * (0.36 + 0.44 * v),
        ];
      },
      { grid: 32, flip: s < 0 },
    );
    k.add(guard, {
      opacity: 1,
      jitter: 0.015,
      ...P,
      weight: 1.2,
      color: (c) => lit(col, c),
    });
  }
  shadow(k, 0.004, 1.45, 0.95);
}

