      // (docs/PACKS.md 7b, draw order), and once more when they are hidden.
      out.resort = model
        ? resortSteps(this, "cnn3d", on ? s : -1, 0.25, 3.2, 0.17)
        : resortSteps(this, "cnn", on ? s : -1, 2.55, 3.2, 0.11);
    }

