          const t0 = 0.15 + i * RNN_STEP;
          if (!on) return;
          if (g === 0) v = Math.max(v, 0.55 * bump(s, t0 + 0.1, t0 + 0.3, t0 + 0.55, t0 + 0.8));
          if (g === 1) v = Math.max(v, bump(s, t0 + 0.05, t0 + 0.25, t0 + 0.45, t0 + 0.7));
