      // (token 4), built where it lands.
      TF.xs.forEach((x) =>
        k.add(k.box(TF_TILE[0] + 0.04, TF_TILE[1] + 0.04, 0.01), {
          pos: [x, TF.row, 0.005],
          flat: 0.2,
          pattern: false,
          color: () => keep("#232c45"),
