        L.levels[i].forEach((grid, v) => {
          const x0 = p[0] - 2.5 * px;
          const y0 = p[1] + 3.5 * px;
          k.add(
            k.param((u, w) => [x0 + u * 5 * px, y0 - w * 7 * px, p[2] + 0.022], {
