      SONG.sample = { samples, rate, duration: samples.length / rate, name: "Sample tune" };
    }
    SONG.want = o.song === "custom" && SONG.custom ? SONG.custom : SONG.sample;
    if (o.song === "recording" && REC.last) SONG.want = await recordingSong(); // r3
    if (!SONG.want.duration) SONG.want.duration = SONG.want.samples.length / SONG.want.rate;
  }

build:
build(k, o) {
    const mode = modeById(o.mode);
    // Lane Live input: a new plate's sand starts scattered.
    Object.assign(SING, { p: 0, want: null, asked: false, last: null });
    SING.builds++;
    CH.bowAtSing = null;
    // The stand: a base, a post, and the plate clamped on top.
    const plate = k.part("plate", { pivot: [0, 0, 0], axis: [0, 1, 0] });
    k.add(k.cylinder(0.5, 0.1, { caps: true }), {
      pos: [0, -1.05, 0],
      color: "#2b3037",
      share: 0.05,
      even: true,
    });
    k.add(k.cylinder(0.09, 1.0, { caps: "bottom" }), {
      pos: [0, -0.55, 0],
      color: (c) => shade("#454c55", 0.8 + 0.3 * Math.abs(c.n[0])),
      share: 0.04,
      even: true,
    });
    // The plate: its top a smooth sheet of overlapping flat discs (brushed
    // steel, a soft light across it), its edge a thin box.
    k.add(k.box(2 * PLATE, PLATE_T, 2 * PLATE), {
      pos: [0, -PLATE_T / 2 - 0.002, 0],
      color: (c) => shade("#56606c", 0.75 + 0.25 * Math.abs(c.n[1])),
      part: plate,
      share: 0.04,
      even: true,
    });
    sheet(k, {
      x0: -PLATE,
      x1: PLATE,
      z0: -PLATE,
      z1: PLATE,
      y: 0.001,
      cells: k.count * 0.16,
      part: plate,
      color: (x, z) => mix("#5d6874", "#7a8593", clamp(0.5 + (0.28 * (x - z)) / PLATE, 0, 1)),
    });
    // The bow: a slim stick with a pale ribbon of hair against the front edge.
    const bow = k.part("bow");
    k.add(k.box(0.05, 1.5, 0.05), {
      pos: [0.15, 0.0, PLATE + 0.16],
      rot: [0, 0, 0],
      color: "#6a4a30",
      part: bow,
      share: 0.02,
    });
    k.add(k.box(0.012, 1.45, 0.11), {
      pos: [0.15, 0.0, PLATE + 0.06],
      color: "#efe6d0",
      part: bow,
      share: 0.015,
    });
    // The sand: one splat per grain in each of the twelve copies.
    const copies = KEYS;
    const n = Math.max(200, Math.floor((k.count * 0.6) / copies));
    const snaps = settle(mode, n, () => k.rand());
    const at = (s, i) => [
      (s[i * 3] * 2 - 1) * PLATE,
      GRAIN_LIFT + s[i * 3 + 2] * HOP,
      (s[i * 3 + 1] * 2 - 1) * PLATE,
    ];
    const tone = Array.from({ length: n }, () => k.rand());
    for (let j = 0; j < copies; j++) {
      const part = k.part(`sand${j}`);
      k.cloud({ share: n / k.count, size: 0.5, pattern: false }, (rand, i) => ({
        p: at(snaps[j], i),
        to: at(snaps[j + 1], i),
        channel: 0,
        color: mix("#e9d8ac", "#f8efd2", tone[i]),
        size: 0.5 + 0.4 * tone[i],
        opacity: 0.98,
        part,
        pattern: false,
      }));
    }
    k.reach([0, HOP + 0.3, 0]);
    k.data = { chladni: { mode, copies } };
  }

drive:
drive(t, c, out, info) {
    const g = info?.data?.chladni;
    if (!g) return;
    // Lane Live input: while the microphone is on, your voice bows the plate.
    const sung = liveIn.on("mic");
    // After the microphone stops, the sung sand stays as it is until the
    // next tap (the bow's own state takes over then), rather than jumping to
    // wherever a tap made while singing had left the bow.
    if (sung) CH.bowAtSing = c.bow ?? 0;
    else if (CH.bowAtSing !== null && (c.bow ?? 0) !== CH.bowAtSing) CH.bowAtSing = null;
    const keep = !sung && CH.bowAtSing !== null && SING.p > 0;
    const p = sung ? singDrive(info.time ?? t, g.mode) : keep ? SING.p : clamp01(c.bow ?? 0);
    // The sound: the hum when the bowing starts, a hiss when it is stirred.
    if (sung) CH.was = p; // your voice is the sound
    else if (CH.was <= 0.001 && p > 0.001) for (const s of chladniCue(g.mode, true)) out.cues.push(s);
    else if (CH.was >= 0.999 && p < 0.999) for (const s of chladniCue(g.mode, false)) out.cues.push(s); // prettier-ignore
    CH.was = p;
    // Which of the twelve copies of the sand shows, and how far it has
    // moved on toward the next.
    const pos = p * KEYS;
    const j = Math.min(KEYS - 1, Math.floor(pos));
    for (let i = 0; i < KEYS; i++) out.parts[`sand${i}`] = { visible: i === j ? 1 : 0 };
    out.morph = [pos - j, 0, 0, 0];
    // The bow is drawn along the front edge while the sand moves.
    const bowing = !sung && p > 0.001 && p < 0.999;
    const ramp = sung ? SING.r : Math.min(smoothstep(0, 0.06, p), 1 - smoothstep(0.94, 1, p));
    out.parts.bow = {
      visible: bowing ? 1 : 0,
      offset: [0, 0.38 * Math.sin(t * 7) * ramp, 0],
    };
    // The plate itself shivers a hair.
    out.parts.plate = { offset: [0, 0.006 * Math.sin(t * 90) * ramp, 0] };
  }

build:
build(k) {
    ECHO.start = null;
    ECHO.energy = null;
    ECHO.tapWas = 0;
    ECHO.listening = false;
    // The floor: warm boards along x, a soft light from the front.
    const floorN = Math.round(Math.sqrt(k.count * 0.22));
    sheet(k, {
      cols: floorN,
      rows: floorN,
      size: ((2 * ROOM) / floorN) * 1.25,
      n: [0, 1, 0],
      at: (a, b) => [(a - 0.5) * 2 * ROOM, 0, (b - 0.5) * 2 * ROOM],
      color: (a, b) => {
        const board = Math.floor(b * 14);
        const tone = 0.86 + 0.12 * Math.sin(board * 12.9898) * Math.sin(board * 4.1);
        const grain = 0.04 * Math.sin(a * 60 + board * 7);
        // A fine dark seam between boards.
        const edge = Math.min(b * 14 - board, board + 1 - b * 14);
        const seam = edge < 0.06 ? 0.7 : 1;
        return shade(mix("#8a5a34", "#b07a48", 0.4 + 0.4 * b), (tone + grain) * seam);
      },
    });
    // Three walls, pale plaster, with a skirting board.
    const walls = k.part("walls");
    const wallN = Math.round(Math.sqrt(k.count * 0.07));
    const wall = (at, n) =>
      sheet(k, {
        cols: wallN * 2,
        rows: Math.max(4, Math.round(wallN * 0.6)),
        size: ((2 * ROOM) / (wallN * 2)) * 1.5,
        n,
        at,
        part: walls,
        color: (a, b) => (b > 0.9 ? "#e8e2d6" : shade("#d9d2c4", 0.92 + 0.08 * b)),
      });
    wall((a, b) => [(a - 0.5) * 2 * ROOM, WALL_H * (1 - b), -ROOM], [0, 0, 1]);
    wall((a, b) => [-ROOM, WALL_H * (1 - b), (a - 0.5) * 2 * ROOM], [1, 0, 0]);
    wall((a, b) => [ROOM, WALL_H * (1 - b), (a - 0.5) * 2 * ROOM], [-1, 0, 0]);
    // The reading: a dark panel on the back wall, its splats colored from
    // the toy's screen (the number).
    const pw = 2.3;
    const ph = pw * (160 / 512);
    const pcols = PANEL_W;
    const prows = PANEL_H;
    const panel = [];
    for (let j = 0; j < prows; j++)
      for (let i = 0; i < pcols; i++) {
        const u = (i + 0.5) / pcols;
        const v = (j + 0.5) / prows;
        panel.push({ p: [(u - 0.5) * pw, WALL_H * 0.55 - (v - 0.5) * ph, -ROOM + 0.02], n: [0, 0, 1], flat: 0.03, size: ((pw / pcols) * 1.5) / 0.01, color: "#101418", kind: "screen", params: [u, v], opacity: 1, pattern: false }); // prettier-ignore
      }
    k.cloud(
      { share: panel.length / k.count, pattern: false, jitter: 0 },
      (rand, i) => panel[i] || null,
    );
    // The clap: a small bright mark where the sound starts.
    const clap = k.part("clap", { pivot: [0, 0.02, 0] });
    k.add(k.sphere(0.06), { pos: [0, 0.06, 0], color: "#fff3c0", part: clap, share: 0.004 });
    // The rings: each a thin circle of splats on the floor about the clap,
    // grown from nothing to the walls by its part's scale.
    const per = 220;
    for (let r = 0; r < RINGS; r++) {
      const ring = k.part(`ring${r}`, { pivot: [0, 0.015, 0] });
      const pts = [];
      for (let i = 0; i < per; i++) {
        const a = (i / per) * TAU;
        pts.push({ p: [1.9 * Math.cos(a), 0.015, 1.9 * Math.sin(a)], n: [0, 1, 0], flat: 0.2, size: 2.4, color: "#ffe9a8", part: ring, opacity: 1, pattern: false }); // prettier-ignore
      }
      k.cloud({ share: per / k.count, pattern: false }, (rand, i) => pts[i] || null);
    }
    k.reach([0, WALL_H + 0.1, ROOM]);
  }

drive:
drive(t, c, out, info) {
    const time = info.time ?? t;
    // The microphone: a clap heard starts the rings from what it measures.
    followMic(time);
    // A tap: the sample room (or the last room measured) claps.
    const tap = c.clap ?? 0;
    if (tap > 0.999 && ECHO.tapWas <= 0.999) {
      const rt = ECHO.result?.rt60 || SAMPLE_RT;
      ECHO.level = sampleLevel(rt);
      ECHO.start = time;
      if (!ECHO.result) {
        ECHO.result = { rt60: SAMPLE_RT, method: "sample" };
        ECHO.sample = true;
      }
      // Its sound: a hand clap that rings as long as the room (not while
      // the microphone listens, so the room isn't measured on our sound).
      if (!live.on("mic")) out.cues.push({ voice: "clap", f: 1400, decay: 1 + rt * 4.2, vol: 0.8 });
    }
    ECHO.tapWas = tap;
    // A pulse that runs out ends the sample's rings (the rest pose).
    let vt = ECHO.start === null ? null : (time - ECHO.start) / SLOW; // seconds of the sound
    if (vt !== null && ECHO.level && tap <= 0 && !ECHO.energy) vt = null;
    let wall = 0;
    for (let r = 0; r < RINGS; r++) out.parts[`ring${r}`] = { visible: 0 };
    if (vt !== null && ECHO.level) {
      let any = false;
      // The newest rings first; each part shows the newest ring on it.
      const newest = Math.floor(vt / RING_GAP);
      for (let g = newest; g >= Math.max(0, newest - RINGS + 1); g--) {
        const tau = g * RING_GAP;
        const L = ECHO.level(tau);
        if (L === null) {
          any = true; // still being heard
          continue;
        }
        const age = (vt - tau) / RING_TRAVEL;
        if (L < 0.02 || age < 0 || age > 1) continue;
        any = true;
        const s = 0.03 + 0.74 * age; // to the walls
        // Bright and warm near the clap's peak, dim and cool as it fades.
        const col = mix("#7fb6ff", "#fff0b0", L);
        const fade = age < 0.85 ? 1 : 1 - smoothstep(0.85, 1, age);
        out.parts[`ring${g % RINGS}`] = { visible: fade > 0.02 ? 1 : 0, scale: s, tint: col, glow: 0.35 + 0.65 * L, bright: 0.25 + 1.1 * L * fade }; // prettier-ignore
        if (age > 0.9) wall = Math.max(wall, L * (1 - smoothstep(0.9, 1, age) * 0.5));
      }
      if (!any && (ECHO.energy?.done || !ECHO.energy)) {
        ECHO.start = null;
        ECHO.energy = null;
      }
    }
    out.parts.walls = wall > 0.01 ? { tint: "#ffe6a0", glow: 0.35 * wall } : {};
    out.parts.clap = { tint: "#fff3c0", glow: vt !== null && vt < 0.12 ? 1 - vt / 0.12 : 0 };
  }

build:
build(k, o) {
    MIRROR.depth = o.depth ?? 0.6;
    const { height } = buildMirror(k, { width: 2, lift: 0.9, look: o.look ?? "plain" });
    // A dark frame round the picture, like a mirror's.
    const f = 0.07;
    const w = 1 + f;
    const h = height / 2 + f;
    const frame = (x, y, sx, sy) =>
      k.add(k.box(sx, sy, 0.06), {
        pos: [x, y, -0.03],
        color: (cc) => shade("#2b2f36", 0.8 + 0.3 * Math.abs(cc.n[2])),
        share: 0.01,
        even: true,
      });
    frame(0, h - f / 2, 2 * w, f);
    frame(0, -h + f / 2, 2 * w, f);
    frame(-w + f / 2, 0, f, 2 * h);
    frame(w - f / 2, 0, f, 2 * h);
    k.reach([0, 0, 0.9]);
    k.data = { mirror: { cols: MIRROR.cols, rows: MIRROR.rows, live: !!MIRROR.cam } };
  }

drive:
drive(t, c, out) {
    // The tap flattens or raises the relief; the picture itself keeps still
    // (the owner's review of October 1, 2026: no swaying).
