build:
build(k, o) {
    const G = GAL.data;
    if (!G) throw new Error("The galaxy hasn't loaded.");
    const half = G.head.half;
    const budget = Math.max(1000, Math.floor(k.count * 0.97));
    // The file holds the dense gas first (all of it, drawn at its own size),
    // then a random share of the diffuse gas (drawn wider by the file's
    // widenRest). A smaller budget keeps DENSE_SHARE of it for dense gas and
    // thins each group evenly, widening by the cube root of its thinning, so
    // the gas still closes (the same mass in fewer, bigger pieces).
    const nDense = Math.min(G.n, G.head.nDense ?? G.n);
    const nRest = G.n - nDense;
    let dKeep = nDense;
    let rKeep = nRest;
    if (G.n > budget) {
      rKeep = Math.min(nRest, Math.round(budget * 0.35));
      dKeep = Math.min(nDense, budget - rKeep);
      rKeep = Math.min(nRest, budget - dKeep);
    }
    const dPick = pickIndices(nDense, dKeep);
    const rPick = pickIndices(nRest, rKeep);
    const count = dKeep + rKeep;
    const at = (j) => (j < dKeep ? (dPick ? dPick[j] : j) : nDense + (rPick ? rPick[j - dKeep] : j - dKeep)); // prettier-ignore
    const widenD = dPick ? Math.cbrt(nDense / dKeep) : 1;
    const widenR = (G.head.widenRest ?? G.head.widen ?? 1) * (rPick ? Math.cbrt(nRest / rKeep) : 1);
    const widenOf = (i) => (i < nDense ? widenD : widenR);
    // The box: its floor (dark, so the gas shows against it from above) and
    // its twelve edges.
    const hy = G.head.halfY ?? half;
    const size = [half, hy, half];
    if (o.box !== false) {
      k.add(evenBox(2 * half, 0.08, 2 * half), {
        pos: [0, -hy - 0.06, 0],
        even: true,
        color: "#090a10",
        jitter: 0,
        opacity: 1,
        flat: 0.3,
        weight: 0.5,
        part: sciPart(SCI_TYPE.plain),
      });
    }
    // Its twelve edges: thin lines of splats stretched along each edge, so
    // they stay crisp.
    if (o.box !== false) {
      const SEG = 80;
      const edges = [];
      for (const axis of [0, 1, 2]) {
        const others = [0, 1, 2].filter((x) => x !== axis);
        for (const a of [-1, 1])
          for (const b of [-1, 1])
            for (let i = 0; i < SEG; i++) {
              const p = [0, 0, 0];
              p[others[0]] = a * size[others[0]];
              p[others[1]] = b * size[others[1]];
              p[axis] = -size[axis] + ((i + 0.5) / SEG) * 2 * size[axis];
              const dir = [0, 0, 0];
              dir[axis] = 1;
              edges.push({ p, dir, len: (2 * size[axis]) / SEG });
            }
      }
      k.cloud({ count: (edges.length * 160000) / k.count, jitter: 0 }, (_r, j) => {
        const e = edges[j];
        if (!e) return null;
        const base = k.baseSize || 0.01;
        const across = 0.03 / 0.7; // about 0.03 kpc across
        return {
          p: e.p,
          dir: e.dir,
          size: across / base,
          stretch: (0.8 * e.len) / across,
          color: "#c4ccdc",
          opacity: 1,
          part: sciPart(SCI_TYPE.plain),
        };
      });
    }
    k.reach([half, hy, half]);
    k.reach([-half, -hy, -half]);
    // The gas is cut round (a disk inside the box), so the galaxy doesn't
    // end in a square.
    const R = half * 0.96;
    let emitted = 0;
    let first = -1;
    k.cloud({ count: (count * 160000) / k.count, jitter: 0 }, (_r, j) => {
      if (j >= count) return null;
      const i = at(j);
      const p = G.pos(i);
      if (p[0] * p[0] + p[2] * p[2] > R * R) return null;
      if (first < 0) first = i;
      emitted++;
      const w = widenOf(i);
      const h = G.h(i) * w;
      const logT = G.logT(i);
      // The Gaussian with the same spread as the simulation's kernel: FIRE's
      // cubic spline, whose smoothing length h is its support radius, has a
      // standard deviation of 0.274 h along each axis (it isn't a Gaussian;
      // this is the look, not the physics).
      const sigma = KERNEL_SIGMA * h;
      const base = k.baseSize || 0.01;
      // Denser gas (smaller h) is more opaque: the column through a
      // particle goes as its mass over h², and the masses are nearly equal.
      // Hot gas is thin and spread out; it is lifted a little so it shows.
      const hot = 1 + 3 * smoothstep(4.3, 5.5, logT);
      // A widened piece is as faint as its size says: the thinned diffuse
      // gas stays a faint haze, so the dense arms show through it.
      const alpha = Math.min(0.8, 0.8 * (0.07 / h) ** 2 * hot);
      // Denser gas is brighter, so the spiral arms stand out.
      const dense = Math.max(0, Math.min(1, (Math.log10(0.5 / h) + 0.1) / 1.4));
      const color =
        o.color === "density"
          ? tempColor(1 + 7 * dense)
          : shade(tempColor(logT), 0.6 + 0.95 * dense);
      return {
        p,
        size: (Math.SQRT2 * sigma) / base,
        color,
        opacity: alpha,
        part: sciPart(SCI_TYPE.gas),
        params: [asF32(logT), 0],
      };
    });
    GAL.info = {
      n: G.n,
      drawn: count,
      half,
      widen: widenD,
      widenRest: widenR,
      nDense,
      simulation: G.head.simulation,
      get emitted() {
        return emitted;
      },
      get first() {
        return first;
      },
    };
    k.data = { galaxy: GAL.info };
  }

drive:
drive(t, c, out) {
    out.grow = 1 - smoothstep(0, 1, c.peel ?? 0);
    // Every particle at least about a pixel wide, wherever the camera is.
    out.morph = [0, 1, 0.0006, 0];
    out.glow = [0, 0, 0, 0];
  }

prepare:
async prepare() {
    if (!GAL.data) GAL.data = readGalaxy(await readAsset(`../../assets/toys/galaxy-box/${GALAXY_SAMPLE.file}`, true)); // prettier-ignore
  }

build:
build(k, o) {
      const scene = ["glass", "splash", "candle", "cup"].includes(o.scene) ? o.scene : "glass";
      LAB.scene = scene;
      if (scene === "glass") glassScene(k, o);
      else if (scene === "splash") splashScene(k, o);
      else if (scene === "candle") candleScene(k, o);
      else cupScene(k, o);
      k.data.liquidId = LIQUID_LOOKS[o.liquid] ? o.liquid : "water";
    }

drive:
drive(t, c, out, info) {
      const d = info.data || {};
      const n = info.tap?.n ?? 0;
      // Seconds since the last tap (99: none yet, or long ago).
      const e = c.go > 0 ? (1 - c.go) * TAP_SECS : 99;
      const fresh = n > LAB.tapN;
      if (n < LAB.tapN) LAB.tapN = 0;
      if (fresh) LAB.tapN = n;
      out.fluid = {};
      // (traced on WebGPU: the splats shrink inside the traced shapes, which
      // cover them, and stay there to be tapped: a tap on the handle pours)
      const splats = d.props?.drawn ? 0.55 : 1;
      if (d.props) out.parts.stand = { visible: splats };
      if (d.scene === "glass") {
        // Every third tap empties the glass before it pours.
        const empty = n > 0 && n % 3 === 0;
        const start = empty ? 1.4 : 0;
        const on = e >= start && e < start + d.pour;
        out.fluid.liquid = { on, drain: empty && e < 1.3 ? 0.55 : 0 };
        // The red handle turns a quarter turn while it pours.
        const open = Math.min(1, Math.max(0, Math.min((e - start) / 0.25, (start + d.pour - e) / 0.25))); // prettier-ignore
        out.parts.valve = { angle: -1.35 * open, visible: splats };
        out.fluid.props = { valve: -1.35 * open };
        // (the pour's sound comes from the simulation: src/fluids/runtime.js)
      } else if (d.scene === "splash") {
        out.fluid.liquid = {
          once: { id: n, do: "drop", at: [0.05, 1.45, 0.03], radius: 0.19, vel: [0, -1.5, 0] },
        };
        // (its splash comes from the simulation, as it lands)
      } else if (d.scene === "candle") {
        // Blown out for three seconds, then it lights again.
        const out3 = e < 3;
        out.fluid.flame = { on: !out3, wind: e < 0.35 ? [2.5, 0, 0] : [0, 0, 0] };
        out.fluid.props = { light: out3 ? 0 : 1 };
        // Put out, the hot wick sends up a thick ribbon of smoke that thins.
        out.fluid.smoke = { on: e < 2.6, flow: e < 2.6 ? (1 - e / 2.6) ** 1.5 : 0 };
        if (fresh) out.cues.push(BLOW_SOUND);
      } else if (d.scene === "cup") {
        const w = e < 2.2 ? Math.sin((Math.PI * e) / 2.2) : 0;
        out.fluid.steam = { wind: [1.4 * w, 0, 0.3 * w] };
        if (fresh) out.cues.push(STEAM_SOUND);
      }
    }

build:
build(k, o) {
      const style = ON_TIME[o.style] ? o.style : "tv";
      SCR.style = style;
      SCR.on = false;
      SCR.at = -1e9;
      SCR.tapN = 0;
      SCR.fresh = true;
      SCR.wasPlaying = false;
      SCR.resume = true;
      SCR.gifPaused = false;
      SCR.live = live.on("screen"); // lane Live input
      if (style === "tv") buildTV(k);
      else if (style === "flat") buildFlat(k);
      else if (style === "cinema") buildCinema(k);
      else buildHologram(k);
    }

drive:
drive(t, c, out, info) {
      const pics = info.data?.pictures;
      const style = SCR.style;
      const time = info.time ?? t;
      const video = pics?.kind === "video";
      const gif = pics?.kind === "gif";
      // A new build starts switched off: a video still playing stops.
      if (SCR.fresh && pics?.kind) {
        SCR.fresh = false;
        if (SCR.live) {
          // Lane Live input: a shared screen switches the set on by itself.
          SCR.on = true;
          SCR.at = time;
          if (video && !pics.playing) pics.togglePlay();
          out.cues.push(ON_SOUND[style]);
        } else if (video && pics.playing) pics.togglePlay();
      }
      const switchOn = () => {
        SCR.on = true;
        SCR.at = time;
        if (video && SCR.resume && !pics.playing) pics.togglePlay();
        out.cues.push(ON_SOUND[style]);
      };
      const n = info.tap?.n ?? 0;
      if (n < SCR.tapN) SCR.tapN = 0;
      if (n > SCR.tapN) {
        SCR.tapN = n;
        if (!SCR.on) switchOn();
        else if (info.tap.pick === PICK_OTHER) {
          // A tap on the picture (or the set round it): play or pause.
          if (video) pics.togglePlay();
          else if (gif) SCR.gifPaused = !SCR.gifPaused;
          out.cues.push(PLAY_SOUND);
        } else {
          // The switch (or the Toy tab's button): off, the video paused
          // where it was, to play on when it comes back on.
          SCR.on = false;
          SCR.at = time;
          SCR.resume = video ? pics.playing : true;
          if (video && pics.playing) pics.togglePlay();
          out.cues.push(OFF_SOUND[style]);
        }
      } else if (!SCR.on && video && pics.playing && !SCR.wasPlaying) {
        // Play in the Toy tab switches it on too.
        SCR.resume = true;
        switchOn();
      }
      SCR.wasPlaying = !!(video && pics.playing);
      // A GIF holds its frame while the set is off (or paused).
      if (gif) pics.hold?.(!SCR.on || SCR.gifPaused);
      // p: 0..1 switching on (1 on); q: 0..1 switching off (1 off).
      const p = SCR.on ? clamp((time - SCR.at) / ON_TIME[style], 0, 1) : 0;
      const q = SCR.on ? 0 : clamp((time - SCR.at) / OFF_TIME[style], 0, 1);
      out.morph = [0, 0, 0, 0];
      let shown;
      const on = SCR.on;
      if (style === "tv") shown = driveTV(on, p, q, out);
      else if (style === "flat") shown = driveFlat(on, p, q, out);
      else if (style === "cinema") shown = driveCinema(on, p, q, out);
      else shown = driveHologram(on, p, q, t, out);
      // The picture shows only while the set is (partly) on: hidden, it is
      // still built ("ahead"), so it is there the moment it switches on.
      out.sheets = { screen: { page: 0, visible: shown ? 1 : 0, ahead: 1 } };
    }
